			short = "蠻鬃水井位於雷霆崖北方，是牛頭人聖井中最北的一口。風怒鷹身人佔據了它周圍的土地，井水已遭污染，等待著淨化。",
			full = "蠻鬃水井位於雷霆崖北方，是牛頭人聖井中最北的一口。風怒鷹身人佔據了它周圍的土地，井水已遭污染，等待著淨化。",
			source = "https://warcraft.wiki.gg/wiki/Wildmane_Water_Well",
		},
		["windfury ridge"] = {
			name = "狂風山",
			short = "狂風山得名於在其高處築巢的鷹身人，這些兇猛的生物會俯衝襲擊任何太過靠近的人，殺死或擄走粗心大意的人。",
			full = "狂風山得名於在其高處築巢的鷹身人，這些兇猛的生物會俯衝襲擊任何太過靠近的人，殺死或擄走粗心大意的人。美洲獅與狼群也在周圍的山丘間徘徊。\n\n然而，雷霆崖的牛頭人卻十分珍視鷹身人那色彩鮮豔的羽毛，將它們用於婚禮與宴會。",
			source = "https://warcraft.wiki.gg/wiki/Windfury_Ridge",
		},
		["winterhoof water well"] = {
			name = "冰蹄水井",
			short = "冰蹄水井位於莫高雷南部草海平原的邊緣。第三次大戰結束數年後，風險投資公司佔據了這口井，並在井水中下毒，企圖切斷牛頭人的水源。",
			full = "冰蹄水井位於莫高雷南部草海平原的邊緣。第三次大戰結束數年後，風險投資公司佔據了這口井，並在井水中下毒，企圖切斷牛頭人的水源。莫爾·雷角製作圖騰來淨化污染，但井水至今仍未恢復純淨。",
			source = "https://warcraft.wiki.gg/wiki/Winterhoof_Water_Well",
		},
	},
	-- 貧瘠之地: 31 subzones
	[1413] = {
		["agamagor"] = {
			name = "阿迦瑪戈",
			short = "阿迦瑪戈位於陶拉祖營地向西延伸的道路北側，是一片被鬃背野豬人佔據的荊棘木迷窟。",
			full = "阿迦瑪戈位於陶拉祖營地向西延伸的道路北側，是一片被鬃背野豬人佔據的荊棘木迷窟。牠們的死者會留下乾涸的血晶碎片，流亡者碎牙十分珍視這些信物，並以他自己那些古怪的恩惠作為交換。",
			source = "https://warcraft.wiki.gg/wiki/Agama'gor",
		},
		["bael modan"] = {
			name = "巴爾莫丹",
			short = "巴爾丹城堡的石造要塞，矗立在昔日石塔牛頭人村莊的所在之處。",
			full = "巴爾丹城堡的石造要塞，矗立在昔日石塔牛頭人村莊的所在之處。在它的下方，矮人挖掘者正朝著一座古老的泰坦建築群挖去，那是一處研究設施，早在牛頭人踏上這片土地之前便已被掩埋，其中的遺物大多仍在黑暗中無人取用。\n\n矮人帶著炸藥而來，炸開了石塔部族視為神聖的土地。挖掘撕裂了大地，也撕裂了牛頭人，部族大多數人不是被殺，就是被迫離開他們世代守護的土地。他們的舊村落如今已被矮人的挖掘機械撕得支離破碎。仍在附近道路上徘徊的加恩·石塔，曾試圖以酋長對酋長的方式解決此事，以言語代替戰鬥。矮人卻不肯放棄挖掘。於是他從外交轉向戰爭，尋求任何能找到的力量，將他們驅逐出去。",
			source = "https://warcraft.wiki.gg/wiki/Bael_Modan",
		},
		["baeldun keep"] = {
			name = "巴爾丹城堡",
			short = "巴爾丹城堡矗立在貧瘠之地南部巴爾莫丹挖掘場的上方。雙辮將軍指揮著這座城堡，率領城中的矮人抵禦周圍平原上的牛頭人與獸人。",
			full = "巴爾丹城堡矗立在貧瘠之地南部巴爾莫丹挖掘場的上方。雙辮將軍指揮著這座城堡，率領城中的矮人抵禦周圍平原上的牛頭人與獸人。",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Keep",
		},
		["blackthorn ridge"] = {
			name = "黑棘山",
			short = "荊棘擠滿了剃刀沼澤以北的山谷，這裡由鋼鬃野豬人佔據。山嶺上住著一位名叫布瑞恩的薩滿。她的營地下方有一池清水，在荊棘之間清澈而純淨。",
			full = "荊棘擠滿了剃刀沼澤以北的山谷，這裡由鋼鬃野豬人佔據。山嶺上住著一位名叫布瑞恩的薩滿。她的營地下方有一池清水，在荊棘之間清澈而純淨。",
			source = "https://warcraft.wiki.gg/wiki/Blackthorn_Ridge",
		},
		["boulder lode mine"] = {
			name = "石礦坑",
			short = "石礦坑位於貧瘠之地，坑道以獸人的木材支撐，掛著部落的旗幟，那是最初將這些礦井鑿入岩石的人所留下的褪色遺物。",
			full = "石礦坑位於貧瘠之地，坑道以獸人的木材支撐，掛著部落的旗幟，那是最初將這些礦井鑿入岩石的人所留下的褪色遺物。那份所有權如今已不復存在。風險投資公司佔據了這座礦坑，哥布林擠滿了昔日獸人工作的坑道。\n\n碼頭管理員迪茲維格聽說，那裡有一名礦工鑿開一道礦脈，挖出了一顆巨大的翡翠。這位碼頭管理員對它渴望至極，甚至承諾任何願意進去從風險投資公司手中奪取它的人，都能分得一份利潤。",
			source = "https://warcraft.wiki.gg/wiki/Boulder_Lode_Mine",
		},
		["bramblescar"] = {
			name = "迅猛龍平原",
			short = "鋼鬃野豬人佔據著迅猛龍平原。道路對面的阿迦瑪戈盤據著鬃背野豬人，兩個部族之間只有戰爭。",
			full = "鋼鬃野豬人佔據著迅猛龍平原。道路對面的阿迦瑪戈盤據著鬃背野豬人，兩個部族之間只有戰爭。若太過靠近鋼鬃野豬人的巢穴，牠們可不會等到被挑釁才動手。",
			source = "https://warcraft.wiki.gg/wiki/Bramblescar",
		},
		["camp taurajo"] = {
			name = "陶拉祖營地",
			short = "陶拉祖營地位於貧瘠之地，靠近通往莫高雷的山口。它為從血蹄村出發的旅人提供休息與補給，讓他們能繼續前往牛頭人的家園。",
			full = "陶拉祖營地位於貧瘠之地，靠近通往莫高雷的山口。它為從血蹄村出發的旅人提供休息與補給，讓他們能繼續前往牛頭人的家園。",
			source = "https://warcraft.wiki.gg/wiki/Camp_Taurajo",
		},
		["crossroads"] = {
			name = "十字路口",
			short = "十字路口坐落在道路交會之處：一條是從黃金之路南下的南北向道路，另一條是從棘齒城一路延伸到石爪山脈的漫長東西向道路。",
			full = "十字路口坐落在道路交會之處：一條是從黃金之路南下的南北向道路，另一條是從棘齒城一路延伸到石爪山脈的漫長東西向道路。這個地方是因道路交會而形成的，而不是因為在這裡建造了什麼──住所寥寥無幾，也沒有雄偉的城牆，只有帳篷、攤位，以及爭相叫賣貨物、喊聲此起彼落的商人。\n\n在聚落的邊緣之外有一片墓地，與身後貿易廣場的喧囂相比，顯得樸素而寧靜。部落就是在這裡向他們的亡者致敬，正如哨兵嶺為聯盟所扮演的角色一樣。",
			source = "https://warcraft.wiki.gg/wiki/Crossroads",
		},
		["dreadmist den"] = {
			name = "鬼霧獸穴",
			short = "一片暗紅色的霧氣永遠籠罩著鬼霧峰，將它掩蓋在暮色之中。燃刃教徒佔據著山中的鬼霧獸穴，守護著惡魔之種，那是他們視為至寶的神器。",
			full = "一片暗紅色的霧氣永遠籠罩著鬼霧峰，將它掩蓋在暮色之中。燃刃教徒佔據著山中的鬼霧獸穴，守護著惡魔之種，那是他們視為至寶的神器。這片霧氣本身似乎也為他們的惡魔崇拜遮蔽了外人的目光。",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Den",
		},
		["dreadmist peak"] = {
			name = "鬼霧峰",
			short = "在十字路口的西北方，鬼霧峰聳立於貧瘠之地，峰頂被紅色的濃霧所籠罩，那是一道古老惡魔詛咒的殘餘。",
			full = "在十字路口的西北方，鬼霧峰聳立於貧瘠之地，峰頂被紅色的濃霧所籠罩，那是一道古老惡魔詛咒的殘餘。燃刃教徒在峰頂安營紮寨，守護著下方鬼霧獸穴中的惡魔之種。",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Peak",
		},
		["dry hills"] = {
			name = "無水嶺",
			short = "無水嶺在貧瘠之地的塵土間青翠聳起，是一片向石爪山脈攀升的丘陵。",
			full = "無水嶺在貧瘠之地的塵土間青翠聳起，是一片向石爪山脈攀升的丘陵。巫翼鷹身人佔據著這片土地，而且日益大膽，襲擊黃金之路北段的商隊，然後消失在綠意之中。",
			source = "https://warcraft.wiki.gg/wiki/Dry_Hills",
		},
		["far watch post"] = {
			name = "前沿哨所",
			short = "前沿哨所就位於連接杜洛塔與貧瘠之地的橋梁西側，只不過是一座瞭望塔、一座獸人地洞和一排投石車，再往南不遠處則是一座狼欄和兩名苦工。",
			full = "前沿哨所就位於連接杜洛塔與貧瘠之地的橋梁西側，只不過是一座瞭望塔、一座獸人地洞和一排投石車，再往南不遠處則是一座狼欄和兩名苦工。這不是一個舒適的崗位，卻是一個必要的崗位，負責守護前往杜洛塔的商隊，並同時抵禦聯盟與野豬人。",
			source = "https://warcraft.wiki.gg/wiki/Far_Watch_Post",
		},
		["field of giants"] = {
			name = "巨人曠野",
			short = "巨人曠野在貧瘠之地南部綿延展開，寬闊而空曠，成群的雷霆蜥蜴與科多獸在此一同遷徙，數量之多，少有其他土地能夠匹敵。",
			full = "巨人曠野在貧瘠之地南部綿延展開，寬闊而空曠，成群的雷霆蜥蜴與科多獸在此一同遷徙，數量之多，少有其他土地能夠匹敵。\n\n黃金之路的南段穿越這片平原，這裡比北方更不安全。沿途曾經矗立著瞭望塔守護往來的商隊；如今它們空無一人，任由風與野草侵蝕。\n\n部落並未放棄這片土地，儘管他們對它的掌控十分薄弱。在曠野南緣的一道山嶺上，住著薩滿布瑞恩，她遠離任何營地或路口。不遠處徘徊著加恩·石塔，心懷一段舊怨──當矮人為了尋找泰坦遺跡而在他們家園旁的土地上挖掘時，他的部族被逐出了村莊。那處挖掘場成了巴爾莫丹，而加恩從未忘記他的族人為此付出的代價。",
			source = "https://warcraft.wiki.gg/wiki/Field_of_Giants",
		},
		["forgotten pools"] = {
			name = "遺忘之池",
			short = "遺忘之池位於十字路口向西延伸的道路北側，是散布在北貧瘠之地的綠洲中最北的一處。",
			full = "遺忘之池位於十字路口向西延伸的道路北側，是散布在北貧瘠之地的綠洲中最北的一處。它的岸邊終年青綠，周圍環繞著別處找不到的飽滿蘑菇，池水中則有著在貧瘠之地其他地方都釣不到的變異魚。\n\n科卡爾半人馬在水邊出沒，與在此棲身的烏龜和野生動物為伍。",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Pools",
		},
		["fray island"] = {
			name = "勇士島",
			short = "勇士島是貧瘠之地東岸外一座小而乾燥的島嶼。",
			full = "勇士島是貧瘠之地東岸外一座小而乾燥的島嶼。\n\n這座島是各個種族與信仰的戰士們的訓練場，他們在克蘭諾克·馬克雷德的號召下聚集於此。",
			source = "https://warcraft.wiki.gg/wiki/Fray_Island",
		},
		["gold road"] = {
			name = "黃金之路",
			short = "黃金之路綿延於摩爾沙農場與大裂谷之間，而在標示著渡口的那座橋以南，它的南段另被稱為南黃金之路。",
			full = "黃金之路綿延於摩爾沙農場與大裂谷之間，而在標示著渡口的那座橋以南，它的南段另被稱為南黃金之路。",
			source = "https://warcraft.wiki.gg/wiki/Gold_Road",
		},
		["groldom farm"] = {
			name = "格羅多姆農場",
			short = "格羅多姆農場是奧格瑪建立後數年間興起的養豬場之一，它的豬圈不斷遭受鋼鬃掠奪者的襲擊。",
			full = "格羅多姆農場是奧格瑪建立後數年間興起的養豬場之一，它的豬圈不斷遭受鋼鬃掠奪者的襲擊。",
			source = "https://warcraft.wiki.gg/wiki/Grol'dom_Farm",
		},
		["lushwater oasis"] = {
			name = "甜水綠洲",
			short = "大裂谷的地勢陡降之處匯聚著水，野獸穿過樹林下來飲水。科卡爾半人馬就在樹根間等待著牠們，獵捕被池水吸引而來的動物。",
			full = "大裂谷的地勢陡降之處匯聚著水，野獸穿過樹林下來飲水。科卡爾半人馬就在樹根間等待著牠們，獵捕被池水吸引而來的動物。\n\n綠洲之下是哀嚎洞穴的入口，一處被稱為受詛咒之地的所在。在地底騷動的東西從未浮上水面，但它的名字至今仍籠罩在水面之上。\n\n這裡的魚與貧瘠之地其他地方的魚截然不同。",
			source = "https://warcraft.wiki.gg/wiki/Lushwater_Oasis",
		},
		["merchant coast"] = {
			name = "商旅海岸",
			short = "商旅海岸得名於途經此地的貿易，這些生意精打細算、從不間斷，全掌握在棘齒城的哥布林手中。",
			full = "商旅海岸得名於途經此地的貿易，這些生意精打細算、從不間斷，全掌握在棘齒城的哥布林手中。\n\n南方的海岸屬於南海海盜。他們之中有一位名叫巴隆·朗紹爾的人，他曾偷走加茲魯維一批貴重的貨物，並在被抓到之前將它埋了起來，這筆財富從此遺落在海岸的某處。",
			source = "https://warcraft.wiki.gg/wiki/Merchant_Coast",
		},
		["morshan base camp"] = {
			name = "莫爾杉營地",
			short = "莫爾杉營地位於梣谷邊界以南，靠近摩爾沙農場，是部落在貧瘠之地較大的據點之一。",
			full = "莫爾杉營地位於梣谷邊界以南，靠近摩爾沙農場，是部落在貧瘠之地較大的據點之一。戰歌偵查騎兵以此為基地，監視著向北通往那片爭奪不休的森林的道路。",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Base_Camp",
		},
		["morshan rampart"] = {
			name = "摩爾沙農場",
			short = "摩爾沙農場矗立在黃金之路向北離開貧瘠之地之處，是為了抵禦聯盟從梣谷推進而築起的一道壁壘。",
			full = "摩爾沙農場矗立在黃金之路向北離開貧瘠之地之處，是為了抵禦聯盟從梣谷推進而築起的一道壁壘。它粗獷簡陋，專為戰爭而建：土木工事與瞭望塔，目的是抵擋從北方壓境而來的敵軍，守住防線。",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Rampart",
		},
		["raptor grounds"] = {
			name = "迅猛龍巢穴",
			short = "擠滿這座小山谷的陽鱗迅猛龍，與貧瘠之地的其他迅猛龍都不一樣。牠們展現出一種不自然的狡猾，會搭建簡陋的小屋，並用那本不該懂得任何技藝的爪子製作工具。",
			full = "擠滿這座小山谷的陽鱗迅猛龍，與貧瘠之地的其他迅猛龍都不一樣。牠們展現出一種不自然的狡猾，會搭建簡陋的小屋，並用那本不該懂得任何技藝的爪子製作工具。\n\n更奇怪的是，牠們對任何閃亮或陌生的東西都充滿渴望，這讓牠們襲擊附近的部落聚落，把任何吸引牠們目光的東西都拖走。",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Grounds",
		},
		["ratchet"] = {
			name = "棘齒城",
			short = "棘齒城坐落在貧瘠之地的東岸，是一座哥布林港口城鎮，與海對岸的藏寶海灣和大財主里維加茲有著熱絡的貿易往來。",
			full = "棘齒城坐落在貧瘠之地的東岸，是一座哥布林港口城鎮，與海對岸的藏寶海灣和大財主里維加茲有著熱絡的貿易往來。加茲魯維用索爾支付他建造奧格瑪的酬勞建立了這座城鎮，而這裡很快便擠滿了走私者，以及其他所有被體面地方拒之門外的人。\n\n這種漠不關心差點讓它付出慘痛的代價。燃刃教派暗中挑撥奧格瑪與塞拉摩之間的關係，在棘齒城的港口附近製造航運事件，讓雙方都只將其視為挑釁。曾經在碼頭上和平共處的獸人與人類水手開始在街頭鬥毆，而當打手馬茲克蘭克逮捕了克拉特與喬克兩位船長時，北方城堡認定這就是獸人正在集結備戰的證據。棘齒城成了部落大軍準備向他們進軍的集結地。直到燃刃在這起事件中的黑手曝光，索爾才在戰鬥開始之前叫停了這一切。",
			source = "https://warcraft.wiki.gg/wiki/Ratchet",
		},
		["shrine of the fallen warrior"] = {
			name = "戰士之魂神殿",
			short = "一條被踩得光禿的小徑爬上十字路口西邊的一座山丘，盡頭是一座紀念一位陣亡戰士的神殿。那裡沒有刻下任何名字，也沒有任何旗幟作為標記。",
			full = "一條被踩得光禿的小徑爬上十字路口西邊的一座山丘，盡頭是一座紀念一位陣亡戰士的神殿。那裡沒有刻下任何名字，也沒有任何旗幟作為標記。這座山丘保持著它的沉默，而通往山頂的小路，是還有人記得這一切的唯一跡象。",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Fallen_Warrior",
		},
		["sludge fen"] = {
			name = "淤泥沼澤",
			short = "淤泥沼澤並非一直都是大地上的一道傷口。在風險投資公司前來並在其上架起一座鑽油井之前，這裡曾有一池水晶般湛藍的清水。",
			full = "淤泥沼澤並非一直都是大地上的一道傷口。在風險投資公司前來並在其上架起一座鑽油井之前，這裡曾有一池水晶般湛藍的清水。如今殘存的只是一片工業廢料形成的泥沼，在一名向公司負責這項作業的哥布林主管的監督下運作。\n\n這座鑽油井在污染水源的同時，也引來了競爭對手。棘齒城的技工工會在瑞德沃克斯主管的施壓下，必須趕上風險投資公司更新型的伐木機，他們放棄了在建造上超越對方的嘗試，轉而決定直接竊取設計。哥布林斯布特瓦夫派維茲克蘭克從沼澤中奪取一台機器，並把它帶回棘齒城。維茲克蘭克好不容易爬進了伐木機，才發現自己根本沒有啟動它的鑰匙，只能受困在敵人的地盤上，直到救援到來，這台機器才得以在公司工人的眼皮底下被開走。",
			source = "https://warcraft.wiki.gg/wiki/Sludge_Fen",
		},
		["southern gold road"] = {
			name = "南黃金之路",
			short = "南黃金之路得名於行經其上的商隊。",
			full = "南黃金之路得名於行經其上的商隊。它從貧瘠之地南緣的升降梯一路向北，延伸到連接貧瘠之地南北兩半的橋梁，在那裡便成了單純的黃金之路。\n\n商人們從遠方沿著這條路而來：來自塔納利斯的加基森、黑海岸的奧伯丁，以及北方的永夜港。所有人都走在同一條路上，被賦予這條路名字的同一種貿易所吸引。",
			source = "https://warcraft.wiki.gg/wiki/Southern_Gold_Road",
		},
		["southfury river"] = {
			name = "怒水河",
			short = "怒水河發源於海加爾山的高處，從一座山中湖泊傾瀉而下，化為轟然墜入低地的瀑布。",
			full = "怒水河發源於海加爾山的高處，從一座山中湖泊傾瀉而下，化為轟然墜入低地的瀑布。從那裡開始，它寬闊而湍急地奔流，將大地一分為二：它標示著梣谷與艾薩拉的分界，再往南則是貧瘠之地的盡頭與杜洛塔的起點。在河口處，這條河越過最後一道瀑布注入無盡之海，就在哥布林港口棘齒城的東北方。\n\n河上架有三座橋梁，一座連接艾薩拉與梣谷，一座載著旅人進入奧格瑪，另一座則連接杜洛塔與貧瘠之地。就在最西邊那座橋的北方，有一段水域同時接觸著四片土地，那是梣谷、艾薩拉、杜洛塔與貧瘠之地唯一的交會之處。",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["stagnant oasis"] = {
			name = "死水綠洲",
			short = "死水綠洲是商旅海岸與黃金之路之間一片靜止不動的綠色水域。科卡爾半人馬沿著它的邊緣紮營，據說他們的存在與活力正是來自這片死水本身。",
			full = "死水綠洲是商旅海岸與黃金之路之間一片靜止不動的綠色水域。科卡爾半人馬沿著它的邊緣紮營，據說他們的存在與活力正是來自這片死水本身。在這裡遊蕩的科多獸虛弱而孤單，不像南方巨人曠野上的龐大獸群，因此也容易獵捕得多。變異魚在水面下游動，烹調後備受珍視，而綠洲鉗嘴龜則與牠們一同潛伏在混濁的水中。",
			source = "https://warcraft.wiki.gg/wiki/Stagnant_Oasis",
		},
		["thorn hill"] = {
			name = "荊棘嶺",
			short = "荊棘嶺位於十字路口與杜洛塔之間一座山頂的北坡，山坡上擠滿了鋼鬃部族的野豬人。",
			full = "荊棘嶺位於十字路口與杜洛塔之間一座山頂的北坡，山坡上擠滿了鋼鬃部族的野豬人。牠們從這處高地襲擊途經此地的部落商隊，引來了下方道路守衛們的怒火。",
			source = "https://warcraft.wiki.gg/wiki/Thorn_Hill",
		},
		["tidus stair"] = {
			name = "提度斯階梯",
			short = "提度斯階梯在商旅海岸上方拔起，由一層層寬闊的石台堆疊而成，宛如一座俯瞰海面的巨人階梯。",
			full = "提度斯階梯在商旅海岸上方拔起，由一層層寬闊的石台堆疊而成，宛如一座俯瞰海面的巨人階梯。兩位牛頭人──水之先知伊斯倫與瑪倫·星眼──守在這些岩架上，將釣線拋入浪花之中，並與棲居在下方水中的精靈交談。",
			source = "https://warcraft.wiki.gg/wiki/Tidus_Stair",
		},
		["wailing caverns"] = {
			name = "哀嚎洞穴",
			short = "哀嚎洞穴得名於這個地方本身的聲音：蒸汽從岩石的裂縫中迸發而出，化為悠長而哀戚的呼號，在黑暗中迴盪。",
			full = "哀嚎洞穴得名於這個地方本身的聲音：蒸汽從岩石的裂縫中迸發而出，化為悠長而哀戚的呼號，在黑暗中迴盪。\n\n發現這些洞穴、並賦予它們使命的，是夜精靈德魯伊納拉雷克斯。熱帶草原之下流淌著地下水道，它們在別處湧出地表，形成了貧瘠之地零星散布的綠洲；納拉雷克斯相信，只要將這些水域與翡翠夢境本身相連，就能將那股翠綠的生命力重新注入上方乾涸的大地。他帶領信徒們深入洞穴，進入冥想，讓自己成為夢境與現實世界之間的通道。\n\n然而翡翠夢魘反而攫住了他。納拉雷克斯無法醒來。夢魘的腐化透過他敞開而沉睡的身軀湧入洞穴，污染了水源，將野生動物扭曲成怪異的變異形態，並讓他的大多數信徒陷入瘋狂──留下來的人成了尖牙德魯伊。\n\n納拉雷克斯至今仍在那裡沉睡，而尖牙德魯伊佔據著洞穴，阻擋任何想要喚醒他的人。",
			source = "https://warcraft.wiki.gg/wiki/Wailing_Caverns",
		},
	},
	-- 奧特蘭克山脈: 5 subzones
	[1416] = {
		["dalaran"] = {
			name = "達拉然",
			short = "達拉然是一座法師之城，在食人妖戰爭之後由阿拉索帝國的巫師們所建立，並自成一國。",
			full = "達拉然是一座法師之城，在食人妖戰爭之後由阿拉索帝國的巫師們所建立，並自成一國。它的人民不效忠任何王冠，只聽命於祈倫托──這個由世上最強大的施法者組成的菁英團體，由六人議會治理。城市的中心矗立著紫羅蘭城堡，那是研習秘法者的聖所與避風港；除了精靈的國度奎爾薩拉斯之外，再也沒有任何城市擁有如此強大的魔法力量。就連奎爾薩拉斯那些自視甚高的高等精靈法師，也向祈倫托的主權低頭。\n\n那份主權在烈火中被粉碎。當天譴軍團進攻達拉然時，它的人民被逐出了自己的王國，阿克蒙德更親手將這座城市化為廢墟，讓祈倫托的倖存者流散到艾澤拉斯各地。\n\n倖存者不願讓他們的城市就此死去。他們回到廢墟，著手重建，並升起一座巨大的魔法穹頂，保護城市殘破的心臟不再受到傷害。",
			source = "https://warcraft.wiki.gg/wiki/Dalaran",
		},
		["dandreds fold"] = {
			name = "達倫德農場",
			short = "一座小農場與莊園坐落在高地的西緣，那裡的土地與霧氣湖岸相接，一座港口向洛丹米爾湖敞開。",
			full = "一座小農場與莊園坐落在高地的西緣，那裡的土地與霧氣湖岸相接，一座港口向洛丹米爾湖敞開。\n\n奧里登就住在這裡，和他一起的還有他的情婦艾麗薩。她戴著一條曾經屬於塔蕾莎·福克斯頓的項鍊。",
			source = "https://warcraft.wiki.gg/wiki/Dandred's_Fold",
		},
		["lordamere internment camp"] = {
			name = "洛丹米爾收容所",
			short = "洛丹米爾收容所坐落在達拉然坑上方的一座山丘上，是奧特蘭克山脈中唯一建立的收容所，由達拉然的部隊看守。",
			full = "洛丹米爾收容所坐落在達拉然坑上方的一座山丘上，是奧特蘭克山脈中唯一建立的收容所，由達拉然的部隊看守。\n\n阿薩斯·米奈希爾王子與珍娜·普勞德摩爾女士前往達拉然途中，曾趁著夜色溜過巡邏的衛兵與瞭望塔，去看看被關押在裡面的獸人。他們所看到的景象讓兩人產生了分歧。珍娜看著那些獸人婦女與她們的嬰孩，心中的篤定動搖了，轉為懷疑與悔恨。阿薩斯卻毫無感觸，堅持無論如何收容所都是必要的。沒有人發現他們。他們循原路離開，而兩人之間的分歧也隨之帶走了。\n\n如今由典獄官貝拉摩爾指揮駐軍，她正在研究凱根·達瑪與他的同伴們為她帶來的血石神器。",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Internment_Camp",
		},
		["ruins of alterac"] = {
			name = "奧特蘭克廢墟",
			short = "殘破的城牆攀附在奧特蘭克山脈的山坡上，那裡曾經矗立著一座城市：宮殿半毀，教堂與市政廳已經坍塌，城門則是仿照暴風城城門的樣式建造。",
			full = "殘破的城牆攀附在奧特蘭克山脈的山坡上，那裡曾經矗立著一座城市：宮殿半毀，教堂與市政廳已經坍塌，城門則是仿照暴風城城門的樣式建造。\n\n它的毀滅來自它自己的國王。第二次大戰期間，艾登·匹瑞諾德國王背叛了人類同胞，投靠獸人部落。有人發現奧特蘭克的士兵與獸人並肩作戰，而城市附近的一座俘虜營中關押著達拉然的市民。真相大白之後，其他人類王國向奧特蘭克進軍以示報復。人民逃離或被逐出家園，羅德隆國王泰瑞納斯·米奈希爾二世宣布這座城市進入戒嚴，將匹瑞諾德推下王座，並給他戴上了鐐銬。\n\n這座城市再也沒有復興。由穆格索爾率領的破碎嶺巨魔佔據了空蕩的街道與宮殿，而舊奧特蘭克人民散落的殘餘則守著城外的村落。損毀的運肉馬車至今仍橫陳在北側城牆與城門附近，城牆內外的墓地、被積雪掩埋的農場，以及瓦礫間破碎的弩砲，都保持著當年被遺棄時的模樣。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Alterac",
		},
		["uplands"] = {
			name = "高地",
			short = "高地曾經養活了一個王國。這片丘陵是奧特蘭克的糧倉，為這個古老的國家提供穀物與牧草。",
			full = "高地曾經養活了一個王國。這片丘陵是奧特蘭克的糧倉，為這個古老的國家提供穀物與牧草。\n\n那個國家分崩離析了。高地沒有落入任何王冠之手，而是落入了辛迪加手中，他們在山脈中沒有任何地方比這裡掌握得更牢固。瓦杜斯男爵在這裡的營地中發號施令，成了一個破碎王國殘存土地的領主。\n\n在最西端矗立著達倫德農場，這個名字比它曾經代表的任何意義都更加長久。",
			source = "https://warcraft.wiki.gg/wiki/Uplands",
		},
	},
	-- 阿拉希高地: 19 subzones
	[1417] = {
		["boulderfist hall"] = {
			name = "石拳大廳",
			short = "石拳大廳位於阿拉希高地南部，靠近薩多爾大橋與枯木村，是一座由巨魔之手加固的石丘。",
			full = "石拳大廳位於阿拉希高地南部，靠近薩多爾大橋與枯木村，是一座由巨魔之手加固的石丘。在它中心較大的洞穴裡，統治著石拳氏族的首領考格雷什·寒怒。\n\n此後巨魔們已向周圍的丘陵擴張，進一步強化了他們的防禦。",
			source = "https://warcraft.wiki.gg/wiki/Boulderfist_Hall",
