		["bouldergor"] = {
			name = "博多戈爾",
			short = "在激流堡北方，博多戈爾的山丘崎嶇破碎地聳立著。石拳巨魔在這裡佔據著他們的石丘，枯木森林食人妖也與他們一同在山坡上逗留。",
			full = "在激流堡北方，博多戈爾的山丘崎嶇破碎地聳立著。石拳巨魔在這裡佔據著他們的石丘，枯木森林食人妖也與他們一同在山坡上逗留。山丘的東側矗立著元素法陣，而山丘正南方則有兩座農場。",
			source = "https://warcraft.wiki.gg/wiki/Boulder'gor",
		},
		["circle of east binding"] = {
			name = "東部禁錮法陣",
			short = "東部禁錮之石守望著阿拉希高地的東部地區，靠近落錘鎮，標示著散布在這片地區的禁錮法陣之一。",
			full = "東部禁錮之石守望著阿拉希高地的東部地區，靠近落錘鎮，標示著散布在這片地區的禁錮法陣之一。水元素至今仍守護著這塊石頭，被束縛在此，彷彿仍在執行某項尚未完成的古老任務。",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_East_Binding",
		},
		["circle of inner binding"] = {
			name = "內禁錮法陣",
			short = "內禁錮法陣位於阿拉希高地南部的激流堡附近，由土元素守護。這裡安放著內禁錮之石，那是所有石頭中最強大的一塊。",
			full = "內禁錮法陣位於阿拉希高地南部的激流堡附近，由土元素守護。這裡安放著內禁錮之石，那是所有石頭中最強大的一塊。\n\n密斯賴爾正是透過它的碎片，找到了與凡人對話的方法。",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Inner_Binding",
		},
		["circle of outer binding"] = {
			name = "外禁錮法陣",
			short = "外禁錮法陣位於阿拉希高地的避難谷地附近。法陣的中心矗立著外禁錮之石，始終有氣元素在一旁守護。",
			full = "外禁錮法陣位於阿拉希高地的避難谷地附近。法陣的中心矗立著外禁錮之石，始終有氣元素在一旁守護。",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Outer_Binding",
		},
		["circle of west binding"] = {
			name = "西部禁錮法陣",
			short = "西部禁錮法陣位於阿拉希高地西部，靠近索拉丁之牆。西部禁錮之石就安放在那裡，由從不讓它無人看守的火元素守護著。",
			full = "西部禁錮法陣位於阿拉希高地西部，靠近索拉丁之牆。西部禁錮之石就安放在那裡，由從不讓它無人看守的火元素守護著。",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_West_Binding",
		},
		["dabyries farmstead"] = {
			name = "達比雷農場",
			short = "在阿拉希高地的北部坐落著達比雷農場，由肯納塔·達比雷和她的孩子法德爾與馬塞爾經營，他們是激流堡的公民，效忠於聯盟。",
			full = "在阿拉希高地的北部坐落著達比雷農場，由肯納塔·達比雷和她的孩子法德爾與馬塞爾經營，他們是激流堡的公民，效忠於聯盟。一支民兵守望著田地，因為這個家族樹敵不少。",
			source = "https://warcraft.wiki.gg/wiki/Dabyrie's_Farmstead",
		},
		["drowned reef"] = {
			name = "水下暗礁",
			short = "在阿拉希高地南岸外的海灣之下，沉睡著一座古老而殘破的精靈城市。它已不再空無一人：刺背納迦佔據了這裡，由納茲賈克王子統治。",
			full = "在阿拉希高地南岸外的海灣之下，沉睡著一座古老而殘破的精靈城市。它已不再空無一人：刺背納迦佔據了這裡，由納茲賈克王子統治。\n\n上方的暗礁已經吞沒了許多船隻，其中包括少女的愚行號與銀松之魂號。據說刺背納迦能夠扭轉海灣的潮水，將那些以為在法迪爾海灣找到了安全港灣的船員，引誘到礁石上。",
			source = "https://warcraft.wiki.gg/wiki/Drowned_Reef",
		},
		["drywhisker gorge"] = {
			name = "枯鬚峽谷",
			short = "枯鬚峽谷切穿阿拉希高地東部的山脈，位於落錘鎮的東北方。峽谷盡頭有一座洞穴，是枯鬚狗頭人的家園，他們與同樣居住在這片高地的巨人結盟。",
			full = "枯鬚峽谷切穿阿拉希高地東部的山脈，位於落錘鎮的東北方。峽谷盡頭有一座洞穴，是枯鬚狗頭人的家園，他們與同樣居住在這片高地的巨人結盟。\n\n在洞穴深處、穿過那些地道之後，安放著一塊石頭碎片，密斯賴爾公主的一部分精華就被困在其中。狗頭人們兇猛地守護著它，以及聚集在洞穴深處的微粒，儘管他們之中似乎沒有人知道這塊碎片裡真正藏著什麼。",
			source = "https://warcraft.wiki.gg/wiki/Drywhisker_Gorge",
		},
		["faldirs cove"] = {
			name = "法迪爾海灣",
			short = "法迪爾海灣得名於法迪爾，據說他和他的追隨者啟程時，便是在這個地點留下了標記。",
			full = "法迪爾海灣得名於法迪爾，據說他和他的追隨者啟程時，便是在這個地點留下了標記。\n\n很久之後，黑水劫掠者前來尋找據說沉在附近水域中的精靈寶藏。斯迪加特船長與奧布瑞恩船長率領三艘船駛入海灣，但一股奇異的潮水向他們湧來，那是守護著暗礁下方沉沒遺跡的納迦所掀起的，三艘船中有兩艘沉沒了。只有先驅者號抵達了岸邊，而她的船員發現自己被困在海灣中，直到納迦被擊退、沉船中的航海日誌被找回之前，都無法離開。\n\n後來，兩位地精工程師──德拉克里格博士與菲茲索普教授，打造了一台裝置，用來搜尋據說在水下暗礁的岩石中鈣化的精靈寶石。\n\n這座海灣至今仍留著那段被淹沒的歷史的傷痕：暗礁、沉船與廢墟，全都訴說著那些本不該沉沒的船隻，以及大海始終不肯交出的寶藏。",
			source = "https://warcraft.wiki.gg/wiki/Faldir's_Cove",
		},
		["goshek farm"] = {
			name = "格沙克農場",
			short = "格沙克農場位於阿拉希高地東部，靠近枯木村。",
			full = "格沙克農場位於阿拉希高地東部，靠近枯木村。第三次大戰之後，來自落錘鎮的被遺忘者與獸人為了各自的目的佔據了這座農場，獸人從這裡取得補給，被遺忘者則將它的田地與附屬建築變成了一處更為黑暗的鍊金術試驗場。\n\n聯盟的探員奎艾與基恩洛前來調查這裡發生的事。在他人的協助下，他們在一名前往塔倫米爾的被遺忘者信使送出訊息之前將他擊殺，並搜查了農莊本身，在那裡找到了一位喬瑞爾藥劑師的筆記。他的研究顯示，某種新的可怕事物正在成形：另一場正在醞釀中的瘟疫。\n\n如今落錘鎮的步兵佔據著這座農場。",
			source = "https://warcraft.wiki.gg/wiki/Go'Shek_Farm",
		},
		["hammerfall"] = {
			name = "落錘鎮",
			short = "落錘鎮的土地記得它曾經的模樣。第二次大戰後，羅德隆聯盟在這裡建立了他們最大的收容所之一，將俘虜的獸人關在圍牆之內。",
			full = "落錘鎮的土地記得它曾經的模樣。第二次大戰後，羅德隆聯盟在這裡建立了他們最大的收容所之一，將俘虜的獸人關在圍牆之內。它並沒有一直是座監獄。大酋長索爾與奧格林·末日錘率領部落進攻收容所，解救他們的族人；在那場解放的混亂中，當索爾掩護撤退時，一名衝鋒而來的騎士將長槍刺進奧格林的背部，力道之猛，竟將他的鎧甲前後貫穿。末日錘就死在那裡，死在他前來解放的土地上。\n\n第三次大戰之後，部落回到了這片廢墟，在其中建立了一座前進基地，並以在奪取此地時陣亡的大酋長之名，將它命名為落錘鎮。它不只是一座前哨──它也成了那些覺得世上已無容身之處的人的避難所，它的靈魂小屋、獸欄、鍛爐與大廳，就矗立在收容所昔日的圍牆所在之處。",
			source = "https://warcraft.wiki.gg/wiki/Hammerfall",
		},
		["northfold manor"] = {
			name = "諾斯弗德農場",
			short = "激流堡陷落之後，諾斯弗德農場落入了辛迪加手中，他們將它變成了阿拉希高地的一座前哨。",
			full = "激流堡陷落之後，諾斯弗德農場落入了辛迪加手中，他們將它變成了阿拉希高地的一座前哨。\n\n食人妖薩滿托爾甘被空氣中某種不對勁的氣息吸引而來。他循著它追查到這座莊園，發現惡魔召喚的殘餘痕跡仍緊附在這個地方，而當他靠近時，他自己的血液也開始沸騰，湧起一股並不完全屬於他的怒火。他在地上找到了一枚血石護身符，那是用來召喚惡魔的，只不過這一枚的力量已經耗盡。他懷疑辛迪加的勾當遠不只是打家劫舍，於是四處尋找其他類似的護身符，以查明他們的真正意圖。",
			source = "https://warcraft.wiki.gg/wiki/Northfold_Manor",
		},
		["refuge pointe"] = {
			name = "避難谷地",
			short = "第三次大戰期間，激流堡的首都化為廢墟，大多數人民向南逃進了阿拉希高地。但激流堡軍隊的殘部並不願隨他們而去。",
			full = "第三次大戰期間，激流堡的首都化為廢墟，大多數人民向南逃進了阿拉希高地。但激流堡軍隊的殘部並不願隨他們而去。他們留了下來，決心奪回失去的一切，而正是在這裡，在避難谷地，他們堅守了陣地。\n\n這座前哨成了聯盟在高地作戰的中樞，士兵們一心要奪回激流堡，並為聯盟的大業盡可能取得資源。這份專一的目標，讓他們幾乎無暇顧及其他事情。當薩多爾大橋遭到黑鐵矮人的猛烈攻擊，橋上的矮人派人前來請求援助，希望奪回丹莫德與大橋本身時，尼艾絲隊長一兵一卒都無法分出。她說，激流堡已經淪陷，在奪回它之前，避難谷地的每一把劍、每一雙手都只屬於這個目標。她告訴信使，榮譽與責任將他們束縛在這片高地上，布萊德·長鬚只能靠自己了。",
			source = "https://warcraft.wiki.gg/wiki/Refuge_Pointe",
		},
		["stromgarde keep"] = {
			name = "激流堡",
			short = "激流堡曾經是激流城，是第一個人類王國的搖籃，也是阿拉索帝國的首都。",
			full = "激流堡曾經是激流城，是第一個人類王國的搖籃，也是阿拉索帝國的首都。當獸人部落來到東部王國時，它仍是羅德隆聯盟中的一股強權，即使在第二次大戰之後，它的名號依然屹立不屈。\n\n第三次大戰之後，這座城市遭到洗劫，從此殘破不堪。如今它被一分為三：內城堡由辛迪加佔據，殘破的法師區被石拳巨魔在枯木食人妖的協助下攻佔，而最後一個區域仍由激流堡軍隊據守，加林·托爾貝恩王子就在那裡指揮著他僅存的子民。",
			source = "https://warcraft.wiki.gg/wiki/Stromgarde_Keep",
		},
		["thandol span"] = {
			name = "薩多爾大橋",
			short = "兩座巨大的石拱橫跨在濕地與阿拉希高地之間的裂谷上，由矮人之手建造，並由安威瑪家族守護了三代。",
			full = "兩座巨大的石拱橫跨在濕地與阿拉希高地之間的裂谷上，由矮人之手建造，並由安威瑪家族守護了三代。它們建於三錘之戰之後，當時鐵爐堡希望與鷹巢山的蠻錘同族保持友好，這些橋梁便成了兩個矮人王國之間的道路與象徵，承載著讓雙方都富裕起來的貿易。\n\n這些橋梁能夠承受整支軍隊的重量，也曾經是矮人與人類之間主要的貿易道路。正是在這裡，安度因·洛薩將舊部落的最後殘部逐出羅德隆，趕回卡茲莫丹，迫使他們戰敗後退過大橋。\n\n如今大橋傷痕累累。卡姆·深怒與卑鄙的巴加拉斯所策劃的黑鐵陰謀，讓橋梁受到了嚴重的損毀，矮人部隊正奮戰著守住剩下的部分，並奪回附近的丹莫德鎮。許多矮人在戰鬥中喪生，其中包括蘇利·巴魯、伊本瑟·拉斯洛克，以及布萊德·長鬚的兄弟。",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thoradins wall"] = {
			name = "索拉丁之牆",
			short = "索拉丁國王建造這道城牆來抵禦阿曼尼食人妖，那時激流城還很年輕，阿拉索才剛為人類奪得這片土地。",
			full = "索拉丁國王建造這道城牆來抵禦阿曼尼食人妖，那時激流城還很年輕，阿拉索才剛為人類奪得這片土地。世世代代以來，它始終是一名堅定的哨兵，一道用來保護人類免受食人妖侵襲的防線。\n\n數百年後，這道城牆依然屹立，卻已嚴重損毀，石塊破碎，它漫長的守望也淪為一片廢墟。",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["tower of arathor"] = {
			name = "阿拉索之塔",
			short = "阿拉索之塔矗立在激流堡的法師區，以這個王國血脈所承襲的古老阿拉索帝國為名。",
			full = "阿拉索之塔矗立在激流堡的法師區，以這個王國血脈所承襲的古老阿拉索帝國為名。\n\n大法師特雷萊恩曾在塔中鑽研學問，並在那裡打造了一套與高塔本身交織在一起的防禦機關，平時處於沉睡狀態，直到被一顆附魔寶石喚醒。當辛迪加與石拳巨魔向激流堡逼近時，特雷萊恩試圖以他的造物守住高塔，但這還不夠。他逃離了城市，高塔也隨之陷落。石拳巨魔將法師區據為己有，巨魔法師魯爾·獨石就住進了塔中的廳堂。\n\n特雷萊恩從未停止思念他留在那裡的東西──他的護命匣、他的寶珠，以及一塊他親手打磨的餘燼瑪瑙。他向昔日的學徒大法師馬林求助，希望能從如今佔據高塔的巨魔手中取回這些東西。後來消息傳回馬林那裡：老師父的遺物已經被找到了，就藏在他曾經視為己有的廳堂中的箱子裡。",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Arathor",
		},
		["witherbark village"] = {
			name = "枯木村",
			short = "枯木村環繞著阿拉希高地東南部的一座小湖而建，是枯木部族食人妖的家園。村子後方有一座大洞穴，部族的首領們大多待在那裡。",
			full = "枯木村環繞著阿拉希高地東南部的一座小湖而建，是枯木部族食人妖的家園。村子後方有一座大洞穴，部族的首領們大多待在那裡。\n\n枯木部族與附近的石拳巨魔結成了同盟，一同對抗激流堡與落錘鎮。食人妖與巨魔聯手佔據了激流堡的一個區域，那是從它昔日的主人手中奪來的。\n\n這份力量讓枯木部族成了眾矢之的，聯盟與部落都在追殺他們，希望將他們徹底剷除。在那些抵抗這場清算的人之中，殺戮者尼瑪爾被認為是最危險的一個，這名戰士在死去時帶走了許多敵人。",
			source = "https://warcraft.wiki.gg/wiki/Witherbark_Village",
		},
	},
	-- 荒蕪之地: 17 subzones
	[1418] = {
		["agmonds end"] = {
