			short = "荒蕪之地中南部的這處挖掘場，以死在那裡的矮人為名。",
			full = "荒蕪之地中南部的這處挖掘場，以死在那裡的矮人為名。埃格蒙德前來鑿石，卻發現早已佔據這片土地的穴居人；他們就地了結了他，這處挖掘場也從此被遺棄給了他們。",
			source = "https://warcraft.wiki.gg/wiki/Agmond's_End",
		},
		["angor fortress"] = {
			name = "苦痛堡壘",
			short = "黑鐵矮人將苦痛堡壘作為他們在荒蕪之地的據點，從這裡指揮通往奧達曼的挖掘工程。",
			full = "黑鐵矮人將苦痛堡壘作為他們在荒蕪之地的據點，從這裡指揮通往奧達曼的挖掘工程。",
