		["dustbowl"] = {
			name = "漫塵盆地",
			short = "漫塵盆地位於卡加斯與巨牙谷之間，是荒蕪之地西北部一片龜裂乾旱的土地。郊狼與禿鷹在其間遊蕩，岩石元素在石塊間蠢動。",
			full = "漫塵盆地位於卡加斯與巨牙谷之間，是荒蕪之地西北部一片龜裂乾旱的土地。郊狼與禿鷹在其間遊蕩，岩石元素在石塊間蠢動。這裡除了仙人掌和幾棵頑強的樹木之外，幾乎寸草不生。瓦格營地就坐落在這片荒原之中。",
