		["dustwind gulch"] = {
			name = "塵風峽谷",
			short = "狂風不斷刮擦著塵風峽谷，直到沒有任何柔軟之物能夠殘存，只剩下岩石與峽谷乾枯的骨架。它位於萊瑟羅峽谷以西，是荒蕪之地中一道貧瘠的裂谷，這裡的塵土從來不會平靜太久。",
			full = "狂風不斷刮擦著塵風峽谷，直到沒有任何柔軟之物能夠殘存，只剩下岩石與峽谷乾枯的骨架。它位於萊瑟羅峽谷以西，是荒蕪之地中一道貧瘠的裂谷，這裡的塵土從來不會平靜太久。",
			source = "https://warcraft.wiki.gg/wiki/Dustwind_Gulch",
