		["hammertoes digsite"] = {
			name = "鐵趾挖掘場",
			short = "鐵趾挖掘場位於荒蕪之地北部，昔日在此工作的礦工早已離去，挖掘溝渠如今一片寂靜。",
			full = "鐵趾挖掘場位於荒蕪之地北部，昔日在此工作的礦工早已離去，挖掘溝渠如今一片寂靜。鐵趾本人已經離開了這處遺址，一群黑鐵矮人取而代之進駐此地，很可能就是推進到奧達曼的同一支部隊。",
			source = "https://warcraft.wiki.gg/wiki/Hammertoe's_Digsite",
		},
		["kargath"] = {
			name = "卡加斯",
			short = "卡加斯孤立於卡茲莫丹，是部落在那片土地上唯一的前哨，以破碎之手氏族的酋長卡加斯·刃拳為名。",
			full = "卡加斯孤立於卡茲莫丹，是部落在那片土地上唯一的前哨，以破碎之手氏族的酋長卡加斯·刃拳為名。\n\n奉大酋長索爾的親自命令，卡加斯遠征軍一次又一次地深入嚴酷的荒蕪之地。它真正的目的是開闢一條穿越灼熱峽谷、通往黑石山的道路，好讓部落能在黑暗部落大酋長雷德·黑手自己的要塞中襲擊他。這條路穿越黑鐵矮人視為己有的土地，因此部落發現自己再度與他們開戰，這並非出於計畫，只是因為他們必須穿越這片土地。\n\n卡加斯的另一項價值則更加顯而易見：它是南北之間的樞紐，來自落錘鎮與幽暗城的道路，在這裡與南下通往格羅姆高、藏寶海灣和斯通納德的道路交會。",
			source = "https://warcraft.wiki.gg/wiki/Kargath",
		},
		["lethlor ravine"] = {
			name = "萊瑟羅峽谷",
			short = "萊瑟羅峽谷寬闊而崎嶇地切穿荒蕪之地東部，谷底有黑龍軍團的雛龍與幼龍出沒。",
			full = "萊瑟羅峽谷寬闊而崎嶇地切穿荒蕪之地東部，谷底有黑龍軍團的雛龍與幼龍出沒。峽谷中散立著一座座水晶方尖碑，在岩石與龍焰之間顯得奇異，卻又彷彿是刻意為之。",
			source = "https://warcraft.wiki.gg/wiki/Lethlor_Ravine",
		},
		["makers terrace"] = {
			name = "造物者遺跡",
			short = "在奧達曼的入口外，大地被一道道寬闊而刻意的切口剝開，留下一道向天空敞開的挖掘傷疤。",
			full = "在奧達曼的入口外，大地被一道道寬闊而刻意的切口剝開，留下一道向天空敞開的挖掘傷疤。如今黑鐵矮人佔據著這處遺跡，監視著挖掘場以及那條通往地底被掩埋之地的道路。",
			source = "https://warcraft.wiki.gg/wiki/Maker's_Terrace",
		},
		["mirage flats"] = {
			name = "霧氣平原",
			short = "霧氣平原位於荒蕪之地火山洞穴的東方。這裡所剩無幾，只是一片無人之地，只有巨型禿鷹、山脊潛獵者族長與狂暴的峭壁土狼盤據其間。",
			full = "霧氣平原位於荒蕪之地火山洞穴的東方。這裡所剩無幾，只是一片無人之地，只有巨型禿鷹、山脊潛獵者族長與狂暴的峭壁土狼盤據其間。",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Flats",
		},
		["uldaman"] = {
			name = "奧達曼",
			short = "在卡茲莫丹的群山深處，沉睡著奧達曼，那是遠古時代由泰坦守護者建造的一座巨大而古老的寶庫。",
			full = "在卡茲莫丹的群山深處，沉睡著奧達曼，那是遠古時代由泰坦守護者建造的一座巨大而古老的寶庫。第三次大戰之前，來自鐵爐堡的矮人曾經深入其中，開鑿它被掩埋的石室，但此後寶庫已落入穴居人與黑鐵矮人之手，他們如今在它的岩石中挖掘，搜尋它仍然藏有的任何塵世財富。\n\n奧達曼仍然充滿了那個泰坦鍛造時代的遺物，願意冒險深入的人依然能在其中找到被掩埋的古物，而探險者協會的考古學家與冒險者們，也仍在廢墟中持續搜尋，一點一點地將它們發掘出來。",
			source = "https://warcraft.wiki.gg/wiki/Uldaman",
		},
		["valley of fangs"] = {
			name = "巨牙谷",
			short = "巨牙谷在荒蕪之地的兩道岩壁之間狹窄地延伸，由狼群與美洲獅佔據，這個地方也以牠們的利齒為名。",
			full = "巨牙谷在荒蕪之地的兩道岩壁之間狹窄地延伸，由狼群與美洲獅佔據，這個地方也以牠們的利齒為名。\n\n流放者馬特克在谷中紮營，他被逐出了自己曾經歸屬的地方，與他為伴的還有里格弗茲與賈茲里克。",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Fangs",
		},
	},
	-- 詛咒之地: 7 subzones
	[1419] = {
		["dark portal"] = {
			name = "黑暗之門",
			short = "這座傳送門的建造從第一筆開始就是一場背叛。古爾丹與人類法師麥迪文──後者當時被黑暗泰坦薩格拉斯附身──聯手撕開了這道裂縫。",
			full = "這座傳送門的建造從第一筆開始就是一場背叛。古爾丹與人類法師麥迪文──後者當時被黑暗泰坦薩格拉斯附身──聯手撕開了這道裂縫。在德拉諾，建造其石框的獸人石匠被術士殺害，以啟動最後的封印；而部落手中幾乎所有仍被關押的德萊尼俘虜，都被帶到門的基座前，在一瞬間被吸乾生命，讓古爾丹得到連接兩個世界的力量。部落經由那道門戶湧入暴風城，揭開了第一次大戰的序幕，而在隨後的戰爭中，它源源不絕地將獸人與巨魔送進艾澤拉斯，周圍的沼澤也凝結成血紅色的荒地，後來被稱為詛咒之地。\n\n戰爭結束時，大法師卡德加與他的法師同伴們擊碎了艾澤拉斯這一側的結構，以阻斷部落的退路，爆炸之猛烈，連德拉諾那一側的門框也一併摧毀。卡德加隨後建立了守望堡來監視這片廢墟，然而兩個世界之間的裂口從未真正被封閉，惡魔在之後的歲月裡仍會再度從中穿越而來。",
			source = "https://warcraft.wiki.gg/wiki/Dark_Portal",
		},
		["dreadmaul post"] = {
			name = "巨槌崗哨",
			short = "巨槌崗哨是巨槌巨魔氏族堆起的一座土丘，他們從德拉諾進入艾澤拉斯，從未遠離過黑暗之門。",
			full = "巨槌崗哨是巨槌巨魔氏族堆起的一座土丘，他們從德拉諾進入艾澤拉斯，從未遠離過黑暗之門。他們至今仍佔據著這片土地。",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Post",
		},
		["garrison armory"] = {
			name = "要塞軍械庫",
			short = "在詛咒之地飽經摧殘的土地上，聯盟的礦工在要塞軍械庫工作，從大地中開採礦物供應守望堡。",
			full = "在詛咒之地飽經摧殘的土地上，聯盟的礦工在要塞軍械庫工作，從大地中開採礦物供應守望堡。他們採集的礦物被運往暴風城，而作為交換，要塞則得到在這片荒蕪之地生存所需的其他補給。",
			source = "https://warcraft.wiki.gg/wiki/Garrison_Armory",
		},
		["nethergarde keep"] = {
			name = "守望堡",
			short = "守望堡矗立在通往詛咒之地的唯一道路上方的一處高崖上，它的城牆是為了監視世界上一道沒有人希望再次開啟的傷疤而建。",
			full = "守望堡矗立在通往詛咒之地的唯一道路上方的一處高崖上，它的城牆是為了監視世界上一道沒有人希望再次開啟的傷疤而建。\n\n第二次大戰之後的那些年，當第一座黑暗之門已經破碎、門後的獸人家園也已凋零成廢墟時，大法師卡德加呼籲建造它。羅德隆聯盟出資興建，有些王國比其他王國更加樂意，而石匠公會則在艾德溫·范克里夫的主持下建起了它。此後由祈倫托駐守，努力阻擋從傳送門的傷口中蔓延而出、威脅要擴散到周圍土地的污染。\n\n卡德加一直是它的主人，直到耐祖奧的氏族從德拉諾那一側重新鑄造了黑暗之門，並圍攻這座要塞。卡德加與他的同伴──圖拉揚、達納斯·托爾貝恩、艾蘭里亞·風行者與庫德蘭·蠻錘，率領聯盟穿過傳送門，在那裡擊潰了部落，隨後留在另一側封閉了它，好讓德拉諾的毀滅不會跟隨他們回到家鄉。此後二十年，傳送門一直沉寂無聲。",
			source = "https://warcraft.wiki.gg/wiki/Nethergarde_Keep",
		},
		["rise of the defiler"] = {
			name = "污染者高地",
			short = "污染者高地從詛咒之地的中央拔地而起，是一片崎嶇破碎的山地。偉大的惡魔拉瑟利克就居住在這裡，光是牠的存在，就足以為這個地方命名。",
			full = "污染者高地從詛咒之地的中央拔地而起，是一片崎嶇破碎的山地。偉大的惡魔拉瑟利克就居住在這裡，光是牠的存在，就足以為這個地方命名。",
			source = "https://warcraft.wiki.gg/wiki/Rise_of_the_Defiler",
		},
		["serpents coil"] = {
			name = "盤蛇谷",
			short = "盤蛇谷是詛咒之地東部一處蜿蜒的洞穴系統，洞口有第二次大戰遺留下來、早已燒毀的獸人建築作為標記。",
			full = "盤蛇谷是詛咒之地東部一處蜿蜒的洞穴系統，洞口有第二次大戰遺留下來、早已燒毀的獸人建築作為標記。在那場戰爭結束很久之後，這些洞穴成了某種更黑暗之物的藏身之處：一群一心崇拜被詛咒者基利斯的教徒。\n\n大法師艾利斯塔傑來到這座迷宮，讓他的魔誓者從內部展開行動。入口附近的一個箱子裡，放著一枚刻有他名字的護身符。",
			source = "https://warcraft.wiki.gg/wiki/Serpent's_Coil",
		},
		["tainted scar"] = {
			name = "腐爛之痕",
			short = "腐爛之痕曾是黑色沼澤的一部分，直到黑暗之門的腐化滲入其中，讓土地變得乾涸、寸木不生，紅得如同鮮血。",
			full = "腐爛之痕曾是黑色沼澤的一部分，直到黑暗之門的腐化滲入其中，讓土地變得乾涸、寸木不生，紅得如同鮮血。如今那裡已沒有水流。惡魔野獸在這片早已不記得曾經長過什麼的土壤上徘徊。\n\n海加爾山之役後，末日守衛領主卡扎克將燃燒軍團在艾澤拉斯殘存的兵力撤入腐爛之痕，將其作為自己的地盤。他任命副官污染者拉瑟利克統治此地，命令這位污染者確保這片土地的安全。卡扎克本人此後一直留在那裡，光是他的存在，就足以讓腐爛之痕在海加爾山之戰於別處打完並獲勝多年之後，仍被標記為燃燒軍團的領土。\n\n很久之後，一名年邁的人類術士──衰老的戴奧來到了腐爛之痕，在它的祭壇旁安身。在那裡，在這片土地早已孕育出的惡魔之間，他不受打擾地舉行他的儀式，並招收年輕的新人，在一個早已被邪能佔據的地方教導他們地獄的技藝。",
			source = "https://warcraft.wiki.gg/wiki/Tainted_Scar",
		},
	},
	-- 提里斯法林地: 28 subzones
	[1420] = {
		["agamand family crypt"] = {
			name = "阿加曼德家族墓穴",
			short = "在阿加曼德磨坊的北方，阿加曼德家族的亡者曾安息在這座墓穴之中。天譴軍團的爪牙達格爾隊長將這裡據為己有，喚醒了其中的每一具屍體與每一個靈魂。",
			full = "在阿加曼德磨坊的北方，阿加曼德家族的亡者曾安息在這座墓穴之中。天譴軍團的爪牙達格爾隊長將這裡據為己有，喚醒了其中的每一具屍體與每一個靈魂。如今陰暗的通道中瀰漫著濃厚的塵埃，心懷怨恨的亡者會攻擊任何未經邀請而闖入的人。",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Family_Crypt",
		},
		["agamand mills"] = {
			name = "阿加曼德磨坊",
			short = "阿加曼德的風車曾經為提里斯法最富有的家族之一而轉動。當天譴軍團北上時，格里高·阿加曼德拒絕逃離。",
			full = "阿加曼德的風車曾經為提里斯法最富有的家族之一而轉動。當天譴軍團北上時，格里高·阿加曼德拒絕逃離。他加固了磨坊，囤積物資以抵禦圍城，並說服家族自己的工人留下來，與他們並肩作戰。\n\n它本該守得住。之所以沒能守住，是因為背叛來自牆內。阿加曼德家最小的兒子德夫林背叛了自己的血親，協助天譴軍團，守軍無法在隨後的攻擊中守住防線。後來瘟疫終究還是奪走了家族其餘的人，那些為保衛家園而死的阿加曼德家人，在自己的家中再度起身，成了沒有心智的亡者。\n\n風車至今仍矗立在提里斯法北部的高地上，而建造它們的家族，如今卻效命於摧毀他們的那支大軍。",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Mills",
		},
		["balnir farmstead"] = {
			name = "巴尼爾農場",
			short = "巴尼爾農場位於殘破首都的東北方，圍籬破敗，馬廄空蕩，只有遊蕩的天譴軍團在其間出沒。",
			full = "巴尼爾農場位於殘破首都的東北方，圍籬破敗，馬廄空蕩，只有遊蕩的天譴軍團在其間出沒。\n\n巴尼爾家族曾經經營這片土地，培育羅德隆王室作為坐騎的高大白馬。首都陷落的那一天，天譴軍團來到農場，殺害了整個家族，只留下他們鬧鬼的土地。\n\n農場花園裡曾經被悉心照料的金魚草至今仍在那裡野生蔓長，而生者們也聽說，瘟疫之地的腐化可能已經悄悄侵入其中。溜過亡靈壁壘的天譴軍團成群聚集在這座殘破的農場周圍。",
			source = "https://warcraft.wiki.gg/wiki/Balnir_Farmstead",
		},
		["brightwater lake"] = {
			name = "澈水湖",
			short = "澈水湖位於布瑞爾的東北方，湖水中央有一座大島，岡瑟爾的居所如今就矗立在島上。",
			full = "澈水湖位於布瑞爾的東北方，湖水中央有一座大島，岡瑟爾的居所如今就矗立在島上。",
			source = "https://warcraft.wiki.gg/wiki/Brightwater_Lake",
		},
		["brill"] = {
			name = "布瑞爾",
			short = "布瑞爾曾經是羅德隆王國一座普通的城鎮，由巴羅夫家族掌管，阿加曼德家族也在鎮內擁有一座自己的莊園。",
			full = "布瑞爾曾經是羅德隆王國一座普通的城鎮，由巴羅夫家族掌管，阿加曼德家族也在鎮內擁有一座自己的莊園。科爾蘇加德來到這裡的那一天，它的平凡便宣告終結。當時仍是活人的這名死靈法師，選擇布瑞爾作為最初試驗亡靈瘟疫的地方，而那場感染如此徹底地成功，讓他大受鼓舞，進而催促巫妖王提早發動對羅德隆的入侵。提里斯法林地的死者多到這片土地無法妥善安葬；布瑞爾城牆外那座巨大的墓地，便是對這些過多死者的回應。鎮上的守衛無法守住城鎮，殘存的倖存者逃離此地，加入了正在追查席捲北方的腐化源頭的阿薩斯·米奈希爾王子。\n\n布瑞爾並未一直沉寂下去。多年後，被遺忘者佔領了這裡，如今由執政官塞弗倫治理這片曾被瘟疫奪走的土地。舊日的仇怨也仍在此縈繞：曾經為阿加曼德家族效力的庫勒曼·法席恩，至今仍在尋找他們的遺骸，他要這些骨頭並非出於憐憫，而是為了一樁他歸咎於他們的死亡而報仇。",
			source = "https://warcraft.wiki.gg/wiki/Brill",
		},
		["brill town hall"] = {
			name = "布瑞爾城鎮大廳",
			short = "城鎮大廳是布瑞爾最顯眼的建築。執政官塞弗倫在它的講台上代表這座城鎮發言，為提里斯法的亡者分派任務。",
			full = "城鎮大廳是布瑞爾最顯眼的建築。執政官塞弗倫在它的講台上代表這座城鎮發言，為提里斯法的亡者分派任務。在任何地方，都很少有這樣的大廳像這座一樣掌握在被遺忘者手中，這也顯示出布瑞爾是多麼牢固地屬於他們。",
			source = "https://warcraft.wiki.gg/wiki/Brill_Town_Hall",
		},
		["bulwark"] = {
			name = "亡靈壁壘",
			short = "亡靈壁壘矗立在提里斯法林地與西瘟疫之地的交界處，是被遺忘者用來抵禦仍在東方集結的天譴軍團的防線。",
			full = "亡靈壁壘矗立在提里斯法林地與西瘟疫之地的交界處，是被遺忘者用來抵禦仍在東方集結的天譴軍團的防線。在這裡，被遺忘者的守衛與銀色黎明面對共同的敵人，擱置了彼此的分歧，一同守望邊界，並派遣戰士向東出擊，打擊巫妖王的爪牙。\n\n與提里斯法其他地方不同，這一帶看起來完全不像林地：一片瘟疫之霧籠罩其上，將天空染成與遠方西瘟疫之地相同的病態黃灰色。",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["cold hearth manor"] = {
			name = "爐灰莊園",
			short = "爐灰莊園當年以爐火的溫暖與田地的豐饒得名，亡靈瘟疫卻終結了這一切。",
			full = "爐灰莊園當年以爐火的溫暖與田地的豐饒得名，亡靈瘟疫卻終結了這一切。住在這裡、在這裡幹活的人全都死於那場疫病，豐沃的土地化為不毛，田壟間擠滿了天譴軍團無知無覺的亡者，至今仍在那裡蹣跚遊蕩。\n\n被遺忘者將這座農舍據為己有，與附近路上往來的旅人打交道。",
			source = "https://warcraft.wiki.gg/wiki/Cold_Hearth_Manor",
		},
		["crusader outpost"] = {
			name = "十字軍前哨",
			short = "提里斯法林地東部的山丘上矗立著一座瞭望塔，由血色十字軍把守。",
			full = "提里斯法林地東部的山丘上矗立著一座瞭望塔，由血色十字軍把守。他們從高處監視著穿過林地向南延伸的道路，隨時準備從側翼襲擊任何膽敢進軍遠方血色修道院的部隊。指揮這裡的是瓦松隊長。",
			source = "https://warcraft.wiki.gg/wiki/Crusader_Outpost",
		},
		["deathknell"] = {
			name = "喪鐘鎮",
			short = "喪鐘鎮坐落在一道狹窄且戒備森嚴的山谷中，剛剛甦醒的被遺忘者便是在這裡，第一次睜眼看見這個他們被賦予的世界。",
			full = "喪鐘鎮坐落在一道狹窄且戒備森嚴的山谷中，剛剛甦醒的被遺忘者便是在這裡，第一次睜眼看見這個他們被賦予的世界。\n\n女妖之王麾下的叛亂亡靈所占據的其他據點，都沿用了它們還是活人城鎮時的舊名，唯獨喪鐘鎮被取了一個全新的名字，名字所指的是這裡正在發生的事，而非這裡曾經有過什麼。如今已無人記得緣由。\n\n在這裡，生存是每日的掙扎，而金錢是最稀缺的東西。村子西北方有一座富含金屬的礦坑，卻已被蜘蛛占據，喪鐘鎮的亡者一次又一次出發，試圖將它清理乾淨，好讓地底的礦石終能開採。精英亡靈衛兵沿著山谷邊緣站崗，他們是脆弱的新亡者與天譴軍團、血色十字軍之間唯一的屏障，否則這些亡者將被再殺死一次。",
			source = "https://warcraft.wiki.gg/wiki/Deathknell",
		},
		["faols rest"] = {
			name = "法奧之墓",
			short = "在提里斯法林地東部、血色修道院的西南方，有一塊曾有弔唁者照料的土地，那就是法奧之墓，大主教阿隆索斯·法奧的長眠之處。",
			full = "在提里斯法林地東部、血色修道院的西南方，有一塊曾有弔唁者照料的土地，那就是法奧之墓，大主教阿隆索斯·法奧的長眠之處。\n\n法奧生前備受尊崇。他在天譴軍團到來之前不久辭世，引得弔唁者紛紛來到此地。\n\n如今他留下的墳墓已無人造訪。昔日前來的弔唁者都已不在，這塊墓地無人打理，幾乎被人遺忘。",
			source = "https://warcraft.wiki.gg/wiki/Faol's_Rest",
		},
		["gallows end tavern"] = {
			name = "恐懼之末旅店",
			short = "恐懼之末旅店位於布瑞爾，它的名字陰森地呼應著它所服務的這座小鎮。",
			full = "恐懼之末旅店位於布瑞爾，它的名字陰森地呼應著它所服務的這座小鎮。旅店地板下的地窖裡並沒有什麼值得一提的酒桶，關著的是一名被俘的血色狂熱者和一名矮人巡山人，他們都是被遺忘者的囚犯。",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_End_Tavern",
		},
		["garrens haunt"] = {
			name = "加倫鬼屋",
			short = "加倫鬼屋曾是提里斯法林地北部一座富饒的農莊，田地遼闊，穀倉滿盈，亡靈瘟疫卻終結了這一切。",
			full = "加倫鬼屋曾是提里斯法林地北部一座富饒的農莊，田地遼闊，穀倉滿盈，亡靈瘟疫卻終結了這一切。天譴軍團席捲羅德隆時，加倫和他的家人在自己的家中慘遭屠戮，殘破的屋舍四周，連土地本身都變得灰敗而毫無生機。\n\n留存下來的建築被蛆眼率領的腐皮豺狼人占據，牠們把農舍和穀倉據為己有，對任何靠得太近的人都毫不猶豫地發動攻擊。\n\n這座農莊再也沒能恢復。它被遺棄在那裡，田地荒蕪，一家人不復存在，只剩下豺狼人宣示著如今誰才是這裡的主人。",
			source = "https://warcraft.wiki.gg/wiki/Garren's_Haunt",
		},
		["gunthers retreat"] = {
			name = "岡瑟爾的居所",
			short = "澈水湖中的一座小島上矗立著岡瑟爾的居所，被遺忘者巫妖岡瑟爾·阿坎努斯和他的殭屍僕從占據了這裡。",
			full = "澈水湖中的一座小島上矗立著岡瑟爾的居所，被遺忘者巫妖岡瑟爾·阿坎努斯和他的殭屍僕從占據了這裡。在它西南岸外，一座光禿禿的無名小島上，擺著一個奇特的標記，人們只知道它叫做莉莉絲的餐桌。",
			source = "https://warcraft.wiki.gg/wiki/Gunther's_Retreat",
		},
		["night webs hollow"] = {
			name = "夜行蜘蛛洞穴",
			short = "夜行蜘蛛洞穴是一道小山谷，一座古老的金礦貫穿其間，兩者都已被蜘蛛占據。幼蛛在開闊的谷地裡遊蕩，成年的夜行蜘蛛則盤踞在礦坑更幽暗的坑道中。",
			full = "夜行蜘蛛洞穴是一道小山谷，一座古老的金礦貫穿其間，兩者都已被蜘蛛占據。幼蛛在開闊的谷地裡遊蕩，成年的夜行蜘蛛則盤踞在礦坑更幽暗的坑道中。\n\n剛甦醒的被遺忘者會來到這裡，試試自己的身軀還能做些什麼。他們先砍殺外頭的幼蛛，然後才敢深入礦坑。\n\n在礦坑最深處，盤踞著夜行蛛母，也就是上方那群蜘蛛的母親。",
			source = "https://warcraft.wiki.gg/wiki/Night_Web's_Hollow",
		},
		["nightmare vale"] = {
			name = "噩夢谷",
			short = "在提里斯法林地血色十字軍瞭望塔的西邊，有一道已然荒廢的山谷。這裡的樹木早已枯萎，曾經棲息林間的野生動物也被黑暗犬和巨大的吸血蝙蝠吃得一乾二淨。",
			full = "在提里斯法林地血色十字軍瞭望塔的西邊，有一道已然荒廢的山谷。這裡的樹木早已枯萎，曾經棲息林間的野生動物也被黑暗犬和巨大的吸血蝙蝠吃得一乾二淨。在這些獵食者之中，飛翔著一隻與眾不同的罕見白色蝙蝠，名叫「刺骨者」雷桑。",
			source = "https://warcraft.wiki.gg/wiki/Nightmare_Vale",
		},
		["north coast"] = {
			name = "北部海岸",
			short = "北部海岸綿延在提里斯法林地與無盡之海交會之處，如今已成為魚人和水中生物的天下。",
			full = "北部海岸綿延在提里斯法林地與無盡之海交會之處，如今已成為魚人和水中生物的天下。自從亡靈瘟疫爆發以來，這片海岸便變得陰暗而冰冷，潮水在水邊留下死去的海洋生物，任其腐爛。",
			source = "https://warcraft.wiki.gg/wiki/North_Coast",
		},
		["ruins of lordaeron"] = {
			name = "羅德隆廢墟",
			short = "在被掩埋的城市上方，羅德隆的王宮依然矗立，殿堂向天空敞開，花園早已荒蕪。聯盟的偉大王國在這裡覆滅，而它的亡魂也從未真正離去。",
			full = "在被掩埋的城市上方，羅德隆的王宮依然矗立，殿堂向天空敞開，花園早已荒蕪。聯盟的偉大王國在這裡覆滅，而它的亡魂也從未真正離去。\n\n終結這一切的是阿薩斯·米奈希爾。這位王子率領一支為屠戮自己子民而組建的大軍回到故鄉，在任何人明白他已變成了什麼之前，人們敲響鐘聲、歡呼著迎他走進這座城門。他在王座廳裡找到了等候著他的父親泰瑞納斯國王，並在那裡將他殺死。他站在父王的屍身前說出的話語，至今仍在那間廳堂裡迴盪，傳入每一個駐足之人的耳中：這個王國終將覆滅，而從它的灰燼中，將崛起一個撼動世界的新秩序。這絕非空洞的誇口。短短數日之內，這座城市和它的子民便慘遭屠戮，羅德隆落入了天譴軍團之手。\n\n據說，至今走過庭院的人，仍能聽見石頭所記得的聲音：低聲的交談、迎賓的鐘聲，以及王座廳裡一陣始終不曾消散的呢喃。那些能看見帷幕另一端的人說，羅德隆的子民仍在那裡行走，渾然不知他們的王國已經不復存在。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
		["scarlet monastery"] = {
			name = "血色修道院",
			short = "在十字軍的掌控下，舊修道院成了兵營和監獄。審判官懷特邁恩和雷諾·莫格萊尼以此為據點，禮拜堂也從祈禱之地變成了審判之所。",
			full = "在十字軍的掌控下，舊修道院成了兵營和監獄。審判官懷特邁恩和雷諾·莫格萊尼以此為據點，禮拜堂也從祈禱之地變成了審判之所。\n\n在成為要塞之前，舊修道院是聖光教會的一座大教堂，裡頭滿是聖騎士們受訓的圖書館。亞歷山德羅斯·莫格萊尼本人年輕時也曾在此度過數月，在他拿起劍之前祈禱、研讀。",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Monastery",
		},
		["scarlet watch post"] = {
			name = "血色十字軍崗哨",
			short = "血色十字軍崗哨守衛著血色修道院無法獨力防守的一條通路。",
			full = "血色十字軍崗哨守衛著血色修道院無法獨力防守的一條通路。指揮這裡的是麥拉其隊長，他堅守崗哨，提防任何人趁著無人察覺，攻擊修道院暴露在外的側翼。",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Watch_Post",
		},
		["shadow grave"] = {
			name = "灰影墓穴",
			short = "灰影墓穴位於喪鐘鎮墓地的山坡頂端，高踞於提里斯法的群山之間。一條踩得光禿的小徑從墓穴入口蜿蜒而下，通往山下的喪鐘鎮。",
			full = "灰影墓穴位於喪鐘鎮墓地的山坡頂端，高踞於提里斯法的群山之間。一條踩得光禿的小徑從墓穴入口蜿蜒而下，通往山下的喪鐘鎮。",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Grave",
		},
		["solliden farmstead"] = {
			name = "索利丹農場",
			short = "索利丹的南瓜田，是提里斯法少數幾塊舊日生活尚未被瘟疫或亡靈吞噬的土地之一。",
			full = "索利丹的南瓜田，是提里斯法少數幾塊舊日生活尚未被瘟疫或亡靈吞噬的土地之一。周遭的鄉野先是淪陷於天譴軍團，後來又落入從中崛起的被遺忘者之手，這裡的農夫卻依然耕作著自己的田壟，受到附近血色柵欄的血色十字軍庇護。\n\n這份庇護讓索利丹成了一個異數。農夫們不信任任何不屬於血色十字軍的人。他們將被遺忘者拒於門外，視之為險些奪走他們性命的那場瘟疫所生的怪物；對聯盟也同樣戒備，唯恐聯盟的旗幟會把他們拖入一場戰爭，而他們至今之所以能夠置身事外，正是因為自己微不足道、無人記得。\n\n被遺忘者偏偏無法對這份平靜置之不理。亡靈衛兵希米爾監視著索利丹，並非為了它此刻的模樣，而是為了它可能變成的樣子：今天是安分的農夫，明天就可能成為聯盟的武裝佃戶，在被遺忘者決意守住的土地上建立據點。",
			source = "https://warcraft.wiki.gg/wiki/Solliden_Farmstead",
		},
		["stillwater pond"] = {
			name = "靜水池",
			short = "在瘟疫來臨之前，靜水池是活人揮灑青春的地方。",
			full = "在瘟疫來臨之前，靜水池是活人揮灑青春的地方。林地裡的人家會到岸邊野餐，年紀太小、還不敢去澈水湖深水處的孩子們，就在這裡學會了游泳。\n\n如今那池水已是一片灰濛。水面下的魚只剩下骨頭仍在游動，彷彿從來沒有人告訴牠們該停下來。遊蕩的亡靈和野獸沿著岸邊經過，黑暗犬貝恩在水邊來回逡巡，吞食任何不夠警覺而逗留的東西。\n\n到了被遺忘者開始從廢墟中重建布瑞爾的時候，血色十字軍的戰士已經開始在靜水池岸邊巡邏。",
			source = "https://warcraft.wiki.gg/wiki/Stillwater_Pond",
		},
		["terrace of repose"] = {
			name = "休息區",
			short = "就在血色修道院的北邊，有一片從未被瘟疫觸及的土地。這裡生長著青翠的樹籬，噴泉流淌著清澈的泉水，而非一灘死水，與提里斯法林地的其他地方截然不同。",
			full = "就在血色修道院的北邊，有一片從未被瘟疫觸及的土地。這裡生長著青翠的樹籬，噴泉流淌著清澈的泉水，而非一灘死水，與提里斯法林地的其他地方截然不同。血色十字軍照料著這裡，讓這座小小的露臺生機常在，以此證明在一片荒蕪之中，潔淨之物仍能長存。",
			source = "https://warcraft.wiki.gg/wiki/Terrace_of_Repose",
		},
		["venomweb vale"] = {
			name = "毒蛛峽谷",
			short = "毒蛛峽谷曾經一片青翠，鹿群與野兔成群，後來卻變成了如今的模樣：一道被毒蜘蛛占據的山谷，由罕見而致命的斯里斯庫克統領，牠們的蛛網取代了青草，也讓這座山谷因此得名。",
			full = "毒蛛峽谷曾經一片青翠，鹿群與野兔成群，後來卻變成了如今的模樣：一道被毒蜘蛛占據的山谷，由罕見而致命的斯里斯庫克統領，牠們的蛛網取代了青草，也讓這座山谷因此得名。黑暗犬在北邊血色十字軍營地附近遊蕩，那座營地由桑德斯中尉把守。",
			source = "https://warcraft.wiki.gg/wiki/Venomweb_Vale",
		},
		["whispering gardens"] = {
			name = "耳語花園",
			short = "在血色修道院南方的山丘上，那些後來成為血色十字軍的人們，曾在此與天譴軍團的大軍展開一場激戰。",
			full = "在血色修道院南方的山丘上，那些後來成為血色十字軍的人們，曾在此與天譴軍團的大軍展開一場激戰。雙方都有許多人倒下。暮色之中，他們的魂魄依然徘徊不去，在花園寂靜的石頭之間化作隱約的低語。",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Gardens",
		},
		["whispering shore"] = {
			name = "耳語海岸",
			short = "耳語海岸位於提里斯法林地西部，在索利丹農場以北。漁夫們曾經偏愛這裡平靜的水面和穩定的漁獲。",
			full = "耳語海岸位於提里斯法林地西部，在索利丹農場以北。漁夫們曾經偏愛這裡平靜的水面和穩定的漁獲。\n\n那份富饒已不復存在。魚人占據了海岸，撲向任何靠近的人，海水也變得冰冷而陰暗。",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Shore",
		},
	},
	-- 銀松森林: 22 subzones
	[1421] = {
		["ambermill"] = {
			name = "安伯米爾",
			short = "安伯米爾曾是一座無足輕重的磨坊小鎮，在銀松森林的洛丹米爾湖西南方伐木為生。",
			full = "安伯米爾曾是一座無足輕重的磨坊小鎮，在銀松森林的洛丹米爾湖西南方伐木為生。\n\n天譴軍團和燃燒軍團改變了這座小鎮的價值。在自身覆滅之後忙於重建的達拉然祈倫托占領了這座小鎮，安伯米爾一度成為它從未成為過的樣子：在達拉然魔法的支撐下，成了銀松森林中一股真正的人類抵抗力量。\n\n被遺忘者並未對此坐視不管。他們的亡靈哨兵從一名俘虜口中得知，法師們在那裡保存著一些與達拉然現況息息相關的文件。磨坊、馬廄和鎮公所仍在祈倫托手中，而間諜們正從森林的陰影中對他們採取行動。",
			source = "https://warcraft.wiki.gg/wiki/Ambermill",
		},
		["berens peril"] = {
			name = "博倫的巢穴",
			short = "在安伯米爾西南方的山丘間，坐落著博倫的巢穴。",
			full = "在安伯米爾西南方的山丘間，坐落著博倫的巢穴。第三次大戰結束多年後，被遺忘者的斥候向暗影牧師奧利斯特回報，說有亡靈正祕密聚集在那裡，準備對瑟伯切爾發動攻擊。這些亡靈效命於亡靈巫師圖勒·鴉爪，他選中此地，是為了在不被察覺的情況下集結僕從：這裡離瑟伯切爾夠近，足以構成威脅，又離大路夠遠，得以避人耳目。",
			source = "https://warcraft.wiki.gg/wiki/Beren's_Peril",
		},
		["dawning isles"] = {
			name = "黎明島",
			short = "黎明島曾經和緩而低矮地浮出洛丹米爾湖清澈如水晶的湖面，是一片未受紛擾侵擾的寧靜小島。亡靈瘟疫改變了這一切。",
			full = "黎明島曾經和緩而低矮地浮出洛丹米爾湖清澈如水晶的湖面，是一片未受紛擾侵擾的寧靜小島。亡靈瘟疫改變了這一切。島上的樹木染上病害，魚人和沼澤獸占據了這些小島。沼澤獸如今已經消失，邪鰭魚人卻不受遏制地繁衍，如今已完全占據了這片群島。",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Isles",
		},
		["dead field"] = {
			name = "亡者農場",
			short = "亡者農場荒廢在銀松森林北部，田地早已腐敗，原本的主人也已被人遺忘。",
			full = "亡者農場荒廢在銀松森林北部，田地早已腐敗，原本的主人也已被人遺忘。人們所知道的，只是此後占據這裡的是誰：效忠天譴軍團的腐皮豺狼人。牠們將這座殘破的農場當作基地，數量不斷增加，這種集結顯示牠們仍在此地籌備某場攻擊。\n\n被遺忘者不止一次突襲這座農場，希望在豺狼人行動之前將其擊潰，但每一次都以失敗告終。每當腐皮豺狼人受到威脅，便會有一名女妖回應牠們的呼喚。這個名叫奈塔拉什的靈魂將豺狼人視為自己的部屬號令，總是憑空現身保護牠們。",
			source = "https://warcraft.wiki.gg/wiki/Dead_Field",
		},
		["decrepit ferry"] = {
			name = "破舊渡口",
			short = "破舊渡口當年負責將貨物運往芬里斯島，一位領主和他的家人在那座島上擁有自己的莊園，每趟付給擺渡人幾枚銅板。",
			full = "破舊渡口當年負責將貨物運往芬里斯島，一位領主和他的家人在那座島上擁有自己的莊園，每趟付給擺渡人幾枚銅板。\n\n後來，天譴軍團降臨羅德隆。擺渡人在他工作的地方遇害，渡船也被砸得粉碎。\n\n如今，食屍鬼、骷髏戰士和腐皮豺狼人在殘破的碼頭上出沒，這處渡口已被廢棄，除了強者之外，對任何人來說都十分危險。",
			source = "https://warcraft.wiki.gg/wiki/Decrepit_Ferry",
		},
		["deep elem mine"] = {
			name = "埃利姆礦坑",
			short = "埃利姆礦坑位於銀松森林中。阿魯高任由他的魔法蔓延到礦坑裡，狼人便在此築巢，率領牠們的是曾經擔任這裡工頭的蒼白的格瑞姆森。",
			full = "埃利姆礦坑位於銀松森林中。阿魯高任由他的魔法蔓延到礦坑裡，狼人便在此築巢，率領牠們的是曾經擔任這裡工頭的蒼白的格瑞姆森。\n\n達拉爾·道恩維沃爾以瓦里瑪薩斯的名義，謀求格瑞姆森的性命，好讓被遺忘者將這座礦坑納為己用。",
			source = "https://warcraft.wiki.gg/wiki/Deep_Elem_Mine",
		},
		["fenris isle"] = {
			name = "芬里斯島",
			short = "芬里斯島位於洛丹米爾湖中央，與黎明島共同構成一圈斷續的陸地，它是其中的一塊，大致也被算作銀松森林的一部分。",
			full = "芬里斯島位於洛丹米爾湖中央，與黎明島共同構成一圈斷續的陸地，它是其中的一塊，大致也被算作銀松森林的一部分。\n\n第三次大戰之前，島上有一座芬里斯城堡，是羅德隆的一處軍事前哨。天譴軍團席捲大地時，城堡隨之陷落。城中的人不是逃走，就是當場被殺，島嶼從此空無一人。\n\n腐皮豺狼人乘虛而入，將廢棄的城堡當作巢穴。牠們的主人是圖勒·鴉爪，一個即使在豺狼人之中也以奸詐聞名的人物。他統治著腐皮豺狼人，並透過牠們掌控了整座芬里斯島，不但據守著他所占領的城堡，還把附近的破舊渡口也一併納入囊中。",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Isle",
		},
		["fenris keep"] = {
			name = "芬里斯城堡",
			short = "芬里斯城堡位於銀松森林的芬里斯島上，矗立在洛丹米爾湖的中央，當年這裡駐紮著羅德隆相當一部分的軍隊。",
			full = "芬里斯城堡位於銀松森林的芬里斯島上，矗立在洛丹米爾湖的中央，當年這裡駐紮著羅德隆相當一部分的軍隊。\n\n天譴軍團席捲大地時，城堡也隨之陷落。圖勒·鴉爪趁著廢墟而來，他是一名曾屬於祈倫托的年輕法師，投靠了天譴軍團，並讓島上的豺狼人屈從於他的意志，將牠們鍛造成了腐皮豺狼人。有了這個部族作為後盾，他成了芬里斯城堡的主人，任何接近他們主人的人，都會遭到腐皮豺狼人的襲擊。",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Keep",
		},
		["greymane wall"] = {
			name = "格雷邁恩之牆",
			short = "吉恩·葛雷邁恩國王在第三次大戰之前築起了他的城牆，當時他已厭倦了吉爾尼斯的錢財被花在獸人收容營上，也被羅德隆聯盟各國國王之間的爭執弄得心力交瘁。",
			full = "吉恩·葛雷邁恩國王在第三次大戰之前築起了他的城牆，當時他已厭倦了吉爾尼斯的錢財被花在獸人收容營上，也被羅德隆聯盟各國國王之間的爭執弄得心力交瘁。他讓王國閉關自守，使吉爾尼斯與羅德隆、與群山之外的世界隔絕開來。\n\n這道城牆擋住了亡靈瘟疫，卻付出了代價。天譴軍團席捲羅德隆時，難民們向南逃難，在城門外紮營，而那扇城門多年來始終不曾開啟。難民們就這樣死在那裡，無人回應。",
			source = "https://warcraft.wiki.gg/wiki/Greymane_Wall",
		},
		["ivar patch"] = {
			name = "伊瓦農場",
			short = "伊瓦農場曾是一座令人稱羨的農場，田壟上結滿了沉甸甸的南瓜，屋裡住滿了為一個名叫伊瓦的人耕作田地的雇工。",
			full = "伊瓦農場曾是一座令人稱羨的農場，田壟上結滿了沉甸甸的南瓜，屋裡住滿了為一個名叫伊瓦的人耕作田地的雇工。那是很好的營生，直到亡靈瘟疫降臨羅德隆，將這一切從他手中奪走。\n\n伊瓦並不只是死去而已。他站了起來，他的家人也站了起來，所有曾在他土地上幹活的雇工也都站了起來，全都變成了腐爛的食屍鬼，如今會撲向任何靠近的人。伊瓦本人則化作了更可怕的東西，如今人們記得他的名字是邪惡的伊瓦。\n\n三名被派往北方評估危險的亡靈哨兵在這裡遭到食屍鬼圍困，邪惡的伊瓦打傷了其中一人奎恩·尤瑞克，隨後奎恩與他的族人蘭妮在伊瓦的舊屋裡築起路障，死守其中。",
			source = "https://warcraft.wiki.gg/wiki/Ivar_Patch",
		},
		["lordamere lake"] = {
			name = "洛丹米爾湖",
			short = "洛丹米爾湖在那些曾以其湖岸為家的王國陰影下鋪展開來。",
			full = "洛丹米爾湖在那些曾以其湖岸為家的王國陰影下鋪展開來。羅德隆在湖的北岸崛起，這座湖的名字很可能就是來自那座偉大的城市，而那座城市本身又是以古時的洛丹命名。在羅德隆聯盟將人類諸王國團結在一起的年代，達拉然和奧特蘭克也曾在湖畔繁榮興盛。\n\n那個時代已經過去，留下的只是一道邊界。如今這座湖橫亙在被遺忘者所控制的提里斯法林地與銀松森林，以及飽受爭奪的奧特蘭克山脈之間，將死者與生者分隔兩地。\n\n湖心坐落著芬里斯島，島上的城堡由圖勒·鴉爪麾下的腐皮豺狼人據守。\n\n在芬里斯島以東的小小黎明島之間，邪鰭魚人宣示了主權，將那些小島完全占據。",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Lake",
		},
		["maldens orchard"] = {
			name = "瑪爾丁果園",
			short = "瑪爾丁果園的樹木變得陰暗而常綠，果實年復一年掛在枝頭無人採摘。瑪爾丁本人早已離去，在天譴軍團降臨羅德隆時被逐出了家園。",
			full = "瑪爾丁果園的樹木變得陰暗而常綠，果實年復一年掛在枝頭無人採摘。瑪爾丁本人早已離去，在天譴軍團降臨羅德隆時被逐出了家園。\n\n如今這座果園屬於座狼，牠們成群地在樹林間、在那間仍然立著的小屋周圍築巢。亡靈哨兵埃蘭德·瑪科雷就是走進了這樣的地方。他在偵察北部森林時被派來察看這座果園，還沒走多遠就被座狼逼得無處可逃，只好躲進那間廢棄的小屋並堵住門窗，被困在裡面好幾天，直到其他被遺忘者特務協助他脫身，回到正在等候他的同伴身邊。",
			source = "https://warcraft.wiki.gg/wiki/Malden's_Orchard",
		},
		["north tides hollow"] = {
			name = "北流谷",
			short = "北流谷就位於銀松森林中瑟伯切爾的北邊，是大法師阿魯高的僕從月怒狼人眾多出沒地點之一。",
			full = "北流谷就位於銀松森林中瑟伯切爾的北邊，是大法師阿魯高的僕從月怒狼人眾多出沒地點之一。牠們在這裡搭起簡陋的營地，除了維生所需最起碼的東西之外一無所有，對於靠著利齒和蠻力過活的生物來說，這樣的棲身之所已經足夠。",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Hollow",
		},
		["north tides run"] = {
			name = "北流海岸",
			short = "銀松森林西北方的海岸線，也就是沙灘與冰冷的無盡之海交會之處，名叫北流海岸。",
			full = "銀松森林西北方的海岸線，也就是沙灘與冰冷的無盡之海交會之處，名叫北流海岸。一艘殘破的部落船隻半沉在淺灘中，船身陷進浪花裡，是這段海岸上最顯眼的標誌。",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Run",
		},
		["olsens farthing"] = {
			name = "奧森農場",
			short = "奧森農場曾經坐落在貫穿銀松森林的商道旁，是一座仍在運作的農莊，田地的收成供應著往來的人潮。",
			full = "奧森農場曾經坐落在貫穿銀松森林的商道旁，是一座仍在運作的農莊，田地的收成供應著往來的人潮。\n\n第三次大戰終結了這一切。短短幾年內，農場便淪為一片廢墟。",
			source = "https://warcraft.wiki.gg/wiki/Olsen's_Farthing",
		},
		["pyrewood village"] = {
			name = "焚木村",
			short = "焚木村位於銀松森林的邊緣，聚居著一群在第三次大戰中熬過天譴軍團第一波侵襲的人類。",
			full = "焚木村位於銀松森林的邊緣，聚居著一群在第三次大戰中熬過天譴軍團第一波侵襲的人類。村子北邊矗立著一座城堡，曾由席瓦萊恩男爵掌管，並由聖騎士斯普林瓦爾指揮官和白銀之手騎士團守衛。席瓦萊恩和他的部下遭到大法師阿魯高的狼人屠殺，阿魯高將城堡據為己有，並將它改名為影牙城堡。阿魯高隨後把他的瘋狂轉向焚木村本身，對村民施下詛咒，讓他們每到夜晚就變成垂涎欲滴的月怒狼人，撕咬任何擋路的人，直到黎明時分才又恢復人形醒來。\n\n儘管如此，村子白天依然向旅人敞開大門，村民們受困於阿魯高施加在他們身上的詛咒，看不到盡頭。",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Village",
		},
		["sepulcher"] = {
			name = "瑟伯切爾",
			short = "瑟伯切爾坐落在銀松森林西部的山丘上，俯瞰著羅德隆的海岸線。那裡曾有一條道路穿過一座簡樸的墓地，墓穴所標示的，不過是死者安息之所。",
			full = "瑟伯切爾坐落在銀松森林西部的山丘上，俯瞰著羅德隆的海岸線。那裡曾有一條道路穿過一座簡樸的墓地，墓穴所標示的，不過是死者安息之所。\n\n第三次大戰之後，被遺忘者占據了這座古老的墓地，將它改建為行動基地，讓一個為死者而建的地方，轉而為不死者所用。\n\n這個選擇是出於不得已。南邊有狼人出沒，東邊仍有天譴軍團盤踞，東南方則有祈倫托虎視眈眈。幾乎四面受敵的被遺忘者發現，瑟伯切爾是銀松森林中少數幾個能讓部落安身立足的地方之一。",
			source = "https://warcraft.wiki.gg/wiki/Sepulcher",
		},
		["shadowfang keep"] = {
			name = "影牙城堡",
			short = "影牙城堡矗立在焚木村上方的一座高崖上。它曾經屬於吉爾尼斯的領主席瓦萊恩男爵，直到天譴軍團降臨羅德隆，皇家大法師阿魯高試圖尋找阻止它們的方法。",
			full = "影牙城堡矗立在焚木村上方的一座高崖上。它曾經屬於吉爾尼斯的領主席瓦萊恩男爵，直到天譴軍團降臨羅德隆，皇家大法師阿魯高試圖尋找阻止它們的方法。阿魯高借鑑法師烏爾的研究，在吉恩·葛雷邁恩國王的首肯下，卻違背祈倫托的忠告，召喚出了狼人。狼人擊退了亡靈的浪潮，隨即轉而攻擊吉爾尼斯本身，在葛雷邁恩之牆肆虐一番後，又在銀松森林中四處橫行。牠們襲擊了這座城堡，殺死了席瓦萊恩男爵和他的家人。\n\n被自己所釋放之物擊垮的阿魯高並沒有逃離。他將狼人稱為自己的孩子，把城堡據為己有，並將它改名為影牙城堡。他與他在狼群教派中所侍奉的一位主人交流，讓詛咒在森林中蔓延，直到連焚木村也被轉化，村民白天是人，夜晚是獸，由一個只聽命於他的議會統治。",
			source = "https://warcraft.wiki.gg/wiki/Shadowfang_Keep",
		},
		["shining strand"] = {
			name = "閃光湖岸",
			short = "閃光湖岸沿著洛丹米爾湖延伸，從北方的羅德隆王都，一路向南直到分隔銀松森林與奧特蘭克山脈的崎嶇丘陵。",
			full = "閃光湖岸沿著洛丹米爾湖延伸，從北方的羅德隆王都，一路向南直到分隔銀松森林與奧特蘭克山脈的崎嶇丘陵。\n\n邪鰭魚人部族在湖岸上密密麻麻地建起聚落，不熟悉這段岸線的旅人早已學會對它心存畏懼。已故的藥劑師伯納德在他的日記中寫道，可以從邪鰭魚人身上取得一種罕見的東西，也就是硬化腫瘤，並推測它或許能用來製造一種新的瘟疫。",
			source = "https://warcraft.wiki.gg/wiki/Shining_Strand",
		},
		["skittering dark"] = {
			name = "粘絲洞",
			short = "那座被稱為粘絲洞的礦坑已被粘絲蜘蛛占據，牠們的蛛網覆蓋在斷裂的木樑和生鏽的工具上。",
			full = "那座被稱為粘絲洞的礦坑已被粘絲蜘蛛占據，牠們的蛛網覆蓋在斷裂的木樑和生鏽的工具上。礦坑深處藏著粘絲蛛母，一隻長得奇大無比的蜘蛛，在她從不離開的黑暗中統治著整群蜘蛛。在外頭，罕見的「影織者」克雷希斯有時會獨自在岩石間潛行。\n\n地上散落著許多蛛繭，裡頭裹著狼人、座狼和熊，還有從西邊岸上一艘沉船中拖來的獸人。",
			source = "https://warcraft.wiki.gg/wiki/Skittering_Dark",
		},
		["south tides run"] = {
			name = "南流海岸",
			short = "南流海岸沿著銀松森林的西南海岸延伸，那裡是陸地與無盡之海交會之處。",
			full = "南流海岸沿著銀松森林的西南海岸延伸，那裡是陸地與無盡之海交會之處。",
			source = "https://warcraft.wiki.gg/wiki/South_Tide's_Run",
