	-- 西瘟疫之地: 18 subzones
	[1422] = {
		["bulwark"] = {
			name = "亡靈壁壘",
			short = "亡靈壁壘矗立在提里斯法林地與西瘟疫之地的交界處，這條防線由被遺忘者據守，對抗仍在東方集結的天譴軍團。",
			full = "亡靈壁壘矗立在提里斯法林地與西瘟疫之地的交界處，這條防線由被遺忘者據守，對抗仍在東方集結的天譴軍團。在這裡，被遺忘者的守軍和銀色黎明為了對抗共同的敵人而擱置了彼此的分歧，一起監視邊界，並派遣戰士向東出擊，打擊巫妖王的爪牙。\n\n與提里斯法的其他地方不同，這一帶看起來完全不像林地。一層瘟疫之霧籠罩其上，將天空染成與遠方西瘟疫之地一樣病懨懨的黃灰色。",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["caer darrow"] = {
			name = "凱爾達隆",
			short = "達隆米爾湖的小島上，曾矗立著一座很久以前由人類之手建造的堡壘，裡頭存放著一塊古老的高等精靈符文石。",
			full = "達隆米爾湖的小島上，曾矗立著一座很久以前由人類之手建造的堡壘，裡頭存放著一塊古老的高等精靈符文石。第二次大戰期間，部落攻占了這座島嶼並洗劫了城堡，將符文石拆解，用來鑄造暴風祭壇，古爾丹就是透過這些祭壇，將魔法注入他部落中的巨魔體內。\n\n城堡重建之後，成了巴羅夫家族的宅邸。隨著歲月一步步走向戰爭，巴羅夫家族開始害怕失去數十年來積累的一切，於是與詛咒神教的首領科爾蘇加德達成了交易。莊園底下的地下墓穴變成了通靈學院，一所亡靈術學校，而家族自己的僕人則被交出去，充當亡靈瘟疫的實驗對象。不到半年，疫病便爆發開來，殺死了島上的每一個人。受害者並不只是死去而已：他們化為鬼魂，被束縛著一再重演自己最後的時刻，至今仍在凱爾達隆殘破的廳堂中行走。",
			source = "https://warcraft.wiki.gg/wiki/Caer_Darrow",
		},
		["chillwind camp"] = {
			name = "冰風營地",
			short = "冰風營地坐落在西瘟疫之地的南方門戶，奧特蘭克的群山在此讓位給遭受毒害的土地。對聯盟的旅人來說，這是最後一個還能站著說腳下土地是潔淨的地方。",
			full = "冰風營地坐落在西瘟疫之地的南方門戶，奧特蘭克的群山在此讓位給遭受毒害的土地。對聯盟的旅人來說，這是最後一個還能站著說腳下土地是潔淨的地方。\n\n據守這裡的是銀色黎明的一支小分隊，手下只有寥寥幾名士兵和專家。營地在人數上的不足，由膽識來彌補：這裡的人對天譴軍團在安多哈爾的據點，以及在大地上散播死亡的瘟疫之鍋，發動游擊戰，依靠的是那些願意出擊後隨即消失的傭兵，而不是去固守他們守不住的陣地。\n\n格雷森·沙東布瑞克公爵將前途看好的年輕白銀之手騎士派到這裡，與指揮官阿胥拉姆·瓦羅菲斯特並肩對抗這一帶的天譴軍團。",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Camp",
		},
		["dalsons tears"] = {
			name = "達爾松之淚",
			short = "達爾松果園曾經為一個以自己的姓氏為它命名的家族結出果實。如今，這片果樹林立於西瘟疫之地，名字所紀念的不再是收穫，而是悲傷：達爾松之淚。",
			full = "達爾松果園曾經為一個以自己的姓氏為它命名的家族結出果實。如今，這片果樹林立於西瘟疫之地，名字所紀念的不再是收穫，而是悲傷：達爾松之淚。\n\n天譴軍團奪走了農場，將它變成大地上的一道傷口。他們在正中央安放了一口巨大的瘟疫之鍋，它從此不曾停歇，不斷將疾病噴向空中，由護鍋領主瑪爾溫尼斯和效忠於他的荒疫亡者看守。\n\n達爾松一家從未離開。達爾松夫人至今仍在這片土地上遊蕩，一具四處徘徊的骷髏，在她生前照料過的土地上翻翻揀揀。她的丈夫並沒有死在她身邊。他被關進了屋外的茅廁，就此被丟在那裡，而他在那片上了鎖的黑暗中變成的東西，已經不再是人，而是一隻食屍鬼。",
			source = "https://warcraft.wiki.gg/wiki/Dalson's_Tears",
		},
		["darrowmere lake"] = {
			name = "達隆米爾湖",
			short = "達隆米爾湖的湖水依然記得第二次大戰的往事，那時湖面上帆影密布。",
			full = "達隆米爾湖的湖水依然記得第二次大戰的往事，那時湖面上帆影密布。停泊在這裡的船隻大多懸掛著普勞德摩爾艦隊的旗幟。在奎爾薩拉斯遭到焚燒之前，海軍上將派出其中一些船隻橫渡這片水域，載著圖拉揚、艾蘭里亞·風行者和他們的軍隊前往斯坦索姆。圖拉揚曾考慮直接航入奎爾薩拉斯，但艾蘭里亞警告他，精靈絕不會讓人類的船隻沿著他們的河流上溯，於是艦隊轉而駛向斯坦索姆。也正是在這場戰爭中，祖爾金和他的部眾被逼退到湖岸，這位食人妖督軍也因此被俘。\n\n湖心矗立著島上的城鎮凱爾達隆，如今空無一人，昔日由巴羅夫家族掌管。在城鎮的石板底下，是詛咒神教與其亡靈一同活動的通靈學院，一片黑暗就潛伏在這座島嶼沉寂如溺的寧靜之下。",
			source = "https://warcraft.wiki.gg/wiki/Darrowmere_Lake",
		},
		["felstone field"] = {
			name = "費爾斯通農場",
			short = "費爾斯通農場曾經養活過生者。直到天譴軍團降臨，不再讓它當一座農場，這一切便告終結。",
			full = "費爾斯通農場曾經養活過生者。直到天譴軍團降臨，不再讓它當一座農場，這一切便告終結。\n\n天譴軍團在田地中央安放了一口巨大的瘟疫之鍋，從那時起它便不曾停止運作。濃重的蒸氣不斷從中湧出，充滿了疾病。護鍋領主拜爾摩守在一旁，身邊還有骷髏巫師、骷髏剝皮者和垂涎的食屍鬼，任何活物都無法接近它而全身而退。\n\n東北角的老房子依然矗立，詹妮絲·費爾斯通仍然守在屋裡，徘徊在這片曾經為她家種出莊稼的土地上。",
			source = "https://warcraft.wiki.gg/wiki/Felstone_Field",
		},
		["gahrrons withering"] = {
			name = "蓋羅恩農場",
			short = "西瘟疫之地東緣的這座農場曾屬於戴爾·蓋羅恩，在它的全盛時期，人們叫它蓋羅恩的新生之地，那是一個播種與生長的地方。",
			full = "西瘟疫之地東緣的這座農場曾屬於戴爾·蓋羅恩，在它的全盛時期，人們叫它蓋羅恩的新生之地，那是一個播種與生長的地方。如今那裡寸草不生。天譴軍團奪走了田地，在中央安放了一口巨大的瘟疫之鍋，而它從未停止運作，不斷將充滿疾病的蒸氣噴向空中，直到連土地本身都像是病了。護鍋領主索瓦斯和天譴軍團的其他軍官一同看守著它，而那些蒸氣召喚出了不該行走於世的東西：縈繞不散的幻影在殘破的田壟間飄蕩，哀嚎的死靈與飢餓的怨靈除了自己的飢渴之外，不聽命於任何主人。",
			source = "https://warcraft.wiki.gg/wiki/Gahrron's_Withering",
		},
		["hearthglen"] = {
			name = "壁爐谷",
			short = "壁爐谷位於安多哈爾北方，城牆環抱著一座城堡、一座法師塔、一座磨坊和一座礦坑，在這片化為廢墟的地區中，儼然是秩序的象徵。",
			full = "壁爐谷位於安多哈爾北方，城牆環抱著一座城堡、一座法師塔、一座磨坊和一座礦坑，在這片化為廢墟的地區中，儼然是秩序的象徵。多年來，它在瑪登霍爾德領主提里奧·弗丁的治理下維持著這份秩序，直到他援助了獸人伊崔格，以叛國罪遭到放逐。後來，他的兒子泰蘭接替他，成為瑪登霍爾德領主。\n\n首都淪陷之後，壁爐谷接納了白銀之手騎士團的殘部，他們響應了泰蘭提供庇護的邀請。在隨後的幾年裡，聖騎士們從這座城牆內出擊，贏得了多場勝利，直到騎士團被扭曲成了血色十字軍，並將這座城鎮據為己有。",
			source = "https://warcraft.wiki.gg/wiki/Hearthglen",
		},
		["mardenholde keep"] = {
			name = "瑪登霍爾德城堡",
			short = "瑪登霍爾德城堡矗立在壁爐谷的中心，早在如今行走於其廳堂中的大多數人記事之前就已存在，即使在獸人入侵羅德隆最黑暗的日子裡，它的城牆也未曾被攻破。",
			full = "瑪登霍爾德城堡矗立在壁爐谷的中心，早在如今行走於其廳堂中的大多數人記事之前就已存在，即使在獸人入侵羅德隆最黑暗的日子裡，它的城牆也未曾被攻破。多年來，這裡是提里奧·弗丁的宅邸。在一間以巨大橡木桌為主角的議事廳裡，牆上掛著一幅把壁爐谷連最小的道路都描繪出來的地圖，這位聖騎士就在那裡與他的顧問們商討國事。提里奧因援助獸人伊崔格而被控叛國，遭到開除教籍並被放逐，瑪登霍爾德後來傳給了他的兒子泰蘭。\n\n羅德隆淪陷之後，泰蘭讓倖存的白銀之手騎士在壁爐谷安身。亞歷山德羅斯·莫格萊尼的死訊傳進了這座城牆之內，對背叛的猜疑使騎士團分裂：瑪克斯韋爾·泰羅索斯帶領他的追隨者離去，創立了銀色黎明，而留下來的人則取名為血色十字軍，瑪登霍爾德成了他們的要塞，泰蘭也被擁立為大領主。",
			source = "https://warcraft.wiki.gg/wiki/Mardenholde_Keep",
		},
		["northridge lumber camp"] = {
			name = "北山伐木場",
			short = "北山伐木場位於西瘟疫之地北部、壁爐谷附近，山坡上的樹木已被血色十字軍砍伐殆盡。",
			full = "北山伐木場位於西瘟疫之地北部、壁爐谷附近，山坡上的樹木已被血色十字軍砍伐殆盡。十字軍經營著這座鋸木廠以取得木材，而聯盟和部落都有理由想讓這批物資付諸東流。\n\n第三次大戰之前，這座鋸木廠屬於納薩尼爾·杜馬的家族，他們一直在這片土地上勞作，直到戰爭與瘟疫將他們逐出家園。米克·萊文的家人也曾在這裡工作。",
			source = "https://warcraft.wiki.gg/wiki/Northridge_Lumber_Camp",
		},
		["ruins of andorhal"] = {
			name = "安多哈爾廢墟",
			short = "安多哈爾化為一片廢墟，躺在西瘟疫之地的中心，殘破的房屋散落在空曠的土地上。",
			full = "安多哈爾化為一片廢墟，躺在西瘟疫之地的中心，殘破的房屋散落在空曠的土地上。殘存下來的一切都由召喚者阿拉基掌控，他是一名力量強大的巫妖，還有效忠於他的亡者：在倒塌的石塊間拖行的食屍鬼，站在衛兵曾經站崗之處充當哨兵的骷髏，哭嚎聲迴盪在廢墟上空的女妖，以及在房屋殘骸間笨重移動的憎惡。\n\n阿拉基依然坐鎮在這一切的中心，統治著一座再也沒能重新崛起的城市。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Andorhal",
		},
		["scholomance"] = {
			name = "通靈學院",
			short = "在廢棄的凱爾達隆城上方的高地上，矗立著一座莊園，它曾是巴羅夫家族的宅邸，這個家族的勢力從凱爾達隆延伸到布瑞爾，延伸到南海鎮，再到塔倫米爾。",
			full = "在廢棄的凱爾達隆城上方的高地上，矗立著一座莊園，它曾是巴羅夫家族的宅邸，這個家族的勢力從凱爾達隆延伸到布瑞爾，延伸到南海鎮，再到塔倫米爾。數十年來，他們安逸地統治著，但隨著歲月逐漸走向戰爭，巴羅夫家族變得尖刻而貪婪，不願讓死亡終結他們所建立的一切。於是他們與詛咒神教的首領科爾蘇加德達成交易，好讓他們的財富與土地超越凡人壽命的極限而永遠保存。\n\n不到六個月，這座城堡便腐化成了截然不同的東西。神教的侍僧們研習亡靈巫師的技藝，而家族自己的僕人則被交出去，充當亡靈瘟疫的活體實驗品。在光明使者烏瑟依約造訪莊園之前，一場在莊園廳堂中孕育的疫病便已在凱爾達隆全境爆發。它沒有留下任何活口，並束縛著受害者，讓他們死後化為鬼魂四處遊蕩。\n\n巴羅夫家族的人自己也以亡靈之姿再度起身，依然被束縛在他們出賣掉的廳堂中。如今，由凡人亡靈巫師黑暗院長加丁擔任院長，他接替了召喚者阿拉基，而阿拉基本人則是科爾蘇加德的繼任者。",
			source = "https://warcraft.wiki.gg/wiki/Scholomance",
		},
		["sorrow hill"] = {
			name = "悔恨嶺",
			short = "在較為平和的年代，悔恨嶺是安多哈爾的墓地，鎮上的死者無論貧富，都長眠在墓穴和簡樸的墓碑之下。",
			full = "在較為平和的年代，悔恨嶺是安多哈爾的墓地，鎮上的死者無論貧富，都長眠在墓穴和簡樸的墓碑之下。亡靈瘟疫的到來終結了這份安寧。隨著天譴軍團一次又一次地猛攻安多哈爾，山丘被填滿的速度遠遠超過它所能容納的，守軍倒下之處，至今仍留著倉促挖成、未立墓碑的墳墓。後來，倖存者乾脆不再埋葬死者，他們太害怕瘟疫會讓他們所愛的人起身反過來對付自己，於是在墓園南邊挖了一個萬人坑，改為焚燒屍體。\n\n這座小鎮的最後一件事，也是最令人心酸的一件事。阿薩斯擊殺烏瑟大人之後，安多哈爾剩下的居民在山頂築起一座宏偉的陵墓，將這位聖騎士殘破的遺體安放其中，然後永遠離開了自己的家園。有人說，這座山丘的名字就是單單因為那座墳墓而來。\n\n附近的瘟疫之鍋也沒有放過山丘上原有的死者。士兵和鎮民從自己的墓地中起身，守衛著那些他們曾經填滿的墳墓。",
			source = "https://warcraft.wiki.gg/wiki/Sorrow_Hill",
		},
		["thondroril river"] = {
			name = "索多里爾河",
			short = "索多里爾河將西瘟疫之地與東瘟疫之地分隔開來。它發源於遙遠北方的惡蛛隧道附近，一路向南流，直到注入達隆米爾湖，再從湖的另一頭繼續流出，成為達隆米爾河。",
			full = "索多里爾河將西瘟疫之地與東瘟疫之地分隔開來。它發源於遙遠北方的惡蛛隧道附近，一路向南流，直到注入達隆米爾湖，再從湖的另一頭繼續流出，成為達隆米爾河。\n\n它的河岸屬於荒疫。蛆蟲和吸血蝙蝠擠滿了潮濕的地面，瘟疫熊和蜘蛛在淺灘間潛行，鉗嘴龜則潛伏在水流變緩的地方。",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["uthers tomb"] = {
			name = "烏瑟之墓",
			short = "烏瑟之墓位於悔恨嶺，是西瘟疫之地唯一一處聖光仍能抵禦這片土地凋亡的地方。",
			full = "烏瑟之墓位於悔恨嶺，是西瘟疫之地唯一一處聖光仍能抵禦這片土地凋亡的地方。\n\n光明使者烏瑟曾經率領身後的白銀之手騎士，與賢者真言者和光明的巴拉多爾並肩，堅守安多哈爾對抗天譴軍團。終結這場堅守的是阿薩斯·米奈希爾，他率領亡靈大軍進攻這座城市，擊殺了真言者、巴拉多爾，以及烏瑟本人。\n\n阿薩斯留下的遺骸，由烏瑟自己的士兵收殮。他們將他的遺體抬到安多哈爾廢墟的南邊，並在其上建起了一座陵墓。他的墓碑刻畫著他生前的模樣，一手捧著聖光之書，一手握著他的戰錘，而墓碑前的碑石上則以通用語刻著文字。\n\n高階牧師賽爾鄧尼斯至今仍守護著這座陵墓，是它的看守者與守護者。對於追隨聖光的人而言，這座墳墓是神聖之地，也是瘟疫之地中少數幾個這樣的虔誠仍有意義的地方之一。",
			source = "https://warcraft.wiki.gg/wiki/Uther's_Tomb",
		},
		["weeping cave"] = {
			name = "哭泣之洞",
			short = "哭泣之洞位於索多里爾河以西，洞穴中滿是沼澤獸和這片瘟疫之地孕育出的軟泥怪。腐爛的巨獸和腐朽的恐魔在黑暗中蹣跚而行。",
			full = "哭泣之洞位於索多里爾河以西，洞穴中滿是沼澤獸和這片瘟疫之地孕育出的軟泥怪。腐爛的巨獸和腐朽的恐魔在黑暗中蹣跚而行。在更深處，據說偶爾會出現一個名叫「空殼」的元素生物，一旦瞥見，總讓人覺得詭異而不安。",
			source = "https://warcraft.wiki.gg/wiki/Weeping_Cave",
		},
		["writhing haunt"] = {
			name = "嚎哭鬼屋",
			short = "嚎哭鬼屋曾經是一片農地，耕作是為了養活生者。那個用途已經不復存在。",
			full = "嚎哭鬼屋曾經是一片農地，耕作是為了養活生者。那個用途已經不復存在。天譴軍團奪走了田地，在中央安放了一口巨大的瘟疫之鍋，從此它便不曾停止運作：充滿疾病的蒸氣源源不絕地噴湧而出，翻滾著漫過昔日種植莊稼的田壟。\n\n這口瘟疫之鍋並非無人看守。護鍋領主拉札克守在一旁，腐爛食屍鬼、冰凍食屍鬼和惡臭殭屍在他身邊徘徊，被束縛在此地充當看守。",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Haunt",
		},
	},
	-- 東瘟疫之地: 28 subzones
	[1423] = {
		["blackwood lake"] = {
			name = "黑木湖",
			short = "黑木湖的湖水污濁不堪，遭到腐化的水元素在渾濁的湖水中盤旋翻騰。達隆郡的古老編年史記載，掠奪者霍古斯的頭顱就沉在那片黑暗中的某處湖底。",
			full = "黑木湖的湖水污濁不堪，遭到腐化的水元素在渾濁的湖水中盤旋翻騰。達隆郡的古老編年史記載，掠奪者霍古斯的頭顱就沉在那片黑暗中的某處湖底。\n\n在瘟疫來臨之前，這裡曾有一座名叫黑木的城鎮，是大元帥歐斯瑪·加里索斯的故鄉。如今那座城鎮已蕩然無存，只剩下這座以它為名的湖泊。",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Lake",
		},
		["browman mill"] = {
			name = "布洛米爾",
			short = "史蒂芬·布洛曼曾在聖光之願禮拜堂北邊的鋸木廠伐木。天譴軍團像殺死所有被瘟疫沾染的人一樣殺死了他，隨後又讓他化為食屍鬼起身，受其驅使。",
			full = "史蒂芬·布洛曼曾在聖光之願禮拜堂北邊的鋸木廠伐木。天譴軍團像殺死所有被瘟疫沾染的人一樣殺死了他，隨後又讓他化為食屍鬼起身，受其驅使。他從未離開。如今他在自己曾經擁有的牆垣之內站崗守衛。\n\n鋸木廠裡擠滿了骷髏、女妖和憎惡，與其說是廢墟，不如說是一座兵營，這裡沒有任何東西會讓人想要逗留。",
			source = "https://warcraft.wiki.gg/wiki/Browman_Mill",
		},
		["corins crossing"] = {
			name = "考林路口",
			short = "考林路口位於魔刃之痕與米雷達爾湖之間，是通往安多哈爾、達隆郡、斯坦索姆和提爾之手的道路交會之處。",
			full = "考林路口位於魔刃之痕與米雷達爾湖之間，是通往安多哈爾、達隆郡、斯坦索姆和提爾之手的道路交會之處。它曾經是一座平凡的十字路口小鎮，有一座鎮公所和一間鐵匠鋪。\n\n如今天譴軍團擠滿了鎮上的每一條街道，而在亡者之間，還有一些完全看不見的東西在移動，那就是隱形僕從，對牠們來說，潛行彷彿形同虛設。穿過考林路口，不存在任何安靜的路徑。",
			source = "https://warcraft.wiki.gg/wiki/Corin's_Crossing",
		},
		["crown guard tower"] = {
			name = "皇冠哨塔",
			short = "皇冠哨塔是東瘟疫之地的瞭望塔之一，守望著這片土地。天譴軍團入侵羅德隆時橫掃了這一帶，這座塔至今仍帶著當時的傷痕，默默標示著這片死寂的土地。",
			full = "皇冠哨塔是東瘟疫之地的瞭望塔之一，守望著這片土地。天譴軍團入侵羅德隆時橫掃了這一帶，這座塔至今仍帶著當時的傷痕，默默標示著這片死寂的土地。",
			source = "https://warcraft.wiki.gg/wiki/Crown_Guard_Tower",
		},
		["darrowshire"] = {
			name = "達隆郡",
			short = "達隆郡曾經是一座自成一格的村莊，直到第三次大戰將天譴軍團帶到了它的門前。率領這場攻擊的是一名叫做掠奪者霍古斯的食屍鬼領主，與他並肩作戰的還有死亡騎士馬杜克·布萊克波爾。",
			full = "達隆郡曾經是一座自成一格的村莊，直到第三次大戰將天譴軍團帶到了它的門前。率領這場攻擊的是一名叫做掠奪者霍古斯的食屍鬼領主，與他並肩作戰的還有死亡騎士馬杜克·布萊克波爾。村裡的守軍起初反擊得頗有成效，但戰局逆轉，最後他們全數遭到屠殺。\n\n死亡並沒有讓他們就此解脫。倒下的人再度化為食屍鬼起身，被迫效命於殺害他們的天譴軍團，他們的靈魂被困在那曾經屬於自己的腐爛血肉之中。\n\n達隆郡本身如今一片死寂、殘破不堪，除了鬼魂和回憶之外空無一物。",
			source = "https://warcraft.wiki.gg/wiki/Darrowshire",
		},
		["eastwall gate"] = {
			name = "東牆大門",
			short = "東牆大門是進入斯坦索姆的側門，直接通往長者廣場，鄰近奧里克斯駐守的阿隆索斯禮拜堂。",
			full = "東牆大門是進入斯坦索姆的側門，直接通往長者廣場，鄰近奧里克斯駐守的阿隆索斯禮拜堂。",
