		["eastwall tower"] = {
			name = "東牆之塔",
			short = "東牆之塔位於東瘟疫之地，是一座曾經為羅德隆守望這片土地的瞭望塔。天譴軍團橫掃了這個王國，這座塔至今仍帶著傷痕，守望著死寂的大地。",
			full = "東牆之塔位於東瘟疫之地，是一座曾經為羅德隆守望這片土地的瞭望塔。天譴軍團橫掃了這個王國，這座塔至今仍帶著傷痕，守望著死寂的大地。",
