		["fungal vale"] = {
			name = "蘑菇谷",
			short = "在瑪瑞斯農場和皇冠哨塔的北邊，坐落著蘑菇谷，這片土地在一層混濁的霧靄下變成了深紫色。",
			full = "在瑪瑞斯農場和皇冠哨塔的北邊，坐落著蘑菇谷，這片土地在一層混濁的霧靄下變成了深紫色。亡靈瘟疫在這裡扎根最深，天譴軍團和詛咒神教在這片腐化中自由來去，將整座谷地完全視為己有。",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Vale",
