		["infectis scar"] = {
			name = "魔刃之痕",
			short = "在考林路口附近，死亡騎士馬杜克·布萊克波爾的符文劍在一名矮人上尉的盾牌上應聲碎裂。他留下了劍柄，把殘破的劍刃當成廢物丟到一旁。",
			full = "在考林路口附近，死亡騎士馬杜克·布萊克波爾的符文劍在一名矮人上尉的盾牌上應聲碎裂。他留下了劍柄，把殘破的劍刃當成廢物丟到一旁。然而劍刃沉入了大地，地面在它下方裂開，湧滿了黑色的水。\n\n留在這裡的一切從裡到外都違背自然，與附近那道不過是天然峽谷的瘟疫之痕截然不同。",
