			full = "米雷達爾湖位於考林路口南方，湖水中充斥著瘟疫，遭到腐化的水元素在水面下移動。湖岸上矗立著一棟老房子的廢墟，還有一間小屋和一座渡口，它們曾經為一座如今已被廢棄的農場服務。",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mereldar",
		},
		["lights hope chapel"] = {
			name = "聖光之願禮拜堂",
			short = "在瘟疫之地東邊的群山腳下，矗立著一座比周遭廢墟古老得多的禮拜堂，它是聖光教會所建立的聖地中，最古老、最受尊崇的幾座之一。",
			full = "在瘟疫之地東邊的群山腳下，矗立著一座比周遭廢墟古老得多的禮拜堂，它是聖光教會所建立的聖地中，最古老、最受尊崇的幾座之一。\n\n那些不願追隨血色十字軍所走道路的聖騎士，轉而退入東瘟疫之地，以這座禮拜堂為基地，自稱為銀色黎明。最初率領他們的是雷蒙德·喬治公爵；他死後，由瑪克斯韋爾·泰羅索斯男爵接替了他的位置。與血色十字軍不同，他們從不因種族而拒絕任何人。\n\n儘管銀色黎明與血色十字軍分道揚鑣，這座禮拜堂依然是一塊中立之地，雙方仍會在此會面交談。",
			source = "https://warcraft.wiki.gg/wiki/Light's_Hope_Chapel",
		},
		["marris stead"] = {
			name = "瑪瑞斯農場",
			short = "瑪瑞斯農場坐落在這一帶主要道路上方的一道低矮山脊上，這座農莊曾經屬於納薩諾斯·瑪瑞斯。",
			full = "瑪瑞斯農場坐落在這一帶主要道路上方的一道低矮山脊上，這座農莊曾經屬於納薩諾斯·瑪瑞斯。他的堂弟史帝芬曾在這裡住過一段時間，而希瓦娜斯·風行者也曾在這座屋簷下探望納薩諾斯。\n\n女妖之王在幽暗城喚起被遺忘者之後解放了納薩諾斯，他回到了自己失去的家園，奉她之命將它重新據為己有。他從這裡招募部落的士兵，投入對抗天譴軍團和仍在瘟疫之地肆虐的血色十字軍的戰鬥，他還收集了達隆郡之戰的遺物，將它們保存在農場裡，至於原因，他從未告訴任何人。",
			source = "https://warcraft.wiki.gg/wiki/Marris_Stead",
		},
		["mazraalor"] = {
			name = "瑪茲拉羅",
			short = "在祖瑪沙爾的中心，聳立著瑪茲拉羅，一座以石塊層層堆砌而成的金字形神塔，俯瞰著周圍殘破的土地。",
			full = "在祖瑪沙爾的中心，聳立著瑪茲拉羅，一座以石塊層層堆砌而成的金字形神塔，俯瞰著周圍殘破的土地。爛苔部族至今仍據守著它，他們的暗影獵手從塔頂高處監視著下方的食人妖聚落。",
			source = "https://warcraft.wiki.gg/wiki/Mazra'Alor",
