		["northdale"] = {
			name = "北谷",
			short = "北谷是聖光之願禮拜堂北方的一座廢棄城鎮，位於奎爾薩拉斯的邊緣。泰蘭·弗丁就是在這裡背棄了白銀之手騎士團，投向血色十字軍。",
			full = "北谷是聖光之願禮拜堂北方的一座廢棄城鎮，位於奎爾薩拉斯的邊緣。泰蘭·弗丁就是在這裡背棄了白銀之手騎士團，投向血色十字軍。\n\n如今女妖和隱形的監視者在殘骸中出沒。附近的湖裡棲息著遭到腐化的水元素。這裡已沒有任何活物。",
