		["noxious glade"] = {
			name = "劇毒林地",
			short = "劇毒林地位於聖光之願禮拜堂北邊的一座山丘上，受荒疫污染的程度比周圍瘟疫之地的其他地方更深。",
			full = "劇毒林地位於聖光之願禮拜堂北邊的一座山丘上，受荒疫污染的程度比周圍瘟疫之地的其他地方更深。空氣中瀰漫著濃重而病態的綠色，地面被染成了深紫色，任何綠色植物都無法在此生長。\n\n天譴軍團將這片林地據為己有：一口瘟疫之鍋、一座屠宰場和幾座通靈塔矗立在受毒害的土地上，大批天譴生物在其中穿梭。",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Glade",
