		["pestilent scar"] = {
			name = "瘟疫之痕",
			short = "瘟疫之痕是荒疫蔓延的東瘟疫之地中的一道深谷，很可能原本是一座湖泊，在亡靈瘟疫來襲時乾涸。",
			full = "瘟疫之痕是荒疫蔓延的東瘟疫之地中的一道深谷，很可能原本是一座湖泊，在亡靈瘟疫來襲時乾涸。如今它大半已經乾枯，成了大地上的一道傷口，深處棲息著由往昔的腐化所孕育出的軟泥怪。",
			source = "https://warcraft.wiki.gg/wiki/Pestilent_Scar",
		},
		["plaguewood"] = {
			name = "病木林",
			short = "斯坦索姆南邊的樹林曾經青翠而安寧，是一片與艾爾文森林頗為相似的林地，邊緣的石拱門附近還坐落著一座小村莊。",
			full = "斯坦索姆南邊的樹林曾經青翠而安寧，是一片與艾爾文森林頗為相似的林地，邊緣的石拱門附近還坐落著一座小村莊。當科爾蘇加德開始他的計畫時，正是在這裡，一名出生在那座村莊的羅德隆士兵莫里根中士，最先注意到來自安多哈爾的毒穀正在這片土地上作祟。他的警告對這個王國來說為時已晚，而他所看守的那條道路，正是阿薩斯王子後來前往斯坦索姆時所行經的路。\n\n此後留下的東西，已經不再是一座森林。土壤本身踩上去變得像海綿一樣鬆軟，蘑菇和毒蕈膨脹到大樹般的高度，高聳在舊日林地的殘跡之上。它們吐出一種深褐色的氣體，與天譴軍團瘟疫之鍋中升起的煙霧頗為相似，但沒有人能確定，這些真菌究竟只是生長在被污染的土地上，還是天譴軍團刻意培育它們，好讓疫病散播得更遠。這片樹林正是因為這番變化，才得到了它的新名字。",
			source = "https://warcraft.wiki.gg/wiki/Plaguewood",
		},
		["quellithien lodge"] = {
			name = "奎爾林斯小屋",
			short = "奎爾林斯小屋曾是奎爾薩拉斯附近的一處遠行者營地，一個溫暖而好客的地方。羅瑟瑪·瑟隆記得自己造訪時，它就是這個模樣，以此為家的同胞們總是熱情地迎接他。",
			full = "奎爾林斯小屋曾是奎爾薩拉斯附近的一處遠行者營地，一個溫暖而好客的地方。羅瑟瑪·瑟隆記得自己造訪時，它就是這個模樣，以此為家的同胞們總是熱情地迎接他。小屋裡曾經收藏著許多精靈文獻，其中有些與王室和銀月城的遊俠將軍有關。到了第二次大戰時，率領那裡獵手的是倫薩爾·鷹矛。",
			source = "https://warcraft.wiki.gg/wiki/Quel'Lithien_Lodge",
		},
		["scarlet base camp"] = {
			name = "血色十字軍營地",
			short = "在米雷達爾湖的東岸，離宗教堡壘提爾之手不遠處，血色十字軍營地矗立在路障之後，防禦工事經過加固，以應付任何可能的來犯者。",
			full = "在米雷達爾湖的東岸，離宗教堡壘提爾之手不遠處，血色十字軍營地矗立在路障之後，防禦工事經過加固，以應付任何可能的來犯者。",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Base_Camp",
		},
		["scarlet basilica"] = {
			name = "血色十字軍教堂",
			short = "血色十字軍教堂位於提爾之手城內，是血色十字軍信仰的最高殿堂，與附近的修道院以及遠在提里斯法林地的血色修道院緊密相連。",
			full = "血色十字軍教堂位於提爾之手城內，是血色十字軍信仰的最高殿堂，與附近的修道院以及遠在提里斯法林地的血色修道院緊密相連。掌管這裡的是十字軍領主瓦德瑪爾，他對十字軍志業的忠誠毫無保留。",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Basilica",
		},
		["stratholme"] = {
			name = "斯坦索姆",
			short = "斯坦索姆的毀滅始於穀物。從安多哈爾運來的糧食被詛咒神教暗中污染，烤成麵包，被渾然不知自己正走向死亡的居民吃下肚。",
			full = "斯坦索姆的毀滅始於穀物。從安多哈爾運來的糧食被詛咒神教暗中污染，烤成麵包，被渾然不知自己正走向死亡的居民吃下肚。阿薩斯·米奈希爾王子與光明使者烏瑟和珍娜·普勞德摩爾一同抵達時，瘟疫已經開始蔓延。阿薩斯相信，與其讓人們慢慢變成行屍走肉，痛快一死才是唯一剩下的仁慈，於是他下令焚城。烏瑟和珍娜拒絕服從，帶著他們的人馬撤離。阿薩斯卻沒有。大火席捲了街道，斯坦索姆幾乎每一個人都遭到殺害，而阿薩斯前來追殺的恐懼魔王瑪爾加尼斯卻笑著溜走了，留下王子去焚燒剩下的一切。\n\n但這樣還不夠。死者依然起身，這座城市成了天譴軍團在羅德隆的首都，先後由巫妖科爾蘇加德和死亡騎士瑞文戴爾男爵統治。\n\n斯坦索姆至今仍在燃燒。",
			source = "https://warcraft.wiki.gg/wiki/Stratholme",
		},
		["terrordale"] = {
			name = "恐懼谷",
			short = "恐懼谷位於病木林的邊緣，街道早已人去樓空，淪為天譴軍團和染上瘟疫的動物的地盤。只有商人精神失常的奧古斯圖斯和鬼魂獵人伊根還逗留在廢墟之中。",
			full = "恐懼谷位於病木林的邊緣，街道早已人去樓空，淪為天譴軍團和染上瘟疫的動物的地盤。只有商人精神失常的奧古斯圖斯和鬼魂獵人伊根還逗留在廢墟之中。\n\n這座城鎮鬧鬼。幽魂在巷弄間行走，在某些地方，恐懼谷本身彷彿搖搖欲墜，現實世界在彼方國度的重壓下扭曲變形，彷彿這片土地記得某種無法釋懷的古老折磨。\n\n正是這份不安，吸引了格雷森·沙東布瑞克公爵前來。他認為這些幽魂正適合用來考驗那些想證明自己配得上審判與犧牲的聖騎士，這是邁向獲得那些專為真正值得之人保留的戰馬的一步。這些幽魂生前是什麼人，並無記載，只知道他們所受的折磨真實得足以扭曲周圍的城鎮。",
			source = "https://warcraft.wiki.gg/wiki/Terrordale",
		},
		["terrorweb tunnel"] = {
			name = "惡蛛隧道",
			short = "這條隧道穿過恐懼谷西北方的山脈，一路向南延伸，直到與索多里爾河相接之處。",
			full = "這條隧道穿過恐懼谷西北方的山脈，一路向南延伸，直到與索多里爾河相接之處。奈幽地穴惡魔把整條通道塞得滿滿的，而在牠們之間，還潛伏著更可怕的東西：一隻奈幽監督者，比牠的同類致命得多。\n\n在隧道靠河的出口處，提里奧·弗丁守望著，從外頭的光明中直面通道裡的黑暗。",
			source = "https://warcraft.wiki.gg/wiki/Terrorweb_Tunnel",
		},
		["thondroril river"] = {
			name = "索多里爾河",
			short = "索多里爾河將西瘟疫之地與東瘟疫之地分隔開來。它發源於遙遠北方的惡蛛隧道附近，一路向南流，直到注入達隆米爾湖，再從湖的另一頭繼續流出，成為達隆米爾河。",
			full = "索多里爾河將西瘟疫之地與東瘟疫之地分隔開來。它發源於遙遠北方的惡蛛隧道附近，一路向南流，直到注入達隆米爾湖，再從湖的另一頭繼續流出，成為達隆米爾河。\n\n它的河岸屬於荒疫。蛆蟲和吸血蝙蝠擠滿了潮濕的地面，瘟疫熊和蜘蛛在淺灘間潛行，鉗嘴龜則潛伏在水流變緩的地方。",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["tyrs hand"] = {
			name = "提爾之手",
			short = "提爾之手是一座設有防禦工事的人類城市，也是這一帶生者對抗天譴軍團的最後幾座堡壘之一。",
			full = "提爾之手是一座設有防禦工事的人類城市，也是這一帶生者對抗天譴軍團的最後幾座堡壘之一。它周圍的環境比瘟疫之地的其他地方好得多，不過樹木和植物仍在逐漸凋零。\n\n這座城市是聖光教會最古老、最受尊崇的聖地之一，城中幾乎全是教堂，其中最宏偉的便是血色十字軍教堂和那座設防的修道院。\n\n當天譴軍團到來、東部林野化為瘟疫之地時，提爾之手並沒有陷落。在瓦德瑪爾領主的治理下，它每日抵禦著敵人的進攻，先是受到白銀之手騎士的保護，後來則由血色十字軍守衛，並將補給和援軍送往其他的血色十字軍據點。每天都有信使帶著來自斯坦索姆的報告，一路在瘟疫瀰漫的道路上殺出重圍，將消息送達這裡。",
			source = "https://warcraft.wiki.gg/wiki/Tyr's_Hand",
		},
		["undercroft"] = {
			name = "墓室",
			short = "墓室是位於東瘟疫之地西南部的一座地穴，裡頭住著由流亡者塞達爾率領的亡靈食人妖，塞達爾本身是一名死而復生的恐怖食人妖。",
			full = "墓室是位於東瘟疫之地西南部的一座地穴，裡頭住著由流亡者塞達爾率領的亡靈食人妖，塞達爾本身是一名死而復生的恐怖食人妖。他從這裡出發，襲擊銀色黎明在聖光之願禮拜堂的墓坑，把屍體偷走據為己有。",
			source = "https://warcraft.wiki.gg/wiki/Undercroft",
		},
		["zulmashar"] = {
			name = "祖瑪沙爾",
			short = "祖瑪沙爾曾是爛苔部族的首都，他們是住在東瘟疫之地東北部的森林食人妖。",
			full = "祖瑪沙爾曾是爛苔部族的首都，他們是住在東瘟疫之地東北部的森林食人妖。與羅德隆人類之間漫長的戰爭讓部族的土地陷入混亂，隨後而來的亡靈瘟疫更讓這裡陷入更深的毀滅。昔日統治此地的城市，如今只剩下往日榮光的一抹殘影。\n\n城中的金字形神塔瑪茲拉羅依然矗立在城市中心，如今由督軍瑟雷什金和祖布林·扭枝據守。然而爛苔部族自己的族人正在暗中被瘟疫轉化，祖瑪沙爾很可能淪為一座不過是亡靈據點的地方。",
			source = "https://warcraft.wiki.gg/wiki/Zul'Mashar",
		},
	},
	-- 希爾斯布萊德丘陵: 29 subzones
	[1424] = {
		["azurelode mine"] = {
