			name = "南點哨塔",
			short = "南點哨塔矗立在希爾斯布萊德丘陵的最西端，就在通往銀松森林的道路南邊。",
			full = "南點哨塔矗立在希爾斯布萊德丘陵的最西端，就在通往銀松森林的道路南邊。石造結構老舊龜裂，是一座被棄置荒廢的瞭望哨，不過塔身本身從未在途經此地的戰火中倒下。附近還有另一座未標示名稱的塔，矗立在塔倫米爾和南海鎮之間，同樣逃過了席捲丘陵其他地方的毀滅。",
			source = "https://warcraft.wiki.gg/wiki/Southpoint_Tower",
		},
		["strahnbrad"] = {
			name = "斯坦恩布萊德",
			short = "斯坦恩布萊德坐落在奧特蘭克山脈東北方的丘陵上，鎮公所和鐵匠鋪如今都已空無一人。",
			full = "斯坦恩布萊德坐落在奧特蘭克山脈東北方的丘陵上，鎮公所和鐵匠鋪如今都已空無一人。這裡曾經屬於奧特蘭克王國，第二次大戰之後則落入羅德隆手中。\n\n這座小鎮的毀滅始於第三次大戰前不久，當時黑石獸人突襲這裡，擄掠奴隸，要將他們獻祭給燃燒軍團。斯坦恩布萊德只有寥寥幾名步兵可以守衛，但消息及時傳到了白銀之手騎士團那裡。光明使者烏瑟策馬先行，試圖攔截這次攻擊，而阿薩斯·米奈希爾王子則被派去守住小鎮本身。阿薩斯沒能及時趕到。在他抵達斯坦恩布萊德之前，迪恩、喬、麥克、史考特和其他許多人已經遇害，而倖存的守軍與他一起擊潰了獸人，並殺死了率領這次突襲的奴隸主。聯盟贏得了這場戰鬥，但斯坦恩布萊德的居民早已不在了。\n\n後來，辛迪加將這座殘破的小鎮據為己有，把它當作奪取奧特蘭克山脈的據點，並將獸人高迪爾關在其中一間牢房裡，把他當成奴隸，驅使他搬運、挖掘。",
			source = "https://warcraft.wiki.gg/wiki/Strahnbrad",
		},
		["tarren mill"] = {
			name = "塔倫米爾",
			short = "塔倫米爾曾經是羅德隆一座樸素的小鎮，坐落在奧特蘭克山脈下方的草原上。",
			full = "塔倫米爾曾經是羅德隆一座樸素的小鎮，坐落在奧特蘭克山脈下方的草原上。第二次大戰初期，一批從銀月城派往南方、親眼察看獸人威脅的高等精靈弓箭手，在小鎮附近遭到伏擊，被拖到附近的一座囚禁營裡。泰瑞納斯國王派遣聯盟士兵前去解救他們，營救行動大獲成功。正是這次成功，促使銀月議會讓奎爾薩拉斯的軍隊加入了羅德隆聯盟。\n\n塔倫米爾並沒有一直留在人類手中。被遺忘者後來奪取了這裡，並讓它維持著他們其他據點一貫的模樣：一座教堂、幾棟零散的房屋、早已腐爛的果園，一切都還立著，卻沒有一樣是完整的。被遺忘者從這裡發動對抗南海鎮和丹加洛克聯盟部隊的戰爭，而塔倫米爾和南海鎮之間的土地，也因兩鎮之間一場又一場的小規模衝突而惡名昭彰，雙方誰也無法擊垮對方。",
			source = "https://warcraft.wiki.gg/wiki/Tarren_Mill",
		},
		["thoradins wall"] = {
			name = "索拉丁之牆",
			short = "索拉丁國王築起這道城牆，用來抵擋阿曼尼食人妖，那時激流堡還很年輕，阿拉索才剛剛為人類奪得這片土地。",
			full = "索拉丁國王築起這道城牆，用來抵擋阿曼尼食人妖，那時激流堡還很年輕，阿拉索才剛剛為人類奪得這片土地。世世代代以來，它始終是一名堅定的哨兵，一道任何食人妖大軍都無法跨越的防線。\n\n數百年後，它依然屹立，卻已嚴重損毀，石塊碎裂，它漫長的守望也淪為一片廢墟。",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["western strand"] = {
			name = "西部海岸",
			short = "西部海岸位於希爾斯布萊德丘陵的西南海岸。碎鰭魚人沿著海岸建起了小型營地，而安迪·莫格爾則在這片水域巡邏，監視著他們棲息的海岸線。",
			full = "西部海岸位於希爾斯布萊德丘陵的西南海岸。碎鰭魚人沿著海岸建起了小型營地，而安迪·莫格爾則在這片水域巡邏，監視著他們棲息的海岸線。",
			source = "https://warcraft.wiki.gg/wiki/Western_Strand",
		},
	},
	-- 辛特蘭: 20 subzones
	[1425] = {
		["aerie peak"] = {
			name = "鷹巢山",
			short = "蠻錘矮人一開始並沒有選擇辛特蘭。",
			full = "蠻錘矮人一開始並沒有選擇辛特蘭。他們的家園原本是深藏於山中的格瑞姆巴托，直到三錘之戰結束，矮人們回來時才發現，莫德古得之死已經污染了他們的要塞。格瑞姆巴托再也無法居住。於是蠻錘矮人在這裡重新建設家園，這一次建在山坡頂上，而不是山體內部，因為經歷過與黑鐵矮人在坑道中廝殺的恐怖之後，他們不願再把自己埋進岩石之中。鷹巢之所以向天空敞開，正是因為那場戰爭。\n\n正是從這裡，庫德蘭·蠻錘率領他的獅鷲騎士，迎戰被派來佯攻辛特蘭的獸人部隊，而真正的部落大軍則正向奎爾薩拉斯推進。安度因·洛薩的部隊前來援助他，協助將獸人和森林食人妖逐出蠻錘矮人的領地，為此，庫德蘭讓他的部族宣誓效忠聯盟。\n\n庫德蘭一去不返之後，弗斯塔德·蠻錘被留下來擔任高階領主，至今仍統治著鷹巢。辛特蘭的森林食人妖將蠻錘矮人視為占據祖先土地的外來者，至今仍不斷襲擊獅鷲的巢穴，而奎爾丹尼的高等精靈則依然是矮人對抗這個共同敵人的盟友。",
			source = "https://warcraft.wiki.gg/wiki/Aerie_Peak",
		},
		["agolwatha"] = {
			name = "亞戈瓦薩",
			short = "亞戈瓦薩的石塊，比最後一批將它們奉為神聖的食人妖還要古老，那是阿曼尼帝國衰亡之前所建造的一座神廟。",
			full = "亞戈瓦薩的石塊，比最後一批將它們奉為神聖的食人妖還要古老，那是阿曼尼帝國衰亡之前所建造的一座神廟。後來的邪枝食人妖將這片廢墟據為己有。如今神廟已被活化的軟泥占據，擠滿了它殘破的庭院。",
			source = "https://warcraft.wiki.gg/wiki/Agol'watha",
