		["hiriwatha"] = {
			name = "西利瓦薩",
			short = "枯木食人妖占據著西利瓦薩，這座村落位於辛特蘭奎爾丹尼小屋的南邊，深藏在他們視為己有的森林之中。",
			full = "枯木食人妖占據著西利瓦薩，這座村落位於辛特蘭奎爾丹尼小屋的南邊，深藏在他們視為己有的森林之中。",
			source = "https://warcraft.wiki.gg/wiki/Hiri'watha",
		},
		["jinthaalor"] = {
			name = "辛薩羅",
			short = "辛薩羅層層疊疊地聳立在辛特蘭之上，在森林食人妖的城市中，規模僅次於祖阿曼。",
			full = "辛薩羅層層疊疊地聳立在辛特蘭之上，在森林食人妖的城市中，規模僅次於祖阿曼。它建於阿曼尼帝國的時代，名字取自阿曼尼古代的領袖之一辛薩。\n\n這座城市屬於邪枝部族，他們將城市的高處變成了一座獻祭的堡壘。邪惡祭司海克斯在那裡侍奉奪魂者哈卡，進行統治，而邪枝食人妖毫不留情地獵殺較弱小的惡齒部族，來餵飽他們神靈的飢渴。惡齒部族的斷齒長者就是在一次這樣的襲擊中被擄走，至今仍被囚禁在城中；他的衛兵隊長獵人馬克霍爾也在同一場襲擊中被俘並遭到處決，遺骸被丟給城牆內飼養的狼群和軟泥怪。\n\n蠻錘部族和惡齒部族因為對邪枝食人妖同仇敵愾而結為一體，共同圍攻這座城市，試圖終結邪枝的襲擊，並為他們的死者報仇。",
			source = "https://warcraft.wiki.gg/wiki/Jintha'Alor",
		},
		["overlook cliffs"] = {
			name = "望海崖",
			short = "望海崖標示著辛特蘭從山脈化為天空的地方。",
			full = "望海崖標示著辛特蘭從山脈化為天空的地方。蜿蜒流經這一帶的大河在這裡匯聚，從懸崖邊緣傾瀉而下，化作一道壯闊的瀑布，落向下方的海岸。\n\n這些懸崖陡峭，而且高得令人難以察覺。許多走到崖邊的人都錯估了落差，墜崖身亡。",
			source = "https://warcraft.wiki.gg/wiki/Overlook_Cliffs",
		},
		["plaguemist ravine"] = {
			name = "毒霧峽谷",
			short = "在奎爾丹尼小屋以西、山壁裂開之處，籠罩著一層霧氣，標示出這道向北切向凱爾達隆的峽谷。這條通道裡沒有任何活物。",
			full = "在奎爾丹尼小屋以西、山壁裂開之處，籠罩著一層霧氣，標示出這道向北切向凱爾達隆的峽谷。這條通道裡沒有任何活物。沒有飛鳥從上方飛過，也沒有野獸在它的岩石間築巢。\n\n周圍的辛特蘭依然青翠潔淨，這道峽谷吐出的卻是另一種東西，一種不屬於這片森林的霧靄。這正是它如今名字的由來：毒霧，這個名字來自那片病懨懨的霧氣，它污染了這唯一的一條路徑，而周圍的土地卻絲毫未受侵擾。",
			source = "https://warcraft.wiki.gg/wiki/Plaguemist_Ravine",
		},
		["queldanil lodge"] = {
			name = "奎爾丹尼小屋",
			short = "奎爾丹尼小屋是高等精靈最後幾處真正的聚落之一，也是羅德隆僅存的兩處這類聚落中較大的一處。",
			full = "奎爾丹尼小屋是高等精靈最後幾處真正的聚落之一，也是羅德隆僅存的兩處這類聚落中較大的一處。第三次大戰之後，這裡成了一處聯絡據點，精靈的使者從這裡向聯盟的其他種族伸出友誼之手。這番交流為高原精靈贏得了與蠻錘矮人的同盟，也為他們招來了惡齒食人妖的仇恨，後者一心想看到精靈遭到屠殺、文獻付之一炬。這些文件最終保存了下來，其中記載著死亡、誕生、四季更迭，以及精靈們締結過的每一份條約。",
			source = "https://warcraft.wiki.gg/wiki/Quel'Danil_Lodge",
		},
		["revantusk village"] = {
			name = "惡齒村",
			short = "惡齒村坐落在辛特蘭的海岸上，是一個選擇了忠誠而非苟存的森林食人妖部族最後的家園。",
			full = "惡齒村坐落在辛特蘭的海岸上，是一個選擇了忠誠而非苟存的森林食人妖部族最後的家園。\n\n第二次大戰中舊部落瓦解時，擄獲獸人的那些人轉而對付他們昔日的盟友，各地的森林食人妖部族毫不猶豫地拋棄了部落。惡齒部族卻沒有。他們人數不足，無法解救被俘的獸人，何況那些獸人本身也幾乎沒有獲救的意願，但他們始終如一的忠誠，讓其他不想再與獸人有任何瓜葛的食人妖將他們視為攻擊的目標。被逐出家園的惡齒部族逃到辛特蘭的海岸，希望與世隔絕能保他們平安，並在那裡建起了自己的村落。\n\n後來，消息終於傳到他們耳中：索爾重建了部落，並帶領他的族人回歸祖先的薩滿之道。惡齒部族派出他們跑得最快的信使去尋找他，而那次會面的結果，便是部族與新部落之間締結的友好盟約。其他森林食人妖從未原諒這件事，斥責惡齒部族軟弱又奸詐，而惡齒部族則認為，所有背棄部落的人才是真正的叛徒。",
			source = "https://warcraft.wiki.gg/wiki/Revantusk_Village",
		},
		["seradane"] = {
			name = "瑟拉丹",
			short = "辛特蘭東北部坐落著瑟拉丹，那裡有一座巨大的環形傳送門，向翡翠夢境敞開。這片森林屬於綠龍軍團，他們被吸引到這裡，守護著他們族類視為神聖的門檻。",
			full = "辛特蘭東北部坐落著瑟拉丹，那裡有一座巨大的環形傳送門，向翡翠夢境敞開。這片森林屬於綠龍軍團，他們被吸引到這裡，守護著他們族類視為神聖的門檻。幼龍洛索斯和夢境追蹤者在這片樹林中安家。\n\n看守這片樹林的大多是龍人，由龍族的力量所生。他們以三人為一組行動，一名翠綠先知由枝葉守衛和樹木守衛隨侍左右，在糾結的小徑間巡邏，持續守望著通往夢境的道路。",
			source = "https://warcraft.wiki.gg/wiki/Seradane",
		},
		["shadraalor"] = {
			name = "沙德拉洛",
			short = "辛特蘭矗立著沙德拉洛，一座由阿曼尼帝國的森林食人妖建立的聚落。在這裡，可以呼喚並召喚洛阿神靈沙德拉降臨，這是一處專為此目的而設的地方。",
			full = "辛特蘭矗立著沙德拉洛，一座由阿曼尼帝國的森林食人妖建立的聚落。在這裡，可以呼喚並召喚洛阿神靈沙德拉降臨，這是一處專為此目的而設的地方。",
			source = "https://warcraft.wiki.gg/wiki/Shadra'Alor",
		},
		["shaolwatha"] = {
			name = "沙爾瓦薩",
			short = "沙爾瓦薩是邪枝森林食人妖位於辛特蘭東北部的一座廢墟。它曾經是一座神廟。",
			full = "沙爾瓦薩是邪枝森林食人妖位於辛特蘭東北部的一座廢墟。它曾經是一座神廟。",
			source = "https://warcraft.wiki.gg/wiki/Shaol'watha",
