		["shindiggers camp"] = {
			name = "拉普索迪營地",
			short = "嗜酒的矮人拉普索迪·鐵鏟，與高等精靈基沃拉丁·獵日者一起，在辛特蘭守著他的小營地，這對奇特的組合守著這片寧靜的土地。",
			full = "嗜酒的矮人拉普索迪·鐵鏟，與高等精靈基沃拉丁·獵日者一起，在辛特蘭守著他的小營地，這對奇特的組合守著這片寧靜的土地。",
			source = "https://warcraft.wiki.gg/wiki/Shindigger's_Camp",
