		["skulk rock"] = {
			name = "隱匿石",
			short = "隱匿石是一座被軟泥占據的森林食人妖廢墟。它底下的洞穴是少數幾個仍能長出鬼魂菇的地方之一。",
			full = "隱匿石是一座被軟泥占據的森林食人妖廢墟。它底下的洞穴是少數幾個仍能長出鬼魂菇的地方之一。\n\n第二次大戰期間，舊部落曾把這塊岩石當作基地，直到羅德隆聯盟將他們驅逐出去。",
			source = "https://warcraft.wiki.gg/wiki/Skulk_Rock",
