		["valorwind lake"] = {
			name = "瓦羅溫湖",
			short = "瓦羅溫湖靜靜地躺在沙德拉洛的東北方，湖水看似平凡無奇。",
			full = "瓦羅溫湖靜靜地躺在沙德拉洛的東北方，湖水看似平凡無奇。然而在它的湖畔，卻生長著一種在已知世界中別無他處可尋的東西：紫色水生菇，一種神秘的蘑菇，它的秘密至今仍無人知曉。",
