	-- 丹莫洛: 25 subzones
	[1426] = {
		["amberstill ranch"] = {
			name = "凍石農場",
			short = "凍石農場位於通往洛克莫丹的道路旁，在古博拉採掘場的北邊，凍石家族的矮人們在這裡飼養牲畜，抵禦丹莫洛的嚴寒。",
			full = "凍石農場位於通往洛克莫丹的道路旁，在古博拉採掘場的北邊，凍石家族的矮人們在這裡飼養牲畜，抵禦丹莫洛的嚴寒。魯德拉·凍石在這裡培育珍貴的山羊，而年幼的雅琳則讓她的雪靴兔在腳邊跑來跑去。\n\n這些牲畜並非無憂無慮。一隻名叫瓦加什的雪怪開始獵捕農場的動物，凍石一家不得不保護自己飼養的牲畜，抵擋牠的飢餓。",
			source = "https://warcraft.wiki.gg/wiki/Amberstill_Ranch",
		},
		["anvilmar"] = {
			name = "安威瑪",
			short = "寒脊山谷中矗立著安威瑪，一座圍繞著巨大鍛爐建造的大廳。它是矮人在這片北方地區建立的第一座真正的聚落，早在其他聚落成形之前，就已是人們聚集的地方。",
			full = "寒脊山谷中矗立著安威瑪，一座圍繞著巨大鍛爐建造的大廳。它是矮人在這片北方地區建立的第一座真正的聚落，早在其他聚落成形之前，就已是人們聚集的地方。它中心的鍛爐至今仍在燃燒，儘管如今已經沒有鐵匠在那裡傳授技藝。",
			source = "https://warcraft.wiki.gg/wiki/Anvilmar",
		},
		["brewnall village"] = {
			name = "烈酒村",
			short = "烈酒村位於諾姆瑞根附近的寒風峽谷，是麥酒家族的家園。麥酒一家全心投入一項追求：讓矮人的釀酒技藝臻於完美。",
			full = "烈酒村位於諾姆瑞根附近的寒風峽谷，是麥酒家族的家園。麥酒一家全心投入一項追求：讓矮人的釀酒技藝臻於完美。他們派出家中的年輕人離開村子，保護村莊免受野獸侵擾，並尋找稀有的原料，以釀出終極的麥酒。",
			source = "https://warcraft.wiki.gg/wiki/Brewnall_Village",
		},
		["chill breeze valley"] = {
			name = "寒風峽谷",
			short = "寒風峽谷由東向西延伸在諾姆瑞根和卡拉諾斯之間，年輕的矮人和地精經常往來其間，早已把這條路走得熟悉無比。",
			full = "寒風峽谷由東向西延伸在諾姆瑞根和卡拉諾斯之間，年輕的矮人和地精經常往來其間，早已把這條路走得熟悉無比。但這座峽谷也向南北兩側彎折，而在那裡，積雪訴說著另一個故事：血跡大片大片地染紅了雪地，撕碎的動物屍體被丟棄在一旁。很少有人願意走上這條岔路。那些真的前往的人，是去獵殺罪魁禍首的野獸，希望終結牠們對矮人土地的威脅，而其中許多人再也沒有回來。在其中一座洞穴的深處，盤踞著一隻雪怪，雪地上的鮮血大多要算在牠頭上。",
			source = "https://warcraft.wiki.gg/wiki/Chill_Breeze_Valley",
		},
		["coldridge pass"] = {
			name = "寒脊山小徑",
			short = "寒脊山小徑是離開寒脊山谷的狹窄通道，也是矮人抵達卡拉諾斯和丹莫洛更寬闊的道路之前，必須穿越的最後一段路。",
			full = "寒脊山小徑是離開寒脊山谷的狹窄通道，也是矮人抵達卡拉諾斯和丹莫洛更寬闊的道路之前，必須穿越的最後一段路。穴居人占據了這條小徑，旅人只剩下兩個選擇：拔腿以最快的速度跑過去，或是在入侵者之間殺出一條血路。\n\n芬德里格·紅鬚曾經帶領另外十二名礦工進入小徑，調查這場侵擾。在深處，他被一場落石壓住。其他人掉頭回去想把他挖出來，這番努力卻讓整條小徑在他們周圍坍塌。十二名礦工喪生。只有被從瓦礫中拉出來的芬德里格倖存下來。",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Pass",
		},
		["coldridge valley"] = {
			name = "寒脊山谷",
			short = "寒脊山谷覆蓋著厚厚的積雪，四面都被山壁環繞，唯一的出路是東北方寒脊山小徑那條狹窄的隧道。",
			full = "寒脊山谷覆蓋著厚厚的積雪，四面都被山壁環繞，唯一的出路是東北方寒脊山小徑那條狹窄的隧道。那條通道裡充斥著穴居人掠奪者，這些野蠻的東西長久以來讓任何獨自前往卡拉諾斯和鐵爐堡的人都路途兇險。\n\n穿過小徑之後，道路先向東攀升，再向北穿過卡拉諾斯，然後蜿蜒穿越群山，一路通往鐵爐堡的大門。",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Valley",
		},
		["frostmane hold"] = {
			name = "霜鬃食人妖要塞",
			short = "霜鬃食人妖要塞矗立在丹莫洛寒冷山脈的西緣，位於諾姆瑞根的南邊，是一群零散的建築，與深入山腹的洞穴系統相連。",
			full = "霜鬃食人妖要塞矗立在丹莫洛寒冷山脈的西緣，位於諾姆瑞根的南邊，是一群零散的建築，與深入山腹的洞穴系統相連。這裡是霜鬃冰霜食人妖的大本營，他們派出獵頭者和剝皮者守住每一條通路，據守著這片土地。",
			source = "https://warcraft.wiki.gg/wiki/Frostmane_Hold",
		},
		["gates of ironforge"] = {
			name = "鐵爐堡大門",
			short = "鐵爐堡大門聳立在丹莫洛的巨大坡道向上攀升、與山體相接之處，旅人還沒走到跟前，就能在數哩外的雪原上望見它們。",
			full = "鐵爐堡大門聳立在丹莫洛的巨大坡道向上攀升、與山體相接之處，旅人還沒走到跟前，就能在數哩外的雪原上望見它們。它們是開闊的矮人領地與鐵爐堡本身之間的門檻。\n\n穿過大門，便會迎來一尊巨大雕像的注視，那是為至高王莫迪姆斯·安威瑪而立的雕像，就安放在入口內側守望，讓任何人進城之前，都必須先從他的目光之下走過。",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
		["gnomeregan"] = {
			name = "諾姆瑞根",
			short = "諾姆瑞根是同名地精王國的地下首都，以鍛鐵鑄就，見證著地精的才華、雄心與巧思。",
			full = "諾姆瑞根是同名地精王國的地下首都，以鍛鐵鑄就，見證著地精的才華、雄心與巧思。\n\n第三次大戰期間，一場穴居人的入侵導致了它的覆滅。泰坦遺址的動盪將穴居人從沉睡中喚醒，牠們從地底蜂擁而上，湧入城中。為了孤注一擲地殺死入侵者，大工匠格爾賓·梅卡托克聽從了他的顧問希科·瑟瑪普拉格的建議，命令他的子民打開巨大研磨機器的壓力閥，在整座諾姆瑞根釋放出有毒的輻射。毒氣雖然殺死了一些穴居人，卻只讓其他穴居人變得更強，而將近八成的地精在幾天之內喪命。倖存者逃到鐵爐堡尋求庇護。其他人則被扭曲成了可怕、無知無覺、作惡多端的麻瘋地精，至今仍在殘破的隧道中出沒。\n\n瑟瑪普拉格本人也被輻射逼瘋了，他自封為「諾姆瑞根之王」，奪取了這座被污染的城市，率領一支由穴居人和麻瘋地精組成的軍隊，穿梭在殘破的大廳與工坊之間。",
			source = "https://warcraft.wiki.gg/wiki/Gnomeregan",
		},
		["golbolar quarry"] = {
			name = "古博拉採掘場",
			short = "古博拉採掘場深挖在丹莫洛的東南部，是一座因為從地底爬上來的東西而被迫中斷的採礦營地。",
			full = "古博拉採掘場深挖在丹莫洛的東南部，是一座因為從地底爬上來的東西而被迫中斷的採礦營地。矮人們開挖這裡，想找出山中蘊藏的寶藏，但挖掘卻驚醒了穴居人，牠們從礦坑深處蜂擁而上，占據了礦工們開鑿的礦坑和隧道。\n\n留下來的營地只是一個立足點，而不是一場勝利：矮人守住了地面，而下方的礦坑依然落在穴居人手中。",
			source = "https://warcraft.wiki.gg/wiki/Gol'Bolar_Quarry",
		},
		["grizzled den"] = {
			name = "灰色洞穴",
			short = "卡拉諾斯西南方有一座巨大的洞穴系統，深深切入丹莫洛的冰層。雪怪在這裡築巢，這些毛髮蓬亂、口吐寒氣的野獸會群起對付任何闖入者。",
			full = "卡拉諾斯西南方有一座巨大的洞穴系統，深深切入丹莫洛的冰層。雪怪在這裡築巢，這些毛髮蓬亂、口吐寒氣的野獸會群起對付任何闖入者。牠們的鬃毛被視為製作座墊的上等材料，但進去獵捕牠們的人很少能不經一番搏鬥就全身而退，因為雪怪不會四散逃竄，而是會團結起來，用利爪和冰凍的吐息把入侵者趕出去。",
			source = "https://warcraft.wiki.gg/wiki/Grizzled_Den",
		},
		["helms bed lake"] = {
			name = "盔枕湖",
			short = "盔枕湖一年之中大部分時間都處於冰封狀態，湖面結著厚厚的冰層，足以讓人安心地在上面行走。只有一個冰洞一直保持開放，是為了讓人們仍能從冰層下汲取清水而鑿開的。",
			full = "盔枕湖一年之中大部分時間都處於冰封狀態，湖面結著厚厚的冰層，足以讓人安心地在上面行走。只有一個冰洞一直保持開放，是為了讓人們仍能從冰層下汲取清水而鑿開的。\n\n安全在岸邊便戛然而止。狼群和其他野生動物在湖岸上遊蕩，零星的穴居人在周圍的岩石間出沒。湖的南邊有一棟被黑鐵矮人占據的廢棄建築，他們會攻擊任何靠得太近的人。",
			source = "https://warcraft.wiki.gg/wiki/Helm's_Bed_Lake",
		},
		["iceflow lake"] = {
			name = "湧冰湖",
			short = "湧冰湖在丹莫洛的嚴寒中凍得堅硬，但烈酒村的矮人們在冰面上鑿開了一個冰洞，從冰封的湖面下汲取清水、捕撈魚獲。",
			full = "湧冰湖在丹莫洛的嚴寒中凍得堅硬，但烈酒村的矮人們在冰面上鑿開了一個冰洞，從冰封的湖面下汲取清水、捕撈魚獲。\n\n在湖心的方向聳立著兩座小島，最好別去招惹。一群飢餓的狼占據了島嶼，由一隻名叫提姆伯的座狼帶領，牠們的存在讓這兩座島上除了占據它們的野獸之外，空無一物。",
			source = "https://warcraft.wiki.gg/wiki/Iceflow_Lake",
		},
		["ironbands compound"] = {
			name = "鐵環營地",
			short = "在盔枕湖的南邊，鐵環營地是黑鐵矮人的一處據點，他們會攻擊任何靠得太近的人。在落入黑鐵矮人手中之前，這個地方曾經屬於斯塔基·鐵環。",
			full = "在盔枕湖的南邊，鐵環營地是黑鐵矮人的一處據點，他們會攻擊任何靠得太近的人。在落入黑鐵矮人手中之前，這個地方曾經屬於斯塔基·鐵環。",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Compound",
		},
		["kharanos"] = {
			name = "卡拉諾斯",
			short = "卡拉諾斯坐落在丹莫洛的群峰之間，街道四周環繞著冰天雪地的荒野，從不讓鎮民過得安逸。",
			full = "卡拉諾斯坐落在丹莫洛的群峰之間，街道四周環繞著冰天雪地的荒野，從不讓鎮民過得安逸。鎮中心燃燒著一座鍛爐，一間地精工坊叮噹作響，雷酒釀製廠則供應著在任何地方都堪稱極品的麥酒，但這座小鎮從來無法安然沉浸在自身的魅力之中。西邊有一座擠滿雪怪的洞穴，西北方則有霜鬃食人妖占據著閃光嶺，監視著下方的小鎮。\n\n那樣的監視曾經演變成戰爭：一隻巨大的霜鬃食人妖襲擊了卡拉諾斯，險些殺光鎮上所有的矮人。在鎮上的守衛動搖之際，有一名矮人卻沒有退縮。拉茲洛·磨齒挺身對抗那隻食人妖，獨自將牠擊倒，小鎮因此尊他為英雄，這個稱號從此便一直跟隨著他，走遍那些至今仍記得自己曾經多麼接近死寂的街道。",
			source = "https://warcraft.wiki.gg/wiki/Kharanos",
		},
		["misty pine refuge"] = {
			name = "霧松避難所",
			short = "霧松避難所靜靜地坐落在丹莫洛中部，是一片被積雪壓枝的松樹所環繞、遮風避雪的空地。",
			full = "霧松避難所靜靜地坐落在丹莫洛中部，是一片被積雪壓枝的松樹所環繞、遮風避雪的空地。",
			source = "https://warcraft.wiki.gg/wiki/Misty_Pine_Refuge",
		},
		["north gate outpost"] = {
			name = "北門崗哨",
			short = "北門崗哨橫跨在北門小徑上，這條穿越群山的狹窄通道連接著丹莫洛和洛克莫丹，而這座崗哨則是這片高地上位置最偏東北的矮人要塞。",
