		["blackrock pass"] = {
			name = "黑石小徑",
			short = "黑石小徑是兩個世界之間的門檻。一邊是赤脊山，青翠而寧靜。另一邊則是燃燒平原，焦黑扭曲得面目全非。",
			full = "黑石小徑是兩個世界之間的門檻。一邊是赤脊山，青翠而寧靜。另一邊則是燃燒平原，焦黑扭曲得面目全非。邊界上立著一道大門，清楚地標示出這條界線。\n\n穿過它，只要一步，就把安全拋在了身後。那些毫無準備就闖過去的人會發現，這種轉變是殘酷的：另一邊的生物，遠比身後山中出沒的任何東西都要兇殘得多。",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Pass",
