		["blackrock stronghold"] = {
			name = "黑石要塞",
			short = "這座要塞聳立在燃燒平原的邊緣，緊貼著黑石塔的陰影，是一座由黑石氏族據守的黑色石造堡壘。",
			full = "這座要塞聳立在燃燒平原的邊緣，緊貼著黑石塔的陰影，是一座由黑石氏族據守的黑色石造堡壘。在城牆外的榮耀之地，氏族的戰士和他們的盟友在此集結操練，由黑石中士以皮鞭和吼聲維持紀律。\n\n要塞的指揮權落在索格伊佐格將軍手中，他管教著聚集在原野上的部隊，確保他的命令被毫無疑問地執行。",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Stronghold",
