		["ruins of thaurissan"] = {
			name = "索瑞森廢墟",
			short = "這片燃燒平原上的灰燼曠野，昔日曾是一片青翠，而此處的城市則以其建立者為名：索瑞森城，黑鐵氏族的首都。三錘之戰期間，黑鐵氏族被逐出鐵爐堡，由巫士親王索瑞森率領南遷至此。",
			full = "這片燃燒平原上的灰燼曠野，昔日曾是一片青翠，而此處的城市則以其建立者為名：索瑞森城，黑鐵氏族的首都。三錘之戰期間，黑鐵氏族被逐出鐵爐堡，由巫士親王索瑞森率領南遷至此。\n\n黑鐵氏族在那場戰爭中節節敗退。他們的大軍才剛在另外兩個氏族的要塞前潰敗，絕望的索瑞森為了扭轉戰局，召集了七名最信任的矮人，向沉睡於大地之下的力量呼喚，祈求一名能助他贏回戰爭的僕從。然而回應他的並非僕從，而是火焰元素領主拉格納羅斯。他的降臨化作一座火山，撕裂了群山，將整座山谷燒成灰燼。城市就此毀滅，倖存的黑鐵矮人淪為炎魔之王的奴隸。他們捨棄了廢墟，在黑石山下建立新的家園，於是在索瑞森的灰燼之上，崛起了黑石塔與一個新的黑鐵王國。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Thaurissan",
		},
		["slither rock"] = {
