	-- 艾爾文森林: 23 subzones
	[1429] = {
		["brackwell pumpkin patch"] = {
			name = "布萊克威爾南瓜田",
			short = "艾爾文森林東南方有一座農場，昔日屬於布萊克威爾一家。他們後來的下落，無人能說得清。",
			full = "艾爾文森林東南方有一座農場，昔日屬於布萊克威爾一家。他們後來的下落，無人能說得清。迪菲亞兄弟會將這地方據為己有，而布萊克威爾一家就這樣從田地與籬笆之間消失無蹤。\n\n關於他們，只留下一段記憶：一頭名叫「公主」的得獎母豬。早在盜匪到來之前，她便夜復一夜偷偷溜到鄰近的斯通菲爾德農場偷吃蔬菜，把自己養得碩大無比。",
			source = "https://warcraft.wiki.gg/wiki/Brackwell_Pumpkin_Patch",
		},
		["crystal lake"] = {
			name = "水晶湖",
			short = "水晶湖位於閃金鎮東方，湖中魚人成群，讓湖岸成了粗心大意者的險地。一座人類農舍在南岸守望著湖水。",
			full = "水晶湖位於閃金鎮東方，湖中魚人成群，讓湖岸成了粗心大意者的險地。一座人類農舍在南岸守望著湖水。",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Lake",
		},
		["eastvale logging camp"] = {
			name = "東谷伐木場",
			short = "東谷的伐木營地散布於艾爾文森林東部，住所就搭在一座座鋸木坑之間，而這裡的工作從未真正停歇過。",
			full = "東谷的伐木營地散布於艾爾文森林東部，住所就搭在一座座鋸木坑之間，而這裡的工作從未真正停歇過。木材訂單湧入的速度遠超過交期所能負荷，伐木工人們在等著暴風城木材的買主不斷催促之下辛勤勞動。\n\n曾經統領暴風城衛兵的治安官哈迦德，數年前卸下了職務，選擇在營地中的一座宅邸安度餘生，而非待在他昔日守護的城市裡。席婭·諾斯布魯克也是在這裡長大的。\n\n森林從四面八方逼近，其中的野性不容小覷。狼群與熊一再侵擾伐木工人，驅散工作隊伍，險些讓營地的交期全數落空。情勢嚴峻到暴風城衛兵不得不向外求援，協助獵殺這些野獸。",
			source = "https://warcraft.wiki.gg/wiki/Eastvale_Logging_Camp",
		},
		["echo ridge mine"] = {
			name = "回音山礦坑",
			short = "回音山礦坑的坑道位於北郡山谷西北方。",
			full = "回音山礦坑的坑道位於北郡山谷西北方。狗頭人蜂擁佔據了礦井，據為己有，令附近的人類居民頭痛不已，而治安官瑪克布萊德能做的，也只有一次又一次派人去削減牠們的數量。",
			source = "https://warcraft.wiki.gg/wiki/Echo_Ridge_Mine",
		},
		["fargodeep mine"] = {
			name = "法戈第礦坑",
			short = "法戈第礦坑曾為暴風城開採黃金，礦井深深鑿入艾爾文森林的土地之中。如今礦坑已遭廢棄，坑道被一個狗頭人部族佔據。",
			full = "法戈第礦坑曾為暴風城開採黃金，礦井深深鑿入艾爾文森林的土地之中。如今礦坑已遭廢棄，坑道被一個狗頭人部族佔據。下層礦坑位於主礦區底下更深處，一路延伸進更幽深的黑暗。\n\n守護艾爾文安全的治安官杜漢，在確認礦坑內有狗頭人出沒後，便增派了周遭的巡邏隊。狗頭人之中潛伏著金牙，牠持有一條從波尼斯·斯通菲爾德姑媽那裡偷來的項鍊，那是她的紀念品，她至今仍未放棄尋回它的希望。",
			source = "https://warcraft.wiki.gg/wiki/Fargodeep_Mine",
		},
		["forests edge"] = {
			name = "林邊空地",
			short = "林邊空地位於暴風城西南方，是一片狹長的林地，夾在明鏡湖果園、納菲瑞提河，以及一條流向西部荒野的小溪之間。",
			full = "林邊空地位於暴風城西南方，是一片狹長的林地，夾在明鏡湖果園、納菲瑞提河，以及一條流向西部荒野的小溪之間。野豬在灌木叢中翻土覓食，河岸沿線則有銅礦脈延伸。這片森林屬於一群豺狼人，而其中有一個絕非尋常的獸類。霍格在較弱小的豺狼人之間巡行於林間，牠可不是什麼普通的野狗。",
			source = "https://warcraft.wiki.gg/wiki/Forest's_Edge",
		},
		["goldshire"] = {
			name = "閃金鎮",
			short = "閃金鎮座落於艾爾文森林的中心，田野可遙望北郡，道路則通往暴風城、西部荒野與赤脊山。",
			full = "閃金鎮座落於艾爾文森林的中心，田野可遙望北郡，道路則通往暴風城、西部荒野與赤脊山。它興起於暴風城建城後的年月，當時王國的子民從首都向四周的鄉野擴散開來。\n\n小鎮最黑暗的時刻發生在第一次大戰期間，當時大酋長黑手率領部落，攻擊連繫暴風要塞與其子民的生命線。閃金鎮與月溪鎮是獸人與首都之間最後兩座屹立的城鎮，當它們陷落之後，通往要塞的道路便門戶洞開。直到第二次大戰結束後，羅德隆聯盟才重建了閃金鎮，最高指揮官圖拉揚親自主持，讓暴風城流離失所的居民得以返鄉。\n\n如今留下的是一份寧靜：獅王之傲旅店矗立於鎮中心，爐火與美酒吸引著從每條交會於此的道路而來的旅人。暴風城衛兵的治安官杜漢依然守護著這座小鎮，始終銘記著當年失去它所付出的代價。",
			source = "https://warcraft.wiki.gg/wiki/Goldshire",
		},
		["heroes vigil"] = {
			name = "英雄崗哨",
			short = "一圈立石環繞著石碑湖中的小島，中央是陣亡英雄的紀念碑。",
			full = "一圈立石環繞著石碑湖中的小島，中央是陣亡英雄的紀念碑。它紀念著第一次大戰中的死者，當年獸人洗劫了閃金鎮與周遭的土地，並將其付之一炬。\n\n如今島上被叛逆巫師盤據。亨茲·法奧克的屍體就躺在立石之間，倒在他殞命之處。",
			source = "https://warcraft.wiki.gg/wiki/Heroes'_Vigil",
