		["jasperlode mine"] = {
			name = "玉石礦坑",
			short = "玉石礦坑曾為暴風城的鍛爐提供原料，是艾爾文森林中為城市戰爭供應礦石的礦場之一。",
			full = "玉石礦坑曾為暴風城的鍛爐提供原料，是艾爾文森林中為城市戰爭供應礦石的礦場之一。那樣的日子已經過去了。狗頭人佔據了坑道，而暴風城的軍隊被更嚴重的威脅分散了兵力，根本無人可派去剷除牠們。\n\n地底的危險不只是狗頭人。在礦坑最深處，一群礦洞蜘蛛已經扎根，對牠們來說，狗頭人並非令人畏懼的入侵者，而是可供獵捕的獵物。牠們的女王毒牙之母在黑暗中伏守，絕不容許任何人闖入她的巢穴。",
			source = "https://warcraft.wiki.gg/wiki/Jasperlode_Mine",
