			short = "傑羅德碼頭是位於納菲瑞提河艾爾文森林一側岸邊的船塢。",
			full = "傑羅德碼頭是位於納菲瑞提河艾爾文森林一側岸邊的船塢。迪菲亞兄弟會控制著這裡，碼頭管理員與他的手下利用此地，將贓物從赤脊山走私到西部荒野的克拉文之塔。",
			source = "https://warcraft.wiki.gg/wiki/Jerod's_Landing",
		},
		["maclure vineyards"] = {
			name = "馬科倫農場",
			short = "馬科倫農場位於艾爾文森林南部，馬科倫一家在一排排葡萄藤與田土之間辛勤耕作。",
			full = "馬科倫農場位於艾爾文森林南部，馬科倫一家在一排排葡萄藤與田土之間辛勤耕作。馬科倫家與鄰近的斯通菲爾德家積怨甚深，彼此之間除了厭惡，什麼都不肯交流。然而，馬科倫家的一個孩子與斯通菲爾德家的一個孩子卻相戀了，違背了兩家所堅持的一切。有人盼望，這份愛情或許能彌合世代累積的仇怨所無法化解的裂痕。",
