		["northshire abbey"] = {
			name = "北郡修道院",
			short = "北郡修道院坐落於與它同名的山谷中，位在艾爾文森林的山麓。修道院的主殿、武器廳與圖書館側翼，就矗立在聖光教會的教士們從羅德隆南下後最初定居之處。",
			full = "北郡修道院坐落於與它同名的山谷中，位在艾爾文森林的山麓。修道院的主殿、武器廳與圖書館側翼，就矗立在聖光教會的教士們從羅德隆南下後最初定居之處。北郡牧師聖教團從這裡為暴風城帶來慰藉與智慧，而提里斯法守護者麥迪文陷入漫長昏迷的那些年間，也正是在這些牆內接受照料。\n\n修道院並未在第一次大戰中毫髮無傷。院長將北郡牧師們派去協助保衛暴風城，而在半獸人迦羅娜被當作俘虜押來此地後不久，獸人便攻陷北郡，將其焚毀殆盡。難民們向羅德隆逃去，但在離開之前，他們從廢墟中搶救出了神聖典籍，這些典籍日後教會了達拉然的法師們隱形之術。\n\n這片廢墟並未長久空置。第二次大戰期間，丘加利的暮光之錘氏族將此地作為總部，直到聯盟收復艾爾文森林，大主教阿隆索斯·法奧才一磚一石地重建了修道院，並在其殿堂中創立了北郡兄弟會。",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Abbey",
		},
		["northshire valley"] = {
			name = "北郡山谷",
			short = "北郡山谷除了一面之外，四面皆被封閉，群山無法穿越，唯一通往南方的隘口則被厚實的石牆與有人把守的大門封鎖。",
			full = "北郡山谷除了一面之外，四面皆被封閉，群山無法穿越，唯一通往南方的隘口則被厚實的石牆與有人把守的大門封鎖。一條河流劃破山谷的寧靜，蜿蜒流向水晶湖，途經修道院與一排排葡萄園，為此地增添一股祥和的氣息。\n\n然而這份祥和並非一向如此穩固。第二次大戰期間，北郡修道院曾是丘加利的暮光之錘氏族的總部，他們效忠於古爾丹的大業，當時修道院的牆內庇護的不是見習者與農夫，而是獸人的作戰會議。\n\n如今治安官瑪克布萊德統領修道院的守軍，負責整個北郡的安全，但即便在他的看守之下，山谷也並非全然安定。狼群從暮色森林湧入，數量多得無人能解釋，狗頭人則在回音山礦坑中打洞鑽掘。",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Valley",
		},
		["northshire vineyards"] = {
			name = "北郡農場",
			short = "葡萄園在修道院東方綿延開來，在迪菲亞兄弟會佔據這片土地之前，這裡曾有人細心照料以待收成。",
			full = "葡萄園在修道院東方綿延開來，在迪菲亞兄弟會佔據這片土地之前，這裡曾有人細心照料以待收成。加瑞克·帕德弗特率領佔據此地的探員，將葡萄藤間作為兄弟會爪牙的據點，而那些爪牙還帶走了米莉·奧斯沃斯被偷的財物。",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Vineyards",
