		["ridgepoint tower"] = {
			name = "山巔之塔",
			short = "山巔之塔守望著艾爾文森林的邊界，是暴風城衛兵的偵察塔之一。",
			full = "山巔之塔守望著艾爾文森林的邊界，是暴風城衛兵的偵察塔之一。塔上的哨兵將目光投向豺狼人與獸人聚集的赤脊山，投向死者不肯安息的暮色森林，也投向附近的迪菲亞營地。守軍防備周全，足以抵禦這三方的威脅。",
			source = "https://warcraft.wiki.gg/wiki/Ridgepoint_Tower",
		},
		["stone cairn lake"] = {
			name = "石碑湖",
			short = "石碑湖之名來自英雄崗哨，那是建於湖心島上的石冢，用以紀念第一次大戰中對抗獸人而死去的人們。當年陣亡者之多，沒有任何一座墳墓能承載對他們的追憶。",
			full = "石碑湖之名來自英雄崗哨，那是建於湖心島上的石冢，用以紀念第一次大戰中對抗獸人而死去的人們。當年陣亡者之多，沒有任何一座墳墓能承載對他們的追憶。這裡曾是靜謐的朝聖之地。\n\n那份寧靜已不復存在。叛逆巫師佔據了小島，原本用來哀悼的石冢如今就立在他們身後。南岸一帶，一群魚人搭起了自己簡陋的住所，對湖對岸的紀念碑毫不在意。",
			source = "https://warcraft.wiki.gg/wiki/Stone_Cairn_Lake",
		},
		["stonefield farm"] = {
			name = "斯通菲爾德農場",
			short = "斯通菲爾德農場位於艾爾文森林南部，由斯通菲爾德一家耕作，他們與鄰近的馬科倫家積怨甚深。",
			full = "斯通菲爾德農場位於艾爾文森林南部，由斯通菲爾德一家耕作，他們與鄰近的馬科倫家積怨甚深。然而兩家各有一個孩子墜入愛河，違抗了兩家之間的宿怨。有人盼望這段戀情能成就多年爭吵所未能達成的事，彌合這場世仇所造成的破裂。",
			source = "https://warcraft.wiki.gg/wiki/Stonefield_Farm",
		},
		["thunder falls"] = {
			name = "雷霆瀑布",
			short = "從明鏡湖的瀑布往上走，小徑陡峭狹窄，一路攀入山中，最後豁然開朗，來到雷霆瀑布。這道峽谷與艾爾文森林的其他峽谷不同，兩端都有瀑布傾瀉而下。",
			full = "從明鏡湖的瀑布往上走，小徑陡峭狹窄，一路攀入山中，最後豁然開朗，來到雷霆瀑布。這道峽谷與艾爾文森林的其他峽谷不同，兩端都有瀑布傾瀉而下。第三道瀑布從北面的峭壁奔流而下，自上方注入峽谷。坡下有一間小小的鄉間農舍，鐵砧旁的爐火始終燃著，屋旁的河上還有一座小碼頭和一艘小船。盜匪在農舍附近徘徊不去。河水繼續向前，在西部荒野邊緣附近又流過第二道瀑布。據說在其他任何地方，都不像在這片水域中這樣容易釣到紫色鱸魚。",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Falls",
		},
		["tower of azora"] = {
			name = "阿祖拉之塔",
			short = "阿祖拉之塔矗立於艾爾文森林中部的田野之間，塔中住著一群侍奉大法師塞歐克瑞圖斯的地精僕從。",
			full = "阿祖拉之塔矗立於艾爾文森林中部的田野之間，塔中住著一群侍奉大法師塞歐克瑞圖斯的地精僕從。\n\n在遙遠的赤脊山中，矗立著它的對手伊爾加拉之塔，由術士莫甘斯所統治。兩座塔從未公開開戰，卻始終以魔法手段互相監視，都在等著抓住對方的失誤。\n\n塔本身的魔法溢散到周遭的田野，任何在附近逗留過久的東西，都可能受其影響，變成比原本更古怪的模樣。僕從們守護著高塔，應付這種細小卻無休無止的麻煩，同時始終留一隻眼睛盯著赤脊山。",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Azora",
		},
		["westbrook garrison"] = {
			name = "西泉要塞",
			short = "西泉要塞位於艾爾文森林的西緣，在這裡，樹林逐漸讓位給貧瘠的西部荒野。對暴風城衛兵來說，這裡一向是個孤寂的崗位。",
			full = "西泉要塞位於艾爾文森林的西緣，在這裡，樹林逐漸讓位給貧瘠的西部荒野。對暴風城衛兵來說，這裡一向是個孤寂的崗位。\n\n它最艱困的歲月，是在女伯爵卡特拉娜·普瑞斯托的腐敗籠罩整個王國、暴風城軍隊主力被派往他處之時。由於兵力捉襟見肘，來自西部荒野的豺狼人與盜賊一季比一季更猖狂地侵擾森林，要塞只能勉強維持道路的安全。\n\n在豺狼人之中，河爪首領霍格成了令人聞之色變的名字。每一次試圖捕捉他的行動都被他擊潰，要塞大門上至今仍貼著寫有他名字的通緝告示，懸賞始終無人領取。",
			source = "https://warcraft.wiki.gg/wiki/Westbrook_Garrison",
		},
	},
