			name = "暗色河灘",
			short = "暗色河灘沿著暮色森林北岸延伸，從這片土地的西緣一路向東，直到連接赤脊山的橋樑。",
			full = "暗色河灘沿著暮色森林北岸延伸，從這片土地的西緣一路向東，直到連接赤脊山的橋樑。河灘西端有一座小營地，難民斯溫·猶根與拉爾斯在此棲身。不論是什麼讓暮色森林的其他地方危險得無法立足，總之是它將他們逼到了水邊。",
			source = "https://warcraft.wiki.gg/wiki/Darkened_Bank",
		},
		["darkshire"] = {
			name = "夜色鎮",
			short = "夜色鎮並非一向叫這個名字。它在很久以前以格蘭德村之名興起，是暴風城的子民向周邊土地擴散時，在林中建起的一座小鎮。",
			full = "夜色鎮並非一向叫這個名字。它在很久以前以格蘭德村之名興起，是暴風城的子民向周邊土地擴散時，在林中建起的一座小鎮。然而這片土地始終沒能從卡拉贊所發生的事情中復原。守護者麥迪文在他的高塔中被殺死時，他的死亡所釋放的邪能滲入了周遭的森林，將它扭曲成至今仍荊棘叢生、不見天日的模樣。亮木成了暮色森林，而格蘭德村也換上了更貼切的名字：夜色鎮。\n\n鎮上的民兵守夜人之所以存在，是因為暴風城拋棄了這裡。當女伯爵卡特拉娜·普瑞斯托在暴風城的陰謀讓王國的守軍撤出森林時，鎮民們選擇自己拿起武器，而不是等待永遠不會到來的士兵。守夜人完全由森林中的居民組成、訓練，從此便一直守護著道路，抵禦狼群、行屍以及更可怕的東西，除了自己之外，再沒有任何軍隊可以倚靠。",
			source = "https://warcraft.wiki.gg/wiki/Darkshire",
		},
		["dawning wood catacombs"] = {
			name = "黎明墓穴",
			short = "在烏鴉嶺墓園底下，大地裂開，通往黎明墓穴，那是一片蜿蜒深入地底的坑道迷宮，獨自進入的人鮮少能再走出來。",
			full = "在烏鴉嶺墓園底下，大地裂開，通往黎明墓穴，那是一片蜿蜒深入地底的坑道迷宮，獨自進入的人鮮少能再走出來。有兩條路通往下方。東側通道通往一座食屍鬼的巢穴，牠們滿身病疫，兇殘無比。西側通道則通往一座骷髏大廳，骷髏們守衛著他們生前遺骸所在的墓穴。",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Wood_Catacombs",
		},
		["forlorn rowe"] = {
			name = "荒棄鬼屋",
			short = "荒棄鬼屋是烏鴉嶺墓園北緣的一座小丘，籠罩在一片比周遭樹影更加緊密的黑暗之中。",
			full = "荒棄鬼屋是烏鴉嶺墓園北緣的一座小丘，籠罩在一片比周遭樹影更加緊密的黑暗之中。這裡是摩本特·費爾的居所，他是一名亡靈巫師，以邪惡的秘法操縱森林中的不死生物。唯有一把力量強大的武器，才有希望讓他安息。",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Rowe",
		},
		["hushed bank"] = {
			name = "寂靜河岸",
			short = "寂靜河岸沿著暮色森林西側的河流延伸，從西部荒野、艾爾文森林與暮色森林三地交界處，向南通往荊棘谷。",
			full = "寂靜河岸沿著暮色森林西側的河流延伸，從西部荒野、艾爾文森林與暮色森林三地交界處，向南通往荊棘谷。一座有頂棚的橋樑在此跨過河流，連接暮色森林與西部荒野。\n\n在河岸北端的角落，拉爾斯與斯溫·猶根兄弟搭起了一座營地。\n\n狼群與蜘蛛在河岸的樹林間出沒。",
			source = "https://warcraft.wiki.gg/wiki/Hushed_Bank",
		},
		["manor mistmantle"] = {
			name = "密斯特曼托莊園",
			short = "密斯特曼托莊園位於暮色森林東北部，庭院腐朽，花園荒蕪。",
			full = "密斯特曼托莊園位於暮色森林東北部，庭院腐朽，花園荒蕪。這裡曾是斯塔文·密斯特曼托的家，他原本是一名學校教師兼家庭教師，後來卻成了不死生物的爪牙，只留下食屍鬼在他的產業中蹣跚遊蕩。在一片腐敗之中，仍有一樣東西在生長：一朵名為蒂羅亞之淚的花，那是這座早已被腐朽吞沒的花園裡，僅存的生命跡象。",
			source = "https://warcraft.wiki.gg/wiki/Manor_Mistmantle",
		},
		["raven hill"] = {
			name = "烏鴉嶺",
			short = "烏鴉嶺的房屋空蕩蕩地立在暮色森林西部，任由腐朽與黑暗吞噬。儘管如此，仍有幾個人堅持留了下來：基特斯，以及躲在樓上不肯露面的哥布林布里茲提克。",
			full = "烏鴉嶺的房屋空蕩蕩地立在暮色森林西部，任由腐朽與黑暗吞噬。儘管如此，仍有幾個人堅持留了下來：基特斯，以及躲在樓上不肯露面的哥布林布里茲提克。\n\n鎮上有隱形者作祟，它們不只名字叫做隱形，在空蕩的房間中穿梭時也確實無人得見。",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill",
		},
		["raven hill cemetery"] = {
			name = "烏鴉嶺墓園",
			short = "烏鴉嶺墓園在與它同名的小鎮北方蔓延開來，自從暮色森林遭到腐化之後，它的範圍已遠遠超出了昔日的邊界。",
			full = "烏鴉嶺墓園在與它同名的小鎮北方蔓延開來，自從暮色森林遭到腐化之後，它的範圍已遠遠超出了昔日的邊界。如今不死生物在墓碑間行走，巨大的蜘蛛與成群的盜墓賊肆無忌憚地翻掘墳墓，把任何誤闖他們勾當的人趕走。\n\n墓園的西北角矗立著荒棄鬼屋，那是亡靈巫師摩本特·費爾的居所，他的黑暗行徑攪動著墓園中的亡者。\n\n拉迪莫爾這個名字，標記著這座墓園最古老的哀傷。摩根·拉迪莫爾從第三次大戰歸來，卻發現妻兒早已葬在這裡。悲痛擊垮了他，他在家人的墳前殺害了三名墓園看守人。如今化為不死生物的摩拉迪姆在墓地中巡行，任何在墓碑間疏於防備而被他撞見的人，都會在無聲無息間迅速喪命。",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill_Cemetery",
		},
		["rolands doom"] = {
			name = "羅蘭之墓",
			short = "羅蘭之墓是暮色森林東南部的一座礦坑，位於爛果園東方。",
			full = "羅蘭之墓是暮色森林東南部的一座礦坑，位於爛果園東方。夜精靈女祭司維琳德·星歌在失蹤前，將月神的鐮刀帶進了這片丘陵，而這件聖物便遺失在礦坑之中。一個名叫基特斯的男人在那裡找到了它，而它的出現引來了更多狼人湧向暮色森林與夜色鎮。\n\n如今這座礦坑屬於夜禍狼群的腸液與納菲魯，牠們的狼人遠至爛果園一帶出沒。",
			source = "https://warcraft.wiki.gg/wiki/Roland's_Doom",
		},
		["rotting orchard"] = {
			name = "爛果園",
			short = "這座果園位於暮色森林南部，果樹因腐爛而發黑，建築則在猶根農場與靜謐花園墓場之間傾頹成廢墟。",
			full = "這座果園位於暮色森林南部，果樹因腐爛而發黑，建築則在猶根農場與靜謐花園墓場之間傾頹成廢墟。\n\n夜禍狼群的狼人已將這裡據為己有。暗影編織者在殘破的建築間施展法術，而潛獵者則隱身於樹與樹之間的黑暗中等待。\n\n如今站在這裡，就是站在一處已不再是農場、而成了獵場的地方。",
			source = "https://warcraft.wiki.gg/wiki/Rotting_Orchard",
		},
		["tranquil gardens cemetery"] = {
			name = "靜謐花園墓場",
			short = "靜謐花園墓場位於夜色鎮東南方，如今它的名字已成了一則苦澀的笑話。",
			full = "靜謐花園墓場位於夜色鎮東南方，如今它的名字已成了一則苦澀的笑話。這裡的死者不得安息，只是比暮色森林其他地方的不死生物孱弱一些，他們在墓碑之間，以及墓園中心那座殘破的教堂周圍遊蕩。瘋狂的食屍鬼在這片土地上出沒，有時在破敗的教堂內，有時在墳墓之間。墓園北方不遠處，就是盲眼瑪麗的房子。",
			source = "https://warcraft.wiki.gg/wiki/Tranquil_Gardens_Cemetery",
		},
		["twilight grove"] = {
			name = "暮光森林",
			short = "一棵無名的巨樹矗立在暮色森林深處的暮光森林中心，旁邊是一座月井和一座古老的夜精靈涼亭。",
			full = "一棵無名的巨樹矗立在暮色森林深處的暮光森林中心，旁邊是一座月井和一座古老的夜精靈涼亭。在它的枝葉之下，有一座通往翡翠夢境的傳送門，這樣的傳送門世上只有四座，其餘三座分別隱藏於菲拉斯、辛特蘭與梣谷。\n\n樹林中的傳送門並非無人看守。四頭巨龍曾是夢境守護者伊瑟拉引以為傲的副官，被她選為夢境的守護者，在此守望。然而翡翠夢魘接連腐化了牠們，將守護者扭曲成只想著死亡的毀滅者，於是聯盟與部落都不得不拿起武器，對抗這些曾經守衛此地的巨龍。",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Grove",
		},
		["vulgol ogre mound"] = {
			name = "沃古爾巨魔山",
			short = "暮色森林南部地勢下沉，形成一座小盆地，道路在此分岔通往荊棘谷，而在巨魔到來之前，這裡曾經有農舍。",
			full = "暮色森林南部地勢下沉，形成一座小盆地，道路在此分岔通往荊棘谷，而在巨魔到來之前，這裡曾經有農舍。如今碎拳巨魔佔據了這裡，此地以他們的首領扎克沃爾為名，他就在土丘之中統治著這座巨魔山。\n\n殘破的農舍是巨魔佔據盆地之前曾有人居住於此的唯一痕跡。那些家庭後來下場如何，無從得知，巨魔們只留下了斷垣殘壁。\n\n守夜人不願為此地分出人手，認為這裡的威脅不如暮色森林面臨的其他危險那樣迫切，因此每當需要削減巨魔的數量時，只能交給外人去處理。巨魔的戰利品中，有一箱從亡靈巫師亞伯克隆比那裡偷來的工具與草藥，是在他們擊潰他之後被搬進土丘的。而扎克沃爾本人還戴著一片單眼鏡，一位研究者曾為了自己的研究而對它垂涎不已，那是這頭殘暴生物身上一點小小的虛榮。",
			source = "https://warcraft.wiki.gg/wiki/Vul'Gol_Ogre_Mound",
		},
		["yorgen farmstead"] = {
			name = "猶根農場",
			short = "猶根農場荒廢在暮色森林南部，田地早已腐爛。斯溫·猶根曾在這片土地上耕作，如今卻只能待在暗色河灘上的一座小營地。",
			full = "猶根農場荒廢在暮色森林南部，田地早已腐爛。斯溫·猶根曾在這片土地上耕作，如今卻只能待在暗色河灘上的一座小營地。此後農場本身落入了迪菲亞兄弟會之手，他們的刺客在田野間無聲無息地穿行，只在為時已晚之際出手。",
			source = "https://warcraft.wiki.gg/wiki/Yorgen_Farmstead",
		},
	},
	-- 洛克莫丹: 16 subzones
	[1432] = {
		["algaz station"] = {
			name = "奧加茲崗哨",
			short = "奧加茲崗哨位於北門小徑東方，其名來自北方的丹奧加茲。",
			full = "奧加茲崗哨位於北門小徑東方，其名來自北方的丹奧加茲。矮人巡山人在此守望，巡山人雷矛也是其中一員，而護甲匠哥索·布朗則負責打理他們的裝備。",
			source = "https://warcraft.wiki.gg/wiki/Algaz_Station",
		},
		["dun algaz"] = {
			name = "丹奧加茲",
			short = "貫穿丹奧加茲的隧道，比分裂矮人的那場紛爭還要古老。當三錘之戰將蠻錘部族逐出鐵爐堡時，他們正是從這道隘口撤離的。",
			full = "貫穿丹奧加茲的隧道，比分裂矮人的那場紛爭還要古老。當三錘之戰將蠻錘部族逐出鐵爐堡時，他們正是從這道隘口撤離的。\n\n部落也曾經由此撤退。獸人在丹莫德被擊退後，向南越過薩多爾山谷，在這裡的前哨據守，安度因·洛薩為了將他們徹底逐出卡茲莫丹，派兵前去摧毀這座要塞。這次進攻失敗了。獸人堅守不退，丹奧加茲成了部落在該地區最後保有的據點，一個無法撼動的立足之地。\n\n看守這道隘口的矮人巡山人多半駐守在上方的山丘，但龍喉氏族攻陷了他們的哨站，將他們逼退到上層隧道，他們至今仍在那裡苦撐。由於下方的隘口失守，矮人故土與米奈希爾港之間的道路變得危險許多。",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["farstrider lodge"] = {
			name = "旅行者營地",
			short = "旅行者營地位於洛克莫丹東南部，建築風格一望即知是高等精靈的手筆，然而如今廳堂之中只剩下一名高等精靈。",
			full = "旅行者營地位於洛克莫丹東南部，建築風格一望即知是高等精靈的手筆，然而如今廳堂之中只剩下一名高等精靈。人類與矮人後來遷入此地，其中不乏獵人，他們就住在這些由早已離去之人所築起的牆垣之內。",
			source = "https://warcraft.wiki.gg/wiki/Farstrider_Lodge",
		},
		["grizzlepaw ridge"] = {
			name = "灰爪山",
			short = "灰爪山聳立於塞爾薩瑪南方，山上熊群密布，早已將這片高地據為己有。",
			full = "灰爪山聳立於塞爾薩瑪南方，山上熊群密布，早已將這片高地據為己有。其中首屈一指的是老煤灰，一頭體型與脾氣都同樣駭人的熊，牠會從巢穴一路晃到山谷底部，隨時撲向任何不幸惹惱牠的人。\n\n戈里克·痛飲也待在這座山上。",
			source = "https://warcraft.wiki.gg/wiki/Grizzlepaw_Ridge",
		},
		["ironbands excavation site"] = {
			name = "鐵環挖掘場",
			short = "鐵環挖掘場位於洛克莫丹東南部，是勘察員鐵環為了尋找古人埋藏之物而開闢的矮人挖掘場。",
			full = "鐵環挖掘場位於洛克莫丹東南部，是勘察員鐵環為了尋找古人埋藏之物而開闢的矮人挖掘場。然而大地吐出的不只是古物：比其他矮人挖掘場所見更加巨大、也更加暴躁的穴居人從地底湧出，佔領了挖掘場，趕走了當初開挖此地的勘察員與礦工。",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Excavation_Site",
