		["north gate pass"] = {
			name = "北門小徑",
			short = "這道隘口穿過高聳的群山，從丹莫洛一路下行至洛克莫丹。",
			full = "這道隘口穿過高聳的群山，從丹莫洛一路下行至洛克莫丹。它是兩地之間最短的道路，前往洛克湖彼方土地的旅人，走這條路的比走其他路線的都多。\n\n北門崗哨在此守衛，扼守著這條通道。",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["silver stream mine"] = {
			name = "銀泉礦坑",
			short = "銀泉礦坑曾蘊藏著豐富的白銀，世世代代以來，鐵爐堡的矮人都從它的礦脈中汲取財富。",
			full = "銀泉礦坑曾蘊藏著豐富的白銀，世世代代以來，鐵爐堡的矮人都從它的礦脈中汲取財富。礦石枯竭之後，礦工聯盟並未捨棄這些坑道，而是將它們改造成了儲藏庫。\n\n礦坑裡仍有一樣值得奪取的東西：充能裂隙寶石。它在別處都找不到，是製作法師長袍的珍貴材料。\n\n但矮人已不再掌控這些坑道。坑道鼠狗頭人佔據了礦坑，想將剩餘的資源據為己有。",
			source = "https://warcraft.wiki.gg/wiki/Silver_Stream_Mine",
		},
		["south gate pass"] = {
			name = "南門小徑",
			short = "南門小徑穿越群山，連接丹莫洛的高原雪地與洛克莫丹較低的山谷。它是通往塞爾薩瑪最短的路，被往來兩地的旅人踩得平坦。",
			full = "南門小徑穿越群山，連接丹莫洛的高原雪地與洛克莫丹較低的山谷。它是通往塞爾薩瑪最短的路，被往來兩地的旅人踩得平坦。\n\n南門崗哨就矗立在此，是一座監視隘口的衛哨。",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["stonesplinter valley"] = {
			name = "碎石怪之谷",
			short = "碎石怪之谷位於洛克莫丹西南部的群山之間。這裡曾是一片未經破壞的淨土，如今卻屬於碎石穴居人，牠們佔據了谷底與山坡。",
			full = "碎石怪之谷位於洛克莫丹西南部的群山之間。這裡曾是一片未經破壞的淨土，如今卻屬於碎石穴居人，牠們佔據了谷底與山坡。洛克莫丹的矮人將牠們視為必須清除的害蟲。在山谷最深處住著格拉姆格，穴居人們都團結在這名首領的麾下。",
			source = "https://warcraft.wiki.gg/wiki/Stonesplinter_Valley",
		},
		["stonewrought dam"] = {
			name = "巨石水壩",
			short = "巨石水壩聳立於丹奧加茲隘口東方，沿著洛克莫丹的北緣延伸。",
			full = "巨石水壩聳立於丹奧加茲隘口東方，沿著洛克莫丹的北緣延伸。\n\n它的建造者是一名黑鐵矮人。該氏族的建築師弗蘭克羅恩·鑄鐵發明了築起這座水壩的石造工法，但走過水壩的人，很少有人知道它出自黑鐵矮人之手。\n\n水壩攔住了洛克湖的湖水，使湖面擴大到原本的兩倍以上，而它所造成的水患，也形成了水壩另一側的濕地，那片土地過去大半都淹沒在水中。\n\n黑鐵氏族曾襲擊水壩，鐵爐堡則以加強戒備作為回應。如今由主工程師辛德維爾七世負責此事。",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Dam",
		},
		["stoutlager inn"] = {
			name = "烈酒旅店",
			short = "烈酒旅店位於塞爾薩瑪，爐火鮮少熄滅。矮人與旅人都聚集在這裡喝酒，交換洛克湖一帶的消息，在這個地區，很少有地方能像這裡一樣門庭若市。",
			full = "烈酒旅店位於塞爾薩瑪，爐火鮮少熄滅。矮人與旅人都聚集在這裡喝酒，交換洛克湖一帶的消息，在這個地區，很少有地方能像這裡一樣門庭若市。",
			source = "https://warcraft.wiki.gg/wiki/Stoutlager_Inn",
		},
		["thelsamar"] = {
			name = "塞爾薩瑪",
			short = "塞爾薩瑪座落在洛克莫丹的洛克湖西岸，位於灰爪山北方、碎石怪之谷東北方。一條道路就從鎮子西邊經過，穿越隘口通往丹莫洛與濕地。",
			full = "塞爾薩瑪座落在洛克莫丹的洛克湖西岸，位於灰爪山北方、碎石怪之谷東北方。一條道路就從鎮子西邊經過，穿越隘口通往丹莫洛與濕地。獅鷲在鎮上的棲架築巢，而鎮上的旅店則為穿越高地的旅人提供庇護。",
			source = "https://warcraft.wiki.gg/wiki/Thelsamar",
		},
		["valley of kings"] = {
			name = "國王谷",
			short = "國王谷位於洛克莫丹的西南端，翠綠的土地在此逐漸收窄，通往一道向下進入焦黑的灼熱峽谷的大門。",
			full = "國王谷位於洛克莫丹的西南端，翠綠的土地在此逐漸收窄，通往一道向下進入焦黑的灼熱峽谷的大門。那道大門緊鎖且有人看守，由巡山人貝波蒂負責監視，她只讓證明了自己配得上的人通過。\n\n這裡最引人注目的，是聳立在隘口上方的兩尊巨大雕像：瑪多蘭·銅鬚與卡德羅斯·蠻錘，以石雕的形象守望著南下的道路。兩位國王辭世後，是他們的兒子們一同立起了這兩尊雕像，將銅鬚與蠻錘以石頭相連，正如他們的父親生前那般。遠方的南方大地已被拉格納羅斯化為烈焰與灰燼，而雕像正面對著那片廢墟：這既是對任何想與矮人王國為敵者的警告，也提醒著世人，黑鐵矮人為其所作所為付出了何等代價。",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Kings",
		},
	},
	-- 赤脊山: 16 subzones
	[1433] = {
		["althers mill"] = {
			name = "奧瑟爾伐木場",
