		["stonewatch"] = {
			name = "石堡",
			short = "石堡曾屬於湖畔鎮的人類，是一座倚靠峭壁而建的要塞，瀑布在要塞下方傾瀉而下。它守望著赤脊山，抵禦來自燃燒平原的獸人威脅。",
			full = "石堡曾屬於湖畔鎮的人類，是一座倚靠峭壁而建的要塞，瀑布在要塞下方傾瀉而下。它守望著赤脊山，抵禦來自燃燒平原的獸人威脅。\n\n那份守望因背叛而破滅。術士莫甘斯與加塞爾佐格及其黑石獸人結盟，雙方的聯軍以殘暴的攻勢襲擊石堡要塞，擊潰了守軍。獸人奪下了要塞，但他們的勝利在信任上卻極為短暫，因為莫甘斯轉而背叛了為他贏得這場勝利的盟友。他為自己建起伊爾加拉之塔，並使一支由范高雷中尉率領的暗皮豺狼人戰團屈從於他的意志。自那次背叛以來，凡是擋了豺狼人去路的獸人與人類，都付出了代價。\n\n被利用他們的術士拋棄之後，黑石獸人獨自守著要塞，由加塞爾佐格統治，他的副官薩瑞爾祖恩隨侍在側。",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch",
		},
		["stonewatch falls"] = {
			name = "石堡瀑布",
			short = "在石堡下方，止水湖東側的河流沿著山坡長長地傾瀉而下，匯聚成赤脊山一隅的一座深湖。",
			full = "在石堡下方，止水湖東側的河流沿著山坡長長地傾瀉而下，匯聚成赤脊山一隅的一座深湖。一小群魚人在湖岸定居，在水中捕魚，並在瀑布下方搭起了簡陋的棲身之所。",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Falls",
		},
		["stonewatch keep"] = {
			name = "石堡要塞",
			short = "石堡要塞曾屬於湖畔鎮的人類，用以守望赤脊山。",
			full = "石堡要塞曾屬於湖畔鎮的人類，用以守望赤脊山。當術士莫甘斯與黑石獸人督軍加塞爾佐格結盟時，它便陷落了。雙方的聯軍在莫甘斯黑暗魔法的助長之下，以殘暴的攻勢猛攻要塞。守軍潰散，要塞失守。\n\n這個同盟並未持續多久。石堡才剛陷落，莫甘斯便背叛了與他並肩浴血的獸人。他在附近建起伊爾加拉之塔，並讓范高雷中尉率領的暗皮豺狼人進駐其中，那些生物只聽命於他一人。從那時起，獸人與人類都曾命喪於他所放出的這些蠻兵之手。\n\n被術士盟友拋棄之後，黑石獸人獨自守著要塞，由加塞爾佐格與他的副官薩瑞爾祖恩統治著剩下的一切。在那場戰鬥中，他們俘虜了暴風城軍隊的基沙恩下士，並將他拖往北方的營地。所羅門鎮長為此懸賞加塞爾佐格的首級，而湖畔鎮的治安官馬瑞斯也發誓要讓薩瑞爾祖恩為他的罪行付出代價。",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Keep",
		},
		["stonewatch tower"] = {
			name = "石堡高塔",
			short = "石堡高塔曾矗立在石堡要塞旁，兩者都由湖畔鎮的人類掌控，直到黑石氏族奪取了這座要塞。",
			full = "石堡高塔曾矗立在石堡要塞旁，兩者都由湖畔鎮的人類掌控，直到黑石氏族奪取了這座要塞。這座高塔如今成了加塞爾佐格手下的偵察哨，黑石氏族的獸人在此監視著他們的同族從湖畔鎮人類手中奪來的要塞。",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Tower",
