		["booty bay"] = {
			name = "藏寶海灣",
			short = "藏寶海灣座落於荊棘谷南端的一座蔚藍潟湖中，徒步進入時，得穿過一頭巨大鯊魚那副已經褪白的顎骨。",
			full = "藏寶海灣座落於荊棘谷南端的一座蔚藍潟湖中，徒步進入時，得穿過一頭巨大鯊魚那副已經褪白的顎骨。在這裡，人命如草芥，誰也不能信任；這裡是盜賊的天堂，到處都是線人和各式各樣的商人。\n\n在得到這個名字之前，這處海灣被稱為黑水灣，原本是人類的一座小港口，直到叢林食人妖將其攻陷。早在第一次大戰爆發之前，熱砂企業的哥布林便將食人妖逐離海岸，將海灣據為己有，並在此建立他們在東部王國的營運中心。\n\n如今由黑水劫掠者與熱砂企業緊密合作經營這座港口，無論旅人效忠於哪一方旗幟，港口都一律敞開大門。大財主里維加茲在旅店頂樓發號施令，與劫掠者的艦隊指揮官海角共同治理，他不惜重金雇用傭兵對抗血帆海盜，這群海盜曾圖謀奪取這座海灣，卻始終未能得逞。",
			source = "https://warcraft.wiki.gg/wiki/Booty_Bay",
		},
		["cape of stranglethorn"] = {
