			name = "流沙泥潭",
			short = "流沙泥潭的淤泥從不靜止。它沿著地面堆積成細細的沙丘，在沼澤上緩緩蠕動，彷彿有某種看不見的東西在拖曳著它，像活物一般捲曲、聚集。",
			full = "流沙泥潭的淤泥從不靜止。它沿著地面堆積成細細的沙丘，在沼澤上緩緩蠕動，彷彿有某種看不見的東西在拖曳著它，像活物一般捲曲、聚集。\n\n有人說，推動這股移動的力量並非惡意，而是某種正面的能量，它攪動著淤泥，卻毫無傷人之意。",
			source = "https://warcraft.wiki.gg/wiki/Shifting_Mire",
		},
		["sorrowmurk"] = {
			name = "憂傷濕地",
			short = "憂傷濕地位於淚水之池東方，靠近沉沒的神廟。",
			full = "憂傷濕地位於淚水之池東方，靠近沉沒的神廟。這裡是龍類的地盤，綠色龍人在一頭巨大綠色幼龍的監視下於泥沼中爬行，除了最魯莽的旅人之外，所有人都被牠擋在外頭。",
			source = "https://warcraft.wiki.gg/wiki/Sorrowmurk",
		},
		["splinterspear junction"] = {
			name = "斷矛路口",
			short = "在通往悲傷沼澤的道路分岔之處，一座古老的獸人瞭望塔依然屹立，部落的巡邏隊嚴密監視著這個路口。",
			full = "在通往悲傷沼澤的道路分岔之處，一座古老的獸人瞭望塔依然屹立，部落的巡邏隊嚴密監視著這個路口。\n\n這座塔是基洛斯的遺跡，那是第一次大戰期間在此建立的獸人前哨。基洛斯比沼澤中部落的任何其他據點都更接近人類的格蘭德村，暴風城無法坐視不管，於是派出戰鬥部隊將其摧毀。\n\n這座塔至今仍守望著這個岔路口。",
			source = "https://warcraft.wiki.gg/wiki/Splinterspear_Junction",
		},
		["stagalbog"] = {
			name = "雄鹿沼澤",
			short = "在淚水之池南方，悲傷沼澤隆起成群山之處，沼地變得愈發濃密，形成了雄鹿沼澤。在這片潮濕荒野的西側、山腳邊緣，一座洞穴在岩壁上敞開。",
			full = "在淚水之池南方，悲傷沼澤隆起成群山之處，沼地變得愈發濃密，形成了雄鹿沼澤。在這片潮濕荒野的西側、山腳邊緣，一座洞穴在岩壁上敞開。",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog",
		},
		["stagalbog cave"] = {
			name = "雄鹿沼澤洞穴",
			short = "在悲傷沼澤的雄鹿沼澤東部，一座洞穴向泥沼敞開。",
			full = "在悲傷沼澤的雄鹿沼澤東部，一座洞穴向泥沼敞開。",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog_Cave",
		},
		["stonard"] = {
			name = "斯通納德",
			short = "斯通納德從悲傷沼澤的泥沼中拔地而起，它的大廳依然屹立，而其他許多獸人大廳早已傾頹。",
			full = "斯通納德從悲傷沼澤的泥沼中拔地而起，它的大廳依然屹立，而其他許多獸人大廳早已傾頹。兩座地洞守衛著入口，獸人巡邏隊出發鎮守附近的小營地，每一座營地都是在沼澤中插下的又一面旗幟。\n\n這座前哨十分古老，比世界這一端幾乎任何其他獸人據點都更古老，它與昔日名為洛卡德的要塞是姊妹據點。在黑暗之門首次開啟後的那段日子裡，舊部落在黑色沼澤建起了它。第二次大戰爆發、部落潰敗之後，斯通納德便沉寂下來，很可能與獸人所建的許多其他事物一同遭到遺棄或摧毀。\n\n但它並未一直空置。隨著新部落的崛起，以及堅守這片土地的決心再度燃起，斯通納德得以重建，大廳修復如初，地洞也重新挖掘。洛卡德就沒那麼幸運了：巨槌巨魔將這座古老要塞據為己有，並改名為巨槌要塞，使得斯通納德成了沼澤中唯一的部落前哨，也是這片低地上最後一座仍然燈火通明的同類大廳。",
			source = "https://warcraft.wiki.gg/wiki/Stonard",
		},
		["temple of atalhakkar"] = {
			name = "阿塔哈卡神廟",
			short = "一千多年前，古拉巴什帝國在內戰中分崩離析。內戰的核心是阿塔萊，一群企圖讓血神奪魂者哈卡重返世間的食人妖祭司。",
			full = "一千多年前，古拉巴什帝國在內戰中分崩離析。內戰的核心是阿塔萊，一群企圖讓血神奪魂者哈卡重返世間的食人妖祭司。他們戰敗遭到放逐，向北逃進悲傷沼澤，在那裡建起一座神廟，為哈卡的回歸做準備。\n\n巨龍守護者伊瑟拉得知了他們的計畫，便將神廟沉入沼澤之下，打算永遠埋葬他們的所作所為。然而事與願違。在淹沒的黑暗中無人打擾，避開了任何可能阻止他們的目光，阿塔萊祭司們得以安安穩穩地繼續舉行他們的儀式。伊瑟拉派來看守廢墟的綠龍們從此一直守望著，守著一扇從未真正封死的門。\n\n這座神廟至今仍沉在水下，半遭淹沒，供奉哈卡的祭壇完好無損，而進入其中的人所冒的風險比死亡更可怕。這位鮮血之神要求的不只是血肉，還有靈魂，而祂所得到的每一個靈魂，都在餵養那終將到來的一天。",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Atal'Hakkar",
		},
	},
	-- 西部荒野: 17 subzones
	[1436] = {
		["alexston farmstead"] = {
			name = "艾力克斯頓農場",
			short = "在迪菲亞兄弟會將這片土地據為己有之前，艾力克斯頓農場的田地曾養活了許多家庭。",
			full = "在迪菲亞兄弟會將這片土地據為己有之前，艾力克斯頓農場的田地曾養活了許多家庭。如今只有機械收割看守者在田壟之間移動，不知疲倦，也無人照管，守衛著再也沒有人耕種的一排排田地。\n\n後來成為暴風城建築師的巴洛斯·艾力克斯頓，就出生在這片土地上。在造就他的這片土地落入他人之手以前，他從小就在這裡勞動，就在如今收割看守者巡邏的同一片田地之間。",
			source = "https://warcraft.wiki.gg/wiki/Alexston_Farmstead",
		},
		["dagger hills"] = {
			name = "匕首嶺",
			short = "匕首嶺是一道位於月溪鎮後方的山脊，在西部荒野南部。如今那裡幾乎毫無動靜。",
			full = "匕首嶺是一道位於月溪鎮後方的山脊，在西部荒野南部。如今那裡幾乎毫無動靜。葛瑞姆·雷酒獨自待在山丘之間，是在那片寂靜土地上寥寥可數的活人之一，而食屍鬼萊普瑞塔斯也會從那裡的土中爬出來。",
			source = "https://warcraft.wiki.gg/wiki/Dagger_Hills",
		},
		["dead acre"] = {
			name = "死亡農地",
			short = "死亡農地曾是西部荒野東南部眾多農場之一，靠近通往暮色森林的橋樑。當迪菲亞兄弟會奪取這個地區時，他們也將原本在此的農場連同田地一併奪走。",
			full = "死亡農地曾是西部荒野東南部眾多農場之一，靠近通往暮色森林的橋樑。當迪菲亞兄弟會奪取這個地區時，他們也將原本在此的農場連同田地一併奪走。\n\n如今再也沒有農夫在此行走。取而代之的是機械收割看守者在地上遊蕩，徘徊在過去作物生長的地方。",
			source = "https://warcraft.wiki.gg/wiki/Dead_Acre",
		},
		["deadmines"] = {
			name = "死亡礦坑",
			short = "在月溪鎮底下，坑道深深延伸，這裡曾經流淌著黃金。",
			full = "在月溪鎮底下，坑道深深延伸，這裡曾經流淌著黃金。早在獸人踏上人類的土地之前，死亡礦坑便一直充實著暴風城的國庫，據某些說法，國庫的三分之一就出自這片岩層。第一次大戰讓礦坑裡的礦工一空，此後這裡便被視為死地，傳說鬧鬼，很長一段時間無人問津。\n\n艾德溫·范克里夫就在這片沉寂之中到來，他召集了迪菲亞兄弟會，那些淪為盜匪的昔日工匠，並在哥布林的協助下，讓他們在地底深處建造一艘巨艦。\n\n范克里夫依然待在那片深處，受到他的兄弟會保護，而格里安·斯托曼則在哨兵嶺召集人馬，誓言要取下他的首級。",
			source = "https://warcraft.wiki.gg/wiki/Deadmines",
		},
		["demonts place"] = {
			name = "迪蒙特荒野",
			short = "迪蒙特荒野位於月溪鎮西方，如今只剩下斷裂的木材與雜草叢生的田地。這裡曾是一座正常運作的農場，如今已被迪菲亞的探員佔據，據為己有。",
			full = "迪蒙特荒野位於月溪鎮西方，如今只剩下斷裂的木材與雜草叢生的田地。這裡曾是一座正常運作的農場，如今已被迪菲亞的探員佔據，據為己有。",
			source = "https://warcraft.wiki.gg/wiki/Demont's_Place",
		},
		["dust plains"] = {
			name = "塵埃平原",
			short = "塵埃平原橫亙於西部荒野南部，這片乾燥的土地已落入豺狼人之手，他們在這裡設立了零星的營地，威脅著任何穿越其領地的人。",
			full = "塵埃平原橫亙於西部荒野南部，這片乾燥的土地已落入豺狼人之手，他們在這裡設立了零星的營地，威脅著任何穿越其領地的人。\n\n平原東緣矗立著莫特維克之塔，這座古老的法師塔早已不再用於原本的用途，而是換上了新的主人。",
			source = "https://warcraft.wiki.gg/wiki/Dust_Plains",
		},
		["furlbrows pumpkin farm"] = {
			name = "法布隆南瓜農場",
			short = "法布隆南瓜農場曾由農夫法布隆與他的妻子弗娜照料，但當迪菲亞兄弟會帶著機械收割魔像橫掃西部荒野時，這座農場也和那片土地上的許多農場一樣陷落了。",
			full = "法布隆南瓜農場曾由農夫法布隆與他的妻子弗娜照料，但當迪菲亞兄弟會帶著機械收割魔像橫掃西部荒野時，這座農場也和那片土地上的許多農場一樣陷落了。法布隆與弗娜逃離家園，在北方傑生農場附近的路邊棲身，把他們的南瓜與名號都拋在了身後。",
			source = "https://warcraft.wiki.gg/wiki/Furlbrow's_Pumpkin_Farm",
		},
		["gold coast quarry"] = {
			name = "金海岸礦坑",
			short = "在西部荒野陷入荒廢之前，金海岸礦坑曾為暴風城出產黃金與礦石。如今迪菲亞兄弟會佔據了這裡，打著自己的旗號開採礦坑。",
			full = "在西部荒野陷入荒廢之前，金海岸礦坑曾為暴風城出產黃金與礦石。如今迪菲亞兄弟會佔據了這裡，打著自己的旗號開採礦坑。西部荒野人民軍與其成員曾在此與兄弟會交戰，在他們仍在巡邏的岩石之間遭到迪菲亞的伏擊。",
			source = "https://warcraft.wiki.gg/wiki/Gold_Coast_Quarry",
		},
		["jangolode mine"] = {
			name = "詹戈洛德礦坑",
			short = "詹戈洛德礦坑曾為暴風城運送礦石，是西部荒野較為穩定的礦產財源之一。",
			full = "詹戈洛德礦坑曾為暴風城運送礦石，是西部荒野較為穩定的礦產財源之一。\n\n這份穩定在迪菲亞兄弟會奪下礦坑時被打破了。此後狗頭人又悄悄爬進礦井，將它們據為己有。",
			source = "https://warcraft.wiki.gg/wiki/Jangolode_Mine",
