		["jansen stead"] = {
			name = "傑生農場",
			short = "傑生農場位於西部荒野的北緣，緊鄰通往艾爾文森林的橋樑。和這個地區的其他農場一樣，迪菲亞兄弟會趕走了它真正的主人，使它人去樓空。",
			full = "傑生農場位於西部荒野的北緣，緊鄰通往艾爾文森林的橋樑。和這個地區的其他農場一樣，迪菲亞兄弟會趕走了它真正的主人，使它人去樓空。\n\n附近站著農夫法布隆和他的妻子，他們逃離了自己在法布隆南瓜農場的家，如今在這座農場棲身。",
			source = "https://warcraft.wiki.gg/wiki/Jansen_Stead",
		},
		["longshore"] = {
			name = "長灘",
			short = "西部荒野的海岸綿長而空曠，是艾澤拉斯最寬闊的海灘之一。",
			full = "西部荒野的海岸綿長而空曠，是艾澤拉斯最寬闊的海灘之一。魚人成群沿著海岸移動，數量多得無法阻擋，而老瞎眼就游在牠們之中，這頭生物讓沿岸的漁民學會了畏懼，也為牠取了名字。在浪花之外，躺著那些未能靠岸的船隻殘骸，其中包括精靈的驅逐艦，任由潮水擺布。\n\n在海灘的遠西南端，矗立著達芙妮·斯迪威爾的農場。迪菲亞兄弟會不只一次找上她，打算像燒毀西部荒野其他許多地方一樣，把她也燒得無家可歸。她的困境傳到了達索瑞恩·拉爾耳中，他派了有志成為白銀之手騎士的年輕人前往海岸，守護她的土地，而他們守住了。",
			source = "https://warcraft.wiki.gg/wiki/Longshore",
		},
		["molsen farm"] = {
			name = "摩爾森農場",
			short = "摩爾森農場是西部荒野眾多被迪菲亞兄弟會佔據的農場之一。",
			full = "摩爾森農場是西部荒野眾多被迪菲亞兄弟會佔據的農場之一。田壟之間只剩鏽蝕與機械，機械收割看守者在田地裡遊蕩，襲擊任何靠得太近的人。",
			source = "https://warcraft.wiki.gg/wiki/Molsen_Farm",
		},
		["moonbrook"] = {
			name = "月溪鎮",
			short = "月溪鎮的田地底下，曾經流淌著暴風城三分之一的國庫財富，那些黃金取自後來被稱為死亡礦坑的坑道。",
			full = "月溪鎮的田地底下，曾經流淌著暴風城三分之一的國庫財富，那些黃金取自後來被稱為死亡礦坑的坑道。這座小鎮曾是王國的糧倉，直到石匠公會遭到解散，引發暴動，導致蒂芬·烏瑞恩王后喪命。瓦里安國王為她的死所展開的報復，最沉重地落在公會身上，石匠們為了躲避他而逃進西部荒野的農田。在暗中有人煽風點火之下，他們的憤怒化成了迪菲亞兄弟會。在艾德溫·范克里夫的率領下，他們淪為盜匪，將農夫趕出月溪鎮，並將鎮底下廢棄的礦坑坑道作為總部，在那裡祕密建造一件意圖從海上摧毀暴風城的武器。\n\n多年來沒有任何軍隊前來應對他們。兄弟會至今仍盤據著月溪鎮，唯有格里安·斯托曼的西部荒野人民軍與之對抗，他們在哨兵嶺積蓄力量，等待著尚未到來的清算之日。",
			source = "https://warcraft.wiki.gg/wiki/Moonbrook",
		},
		["saldeans farm"] = {
			name = "薩丁農場",
			short = "薩丁農場是西部荒野唯一從未被迪菲亞兄弟會攻陷的農場。迪菲亞的收割魔像在它的田地上遊蕩，但農夫薩丁與他的妻子薩爾瑪拒絕離開。",
			full = "薩丁農場是西部荒野唯一從未被迪菲亞兄弟會攻陷的農場。迪菲亞的收割魔像在它的田地上遊蕩，但農夫薩丁與他的妻子薩爾瑪拒絕離開。多年來，他們的農舍一直充當中途之家，這對夫妻竭盡所能地讓他們的客人活下去。",
			source = "https://warcraft.wiki.gg/wiki/Saldean's_Farm",
		},
		["sentinel hill"] = {
			name = "哨兵嶺",
			short = "哨兵嶺位於西部荒野農田上方的高地，它的高塔俯瞰著建在下方山坡上的小屋、鍛爐與磨坊。",
			full = "哨兵嶺位於西部荒野農田上方的高地，它的高塔俯瞰著建在下方山坡上的小屋、鍛爐與磨坊。\n\n河爪豺狼人與迪菲亞兄弟會都曾襲擊過這座山嶺與它所守護的土地。",
			source = "https://warcraft.wiki.gg/wiki/Sentinel_Hill",
		},
		["stendels pond"] = {
			name = "斯特登的池塘",
			short = "哨兵嶺西南方有一座小池塘，在一圈豺狼人的環伺之下，池水一片死寂。",
			full = "哨兵嶺西南方有一座小池塘，在一圈豺狼人的環伺之下，池水一片死寂。池邊有兩座墳墓，還散落著一些陳年白骨，池水似乎有什麼地方不對勁，彷彿它再也不是用來飲用的。\n\n在那裡碰運氣的漁夫，多半只能釣起普通的鼠尾魚。但據說水面下還游著別的東西，一種名為斯特登之禍的魚，難得一見，能釣到的更是少之又少。",
			source = "https://warcraft.wiki.gg/wiki/Stendel's_Pond",
		},
		["westfall lighthouse"] = {
			name = "西部荒野燈塔",
			short = "這座燈塔矗立在西部荒野的最南端，夜裡燈光依然在海面上旋轉，只是看守它的那雙手，如今屬於一個死人。",
			full = "這座燈塔矗立在西部荒野的最南端，夜裡燈光依然在海面上旋轉，只是看守它的那雙手，如今屬於一個死人。\n\n曾有一戶人家負責看守燈火，直到魚人老瞎眼從浪花中爬出，把他們嚇得落荒而逃。他們回來後重新點亮了燈塔，但老瞎眼又回來了，這一次還帶著沿岸的魚人一同突襲燈塔。那戶人家沒能活下來。格雷森眼睜睜看著他們死在自己面前，卻無力阻止，如今看守燈火的正是他的鬼魂，他站在塔外守望，再也沒有人能來替他換班。",
			source = "https://warcraft.wiki.gg/wiki/Westfall_Lighthouse",
		},
	},
	-- 濕地: 23 subzones
	[1437] = {
		["angerfang encampment"] = {
			name = "怒牙營地",
			short = "怒牙營地橫跨濕地中部，是龍喉氏族在該地區最大的營地，也是怒牙獸人的家園。",
			full = "怒牙營地橫跨濕地中部，是龍喉氏族在該地區最大的營地，也是怒牙獸人的家園。\n\n在納克羅斯·碎顱者之子納克羅西·碎顱者的統領下，這座營地已成為一處集結地，囤積著準備用來進攻米奈希爾港的投石車。這個威脅千真萬確，以至於斯托菲隊長誓言要在投石車出動之前，親眼看到納克羅西死去，並扯下這個氏族的戰旗。",
			source = "https://warcraft.wiki.gg/wiki/Angerfang_Encampment",
		},
		["baradin bay"] = {
			name = "巴拉丁海灣",
			short = "巴拉丁海灣的海水沖刷著卡茲莫丹與羅德隆交界的海岸，拍打著米奈希爾港與激流堡的岸邊。",
			full = "巴拉丁海灣的海水沖刷著卡茲莫丹與羅德隆交界的海岸，拍打著米奈希爾港與激流堡的岸邊。魚人與鱷魚在淺水處漂游，鯊魚與螃蟹則盤據著較深的水域。\n\n海灣真正的歷史，破碎地躺在海底。第二次大戰期間，庫爾提拉斯艦隊在這片水域巡邏，守護海岸，抵禦蔓延整個東部王國的戰火。然而庫爾提拉斯為這份警戒付出了慘痛的代價：該國的第三艦隊在戰鬥中全軍覆沒。部分殘骸至今仍破碎地躺在濕地沿岸，在它們解體的淺水處清晰可見，其餘的則完全沉沒，落入下方的黑暗之中，從此再也沒有人將它們打撈上來。",
			source = "https://warcraft.wiki.gg/wiki/Baradin_Bay",
		},
		["black channel marsh"] = {
			name = "黑水沼澤",
			short = "通往米奈希爾港的道路沿著濕地西南部的黑水沼澤邊緣延伸。",
			full = "通往米奈希爾港的道路沿著濕地西南部的黑水沼澤邊緣延伸。迅猛龍在整片沼地中築巢，較飢餓的那些還會遊蕩到路邊附近，因此經過這一段路的旅人最好保持警戒。",
			source = "https://warcraft.wiki.gg/wiki/Black_Channel_Marsh",
		},
		["bluegill marsh"] = {
			name = "藍腮沼澤",
			short = "在濕地西部的藍腮沼澤水域中，分布著藍腮魚人的營地，牠們從不單獨行動，總是三三兩兩地出沒於蘆葦之間。",
			full = "在濕地西部的藍腮沼澤水域中，分布著藍腮魚人的營地，牠們從不單獨行動，總是三三兩兩地出沒於蘆葦之間。率領牠們的是貪吃者，一隻比其他魚人更兇猛的魚人，有牠在，這片沼澤最好還是小心進入。",
			source = "https://warcraft.wiki.gg/wiki/Bluegill_Marsh",
		},
		["deepwater tavern"] = {
			name = "深水旅店",
			short = "深水旅店位於米奈希爾港，大廳裡總是充斥著過往水手的談笑聲。",
			full = "深水旅店位於米奈希爾港，大廳裡總是充斥著過往水手的談笑聲。這是個粗野的地方，椅子被扔出去的次數和倒酒的次數一樣多，而鬥毆往往是在「乾柴」塔伯克·賈恩的慫恿之下開始的。",
			source = "https://warcraft.wiki.gg/wiki/Deepwater_Tavern",
		},
		["direforge hill"] = {
			name = "惡鐵嶺",
			short = "惡鐵嶺曾是黑鐵矮人的一座主要營地，由術士卑鄙的巴加拉斯率領。",
			full = "惡鐵嶺曾是黑鐵矮人的一座主要營地，由術士卑鄙的巴加拉斯率領。",
			source = "https://warcraft.wiki.gg/wiki/Direforge_Hill",
		},
		["dragonmaw gates"] = {
			name = "龍喉大門",
			short = "龍喉大門由紅龍軍團把守，統領牠們的是幼龍埃克斯托茲，牠擋住了所有試圖前往格瑞姆巴托的人。",
			full = "龍喉大門由紅龍軍團把守，統領牠們的是幼龍埃克斯托茲，牠擋住了所有試圖前往格瑞姆巴托的人。",
			source = "https://warcraft.wiki.gg/wiki/Dragonmaw_Gates",
		},
		["dun algaz"] = {
			name = "丹奧加茲",
			short = "貫穿丹奧加茲的隧道，比分裂矮人的那場紛爭還要古老。當三錘之戰將蠻錘部族逐出鐵爐堡時，他們正是從這道隘口撤離的。",
			full = "貫穿丹奧加茲的隧道，比分裂矮人的那場紛爭還要古老。當三錘之戰將蠻錘部族逐出鐵爐堡時，他們正是從這道隘口撤離的。\n\n部落也曾經由此撤退。獸人在丹莫德被擊退後，向南越過薩多爾山谷，在這裡的前哨據守，安度因·洛薩為了將他們徹底逐出卡茲莫丹，派兵前去摧毀這座要塞。這次進攻失敗了。獸人堅守不退，丹奧加茲成了部落在該地區最後保有的據點，一個無法撼動的立足之地。\n\n看守這道隘口的矮人巡山人多半駐守在上方的山丘，但龍喉氏族攻陷了他們的哨站，將他們逼退到上層隧道，他們至今仍在那裡苦撐。由於下方的隘口失守，矮人故土與米奈希爾港之間的道路變得危險許多。",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["dun modr"] = {
			name = "丹莫德",
			short = "丹莫德位於薩多爾大橋南方，是一座早已淪為廢墟的古老矮人城市，鐵匠舖與兼營釀酒的旅店依然矗立在殘骸之中，而這片殘骸如今已被黑鐵矮人據為己有。",
			full = "丹莫德位於薩多爾大橋南方，是一座早已淪為廢墟的古老矮人城市，鐵匠舖與兼營釀酒的旅店依然矗立在殘骸之中，而這片殘骸如今已被黑鐵矮人據為己有。\n\n第二次大戰期間，獸人部落奪下了這片廢墟，並在此建立前哨，用來擊退聯盟軍隊、劫掠周遭的農田，這裡成了他們大軍至關重要的集結地。激流堡的戰士從島上要塞托爾巴拉德出擊，意圖摧毀這座前哨，他們展開圍攻，將獸人逼退至南方位於丹奧加茲的第二據點。部落隨即反擊，奪回丹莫德，甚至將兵鋒指向托爾巴拉德本身。直到部落在王都潰敗，安度因·洛薩才將他們經由薩多爾大橋逐回卡茲莫丹，丹莫德也因此落入聯盟手中。\n\n那份和平並未持續。鐵爐堡的士兵在遠離家鄉的戰爭中消耗殆盡，黑鐵矮人趁機突破薩多爾大橋，不久之後，丹莫德便落入術士卑鄙的巴加拉斯之手，如今他掌控著這座被他族人據為己有的城市。",
			source = "https://warcraft.wiki.gg/wiki/Dun_Modr",
		},
		["green belt"] = {
			name = "綠帶草地",
			short = "綠帶草地遍布著鱷魚、沼澤獸與軟泥怪，綠色守護者雷希爾在此守望，他對這片變得怪異而不安寧的土地感到憤怒。",
			full = "綠帶草地遍布著鱷魚、沼澤獸與軟泥怪，綠色守護者雷希爾在此守望，他對這片變得怪異而不安寧的土地感到憤怒。\n\n在西方，泥沼獸變得充滿惡意。在東北方，火元素出人意料地從惡鐵嶺中冒了出來。兩者都是雷希爾所守護的這片土地上的傷口，而且都未曾平息。\n\n綠帶草地之中有一支被摧毀的龍喉氏族車隊，如今紅色幼龍在殘骸間築巢。這是一次企圖偷走黑龍軍團幼龍的行動所留下的唯一痕跡，那次行動在此告終，被沼澤吞沒。",
			source = "https://warcraft.wiki.gg/wiki/Green_Belt",
		},
		["grim batol"] = {
			name = "格瑞姆巴托",
			short = "格瑞姆巴托是一座位於濕地東部的山中要塞。它有著巍峨的城牆與尖塔，直指鋼灰色的天空，但要塞的主體卻深藏於地底。",
			full = "格瑞姆巴托是一座位於濕地東部的山中要塞。它有著巍峨的城牆與尖塔，直指鋼灰色的天空，但要塞的主體卻深藏於地底。它由蠻錘矮人建立，直到三錘之戰期間遭到詛咒。後來它被獸人奪取，作為囚禁巨龍守護者雅立史卓莎的牢籠，直到她在格瑞姆巴托之戰中獲救。",
			source = "https://warcraft.wiki.gg/wiki/Grim_Batol",
		},
		["ironbeards tomb"] = {
			name = "鐵鬚之墓",
			short = "鐵鬚之墓位於濕地中北部、通往丹莫德道路的西側。一座矮人雕像矗立在墓地上方，想必是依照鐵鬚本人的樣貌所雕刻的。",
			full = "鐵鬚之墓位於濕地中北部、通往丹莫德道路的西側。一座矮人雕像矗立在墓地上方，想必是依照鐵鬚本人的樣貌所雕刻的。\n\n長眠於此的死者已不再安寧。黑色、深紅色以及各種怪異色澤的軟泥怪爬進了墓穴，玷污了它，並擴散到整座墓地，如今想要安葬親人的人，再也沒有誰願意靠近這裡。",
			source = "https://warcraft.wiki.gg/wiki/Ironbeard's_Tomb",
		},
		["lost fleet"] = {
			name = "失落的艦隊",
			short = "浪潮女王號與無畏號的殘骸躺在巴拉丁海灣的海床上，位於藍腮沼澤北部的外海。",
			full = "浪潮女王號與無畏號的殘骸躺在巴拉丁海灣的海床上，位於藍腮沼澤北部的外海。\n\n它們隸屬於庫爾提拉斯第三艦隊，在第二次大戰期間由德瑞克·普勞德摩爾指揮，他是海軍上將戴林·普勞德摩爾的長子。在冠陷之戰中，被龍喉氏族奴役的紅龍從天而降，將艦隊付之一炬。德瑞克爬上瞭望台，想要警告他的父親危險將至。然而在警告發揮作用之前，一頭巨龍便在那裡殺死了他，不久之後，他的船也隨著艦隊的其餘船隻一同沉沒。只有一個人倖存下來，那就是浪潮女王號的大副菲茲莫斯。\n\n死者並未就此安息。在無畏號的貨艙深處，船長哈林多爾出於貪婪，藏了一顆焦黑的寶珠：帕雷斯的詛咒之眼。多年之後，它的詛咒侵入了沉船上的船員，將他們束縛於不死之身。唯有大副斯內利格在這之中保住了神智，他的鬼魂至今仍在附近的海岸上徘徊。",
			source = "https://warcraft.wiki.gg/wiki/Lost_Fleet",
		},
		["menethil bay"] = {
			name = "米奈希爾海灣",
			short = "米奈希爾海灣位於港口與丹莫洛的峭壁之間，蜷縮在巴拉丁海灣的入海口內。",
			full = "米奈希爾海灣位於港口與丹莫洛的峭壁之間，蜷縮在巴拉丁海灣的入海口內。\n\n海灣的入口附近躺著飛鷹號的殘骸，殘破的船身沉落在水中。",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Bay",
		},
		["menethil harbor"] = {
			name = "米奈希爾港",
			short = "任何人首先注意到的都是城牆，厚實的石牆環繞著一座港口小鎮，小鎮一半建在岩石上，一半伸入海中。",
			full = "任何人首先注意到的都是城牆，厚實的石牆環繞著一座港口小鎮，小鎮一半建在岩石上，一半伸入海中。四座塔樓高聳其上，同時監視著海面與道路，除了橋樑、潮水，或一條通往大陸的地下密道之外，再無其他入口。\n\n這裡最早的造船廠是獸人建立的。第一次大戰之後，大酋長奧格林·末日錘選中這片海岸，打造一支艦隊，用來載運部落繞過羅德隆的陸上防線，為此他從卡茲莫丹的矮人礦坑中掠奪鐵礦與木材。第二次大戰結束後，聯盟接收了此地，將其重建為自己的港口，海軍上將戴林·普勞德摩爾以羅德隆國王泰瑞納斯·米奈希爾二世之名，將它命名為米奈希爾港。\n\n此後多年，迅猛龍不時從山丘中衝出襲擊小鎮，數量從來不多，但次數卻相當頻繁。",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Harbor",
		},
		["menethil keep"] = {
			name = "米奈希爾城堡",
			short = "四座塔樓聳立在米奈希爾港上方，如嚴厲的守衛般俯瞰著下方的小鎮。這就是米奈希爾城堡。",
			full = "四座塔樓聳立在米奈希爾港上方，如嚴厲的守衛般俯瞰著下方的小鎮。這就是米奈希爾城堡。",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Keep",
		},
		["mosshide fen"] = {
			name = "蘚皮沼澤",
			short = "蘚皮沼澤是濕地東部一片積水的地帶，地面被蘚皮豺狼人的營地分割得支離破碎。",
			full = "蘚皮沼澤是濕地東部一片積水的地帶，地面被蘚皮豺狼人的營地分割得支離破碎。這個部族佔據著沼澤，捕捉並吞食任何深入沼地太遠的人。",
			source = "https://warcraft.wiki.gg/wiki/Mosshide_Fen",
		},
		["raptor ridge"] = {
			name = "恐龍嶺",
			short = "恐龍嶺聳立於濕地東部、龍喉大門西北方，山坡與洞穴中滿是迅猛龍。刺喉龍族母就在洞穴深處守護著她的蛋。",
			full = "恐龍嶺聳立於濕地東部、龍喉大門西北方，山坡與洞穴中滿是迅猛龍。刺喉龍族母就在洞穴深處守護著她的蛋。",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Ridge",
		},
		["saltspray glen"] = {
			name = "鹽沫沼澤",
			short = "鹽沫沼澤位於濕地與巴拉丁海灣的交界處，在藍腮沼澤與鐵鬚之墓之間。",
			full = "鹽沫沼澤位於濕地與巴拉丁海灣的交界處，在藍腮沼澤與鐵鬚之墓之間。它的名字來自於風：當強風從海灣吹來時，海浪會將水沫拋向這裡的內陸，比這段海岸的任何地方都更深入，直到連地面都覆上一層鹹濕的鹽漬。迅猛龍密集地在整片沼澤中築巢，就像牠們在附近的沼地與山嶺一樣。",
			source = "https://warcraft.wiki.gg/wiki/Saltspray_Glen",
		},
		["sundown marsh"] = {
			name = "日落沼澤",
			short = "日落沼澤深藏於濕地的西北部，遍布著鱷魚、豺狼人、迅猛龍、沼澤獸與軟泥怪，讓大多數旅人望而卻步。",
			full = "日落沼澤深藏於濕地的西北部，遍布著鱷魚、豺狼人、迅猛龍、沼澤獸與軟泥怪，讓大多數旅人望而卻步。沼澤中心矗立著迅輪崗哨，那是一座附有風車的小石屋，弗拉德·迅輪與溫娜·絲鬚在此安家。這對搭檔販售沼澤的出產，那些從泥濘中撈出的奇特物品，以及在別處難得一見的配方。",
			source = "https://warcraft.wiki.gg/wiki/Sundown_Marsh",
		},
		["thandol span"] = {
			name = "薩多爾大橋",
			short = "兩座巨大的石拱橫跨在濕地與阿拉希高地之間的峽谷上，由矮人之手築成，並由安威瑪家族守護了三代。",
			full = "兩座巨大的石拱橫跨在濕地與阿拉希高地之間的峽谷上，由矮人之手築成，並由安威瑪家族守護了三代。它們建於三錘之戰之後，當時鐵爐堡希望與鷹巢山的蠻錘同胞維繫情誼，於是這兩座橋既成了兩個矮人王國之間的道路，也成了它們之間的象徵，承載著讓雙方都富裕起來的貿易。\n\n如今這兩座橋傷痕累累。卡姆·深怒與卑鄙的巴加拉斯率領黑鐵矮人進攻大橋，將兩座石拱中的一座徹底摧毀，另一座也險些失守。矮人部隊奮勇作戰，守護殘存的部分，並試圖奪回附近的丹莫德鎮，許多人在那場戰鬥中陣亡，其中包括蘇利·巴魯、伊本瑟·鏽鎖，以及布萊德·長鬚的兄弟。黑鐵矮人至今仍佔據著殘骸，而卑鄙的巴加拉斯依然活在他們之中。",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thelgen rock"] = {
			name = "瑟根石",
			short = "瑟根石聳立於濕地南部，洞穴深入山中，裡頭滿是毒蜘蛛，每一道縫隙都被牠們吐出的蛛絲纏繞。",
			full = "瑟根石聳立於濕地南部，洞穴深入山中，裡頭滿是毒蜘蛛，每一道縫隙都被牠們吐出的蛛絲纏繞。在更深處的坑道中，藏著火岩礦石的礦脈，由成群的蜘蛛守護著。",
			source = "https://warcraft.wiki.gg/wiki/Thelgen_Rock",
		},
		["whelgars excavation site"] = {
			name = "維爾加挖掘場",
			short = "米奈希爾港東方的這處挖掘場，曾是矮人們安靜工作的地方，他們在這裡挖掘比記憶更古老的土地。後來斑駁迅猛龍佔據了這裡，將挖掘者困在他們自己挖掘場上方的一道山脊上。",
			full = "米奈希爾港東方的這處挖掘場，曾是矮人們安靜工作的地方，他們在這裡挖掘比記憶更古老的土地。後來斑駁迅猛龍佔據了這裡，將挖掘者困在他們自己挖掘場上方的一道山脊上。他們沒能堅守下去，最終放棄了挖掘場，在主要道路旁另建了一座營地，也就是維爾加營地。\n\n他們留下的東西至今仍半掩於土中。如今活化石與古老的元素生物在坑洞中遊走，對那些留在原地生鏽的鎬頭毫不在意。",
			source = "https://warcraft.wiki.gg/wiki/Whelgar's_Excavation_Site",
		},
	},
	-- 泰達希爾: 17 subzones
	[1438] = {
		["aldrassil"] = {
