		["lake alameth"] = {
			name = "奧拉密斯湖",
			short = "奧拉密斯湖在多蘭納爾南方廣闊地延展，是泰達希爾的大湖之一。湖岸上除了一座小碼頭之外別無他物。",
			full = "奧拉密斯湖在多蘭納爾南方廣闊地延展，是泰達希爾的大湖之一。湖岸上除了一座小碼頭之外別無他物。\n\n最近湖水的寧靜已經變了調：憤怒的林精在岸邊出沒，獨自在湖畔行走已不再安全。",
			source = "https://warcraft.wiki.gg/wiki/Lake_Al'Ameth",
