		["oracle glade"] = {
			name = "神諭林地",
			short = "神諭林地位於泰達希爾西北部，懷抱著這棵巨樹上第一座、也是最強大的一座月井。",
			full = "神諭林地位於泰達希爾西北部，懷抱著這棵巨樹上第一座、也是最強大的一座月井。這裡矗立著神諭之樹，粗壯的樹幹向上伸展成枝椏，形狀宛如一隻老鷹棲息在一頭熊的背上。許多人私下說，尋常的生長不可能長成這般形態，唯有自然魔法才能將它塑造成這樣。\n\n這棵樹與德魯伊們一同守望著泰達希爾的成長。\n\n血羽鳥身女妖在附近築巢，威脅著這棵樹，一小隊哨兵已被派來阻擋她們。",
