		["pools of arlithrien"] = {
			name = "亞里斯瑞恩之池",
			short = "在達納蘇斯以南、泰達希爾西部，亞里斯瑞恩之池曾是一片安寧之地。當瘤背熊怪佔領這一帶時，夜精靈便拋棄了那裡的一座月井。",
			full = "在達納蘇斯以南、泰達希爾西部，亞里斯瑞恩之池曾是一片安寧之地。當瘤背熊怪佔領這一帶時，夜精靈便拋棄了那裡的一座月井。這座月井仍無人照料地佇立在水池之間，如今成了充滿敵意的野生動物的棲息地。",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Arlithrien",
		},
		["ruttheran village"] = {
			name = "魯瑟蘭村",
			short = "魯瑟蘭村位於泰達希爾的根部，就在世界之樹與海水相接之處，遠在上方的達納蘇斯之下。",
			full = "魯瑟蘭村位於泰達希爾的根部，就在世界之樹與海水相接之處，遠在上方的達納蘇斯之下。它的建築與首都相比十分簡樸，卻保持得異常清新，彷彿這裡的人以簡樸為傲，而非以宏大為榮。\n\n卡多雷在這裡照料角鷹獸的棲所，收集並照顧獸蛋，將幼獸撫養到能夠飛翔。這是一份安靜的工作，由那些平日辛勤維持村莊運作、支援上方城市的人們承擔，他們從不求多少讚譽。\n\n不過，村莊裡並非只有勞動。每當仲夏火焰節慶來臨，村中的火盆便會點燃，那些照料角鷹獸蛋、裝載船隻的雙手，轉而投入歡慶之中。",
			source = "https://warcraft.wiki.gg/wiki/Rut'theran_Village",
		},
		["shadowglen"] = {
			name = "幽影谷",
			short = "在泰達希爾的枝葉之下，隱藏在島嶼東北角的，是一片從未真正見過全日光照的林間谷地。幽影谷終年籠罩在暮色之中，除了一面之外，四周都被山巒環繞。",
			full = "在泰達希爾的枝葉之下，隱藏在島嶼東北角的，是一片從未真正見過全日光照的林間谷地。幽影谷終年籠罩在暮色之中，除了一面之外，四周都被山巒環繞。只有在南方，岩壁才出現缺口，讓一條小徑穿過，通往多蘭納爾。\n\n谷地中央矗立著奧達希爾，這棵巨樹完全主宰了整片林間空地，彷彿整座山谷都是圍繞著它而佈置的。在西北方，地面敞開成影絲洞，那是一道切入環繞谷地的丘陵之中的幽暗裂隙。",
			source = "https://warcraft.wiki.gg/wiki/Shadowglen",
		},
		["shadowthread cave"] = {
			name = "影絲洞",
			short = "影絲洞位於幽影谷的西北角，在泰達希爾的根部之中。這裡一向屬於島上的巨型蜘蛛，但近來牠們變得躁動不安，洞穴也更加危險。",
			full = "影絲洞位於幽影谷的西北角，在泰達希爾的根部之中。這裡一向屬於島上的巨型蜘蛛，但近來牠們變得躁動不安，洞穴也更加危險。\n\n洞穴最深處住著『卑劣者』基塞伊斯，牠是這窩蜘蛛中最大的一隻，已經毀了不只一名誤入太深的年輕卡多雷。",
			source = "https://warcraft.wiki.gg/wiki/Shadowthread_Cave",
		},
		["starbreeze village"] = {
			name = "星風村",
			short = "星風村曾經屬於夜精靈，是幽影谷東南方的一群小屋。如今夜精靈已不在此，房屋被墮落的瘤背熊怪佔據。",
			full = "星風村曾經屬於夜精靈，是幽影谷東南方的一群小屋。如今夜精靈已不在此，房屋被墮落的瘤背熊怪佔據。烏魯森在村中的小徑上來回踱步，而在村子的邊緣，潛伏著噬夢者菲羅斯塔，單憑這頭野獸的存在，就足以說明這座村莊已經從昔日的樣貌淪落到何等地步。",
			source = "https://warcraft.wiki.gg/wiki/Starbreeze_Village",
		},
		["wellspring lake"] = {
			name = "湧泉湖",
			short = "湧泉湖的湖水源自泰達希爾內部深處的一道泉水，溢出的水流化為湧泉河。夜精靈漁夫曾經偏愛這片寧靜的水域。",
			full = "湧泉湖的湖水源自泰達希爾內部深處的一道泉水，溢出的水流化為湧泉河。夜精靈漁夫曾經偏愛這片寧靜的水域。如今棲息在這裡的林精已經墮落，夜刃豹和蜘蛛也潛入了周圍的土地，讓這個曾經寧靜的垂釣之地變得危機四伏。",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_Lake",
		},
		["wellspring river"] = {
			name = "湧泉河",
			short = "湧泉河發源於泰達希爾內部深處的一道泉水，從湧泉湖向北流到巨樹的邊緣，在那裡化為一道巨大的瀑布，傾瀉入下方的大海。",
			full = "湧泉河發源於泰達希爾內部深處的一道泉水，從湧泉湖向北流到巨樹的邊緣，在那裡化為一道巨大的瀑布，傾瀉入下方的大海。\n\n發狂的林精如今在河岸上遊蕩，攻擊任何靠近的人。",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_River",
		},
