	-- 黑海岸: 15 subzones
	[1439] = {
		["ametharan"] = {
			name = "亞米薩蘭",
			short = "亞米薩蘭的廢墟位於黑海岸奧伯丁的東南方，而這座城鎮的某些東西至今仍在那裡徘徊。",
			full = "亞米薩蘭的廢墟位於黑海岸奧伯丁的東南方，而這座城鎮的某些東西至今仍在那裡徘徊。\n\n艾薩拉女王曾建起亞米薩蘭，作為巴莎蘭的雙子城，讓她寵愛的精靈貴族安居於城中的市集和伊露恩神殿。她命埃瑟里克斯·納拉辛統治此地，這位法力強大的法師深居在他的奧薩拉克斯之塔中。\n\n當大崩裂來臨、城鎮已經開始崩塌時，城中的人民緊緊攀附著大地，彷彿只有這樣才能自救。埃瑟里克斯·納拉辛出現在他們之中，許諾施展一道法術，讓他們免於即將到來的毀滅，並在他攜帶的靈魂寶石中賜予他們永恆的生命。當他念出咒語時，他周圍的精靈紛紛死去。他所給予的永恆是一座牢籠，而非救贖；從那以後在亞米薩蘭徘徊不去的，是他們的靈魂，而非他們的生命。\n\n兩塊巨大的石碑仍佇立在廢墟之中，上面刻著這座城鎮淪陷的故事。一名前來解讀石碑的哨兵還沒讀完，就遭到不得安息的精靈貴族襲擊，只得逃離。",
			source = "https://warcraft.wiki.gg/wiki/Ameth'Aran",
		},
		["auberdine"] = {
			name = "奧伯丁",
			short = "奧伯丁坐落在大崩裂撕裂大地之處，這片海岸吞沒了古老卡多雷帝國的偉大城市。此後在黑海岸嘗試建立的每一處聚落都失敗了，唯有這座迷霧之海畔的城鎮例外。",
			full = "奧伯丁坐落在大崩裂撕裂大地之處，這片海岸吞沒了古老卡多雷帝國的偉大城市。此後在黑海岸嘗試建立的每一處聚落都失敗了，唯有這座迷霧之海畔的城鎮例外。\n\n它的發展與夜精靈社會的其他地方截然不同。它的港口吸引了來自東部王國的船隻和商人，街道上擠滿了矮人、地精、人類，甚至還有高等精靈，因此奧伯丁的燈火比一座夜精靈城鎮應有的還要明亮，為了外地人，路標上還寫著兩種文字。達納蘇斯因此看不起它。曾經造訪此地的布洛爾·熊皮認為這裡的居民不過是些被放逐者和格格不入之人，駐紮在這裡的哨兵也與她們所守護的人民保持距離。然而，曾經駐守此地的珊蒂斯·羽月卻記得，這是個充滿歡笑的地方。\n\n在燈塔附近，一艘曾由精靈艾魯拉指揮的船隻殘骸仍擱淺在礁石上，船上裝載的月神礦石也隨著船沉沒而失落。",
			source = "https://warcraft.wiki.gg/wiki/Auberdine",
		},
		["bashalaran"] = {
			name = "巴莎蘭",
			short = "在大海升起、撕裂世界之前，艾薩拉女王在黑海岸北部為她寵愛的精靈貴族建起了兩座雙子城：亞米薩蘭與巴莎蘭。",
			full = "在大海升起、撕裂世界之前，艾薩拉女王在黑海岸北部為她寵愛的精靈貴族建起了兩座雙子城：亞米薩蘭與巴莎蘭。她命法力強大的精靈埃瑟里克斯·納拉辛統治這兩座城，在他麾下效力的是阿斯特利安，一位在奧術與武藝上同樣精湛的法師。他住在巴莎蘭的人民之中，也經常前往亞米薩蘭照顧那裡的居民。在那些日子裡，這對雙子城擁有市集和伊露恩神殿，並蒙受女王本人的恩寵。\n\n當最初的永恆之井破碎時，兩座城市都化為廢墟。但在某個時候，埃瑟里克斯·納拉辛將他的法術轉而對付自己的副手，把阿斯特利安封印在一枚月石封印中，囚禁在巴莎蘭的石塊之間。主人為何背叛他的僕人，如今已無人能夠說清。阿斯特利安在囚禁中熬過了漫長而痛苦的一生，當他終於死去時，他發現死亡並沒有讓他獲得自由。他的靈魂仍被牢牢束縛，就像他的肉體曾經一樣。",
			source = "https://warcraft.wiki.gg/wiki/Bashal'Aran",
		},
		["blackwood den"] = {
			name = "黑木洞穴",
			short = "在黑海岸的最南端，靠近梣谷的邊界，散落的熊怪營地和一座小洞穴構成了名為黑木洞穴的地方，有時也被稱作黑木要塞。",
			full = "在黑海岸的最南端，靠近梣谷的邊界，散落的熊怪營地和一座小洞穴構成了名為黑木洞穴的地方，有時也被稱作黑木要塞。佔據這裡的熊怪已經墮落，扭曲得不復原本的模樣。\n\n洞穴中坐著一位名叫沃科爾的夜精靈，孤身一人被熊怪俘虜。",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Den",
		},
		["cliffspring falls"] = {
			name = "峭壁之泉",
			short = "峭壁之泉是壁泉河的源頭，曾是河中最純淨的水，也是整個黑海岸的飲用水源。那水已經不再潔淨了。",
			full = "峭壁之泉是壁泉河的源頭，曾是河中最純淨的水，也是整個黑海岸的飲用水源。那水已經不再潔淨了。瀑布湧出的洞穴已經變得污穢，腐化隨著水流向下蔓延，擴散到它曾經滋養的整個地區。\n\n沒有人能確定原因。有些人歸咎於費伍德森林，說污染只是從那片被毀的森林向外滲透而來。另一些人則指向在洞穴深處發現的東西：如今納迦正在水源處的黑暗中爬行。",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_Falls",
		},
		["cliffspring river"] = {
			name = "壁泉河",
			short = "壁泉河從峭壁之泉流向黑海岸北部的大海。河水被風暴鱗納迦所污染，飲用河水的野生動物常常因此患病。",
			full = "壁泉河從峭壁之泉流向黑海岸北部的大海。河水被風暴鱗納迦所污染，飲用河水的野生動物常常因此患病。",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_River",
		},
		["grove of the ancients"] = {
			name = "古樹之林",
			short = "古樹之林是一座古老的夜精靈神殿，它的石塊環繞著黑海岸山區中奔騰的急彎河而立。",
			full = "古樹之林是一座古老的夜精靈神殿，它的石塊環繞著黑海岸山區中奔騰的急彎河而立。知識古樹安努與一位沉睡的德魯伊和兩名商人住在這裡，古樹議會至今也仍在此聚會。",
			source = "https://warcraft.wiki.gg/wiki/Grove_of_the_Ancients",
		},
		["long wash"] = {
			name = "長橋碼頭",
			short = "長橋碼頭從奧伯丁向南延伸到亞米薩蘭以西的水域，儘管名字如此，它卻是黑海岸最短的一段海岸。",
			full = "長橋碼頭從奧伯丁向南延伸到亞米薩蘭以西的水域，儘管名字如此，它卻是黑海岸最短的一段海岸。灰色的沙灘躺在終年陰霾的天空之下。潮水退去後，只留下浮木和死去海洋生物的屍骸。海岸上可以看到魚人出沒。",
			source = "https://warcraft.wiki.gg/wiki/Long_Wash",
		},
		["masters glaive"] = {
			name = "主宰之劍",
			short = "在黑海岸的西南部，有一顆巨大的頭骨半埋在土中，一把精金戰刃仍然貫穿著骨頭。",
			full = "在黑海岸的西南部，有一顆巨大的頭骨半埋在土中，一把精金戰刃仍然貫穿著骨頭。這是『蠕行者』索苟斯，上古之神的使者，而那把利刃則被稱為主宰之劍。\n\n在雷姆塔維爾挖掘場出土的石板記載了這裡發生的事。泰坦派出二十名石巨人對抗索苟斯，隨之而來的戰鬥是如此可怕，最後只有一名巨人活著看到了結局：克羅恩，二十名巨人中體型最大的一位。當索苟斯的觸鬚將他纏住時，克羅恩沒有掙扎脫身。他任由自己被拖向內側，離那怪物的頭顱越來越近，直到近得足以出手。殺死索苟斯的那一擊，正是在牠自己的掌握之中揮出的，而留在牠頭骨中的那把劍，也以那場勝利為名。\n\n此後暮光之錘佔據了這個地方，挖掘索苟斯的遺骸，企圖推翻克羅恩之劍所成就的一切，將上古之神的使者召回這個世界。",
			source = "https://warcraft.wiki.gg/wiki/Master's_Glaive",
		},
		["mists edge"] = {
			name = "薄霧海",
			short = "被稱為薄霧海的海岸綿延於整個黑海岸，是這個地區最長的海岸線。",
			full = "被稱為薄霧海的海岸綿延於整個黑海岸，是這個地區最長的海岸線。\n\n這是一段陰鬱的海岸：灰色的沙灘和冷峻的海灣上，散落著死去的巨大海洋生物的屍骸，以及沉船的殘骸。\n\n螃蟹在整段海岸上橫行，魚人則潛伏在淺灣之中，對任何沿著海岸行走的人都是揮之不去的威脅。",
			source = "https://warcraft.wiki.gg/wiki/Mist's_Edge",
		},
		["remtravels excavation"] = {
			name = "雷姆塔維爾挖掘場",
			short = "勘察員雷姆塔維爾以自己的名字為黑海岸的這處挖掘場命名。",
			full = "勘察員雷姆塔維爾以自己的名字為黑海岸的這處挖掘場命名。他在挖掘時發現了一塊與眾不同的化石，散發著神秘的力量，但這位心不在焉的勘察員後來卻忘了自己把它放在哪裡。\n\n挖掘場本身也變得危險起來：礫燧穴居人佔據了它的坑道，而因挖掘而出土的巨大石像，如今也在其中甦醒。",
			source = "https://warcraft.wiki.gg/wiki/Remtravel's_Excavation",
		},
		["ruins of mathystra"] = {
			name = "瑪塞斯特拉廢墟",
			short = "越過奧薩拉克斯之塔，在黑海岸北部，坐落著瑪塞斯特拉廢墟。在大崩裂之前，它是夜精靈的一座城市，建於精靈貴族的時代。",
			full = "越過奧薩拉克斯之塔，在黑海岸北部，坐落著瑪塞斯特拉廢墟。在大崩裂之前，它是夜精靈的一座城市，建於精靈貴族的時代。當永恆之井自我毀滅、世界在它之下崩裂時，瑪塞斯特拉和許多其他地方一同被毀，倖存的夜精靈再也沒有回來重建它。他們轉而退往南方沿海較小的村落，將廢墟拋在身後。\n\n古代精靈貴族的遺物仍散落在倒塌的石塊之間，年輕的夜精靈有時會到瑪塞斯特拉搜尋它們，同時也要提防在他們的先人所建造的廢墟之間徘徊的幽靈豹。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Mathystra",
		},
		["tower of althalaxx"] = {
			name = "奧薩拉克斯之塔",
			short = "在大崩裂的時代，當艾薩拉女王將精靈貴族置於眾人之上時，她命一位名叫埃瑟里克斯·納拉辛的精靈統治亞米薩蘭和巴莎蘭這兩座雙子城。",
			full = "在大崩裂的時代，當艾薩拉女王將精靈貴族置於眾人之上時，她命一位名叫埃瑟里克斯·納拉辛的精靈統治亞米薩蘭和巴莎蘭這兩座雙子城。埃瑟里克斯起初為她盡忠職守，但這份工作讓他感到厭倦，於是他開始遠離城鎮，在一座屬於自己、名為奧薩拉克斯的高塔中度日。\n\n一萬年後，長久以來關於這座高塔的傳聞被證實了。一個自稱暗灘教派的教團聚集在那裡，其中有術士，也有一名薩特，而站在他們之首的，正是埃瑟里克斯·納拉辛本人。他們的目的一直不明，直到後來才揭露，這個教派聽命於暗影議會，而奧薩拉克斯已成為那個古老陰謀之網中的又一條絲線。",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Althalaxx",
		},
		["twilight vale"] = {
			name = "暮光谷",
			short = "亞米薩蘭以南、一直延伸到梣谷邊界的森林，被稱為暮光谷。",
			full = "亞米薩蘭以南、一直延伸到梣谷邊界的森林，被稱為暮光谷。墮落的熊怪、野性的夜刃豹和狂暴的熊在這片森林中出沒，旅人們最好沿著道路前行，而不要在樹林間遊蕩。",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Vale",
		},
		["wildbend river"] = {
			name = "急彎河",
			short = "急彎河從山區帶來了病害，它是血毒河的延續，從費伍德森林流入黑海岸南部，靠近古樹之林。",
			full = "急彎河從山區帶來了病害，它是血毒河的延續，從費伍德森林流入黑海岸南部，靠近古樹之林。河水已被污染，費伍德森林的腐化隨著水流一路向下，蔓延到這片低地。",
			source = "https://warcraft.wiki.gg/wiki/Wildbend_River",
		},
	},
	-- 梣谷: 41 subzones
	[1440] = {
		["astranaar"] = {
			name = "阿斯特蘭納",
			short = "阿斯特蘭納從梣谷中心的一座島嶼上拔地而起，是該地區最大的夜精靈聚落，只能經由兩座將道路架設於水面之上的橋樑抵達。",
			full = "阿斯特蘭納從梣谷中心的一座島嶼上拔地而起，是該地區最大的夜精靈聚落，只能經由兩座將道路架設於水面之上的橋樑抵達。湖泊將它與周圍的森林隔開，使它成為這片爭奪之地中心一處寧靜而易守的據點。\n\n它的墓地位於湖岸邊，城鎮的逝者安息在一排排寂靜的石碑之間。\n\n在城鎮之外，薊皮熊怪已在北方壯大了力量，阿斯特蘭納的居民擔心，牠們總有一天會鼓起勇氣，將這股力量轉而對付城鎮本身。",
			source = "https://warcraft.wiki.gg/wiki/Astranaar",
		},
		["bathrans haunt"] = {
			name = "巴斯蘭鬼屋",
			short = "巴斯蘭鬼屋的石柱曾是一座卡多雷遺跡的一部分，建於夜精靈仍在梣谷這一帶行走的年代。",
			full = "巴斯蘭鬼屋的石柱曾是一座卡多雷遺跡的一部分，建於夜精靈仍在梣谷這一帶行走的年代。那個年代過去了，精靈們撤離了，大理石被留下來任其龜裂傾倒。\n\n如今這裡並非空無一人。被遺忘者的密探已在斷裂的石柱間落腳，其中有草藥師，也有保護他們的打手，而無論他們在哪裡落腳，土地都會隨之回應：草地變得枯黃，花朵紛紛凋零。他們在倒塌的石塊間搭起了一座簡陋的實驗室，為了自己的目的處理當地的草藥。\n\n吸引他們來到這裡的，主要是一種附近別處都找不到的植物：巴斯蘭之髮，一種療效珍稀的草藥，光是它就值得他們獨佔此地。",
			source = "https://warcraft.wiki.gg/wiki/Bathran's_Haunt",
		},
		["blackfathom deeps"] = {
			name = "黑澗深淵",
			short = "在佐拉姆海岸之下，古城佐拉姆沉入大海之處，坐落著拉薩拉薩爾被淹沒的殿堂，那裡曾是一座伊露恩神殿。",
			full = "在佐拉姆海岸之下，古城佐拉姆沉入大海之處，坐落著拉薩拉薩爾被淹沒的殿堂，那裡曾是一座伊露恩神殿。人們以為大崩裂已將它徹底摧毀，數千年來，大海一直將它收藏在深處。\n\n後來暮光之錘來了，他們受到低語與邪惡夢境的吸引，進入了神殿所化成的水下洞窟。這個教派在那片深淵中獻祭了無數無辜的生命，並因此獲得了一項任務：培育並守護一頭上古之神所珍愛的生物——可怕的九頭蛇『吞噬者』阿庫麥爾——直到牠被釋放到世界上的那一天。這個地方如今被稱為黑澗，這個名字再貼切不過。",
			source = "https://warcraft.wiki.gg/wiki/Blackfathom_Deeps",
		},
		["bloodtooth camp"] = {
			name = "血牙營地",
			short = "血牙營地位於弗倫河以西，在梣谷南方月井的西南方。它的名字來自佔據這裡的熊怪部族酋長蘭·血牙。",
			full = "血牙營地位於弗倫河以西，在梣谷南方月井的西南方。它的名字來自佔據這裡的熊怪部族酋長蘭·血牙。\n\n這些熊怪曾經和其他同類沒什麼兩樣，但腐化已經吞噬了牠們每一個，如今營地對任何靠近的外人都報以敵意。",
			source = "https://warcraft.wiki.gg/wiki/Bloodtooth_Camp",
		},
		["bough shadow"] = {
			name = "大樹蔭",
			short = "越過林歌神殿，在梣谷樹木茂密而古老之處，大樹蔭守護著一道通往翡翠夢境的傳送門。",
			full = "越過林歌神殿，在梣谷樹木茂密而古老之處，大樹蔭守護著一道通往翡翠夢境的傳送門。\n\n綠龍軍團守衛著這裡。幼龍范提姆和夢境追獵者看守著這道通道，龍人則以三人一組在周圍的森林中巡邏，一名翡翠龍人神諭者由枝幹守衛和樹木守護者護衛在兩側，在漫長的守望中一再踏過同一片土地。",
			source = "https://warcraft.wiki.gg/wiki/Bough_Shadow",
		},
		["demon fall canyon"] = {
			name = "屠魔峽谷",
			short = "屠魔峽谷留有獸人掙脫古老束縛那一刻的傷痕。",
			full = "屠魔峽谷留有獸人掙脫古老束縛那一刻的傷痕。\n\n深淵領主瑪諾洛斯就是在這裡與葛羅瑪許·地獄吼和索爾展開殊死搏鬥。惡魔擊倒了索爾，卻來不及避開葛羅的戰斧，那一斧深深劈進了他的胸膛。瑪諾洛斯死時爆發出烈焰與光芒，而同一道火焰在吞噬惡魔的同時，也奪走了葛羅的生命。獸人以這個他犧牲的地方為他命名，因為正是在這裡，燃燒軍團加諸於他們族人身上的詛咒被打破了。\n\n至今仍有許多獸人長途跋涉來到這裡，向這位為自由付出代價的戰士致敬，一座紀念碑也為了紀念他而矗立於此。但這片土地仍受邪能沾染，如今低階惡魔在峽谷中出沒。",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Canyon",
		},
		["demon fall ridge"] = {
			name = "屠魔山",
			short = "在屠魔峽谷上方，山脊崎嶇破碎，它的山坡以及鑿入山側的獸穴都被低階惡魔佔據。",
			full = "在屠魔峽谷上方，山脊崎嶇破碎，它的山坡以及鑿入山側的獸穴都被低階惡魔佔據。在更深處，日光照不到的地方，等待著『追尋者』迪亞索魯斯，這名恐懼魔王統治著聚集在梣谷的惡魔集會，他在黑暗中發號施令，而低階的惡魔則守衛著上方的山脊。",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Ridge",
		},
		["dordanil barrow den"] = {
			name = "朵丹尼爾獸穴",
			short = "朵丹尼爾獸穴長久以來一直是夜精靈德魯伊的安息之所，他們的肉體在此沉睡，靈魂則自由遊蕩。",
			full = "朵丹尼爾獸穴長久以來一直是夜精靈德魯伊的安息之所，他們的肉體在此沉睡，靈魂則自由遊蕩。正是被遺忘者將注意力轉向了這些沉睡者，切斷了德魯伊與他們遊蕩靈魂之間的聯繫。這場實驗沒有殺死他們，卻讓他們陷入了瘋狂。\n\n如今獸穴裡已沒有安詳的沉睡者。被遺忘者的刺客在其中神不知鬼不覺地穿梭，而被切斷聯繫的德魯伊那憤怒的靈魂則在墓穴中肆虐，無處可歸。其中有三個靈魂比其他的更加強大——尤希爾·喚月、瑪沃裡斯·裂雲和坦尼爾·黑木。",
			source = "https://warcraft.wiki.gg/wiki/Dor'Danil_Barrow_Den",
		},
		["falfarren river"] = {
			name = "弗倫河",
			short = "弗倫河幾乎將梣谷一分為二。河的西邊是阿斯特蘭納治下的夜精靈；東邊則是獸人據守的碎木崗哨。",
			full = "弗倫河幾乎將梣谷一分為二。河的西邊是阿斯特蘭納治下的夜精靈；東邊則是獸人據守的碎木崗哨。這條河淺得可以涉水而過，窄得不費多少力氣就能渡過，除非雨水讓它漫過河岸；但它依然是一條界線，兩個種族都心照不宣。\n\n它的河水發源於海加爾山的山坡，經由層層瀑布流入薩維亞的湖泊，然後流經碎木崗哨與夜道谷之間，從大多數旅人橫越梣谷時所走的大橋下穿過，再經過銀翼哨站和淨化月井，最後潛入北方山脈之下，流向貧瘠之地。\n\n在冥火嶺附近，這條河還隱藏著另一種危險。沼澤獸潛伏在那裡的水面下，襲擊任何在水中逗留太久的東西。",
			source = "https://warcraft.wiki.gg/wiki/Falfarren_River",
		},
		["fallen sky lake"] = {
			name = "墜星湖",
			short = "在梣谷銀翼哨站的南方有一座小湖，湖水環繞著一座孤島。",
			full = "在梣谷銀翼哨站的南方有一座小湖，湖水環繞著一座孤島。島上住著一名沼澤獸神諭者，牠是沼澤獸族群中的長者，較少數的同族環繞在湖岸，從周圍的蘆葦和灌木叢中守望著湖水。",
			source = "https://warcraft.wiki.gg/wiki/Fallen_Sky_Lake",
		},
		["felfire hill"] = {
			name = "冥火嶺",
			short = "冥火嶺至今仍帶著第三次大戰的傷痕，當時地獄火從天空燃燒著墜落，撞擊在這片大地上。從那以後惡魔便一直在此徘徊，這些污穢之物在岩石間築巢。",
			full = "冥火嶺至今仍帶著第三次大戰的傷痕，當時地獄火從天空燃燒著墜落，撞擊在這片大地上。從那以後惡魔便一直在此徘徊，這些污穢之物在岩石間築巢。\n\n部落在通往山嶺的兩座橋上都築起了防禦工事，把守著它們，以防惡魔湧向附近的聚落。",
			source = "https://warcraft.wiki.gg/wiki/Felfire_Hill",
		},
		["fire scar shrine"] = {
			name = "火痕神殿",
			short = "火痕神殿位於梣谷西南部，受到暗影議會的惡魔影響而墮落，最終成了一處極度邪惡之地。",
			full = "火痕神殿位於梣谷西南部，受到暗影議會的惡魔影響而墮落，最終成了一處極度邪惡之地。獸人術士伊克魯德·瑪格蘇爾曾住在這裡，效力於暗灘教派的首領埃瑟里克斯·納拉辛。\n\n如今惡魔盤據著神殿，受到石塊中殘留的污穢所吸引。其中一名叫做阿克里魯斯的末日守衛不時會在這一帶出現，這罕見而危險的徵兆顯示了腐化有多麼深重。",
			source = "https://warcraft.wiki.gg/wiki/Fire_Scar_Shrine",
		},
		["forest song"] = {
			name = "林歌神殿",
			short = "林歌神殿是梣谷森林中一座古老的夜精靈遺跡，長久以來只剩苔蘚與回憶。有一段時間，這裡幾乎空無一人。",
			full = "林歌神殿是梣谷森林中一座古老的夜精靈遺跡，長久以來只剩苔蘚與回憶。有一段時間，這裡幾乎空無一人。\n\n後來德魯伊凱尼斯·靜風將這裡據為己有，成為遺跡中唯一的居民，並在這些石塊間指揮當地對抗被遺忘者的戰鬥。一個被遺忘的地方就此成了哨站，靠的不是人數，而是一位德魯伊不肯離去的決心。",
			source = "https://warcraft.wiki.gg/wiki/Forest_Song",
		},
		["greenpaw village"] = {
			name = "綠爪村",
			short = "綠爪村是汙林部族的家園，這些熊怪由酋長穆戈特和薩滿橡爪領導。這裡的熊人都已墮落。",
			full = "綠爪村是汙林部族的家園，這些熊怪由酋長穆戈特和薩滿橡爪領導。這裡的熊人都已墮落。",
			source = "https://warcraft.wiki.gg/wiki/Greenpaw_Village",
		},
		["howling vale"] = {
			name = "狼嚎谷",
			short = "一座洞穴通向麥爾莎迪絲神殿所在的山谷，神殿的石頭上刻著讚頌伊露恩的古老銘文，上方還以達納蘇斯語寫著：真理是指引的明燈。",
			full = "一座洞穴通向麥爾莎迪絲神殿所在的山谷，神殿的石頭上刻著讚頌伊露恩的古老銘文，上方還以達納蘇斯語寫著：真理是指引的明燈。\n\n這座神殿是維琳德·星歌的母親為了紀念麥爾莎迪絲而建，麥爾莎迪絲曾受託保管月神的鐮刀。麥爾莎迪絲死後，鐮刀便被安放在這裡，藏在神殿之中。它一直被人遺忘，直到維琳德在達納蘇斯找到一本記載這段故事的書，親自來到山谷將它發掘出來。\n\n隨著時間流逝，神殿淪為廢墟，一支名為特洛烏夫的狼人部族佔領了這裡，將洞穴當成了巢穴。牠們的嚎叫在石壁間迴盪，讓這座山谷得到了現在的名字。",
			source = "https://warcraft.wiki.gg/wiki/Howling_Vale",
		},
		["iris lake"] = {
			name = "伊瑞斯湖",
			short = "伊瑞斯湖位於梣谷中北部，在阿斯特蘭納以東、莎爾蒂恩的月井以西。",
			full = "伊瑞斯湖位於梣谷中北部，在阿斯特蘭納以東、莎爾蒂恩的月井以西。它曾是完整無缺的夜精靈森林的一部分，後來卻被從費伍德森林蔓延而來的腐化所吞沒，湖水變成了令人作嘔的黃綠色。扭曲的沼澤獸如今在湖岸出沒，攻擊任何前來尋找月神之淚的人。",
			source = "https://warcraft.wiki.gg/wiki/Iris_Lake",
		},
		["kargathia keep"] = {
			name = "卡加希亞要塞",
			short = "卡加希亞要塞矗立在梣谷東部戰歌伐木營地的尖刺路障之間，靠近怒水河。",
			full = "卡加希亞要塞矗立在梣谷東部戰歌伐木營地的尖刺路障之間，靠近怒水河。它是戰歌氏族軍官的指揮所，選址的用意在於：一旦聯盟大舉進攻營地，便可以從奧格瑪召來援軍。\n\n這座要塞的名字來自獸人英雄卡加斯·刃拳，荒蕪之地的卡加斯與杜洛塔的刃拳海灣也同樣是為了紀念他而命名。監工葛薩克在要塞中指揮營地，主導梣谷林木的砍伐。",
			source = "https://warcraft.wiki.gg/wiki/Kargathia_Keep",
		},
		["lake falathim"] = {
			name = "法拉希姆湖",
			short = "法拉希姆湖位於梣谷西部，無論白天或黑夜，女神的月光總是照耀著湖面。夜精靈曾經自由地來此游泳和捕魚，直到魚人佔領了湖泊，讓它變得兇險蠻荒。",
			full = "法拉希姆湖位於梣谷西部，無論白天或黑夜，女神的月光總是照耀著湖面。夜精靈曾經自由地來此游泳和捕魚，直到魚人佔領了湖泊，讓它變得兇險蠻荒。學者泰洛尼斯最後一次被人看見就是在湖岸附近，從此再也沒有回來。",
			source = "https://warcraft.wiki.gg/wiki/Lake_Falathim",
		},
		["maestras post"] = {
			name = "邁斯特拉崗哨",
			short = "一座高塔和一座夜精靈的殿堂靜靜地佇立在這裡，駐守著寥寥數名守衛，而在梣谷最奇特的是，精靈之中還有兩名人類：費羅·艾隆漢和淨化者德爾葛蘭，他們是這座崗哨上僅有的人類。",
			full = "一座高塔和一座夜精靈的殿堂靜靜地佇立在這裡，駐守著寥寥數名守衛，而在梣谷最奇特的是，精靈之中還有兩名人類：費羅·艾隆漢和淨化者德爾葛蘭，他們是這座崗哨上僅有的人類。\n\n他們的人數很少，因為在附近熊怪之間蔓延的腐化，牽制了原本可以在這裡站崗的人手，使得崗哨的守衛捉襟見肘。",
			source = "https://warcraft.wiki.gg/wiki/Maestra's_Post",
		},
		["mystral lake"] = {
			name = "密斯特拉湖",
			short = "密斯特拉湖的湖水曾由效忠夜精靈的精靈守護，它們被束縛在湖中，作為湖的守衛。",
			full = "密斯特拉湖的湖水曾由效忠夜精靈的精靈守護，它們被束縛在湖中，作為湖的守衛。薩瑞魯斯·法伯尼使它們倒戈，腐化了這些元素，讓它們聽命於他，而不再效忠牠們曾經侍奉的精靈。如今在湖中等待的，已不是從前的模樣。",
			source = "https://warcraft.wiki.gg/wiki/Mystral_Lake",
		},
		["night run"] = {
			name = "夜道谷",
			short = "夜道谷位於一座伸入陸地的岬角上，懸崖陡峭得無法攀爬，因此旅人必須沿著弗倫河幾乎走到薩維亞的水域才能轉向西方，否則就得找到林中樹居北方那條狹窄的岩架。",
			full = "夜道谷位於一座伸入陸地的岬角上，懸崖陡峭得無法攀爬，因此旅人必須沿著弗倫河幾乎走到薩維亞的水域才能轉向西方，否則就得找到林中樹居北方那條狹窄的岩架。進去之後也沒什麼可找的：只有散落的斷柱和殘破的石造建築，這是梣谷三座薩特據點中最小也最貧瘠的一座，與薩維亞和薩提納爾相比都相形見絀。在這些廢墟中棲身的邪麝薩特並不需要城牆，因為土地本身就守護著他們。瓦礫之間藏著一顆暗灘教派的靈魂寶石，邪麝薩特正是這個教派的盟友。",
			source = "https://warcraft.wiki.gg/wiki/Night_Run",
		},
		["nightsong woods"] = {
			name = "夜歌森林",
			short = "弗倫河將東部的森林一分為二，它所劃下的界線，正是一場永無止境的戰爭的界線。",
			full = "弗倫河將東部的森林一分為二，它所劃下的界線，正是一場永無止境的戰爭的界線。在河岸以西，銀翼哨兵為聯盟堅守陣地；在河的東邊，戰歌氏族已將木樁打入大地，兩個種族之間的戰鬥在這裡最為激烈，也最為頻繁。\n\n再往東，另一條無名的河流劃出了另一道界線。一側是碎木崗哨，部落在這片森林中力量的核心；另一側則是為聯盟據守的銀翼樹林。那條河的彼岸是一片沒有人能長久擁有的土地，被林歌神殿的夜精靈、薩提納爾和薩維亞的薩特、戰歌獸人，以及燃燒軍團本身分割佔據。從來沒有哪一面旗幟能在那裡飄揚而不受挑戰。\n\n在戰線以南，森林為戰爭付出了代價。戰歌氏族將這一帶砍伐殆盡，伐倒古老的樹木取材建造聚落，在曾經綿延不絕的遠古森林之處，留下了一片光禿而傷痕累累的土地。",
			source = "https://warcraft.wiki.gg/wiki/Nightsong_Woods",
		},
		["raynewood retreat"] = {
			name = "林中樹居",
			short = "在賜予此地名字的巨樹高處枝椏間，隱藏著奧達努斯，他是林地的守護者，也是塞納留斯最年長的兒子之一。",
			full = "在賜予此地名字的巨樹高處枝椏間，隱藏著奧達努斯，他是林地的守護者，也是塞納留斯最年長的兒子之一。他來到這裡是為了躲避暗影議會，議會的爪牙已將他列為刺殺目標。其中為首的是布蕾琳·火手，她將取他性命視為唯一的目標，並派出殺手對付他。奧達努斯在這次暗殺中倖存下來，至今仍藏身於巨樹的高枝之間。\n\n在他下方，塞納里奧保衛者、閃現龍和歡笑的姐妹在哨站中守望，看守著通往費伍德森林那片枯萎之地的北方小徑。",
			source = "https://warcraft.wiki.gg/wiki/Raynewood_Retreat",
		},
		["ruins of ordilaran"] = {
			name = "奧迪拉蘭廢墟",
			short = "奧迪拉蘭如今只剩下殘破的石塊。暗灘教派曾經將這片廢墟據為己有，隨時準備襲擊任何靠得太近的人。",
			full = "奧迪拉蘭如今只剩下殘破的石塊。暗灘教派曾經將這片廢墟據為己有，隨時準備襲擊任何靠得太近的人。這一切以血腥告終：薊皮熊怪將他們趕走，把廢墟佔為己有，教徒們的屍體至今仍散落在他們倒下的地方。\n\n在殘骸之中矗立著同心樹，它紮根在一座曾經頗有名望與地位的城市之上。除此之外，再也沒有任何東西留存下來，能訴說那座城市曾經的模樣。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ordil'Aran",
		},
		["ruins of stardust"] = {
			name = "星塵廢墟",
			short = "星塵廢墟位於湖中的一座島上，曾經沉浸在神聖之中，如今卻沉淪於腐朽。從費伍德森林滲透而下的惡魔污染已經侵入湖水與石塊，將這座島染成令人作嘔的黃綠色。",
			full = "星塵廢墟位於湖中的一座島上，曾經沉浸在神聖之中，如今卻沉淪於腐朽。從費伍德森林滲透而下的惡魔污染已經侵入湖水與石塊，將這座島染成令人作嘔的黃綠色。被毒化的湖水扭曲的沼澤獸，如今拖著身軀穿行於殘骸之間。\n\n然而星塵灌木仍在那裡生長，不受周遭腐化的影響。據說它們的葉子擁有療癒的功效，是這片廢墟中唯一仍與腐朽降臨前的模樣相似的東西。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Stardust",
		},
		["satyrnaar"] = {
			name = "薩提納爾",
			short = "薩提納爾殘破地矗立在梣谷東北部的林木之間，建築早已淪為廢墟，不過如今殘骸間聚集著帳篷，冷心薩特已在此安家。",
			full = "薩提納爾殘破地矗立在梣谷東北部的林木之間，建築早已淪為廢墟，不過如今殘骸間聚集著帳篷，冷心薩特已在此安家。在森林中三座薩特據點裡，唯有薩提納爾大致保存完整，而它位於從碎木崗哨通往艾薩拉的道路旁，這使它成為三者之中最容易抵達、也最常遭到爭奪的一座。\n\n冷心薩特在這裡守護的不只是棲身之所。薩提納爾之中存放著一顆暗灘教派的靈魂寶石，象徵著將薩特與該教派黑暗目的綁在一起的盟約。",
			source = "https://warcraft.wiki.gg/wiki/Satyrnaar",
		},
		["shady nook"] = {
			name = "林蔭小徑",
			short = "林蔭小徑位於林中樹居以南、綠爪村以東，是一座靜靜隱沒在梣谷之中的小山谷。",
			full = "林蔭小徑位於林中樹居以南、綠爪村以東，是一座靜靜隱沒在梣谷之中的小山谷。山坡上有一座洞穴，一小家熊住在裡面，在林木與陰影之間與世無爭。",
			source = "https://warcraft.wiki.gg/wiki/Shady_Nook",
		},
		["shrine of aessina"] = {
			name = "艾森娜神殿",
			short = "艾森娜神殿位於梣谷西南部，隱身於邁斯特拉崗哨與阿斯特蘭納之間。",
			full = "艾森娜神殿位於梣谷西南部，隱身於邁斯特拉崗哨與阿斯特蘭納之間。",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Aessina",
		},
		["silverwind refuge"] = {
			name = "銀風避難所",
			short = "銀風避難所屬於夜精靈，由哨兵以及與她們並肩服役的水元素守衛。",
			full = "銀風避難所屬於夜精靈，由哨兵以及與她們並肩服役的水元素守衛。它與阿斯特蘭納並列為梣谷的主要據點之一，它的名字也名副其實：這是一個令人賓至如歸的地方，它的旅店被認為是這個地區較為舒適的旅店之一。",
			source = "https://warcraft.wiki.gg/wiki/Silverwind_Refuge",
		},
		["silverwing grove"] = {
			name = "銀翼樹林",
			short = "銀翼樹林位於梣谷中南部，是銀翼哨兵據守的一片樹林，在她們哨站的西南方、墜星湖的西邊。",
			full = "銀翼樹林位於梣谷中南部，是銀翼哨兵據守的一片樹林，在她們哨站的西南方、墜星湖的西邊。哨兵輕歌與那些誓言守護這片樹林的人一同在此守望。",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Grove",
		},
		["silverwing outpost"] = {
			name = "銀翼哨站",
			short = "銀翼哨站坐落在弗倫河錯誤的一側，深入碎木崗哨的獸人意圖清除的地帶。",
			full = "銀翼哨站坐落在弗倫河錯誤的一側，深入碎木崗哨的獸人意圖清除的地帶。指揮這裡的是杜瑞爾·月火，而在這裡指揮就意味著無休止的戰爭——獸人的襲擊不是為了掠奪，而是要抹去這座哨站，把每一名哨兵永遠趕出這片森林。",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Outpost",
		},
		["southfury river"] = {
			name = "怒水河",
			short = "怒水河發源於海加爾山的高處，從一座高山湖泊中傾瀉而出，化為一道轟然墜入低地的瀑布。",
			full = "怒水河發源於海加爾山的高處，從一座高山湖泊中傾瀉而出，化為一道轟然墜入低地的瀑布。從那裡開始，它寬闊而湍急地奔流，將大地一分為二：它標示出梣谷與艾薩拉的交界，再往南則是貧瘠之地的盡頭與杜洛塔的起點。在河口處，河水越過最後一道瀑布，投入無盡之海，就在哥布林港口棘齒城的東北方。\n\n沿著河道有幾座橋樑橫跨其上，一座連接艾薩拉與梣谷，另一座連接杜洛塔與貧瘠之地。在最西邊那座橋的北方不遠處，有一段水域同時觸及這四片土地，那是梣谷、艾薩拉、杜洛塔和貧瘠之地唯一交會的地方。\n\n這條河仍然灌溉著兩岸的田地，所流經之處依然讓土壤青翠。但它的水已經不能喝了。",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["splintertree post"] = {
			name = "碎木崗哨",
			short = "碎木崗哨的木材上仍留著建造它時的斧痕，因為這座哨站正是葛羅瑪許·地獄吼和他的戰歌氏族在第三次大戰期間，獸人首次挺進梣谷時所建，他們為了開路和紮營而砍伐了古老的樹木。",
			full = "碎木崗哨的木材上仍留著建造它時的斧痕，因為這座哨站正是葛羅瑪許·地獄吼和他的戰歌氏族在第三次大戰期間，獸人首次挺進梣谷時所建，他們為了開路和紮營而砍伐了古老的樹木。\n\n夜精靈從未原諒戰歌氏族對他們森林所做的一切，這些舊傷在部落與聯盟之間緊繃的停戰協定下隱隱作痛。因此，碎木崗哨比這片森林中大多數哨站招來更多報復，雙方對鄰近的阿斯特蘭納的襲擊也十分頻繁。\n\n如今留下的是一支駐軍，而非一個聚落：獸人和牛頭人擔任斥候和守衛，監視著林線，提防那些他們早已料到會來的襲擊者。",
			source = "https://warcraft.wiki.gg/wiki/Splintertree_Post",
		},
		["talondeep path"] = {
			name = "石爪小徑",
			short = "石爪小徑是一條連接梣谷與石爪山脈的蜿蜒隧道，通道崎嶇不平，岩石中磨出了一些小小的死路和奇異的凹洞。",
			full = "石爪小徑是一條連接梣谷與石爪山脈的蜿蜒隧道，通道崎嶇不平，岩石中磨出了一些小小的死路和奇異的凹洞。它的一端開口在密斯特拉湖以西，另一端則在狂風峭壁的西北角。那裡什麼都沒有棲息；它只是一條穿越山脈的通道。",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["thistlefur village"] = {
			name = "薊皮村",
			short = "薊皮村位於梣谷中西部，在阿斯特蘭納的北方。這裡是薊皮部族的家園，這些熊怪已經墮落並充滿敵意，攻擊任何靠近的人。",
			full = "薊皮村位於梣谷中西部，在阿斯特蘭納的北方。這裡是薊皮部族的家園，這些熊怪已經墮落並充滿敵意，攻擊任何靠近的人。兩名兇猛的戰士戴爾·血爪和羅吉許·巨顎領導著這個部族，抵禦所有接近村莊的人。",
			source = "https://warcraft.wiki.gg/wiki/Thistlefur_Village",
		},
		["warsong labor camp"] = {
			name = "戰歌勞工營地",
			short = "在梣谷東南部、墜星湖的東邊，戰歌氏族設有一座勞工營地，伐木工和採集工在獸人的看守下工作，為氏族的據點砍伐木材。",
			full = "在梣谷東南部、墜星湖的東邊，戰歌氏族設有一座勞工營地，伐木工和採集工在獸人的看守下工作，為氏族的據點砍伐木材。\n\n這座營地與戰歌氏族的主力相隔甚遠，它的守衛孤立無援，毫無增援的希望。",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Labor_Camp",
		},
		["warsong lumber camp"] = {
			name = "戰歌伐木營地",
			short = "梣谷的森林中迴盪著斧頭的聲響，那是在戰歌伐木營地，戰歌氏族正在那裡砍伐古老的樹木取材。",
			full = "梣谷的森林中迴盪著斧頭的聲響，那是在戰歌伐木營地，戰歌氏族正在那裡砍伐古老的樹木取材。營地以一座戰獸獸欄和卡加希亞要塞為根基，這座要塞是為了保護伐木作業而建的據點。\n\n氏族對木材的貪婪並非沒有遭到回應。伊莉亞娜和她的姐妹們已經進入這裡的森林，用自然魔法對付那些啃噬樹幹的伐木機，而堆積的原木之間的土地，也成了聯盟與部落的戰場。\n\n即便如此，營地仍在發揮它的作用：一列列木材源源不斷地從這裡運往碎木崗哨，那裡的城牆和人民都仰賴戰歌伐木營地送來的物資。",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Lumber_Camp",
		},
		["xavian"] = {
			name = "薩維亞",
			short = "薩維亞坐落在一座夜精靈神殿曾經矗立的地方，如今它的石塊已歸薩特所有。",
			full = "薩維亞坐落在一座夜精靈神殿曾經矗立的地方，如今它的石塊已歸薩特所有。在梣谷的三座薩特據點中，權力正是聚集在這裡：雷茲王子和蓋爾薩瑞斯都在這片廢墟中設立了據點，也正是在這裡，薩特開始使用偷來的戰歌燃油進行他們的儀式。\n\n這個地方的名字來自薩維斯，他在很久以前透過一道汲取辛艾薩莉永恆之井力量的傳送門，協助為燃燒軍團開啟了道路。薩格拉斯對這項工作的緩慢進展感到不滿，於是將薩維斯扭曲成了史上第一個薩特。薩維亞離艾薩拉如此之近，這個名字似乎並非巧合。\n\n樹妖曾經前來對抗薩維亞——其中一位名叫安妮莉亞的樹妖，在搜尋一根被薩特據為己有的塞納留斯之枝後，被人發現身受致命重傷，倒在她未能肅清的廢墟之間。",
			source = "https://warcraft.wiki.gg/wiki/Xavian",
		},
		["zoram strand"] = {
			name = "佐拉姆海岸",
			short = "佐拉姆海岸的浪濤拍打在一座昔日的城市之上。",
			full = "佐拉姆海岸的浪濤拍打在一座昔日的城市之上。在世界於大崩裂中被撕裂之前，佐拉姆是一座矗立於此的夜精靈城鎮，當大海升起索取它在破碎世界中的那一份時，佐拉姆也隨之沉沒。如今水面上除了這個名字之外，什麼也沒有留下。\n\n今天在海岸上行走的不是精靈，而是納迦。牠們將海岸據為己有，而散落在沙灘上的殘骸，破碎的船隻，擱淺的海洋生物屍體，都顯示出這片海岸已經多麼徹底地落入牠們手中。在附近的岩石和被淹沒的窪地之間，坐落著黑澗深淵，它沉入大地，正如佐拉姆當年沉入大海一樣。\n\n部落在這裡的左拉姆加前哨站保有一小塊立足之地，與其說是出於選擇，不如說是被迫至此，他們耗盡力氣與爭奪海岸每一寸土地的怒尾納迦作戰。同樣是這些納迦襲擊了塔爾倫，讓前哨站面臨來自不只一個方向的敵人。這是一段艱苦、潮濕、飽受爭奪的海岸，曾被一個沉沒的帝國所擁有，如今則被誕生於吞沒它的那片大海的生物所佔據。",
			source = "https://warcraft.wiki.gg/wiki/Zoram_Strand",
		},
		["zoramgar outpost"] = {
			name = "左拉姆加前哨站",
			short = "左拉姆加前哨站是部落位於梣谷佐拉姆海岸的一座港口，它的碼頭一直延伸到下方的水域。",
			full = "左拉姆加前哨站是部落位於梣谷佐拉姆海岸的一座港口，它的碼頭一直延伸到下方的水域。",
			source = "https://warcraft.wiki.gg/wiki/Zoram'gar_Outpost",
		},
	},
	-- 千針石林: 20 subzones
	[1441] = {
		["camp ethok"] = {
			name = "伊索克營地",
			short = "伊索克營地是千針石林西北部的一座加拉克半人馬營地。",
			full = "伊索克營地是千針石林西北部的一座加拉克半人馬營地。營地的半人馬曾襲擊一支載有哥布林維茲羅的商隊，卻偷不走他最珍愛的那個小玩意兒，它被安全地掛在他那隻兇猛寵物黑豹的脖子上。",
			source = "https://warcraft.wiki.gg/wiki/Camp_E'thok",
		},
		["darkcloud pinnacle"] = {
			name = "黑雲峰",
			short = "黑雲峰聳立在升降梯以東的三座小平頂山上，山頂之間以懸空的繩橋相連。",
			full = "黑雲峰聳立在升降梯以東的三座小平頂山上，山頂之間以懸空的繩橋相連。只有兩條路能夠上去，每一條都戒備森嚴：一條是橫越第四座平頂山的天然斜坡，另一條則是從剃刀高地延伸過來的橋樑。\n\n恐怖圖騰牛頭人佔據著這些高地，由阿納克·恐怖圖騰和哈布·惡山領導。在戒備森嚴的橋樑後方，這兩名首領與某個身分不明的黑暗勢力秘密通信。他們之間的往來從不公開談論，但他們封鎖這些平頂山的謹慎程度，顯示出這個秘密被守護得多麼嚴密。",
			source = "https://warcraft.wiki.gg/wiki/Darkcloud_Pinnacle",
		},
		["freewind post"] = {
			name = "亂風崗",
			short = "亂風崗高踞在千針石林的一座平頂山上，建在下方遊蕩的半人馬所無法觸及之處。",
			full = "亂風崗高踞在千針石林的一座平頂山上，建在下方遊蕩的半人馬所無法觸及之處。木造的升降梯將居民從峽谷底部載上來，繩橋則在相鄰的石峰之間相連，一座接著一座攀升，直到抵達村莊。在下方，加拉克半人馬的戰隊不斷進逼，鳥身女妖在平原上盤旋尖叫，但真正守護這座哨站的，是它的高度本身。\n\n更深的麻煩來自西北方的黑雲峰，恐怖圖騰部族在那裡佔據著他們自己的高地。早在公開開戰之前，亂風崗就已經對他們心存戒備：牛頭人接連失蹤，有人看見來歷不明的黑暗密使造訪那座山峰，謀殺的罪名也被歸到恐怖圖騰頭上。酋長阿納克·恐怖圖騰承受了最多的指責。當亂風崗的拉克塔·風歌拒絕他的追求時，他派人強行擄走了她，而當她的兄弟前來保護她時，恐怖圖騰殺了他。",
			source = "https://warcraft.wiki.gg/wiki/Freewind_Post",
		},
