		["mirage raceway"] = {
			name = "沙漠賽道",
			short = "一個名叫普茲克的哥布林和一個名叫菲茲爾·銅栓的地精，都認為自己的種族才是更聰明的工程師，誰也不肯讓步。",
			full = "一個名叫普茲克的哥布林和一個名叫菲茲爾·銅栓的地精，都認為自己的種族才是更聰明的工程師，誰也不肯讓步。於是他們用工匠的方式解決了這個問題：他們建了一條賽道，又造了能在上面奔馳的火箭車。\n\n這場較勁吸引的觀眾遠遠不只他們兩人。部落和聯盟的人都會前來為自己支持的一方加油，地精和哥布林的直線加速賽車每天都在比賽，每支隊伍賽後都爭先恐後地重建引擎，想取得新的優勢。真正的較量永遠是同一個問題：哪個種族能造出更好的機器，而這個問題永遠沒有定論。",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Raceway",
