		["nijels point"] = {
			name = "尼耶爾前哨站",
			short = "尼耶爾前哨站在淒涼之地北部山區守望，是由聯盟和塞納里奧議會共同據守的前哨站。",
			full = "尼耶爾前哨站在淒涼之地北部山區守望，是由聯盟和塞納里奧議會共同據守的前哨站。\n\n守護者瑪蘭迪斯與他的樹妖姐妹來到這裡，以這座前哨站為基地追擊瑟萊德絲公主。他們的目的是從瑪拉頓深處取回札爾塔的遺體，帶回石爪山脈的家鄉。\n\n與此同時，暴風城軍隊在潘迪加斯船長的指揮下，將尼耶爾前哨站衛隊駐紮在這裡，以對抗盤據這個地區的半人馬部族的威脅。潘迪加斯以軍人的警覺注視著吉爾吉斯與瑪格拉姆之間的競爭，他確信無論哪個部族勝出，都會膽大到轉而攻擊附近的聯盟據點，因此他試圖了解如何利用一個部族牽制另一個部族來擊敗半人馬。",
			source = "https://warcraft.wiki.gg/wiki/Nijel's_Point",
		},
		["ranazjar isle"] = {
			name = "拉納加爾島",
			short = "拉納加爾島是淒涼之地西北海岸外一座多岩石的小島，是蛇形納迦的家園。",
			full = "拉納加爾島是淒涼之地西北海岸外一座多岩石的小島，是蛇形納迦的家園。在岩石之間佇立著夜精靈的廢墟，與艾瑟雷索同屬一座古老的城市，如今靜靜地俯臨著棲息於此的納迦。",
			source = "https://warcraft.wiki.gg/wiki/Ranazjar_Isle",
		},
		["sargeron"] = {
			name = "薩格隆",
			short = "矗立於此的城市曾經有一個夜精靈的名字，自從先祖之戰撕裂世界以來便已失傳。",
			full = "矗立於此的城市曾經有一個夜精靈的名字，自從先祖之戰撕裂世界以來便已失傳。如今留下的只有廢墟，被棲息於此的怨怒薩特稱為薩格隆，以紀念他們的惡魔主人薩格拉斯。\n\n這片廢墟曾經擁有三處伊露恩的聖地：她的大教堂、她的神殿和她的聖所。那個古老信仰的遺物至今仍散落在石塊之間：伊露恩的火盆、伊露恩的侍女、伊露恩之杯，以及古代漩渦符文石。",
			source = "https://warcraft.wiki.gg/wiki/Sargeron",
		},
		["sartheris strand"] = {
			name = "薩瑟里斯海岸",
			short = "淒涼之地與大海相接的海岸，與它背後的土地截然不同。內陸一片灰暗荒涼，薩瑟里斯海岸卻陽光明媚，綠草如茵。",
			full = "淒涼之地與大海相接的海岸，與它背後的土地截然不同。內陸一片灰暗荒涼，薩瑟里斯海岸卻陽光明媚，綠草如茵。海巨人在淺灘中涉水而行，納迦在水中盤繞，龍蝦人則在沙灘上橫行。\n\n在艾瑟雷索下方，一艘小船撞毀在海灘上，船身的木板碎裂，船上的船員早已不知去向。",
			source = "https://warcraft.wiki.gg/wiki/Sar'theris_Strand",
		},
		["scrabblescrews camp"] = {
			name = "瑟卡布斯庫的營地",
			short = "在淒涼之地的科多獸墳場附近，有一座哥布林的小營地。",
			full = "在淒涼之地的科多獸墳場附近，有一座哥布林的小營地。它屬於斯米德·瑟卡布斯庫，一個富有進取心的哥布林，他經營著一支科多獸商隊，驅趕這些巨獸穿越荒野，賺取這片土地所能提供的一切利潤。",
			source = "https://warcraft.wiki.gg/wiki/Scrabblescrew's_Camp",
		},
		["shadowbreak ravine"] = {
			name = "破影峽谷",
			short = "破影峽谷隱藏在修克索卡東南方的山區中，是淒涼之地一處很少有人會偶然發現的褶皺。",
			full = "破影峽谷隱藏在修克索卡東南方的山區中，是淒涼之地一處很少有人會偶然發現的褶皺。巨大的蘑菇在岩石間高聳，峽谷中央是一座被巨大鎖鏈束縛的召喚法陣，由將這座峽谷當作避風港的燃刃信徒所建。",
			source = "https://warcraft.wiki.gg/wiki/Shadowbreak_Ravine",
		},
		["shadowprey village"] = {
			name = "葬影村",
			short = "葬影村坐落在薩瑟里斯海岸與淒涼之地南部海岸的交會處，是食人妖的一座漁村。",
			full = "葬影村坐落在薩瑟里斯海岸與淒涼之地南部海岸的交會處，是食人妖的一座漁村。村民以海為生，他們的漁獲正是供養更內陸的幽靈崗哨的糧食。",
			source = "https://warcraft.wiki.gg/wiki/Shadowprey_Village",
		},
		["tethris aran"] = {
			name = "塔迪薩蘭",
			short = "夜精靈的廢墟散落在淒涼之地北部、雷斧堡壘的北方，那是一座被認為毀於大崩裂的聚落遺跡。",
			full = "夜精靈的廢墟散落在淒涼之地北部、雷斧堡壘的北方，那是一座被認為毀於大崩裂的聚落遺跡。這裡沒有任何重建。如今只有淒涼之地的野生生物在斷裂的石塊之間行走。",
			source = "https://warcraft.wiki.gg/wiki/Tethris_Aran",
		},
		["thunder axe fortress"] = {
			name = "雷斧堡壘",
			short = "雷斧堡壘位於淒涼之地西北部，已落入燃刃教派之手。",
			full = "雷斧堡壘位於淒涼之地西北部，已落入燃刃教派之手。在它由要塞、兵營、洞穴和瞭望塔構成的城牆之後，寇霍爾率領下的信徒們正致力於召喚全盛力量的惡魔納薩根，他們小心翼翼，唯恐過早召喚他，使他虛弱到足以被消滅。\n\n這座堡壘曾經存放著聖光節杖，這件威力可怕的神器是燃刃教派從納迦手中偷來的。效力於銀色黎明的阿佐爾·奧達蒙特立志要奪回它，並在他人的協助下，成功地從教派手中將它搶了回來。\n\n在這些城牆之內也曾住著提拉尼斯·瑪雷姆，這個名字在他的族人之間被人鄙夷地提起，因為他背叛了他們，投身於惡魔魔法的研究，把雷斧堡壘當成了從事這些黑暗勾當的避風港。",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Axe_Fortress",
		},
		["valley of bones"] = {
			name = "白骨之谷",
			short = "白骨之谷是淒涼之地南緣的一處峭壁，骷髏、半人馬死靈法師以及被殺害的瑪格拉姆部族的鬼魂在此出沒。",
			full = "白骨之谷是淒涼之地南緣的一處峭壁，骷髏、半人馬死靈法師以及被殺害的瑪格拉姆部族的鬼魂在此出沒。在峭壁的岩壁邊躺著一對巨大的骸骨，被稱為死亡巨人，它們的來歷無人知曉。",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Bones",
		},
		["valley of spears"] = {
			name = "長矛谷",
			short = "長矛谷位於淒涼之地西部，是瑪洛迪半人馬部族的家園，徒步只能經由南方和東方狹窄的山口抵達。",
			full = "長矛谷位於淒涼之地西部，是瑪洛迪半人馬部族的家園，徒步只能經由南方和東方狹窄的山口抵達。在山谷的西南端是瑪拉頓的入口。在半人馬之中，被囚禁的是梅麗薩。",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Spears",
		},
