	-- 菲拉斯: 28 subzones
	[1444] = {
		["camp mojache"] = {
			name = "莫沙徹營地",
			short = "莫沙徹營地坐落在一條湍急溪流匯入狂風湖的地方。",
			full = "莫沙徹營地坐落在一條湍急溪流匯入狂風湖的地方。據守這片土地的牛頭人以堅韌的皮膚和勇士的勇氣聞名，他們保護旅人免受菲拉斯種種危險的侵害。",
			source = "https://warcraft.wiki.gg/wiki/Camp_Mojache",
		},
		["dire maul"] = {
			name = "厄運之槌",
			short = "一萬兩千年前，一個秘密的夜精靈術士教派建起了埃德薩拉斯，以守護艾薩拉女王最珍視的奧術秘密。",
			full = "一萬兩千年前，一個秘密的夜精靈術士教派建起了埃德薩拉斯，以守護艾薩拉女王最珍視的奧術秘密。在城中的精靈貴族之間，被稱為辛德拉的奧術師們過著低調而華美的生活，其中一位名叫米莉仙·瑟琳的奧術師創造了豐饒之果，這種藤蔓散發出生長與守護的靈氣，讓整座城市欣欣向榮。\n\n大崩裂之後，精靈貴族與永恆之井斷絕了聯繫，於是他們束縛了一個名叫伊莫塔爾的惡魔，從對他的囚禁中汲取力量。這股力量支撐了他們數千年，直到囚禁他的代價超過了他所能提供的一切。他們的首領托塞德林王子對此的回應，是轉而對付自己的族人，屠殺了其中許多人，以釋放足夠的力量讓其餘的人存活。倖存者退入他們曾經統治的廢墟更深處，將城市的其餘部分拋棄，任由任何前來棲身的東西佔據。\n\n埃德薩拉斯的石塊至今仍然矗立，一種如今已無人記得的技藝將奧術能量封存在其中，維持著一座靠吞噬自己的人民而存活的城市的形貌。",
			source = "https://warcraft.wiki.gg/wiki/Dire_Maul",
		},
		["dream bough"] = {
			name = "夢境之樹",
			short = "一棵巨樹從加德米爾湖中央的一座小島上拔地而起，它的根與枝幹守護著一道通往翡翠夢境的傳送門。",
			full = "一棵巨樹從加德米爾湖中央的一座小島上拔地而起，它的根與枝幹守護著一道通往翡翠夢境的傳送門。綠龍軍團守望著它，守衛著這道門檻，防止任何人干擾下方的夢境。",
			source = "https://warcraft.wiki.gg/wiki/Dream_Bough",
		},
		["feathermoon stronghold"] = {
			name = "羽月要塞",
			short = "在菲拉斯西海岸外的薩爾多島上，矗立著一座由珊蒂斯·羽月將軍在海中建立的要塞，一萬年來，她一直作為泰蘭妲·語風的左右手，在哨兵之中站在她的身旁。",
			full = "在菲拉斯西海岸外的薩爾多島上，矗立著一座由珊蒂斯·羽月將軍在海中建立的要塞，一萬年來，她一直作為泰蘭妲·語風的左右手，在哨兵之中站在她的身旁。她以自己的名字為這座要塞命名，至今它仍為夜精靈守護著卡林多的這段海岸。\n\n只有大海將它與大陸相連，一艘小船從被遺忘的海岸渡海駛往島上的碼頭。",
			source = "https://warcraft.wiki.gg/wiki/Feathermoon_Stronghold_(Classic)",
		},
		["feral scar vale"] = {
			name = "深痕谷",
			short = "在菲拉斯西部的高原荒野中，坐落著深痕谷，由深痕雪人所佔據，山谷也因牠們而得名。",
			full = "在菲拉斯西部的高原荒野中，坐落著深痕谷，由深痕雪人所佔據，山谷也因牠們而得名。",
			source = "https://warcraft.wiki.gg/wiki/Feral_Scar_Vale",
		},
		["forgotten coast"] = {
			name = "被遺忘的海岸",
			short = "被遺忘的海岸綿延於菲拉斯整個西部邊緣，那裡的陸地與迷霧之海相接。水元素從這裡的浪濤中升起，海巨人則在海岸線上徘徊。",
			full = "被遺忘的海岸綿延於菲拉斯整個西部邊緣，那裡的陸地與迷霧之海相接。水元素從這裡的浪濤中升起，海巨人則在海岸線上徘徊。\n\n一座魚人漁村緊附在這片海岸上。曾有鳥類俯衝而下叼走蝌蚪，這座村子也先後遭受人類和豺狼人的襲擊。最糟的是戈杜尼巨魔，多年來牠們一直獵捕這座村莊，將魚人拖進厄運之槌的廢墟中囚禁。已經有十幾隻或更多的魚人以這種方式被抓走，其中有兩隻名叫莫爾和莫格利。",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Coast",
		},
		["frayfeather highlands"] = {
			name = "亂羽高地",
			short = "亂羽高地屬於亂羽角鷹獸，牠們在那裡的高處築巢，這片土地也因牠們而得名。",
			full = "亂羽高地屬於亂羽角鷹獸，牠們在那裡的高處築巢，這片土地也因牠們而得名。在山岩之間，牠們的蛋藏在分散的巢穴中，由以高地為家、在空中盤旋的獸群守護著。",
			source = "https://warcraft.wiki.gg/wiki/Frayfeather_Highlands",
		},
		["gordunni outpost"] = {
			name = "戈杜尼前哨站",
			short = "在拉瑞斯小亭北方的山區，大地帶著戈杜尼的印記。菲拉斯其他地方一片青翠，這座前哨站卻因巨魔的存在而一片枯黃。",
			full = "在拉瑞斯小亭北方的山區，大地帶著戈杜尼的印記。菲拉斯其他地方一片青翠，這座前哨站卻因巨魔的存在而一片枯黃。\n\n山丘上有兩座洞穴，一座小的靠近入口，另一座巨大的土丘位於後方，兩者都被佔據這片荒蕪土地的戈杜尼巨魔所控制。",
			source = "https://warcraft.wiki.gg/wiki/Gordunni_Outpost",
		},
		["grimtotem compound"] = {
			name = "恐怖圖騰營地",
			short = "恐怖圖騰營地位於厄運之槌以東，是恐怖圖騰牛頭人為自己建立的家園。營地的南區有一座大籠子，裡面關著被俘的小精龍。",
			full = "恐怖圖騰營地位於厄運之槌以東，是恐怖圖騰牛頭人為自己建立的家園。營地的南區有一座大籠子，裡面關著被俘的小精龍。在北區的東邊，豺狼人建起了牠們自己的營地。",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Compound",
		},
		["high wilderness"] = {
			name = "高原荒野",
			short = "高原荒野遍佈菲拉斯西部，從被遺忘的海岸一直延伸到沃丹提斯河。",
			full = "高原荒野遍佈菲拉斯西部，從被遺忘的海岸一直延伸到沃丹提斯河。熊、狼和角鷹獸在它古老的樹林間遊蕩，樹人佇立在較深的樹叢之中，而雪人和巨魔則佔據著更遠處更荒野的地帶。",
			source = "https://warcraft.wiki.gg/wiki/High_Wilderness",
		},
		["isle of dread"] = {
			name = "恐怖之島",
			short = "恐怖之島位於菲拉斯海岸外，在薩爾多島以南，它的中央山谷四面都被陡峭的懸崖包圍，只有東南方有一條通路。",
			full = "恐怖之島位於菲拉斯海岸外，在薩爾多島以南，它的中央山谷四面都被陡峭的懸崖包圍，只有東南方有一條通路。在那座隱蔽的盆地中棲息著奇美洛克，既有受奧術浸染的野獸，也有吞噬者，由拉克麥拉領主統治。他的肉曾被人以比求生更奇特的目的所追尋：經過熬煮和重塑，它變成了一隻五百磅重的巨禽，被地精巫師納里安整隻吞下。\n\n在島的北端，有一座深入岩石的洞穴，與島上已知的一切截然不同，它又深又奇特。一條水下的秘密通道通往一間內室，除了在深處庇護夏拉女士之外，至今無人發現它還有什麼用途。這座洞穴和其中的納迦由沙爾札魯領主統率，他的存在引起了羽月要塞的注意，她們對如此靠近自己海岸的納迦心存戒備。",
			source = "https://warcraft.wiki.gg/wiki/Isle_of_Dread",
		},
		["jademir lake"] = {
			name = "加德米爾湖",
			short = "菲拉斯北部的加德米爾湖中央有一座小島，名為夢境之樹。一道通往翡翠夢境的傳送門立於島上，由萊斯拉斯和一群綠色龍人守護。",
			full = "菲拉斯北部的加德米爾湖中央有一座小島，名為夢境之樹。一道通往翡翠夢境的傳送門立於島上，由萊斯拉斯和一群綠色龍人守護。受感染的綠色雛龍則在湖的西北岸徘徊不去。",
			source = "https://warcraft.wiki.gg/wiki/Jademir_Lake",
		},
		["lariss pavilion"] = {
			name = "拉瑞斯小亭",
			short = "拉瑞斯小亭的石造建築出自夜精靈之手，位於菲拉斯莫沙徹營地的北方。這裡的樹妖曾經平和，但翡翠夢魘已經腐化了她們，如今她們會攻擊任何靠近的人。",
			full = "拉瑞斯小亭的石造建築出自夜精靈之手，位於菲拉斯莫沙徹營地的北方。這裡的樹妖曾經平和，但翡翠夢魘已經腐化了她們，如今她們會攻擊任何靠近的人。\n\n小亭下方有一條隱秘的通道通往地底，這條路為埃斯托爾迪所知，他是一名與托塞德林王子決裂、並經由這條通道逃離厄運之槌的精靈貴族。他逃出時幾乎一無所有，因為一個名叫普希林的小鬼在他消失於地底之前偷走了他的咒語書，從那以後他便一直待在那條通道裡。",
			source = "https://warcraft.wiki.gg/wiki/Lariss_Pavilion",
		},
		["lower wilds"] = {
			name = "低地荒野",
			short = "低地荒野佔據了菲拉斯的東部，樹人在林間穿行，墮落的樹妖四處遊走，她們的天賦已經變得詭異。",
			full = "低地荒野佔據了菲拉斯的東部，樹人在林間穿行，墮落的樹妖四處遊走，她們的天賦已經變得詭異。",
			source = "https://warcraft.wiki.gg/wiki/Lower_Wilds",
