		["rage scar hold"] = {
			name = "怒痕堡",
			short = "怒痕堡是菲拉斯一座深挖入地的洞穴，住著這一帶最兇猛的雪人。",
			full = "怒痕堡是菲拉斯一座深挖入地的洞穴，住著這一帶最兇猛的雪人。洞內散落著書籍和奇異的符號，暗示著某種奧術研究，或者也許是某位不幸在此喪命的法師所留下的遺物。",
			source = "https://warcraft.wiki.gg/wiki/Rage_Scar_Hold",
		},
		["ruins of isildien"] = {
			name = "伊斯迪爾廢墟",
			short = "伊斯迪爾廢墟是一座偉大的夜精靈城市的遺跡，毀於一萬年前。戈杜尼巨魔如今在它倒塌的柱廊間築巢，統治著由遠比牠們古老的雙手所建起的石塊。",
			full = "伊斯迪爾廢墟是一座偉大的夜精靈城市的遺跡，毀於一萬年前。戈杜尼巨魔如今在它倒塌的柱廊間築巢，統治著由遠比牠們古老的雙手所建起的石塊。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Isildien",
		},
		["ruins of ravenwind"] = {
			name = "鴉風廢墟",
			short = "菲拉斯北部留有鴉風的斷垣殘壁，它是很久以前由卡多雷的精靈貴族所建，正如厄運之槌建於他處一樣。",
			full = "菲拉斯北部留有鴉風的斷垣殘壁，它是很久以前由卡多雷的精靈貴族所建，正如厄運之槌建於他處一樣。昔日的榮光如今已所剩無幾。北泉鳥身女妖已將廢墟據為己有，在倒塌的石柱和空蕩的殿堂之間築巢。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ravenwind",
		},
		["ruins of solarsal"] = {
			name = "索蘭薩爾廢墟",
			short = "在薩爾多島上羽月要塞的西南方，索蘭薩爾的古老石塊仍佇立在林木之間，這是早已被遺棄於荒野的夜精靈建築。",
			full = "在薩爾多島上羽月要塞的西南方，索蘭薩爾的古老石塊仍佇立在林木之間，這是早已被遺棄於荒野的夜精靈建築。憎世納迦如今佔據著這片廢墟，在精靈們曾經行走的斷柱之間盤繞穿行。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Solarsal",
		},
		["sardor isle"] = {
			name = "薩爾多島",
			short = "薩爾多島從菲拉斯的海岸外升起，是在珊蒂斯·羽月領導下由夜精靈據守的一處小小避難所。",
			full = "薩爾多島從菲拉斯的海岸外升起，是在珊蒂斯·羽月領導下由夜精靈據守的一處小小避難所。納迦已經爬上了它的海岸，狼群也在殘存的荒野之地遊蕩，因此要塞的守衛從未閒下來過。",
			source = "https://warcraft.wiki.gg/wiki/Sardor_Isle",
		},
		["shalzarus lair"] = {
			name = "沙爾札魯的巢穴",
			short = "在羽月要塞所在島嶼的南方、恐怖之島的北端，有一座曲折的洞穴，裡面有兩間由水道相連的洞室。",
			full = "在羽月要塞所在島嶼的南方、恐怖之島的北端，有一座曲折的洞穴，裡面有兩間由水道相連的洞室。憎世納迦的女巫和蛇人守衛遍佈洞穴各處。在洞穴深處住著沙爾札魯，憎世納迦的首領。",
			source = "https://warcraft.wiki.gg/wiki/Shalzaru's_Lair",
		},
		["thalanaar"] = {
			name = "薩蘭納爾",
			short = "薩蘭納爾靜靜地佇立著，是一座小小的前哨站，除了它本身的用途之外，沒有什麼能吸引旅人。",
			full = "薩蘭納爾靜靜地佇立著，是一座小小的前哨站，除了它本身的用途之外，沒有什麼能吸引旅人。凱雷希亞·獵月在這裡從事她的手藝，以古老的部族方式加工獸皮和皮革，這是少數讓人有理由在此逗留的原因之一。",
			source = "https://warcraft.wiki.gg/wiki/Thalanaar",
		},
		["twin colossals"] = {
			name = "雙塔山",
			short = "雙塔山聳立在菲拉斯的西緣，兩座垂直的山峰高聳入雲，是這一地區的最高點，通往淒涼之地的道路就從兩山之間的缺口穿過。",
			full = "雙塔山聳立在菲拉斯的西緣，兩座垂直的山峰高聳入雲，是這一地區的最高點，通往淒涼之地的道路就從兩山之間的缺口穿過。\n\n東峰的頂端有一座又小又深的池塘，池水平靜得足以垂釣，格雷甘·山酒就在那裡。從山頂望下，整個地區盡收眼底。",
			source = "https://warcraft.wiki.gg/wiki/Twin_Colossals",
		},
		["verdantis river"] = {
			name = "沃丹提斯河",
			short = "沃丹提斯河蜿蜒流經菲拉斯中部，在厄運之槌廢墟的東南方，在糾結的森林中劃出一道寧靜的綠色絲線。",
			full = "沃丹提斯河蜿蜒流經菲拉斯中部，在厄運之槌廢墟的東南方，在糾結的森林中劃出一道寧靜的綠色絲線。它的河水中有菲拉斯鮪魚，這種魚在世界其他地方都找不到。",
			source = "https://warcraft.wiki.gg/wiki/Verdantis_River",
		},
		["wildwind lake"] = {
			name = "狂風湖",
			short = "狂風湖位於菲拉斯的莫沙徹營地附近，湖水在四周的荒野之下一片寧靜，除了水面下游動的生物和籠罩著附近營地的靜謐之外，再沒有什麼值得一提的東西。",
			full = "狂風湖位於菲拉斯的莫沙徹營地附近，湖水在四周的荒野之下一片寧靜，除了水面下游動的生物和籠罩著附近營地的靜謐之外，再沒有什麼值得一提的東西。",
			source = "https://warcraft.wiki.gg/wiki/Wildwind_Lake",
		},
		["woodpaw den"] = {
			name = "木爪巢穴",
			short = "在菲拉斯的中心坐落著木爪巢穴，那是木爪豺狼人的巢窟。木爪首領在這裡統治著牠們的同族，牠們數量眾多，很少有外人願意去招惹。",
			full = "在菲拉斯的中心坐落著木爪巢穴，那是木爪豺狼人的巢窟。木爪首領在這裡統治著牠們的同族，牠們數量眾多，很少有外人願意去招惹。在巢穴的南方是暗霧廢墟，靜默地與豺狼人的喧鬧為鄰。",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Den",
		},
		["woodpaw hills"] = {
			name = "木爪嶺",
			short = "木爪嶺林木茂密，是木爪部族豺狼人的家園。",
			full = "木爪嶺林木茂密，是木爪部族豺狼人的家園。牠們對這片土地的掌控正在鬆動，因為在最東南端，大地已經裂開，形成了如今被稱為痛苦深淵的地方，從地底湧出的成群生物一直在把豺狼人趕出牠們自己的領地。木爪首領曾經率領部族從各處營地出擊，如今卻只能據守木爪巢穴。",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Hills",
		},
		["writhing deep"] = {
			name = "痛苦深淵",
			short = "位於菲拉斯東南部的痛苦深淵，已被祖卡什蟲巢所佔據。那裡的異種蠍毒害了周圍的土地，使附近的豺狼人陷入瘋狂，向北攻擊莫沙徹營地。",
			full = "位於菲拉斯東南部的痛苦深淵，已被祖卡什蟲巢所佔據。那裡的異種蠍毒害了周圍的土地，使附近的豺狼人陷入瘋狂，向北攻擊莫沙徹營地。\n\n營地的戰士們在地面上斬殺了異種蠍，但蟲巢位於地底、塞滿蟲卵的核心卻從未被觸及。雷克薩警告說，下一代孵化出來只是時間問題。",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Deep",
		},
	},
	-- 塵泥沼澤: 24 subzones
	[1445] = {
		["alcaz island"] = {
			name = "奧卡茲島",
			short = "奧卡茲島從塵泥沼澤外的海中升起，島上長滿了熱帶的蒼翠植物，它們本不該生長在離沼澤灰色泥濘如此近的地方，彷彿某種更古老、更溫暖的力量曾經佔據這片土地，從未放手。",
			full = "奧卡茲島從塵泥沼澤外的海中升起，島上長滿了熱帶的蒼翠植物，它們本不該生長在離沼澤灰色泥濘如此近的地方，彷彿某種更古老、更溫暖的力量曾經佔據這片土地，從未放手。斯塔莎茲納迦佔據著這座島，沿岸遍佈納迦戰士和海妖。\n\n然而在對抗安其拉的戰爭期間，維維爾博士乘坐飛行器來到島上，帶著他的爪牙在山頂落腳，將一段海岸變成了發明科技的工坊。",
			source = "https://warcraft.wiki.gg/wiki/Alcaz_Island",
		},
		["beezils wreck"] = {
			name = "比吉爾的飛艇殘骸",
			short = "一艘載著補給品向南航行的哥布林飛艇，墜毀在塵泥沼澤的最深處，塔貝薩的農場以東。",
			full = "一艘載著補給品向南航行的哥布林飛艇，墜毀在塵泥沼澤的最深處，塔貝薩的農場以東。它的船身破碎地躺在泥濘中，貨物散落在殘骸之間，爆鹽增壓器仍躺在它們掉落的地方。",
			source = "https://warcraft.wiki.gg/wiki/Beezil's_Wreck",
		},
		["bloodfen burrow"] = {
			name = "鮮血沼澤墓穴",
			short = "塵泥沼澤西南部的一座洞穴裡，棲息著數量異常眾多的鮮血沼澤迅猛龍。入口外躺著某個聚落的殘跡，被這些生物撕成碎片，居民如今已消失在沼澤的泥濘中。",
			full = "塵泥沼澤西南部的一座洞穴裡，棲息著數量異常眾多的鮮血沼澤迅猛龍。入口外躺著某個聚落的殘跡，被這些生物撕成碎片，居民如今已消失在沼澤的泥濘中。在洞穴內的某處，科泰羅的謎題的一部分正在殘骸之間等待著。",
			source = "https://warcraft.wiki.gg/wiki/Bloodfen_Burrow",
		},
		["bluefen"] = {
			name = "藍色沼澤",
			short = "藍色沼澤位於塵泥沼澤北部，低窪的地面上長滿了蘆葦，積滿了死水。",
			full = "藍色沼澤位於塵泥沼澤北部，低窪的地面上長滿了蘆葦，積滿了死水。蜘蛛、鱷魚、迅猛龍和沼澤鳥類在沼澤中不受阻攔地穿行，塞拉摩的滲透者則隱身在蘆葦之間悄然經過。",
			source = "https://warcraft.wiki.gg/wiki/Bluefen",
		},
		["brackenwall village"] = {
			name = "蕨牆村",
			short = "蕨牆村坐落在塵泥沼澤西北部的小屋與巨魔土丘之間，是石槌巨魔的家園，並已宣誓效忠部落。",
			full = "蕨牆村坐落在塵泥沼澤西北部的小屋與巨魔土丘之間，是石槌巨魔的家園，並已宣誓效忠部落。這裡並非一直是他們的家。石槌巨魔曾經在南方擁有一座村莊，直到黑龍軍團襲擊了那裡，將它燒成廢墟。在雷克薩之後接掌領導權的莫克莫洛克霸王率領倖存者北上，建起了蕨牆村取而代之。\n\n莫克莫洛克的統治建立在按兵不動之上。當巨魔德拉茲伊爾布得知襲擊者是奧妮克希亞的子嗣，並將真相告訴他時，莫克莫洛克卻不願採取行動。蕨牆村很安全，這裡沒有黑龍棲息，對他來說這樣就夠了。德拉茲伊爾布不肯就此罷休，他暗中盤算著，要付出什麼代價才能看到霸王垮台，讓石槌巨魔被帶領著奪回他們失去的一切。",
			source = "https://warcraft.wiki.gg/wiki/Brackenwall_Village",
		},
		["darkmist cavern"] = {
			name = "暗霧洞穴",
			short = "在塵泥沼澤的西北部有一座小礦坑，早已被在黑暗中長得大得嚇人的蜘蛛所佔據。",
			full = "在塵泥沼澤的西北部有一座小礦坑，早已被在黑暗中長得大得嚇人的蜘蛛所佔據。沼澤的居民稱牠們為暗霧蜘蛛，並因此稱這座洞穴為暗霧，不過沒有人說得清哪個名字先出現，是這個地方，還是佔據它的生物。\n\n在礦坑口外佇立著小屋的廢墟，半沉在潮濕的地面中，那是某個早已被遺忘的聚落僅存的遺跡。",
			source = "https://warcraft.wiki.gg/wiki/Darkmist_Cavern",
		},
		["den of flame"] = {
			name = "火焰洞穴",
			short = "火焰洞穴是石槌巨魔所建的土丘，它的石造結構至今仍帶有他們的手藝。它位於石槌廢墟以西，在奧妮克希亞所佔據的沼澤地中。",
			full = "火焰洞穴是石槌巨魔所建的土丘，它的石造結構至今仍帶有他們的手藝。它位於石槌廢墟以西，在奧妮克希亞所佔據的沼澤地中。\n\n如今巨魔已經離開了這裡。黑龍族佔據了這座洞穴，把它當作黑龍軍團的巢穴。只有古老的石造結構，以及留在洞中仍然豎立的石槌旗幟，還能讓人想起它最初的建造者。",
			source = "https://warcraft.wiki.gg/wiki/Den_of_Flame",
		},
		["dragonmurk"] = {
			name = "黑龍谷",
			short = "在塵泥沼澤的南部有一片惡臭的土地，名為黑龍谷，到處都是黑龍軍團的雛龍和龍人。",
			full = "在塵泥沼澤的南部有一片惡臭的土地，名為黑龍谷，到處都是黑龍軍團的雛龍和龍人。附近是火焰洞穴和石槌廢墟，兩者同樣被黑色龍人佔據。",
			source = "https://warcraft.wiki.gg/wiki/Dragonmurk",
		},
		["dreadmurk shore"] = {
			name = "恐懼海岸",
			short = "塞拉摩島與北方城堡之間的海岸上擠滿了沼鰭魚人部族，牠們將這段海岸線及其散落的小島據為己有。",
			full = "塞拉摩島與北方城堡之間的海岸上擠滿了沼鰭魚人部族，牠們將這段海岸線及其散落的小島據為己有。海龜和其他生物與牠們共享周圍的水域。",
			source = "https://warcraft.wiki.gg/wiki/Dreadmurk_Shore",
