		["foothold citadel"] = {
			name = "塞拉摩堡壘",
			short = "塞拉摩堡壘矗立在塞拉摩島的中心，是塞拉摩衛隊的總部。",
			full = "塞拉摩堡壘矗立在塞拉摩島的中心，是塞拉摩衛隊的總部。\n\n當索爾的部隊攻打塞拉摩時，在雷克薩和他的同伴帶領下攻進了要塞，戴林·普勞德摩爾就是在這裡喪命的。這位違抗女兒珍娜與獸人和平協議的海軍上將，就倒在這些城牆之內。",
