		["lost point"] = {
			name = "廢棄哨塔",
			short = "廢棄哨塔是塞拉摩曾在塵泥沼澤西部建起的一座破舊偵察塔，如今已不再為它的建造者效力。",
			full = "廢棄哨塔是塞拉摩曾在塵泥沼澤西部建起的一座破舊偵察塔，如今已不再為它的建造者效力。塞拉摩的逃兵如今佔據著這裡，由巴魯斯·加科因領導，他知道亨德爾下士參與綁架了一位極其重要的人物。",
			source = "https://warcraft.wiki.gg/wiki/Lost_Point",
