		["north point tower"] = {
			name = "北點哨塔",
			short = "北點哨塔在一條往來頻繁的道路旁守望著塵泥沼澤北部，由一支人數可觀的塞拉摩衛兵駐守。",
			full = "北點哨塔在一條往來頻繁的道路旁守望著塵泥沼澤北部，由一支人數可觀的塞拉摩衛兵駐守。自從逃兵佔領了廢棄哨塔之後，這座塔就成了塞拉摩最遠的前哨。",
			source = "https://warcraft.wiki.gg/wiki/North_Point_Tower",
		},
		["onyxias lair"] = {
			name = "奧妮克希亞的巢穴",
			short = "通往奧妮克希亞巢穴的通道，形狀就像這位龍后自己張開的巨顎。穿過它之後，道路兩旁佈滿岩漿，地面龜裂，底下透出火光。",
			full = "通往奧妮克希亞巢穴的通道，形狀就像這位龍后自己張開的巨顎。穿過它之後，道路兩旁佈滿岩漿，地面龜裂，底下透出火光。上方的石頂嘎吱作響、不斷移動，落石接連不斷，在熱氣無法抑制的地方，牆壁本身也滲出熔岩。這個地方是奧妮克希亞親自開鑿的，就在塵泥沼澤中那片陰鬱的沼地——黑龍谷的深處。\n\n她與她的同族不同。她的父親靠蠻力統治，她的兄弟打造扭曲的怪物供他差遣，奧妮克希亞則透過耳語與魅惑行事，她樂於操弄凡人錯綜複雜的政治，悄悄地讓它們為自己的目的服務。有一段時間，她頂著一個偷來的名字，自稱卡特拉娜·普瑞斯托，並以這個身分潛入暴風城宮廷的核心，企圖從內部將它瓦解。是溫德索爾元帥識破了她的偽裝，揭露了她的真面目。身分暴露之後，她逃離了這座城市，回到沼澤下她那炙熱的殿堂，至今仍待在那裡，依然由她自己的同族——黑龍軍團——守護著。",
			source = "https://warcraft.wiki.gg/wiki/Onyxia's_Lair",
		},
		["quagmire"] = {
			name = "泥潭沼澤",
			short = "泥潭沼澤是塵泥沼澤濕透的中心地帶，綿延於廢棄哨塔與塵泥海灣之間，北邊是蕨牆村，南邊是黑龍谷。",
			full = "泥潭沼澤是塵泥沼澤濕透的中心地帶，綿延於廢棄哨塔與塵泥海灣之間，北邊是蕨牆村，南邊是黑龍谷。\n\n鱷魚潛伏在它漆黑的水中，軟泥怪和蜘蛛在蘆葦間爬行，恐怖圖騰牛頭人也在這裡佔據一方，遠離任何會認他們為同族的人。這裡最好快速通過，不宜久留。",
			source = "https://warcraft.wiki.gg/wiki/Quagmire",
		},
		["sentry point"] = {
			name = "警戒崗哨",
			short = "警戒崗哨就在塞拉摩的橋對面，是這座要塞為了監視下方道路而建的偵察塔。它完好無損地矗立著，默默守望著所有前往這座城市的人。",
			full = "警戒崗哨就在塞拉摩的橋對面，是這座要塞為了監視下方道路而建的偵察塔。它完好無損地矗立著，默默守望著所有前往這座城市的人。",
			source = "https://warcraft.wiki.gg/wiki/Sentry_Point",
		},
		["shady rest inn"] = {
			name = "樹蔭旅店",
			short = "樹蔭旅店曾經坐落在塵泥沼澤與南貧瘠之地的交界附近，是一座人類建造的驛站。",
			full = "樹蔭旅店曾經坐落在塵泥沼澤與南貧瘠之地的交界附近，是一座人類建造的驛站。\n\n它在毫無預警的情況下被燒成了平地。有兩個人或許能說出兇手是誰，帕瓦爾·雷瑟和卡德維爾上尉，但兩人都在說出真相之前被殺了，這場大火至今仍是懸案。",
			source = "https://warcraft.wiki.gg/wiki/Shady_Rest_Inn",
		},
		["stonemaul ruins"] = {
			name = "石槌廢墟",
			short = "石槌村曾經坐落在塵泥沼澤，是石槌氏族巨魔的家園，直到軍閥寇加爾奪得古老的獸人戰斧瑟拉希爾，接管了這個氏族，並以殘暴的手段統治它。",
			full = "石槌村曾經坐落在塵泥沼澤，是石槌氏族巨魔的家園，直到軍閥寇加爾奪得古老的獸人戰斧瑟拉希爾，接管了這個氏族，並以殘暴的手段統治它。雷克薩就是在這裡被拒於門外，一路殺了進去。寇加爾提出，只要他能在試煉谷中存活下來，就讓他在氏族中佔有一席之地，那是一座充滿致命野獸的山谷。雷克薩熬了過來並回到村中，成為了石槌氏族的一員。當寇加爾拒絕讓氏族參與部落對抗庫爾提拉斯的戰爭時，雷克薩向他挑戰爭奪領導權並殺死了他，然後親自率領石槌氏族投入戰爭。之後，他任命莫克莫洛克代替他統治，然後便離開了。\n\n莫克莫洛克的統治方式與雷克薩截然不同。他向自己的人民索取，而不是為他們服務，當奧妮克希亞的子嗣降臨村莊並將它佔據時，他帶領倖存者逃到安全的地方，並滿足於待在那裡，遠離巨龍，而不願為奪回故鄉而戰。\n\n這片廢墟如今位於黑龍谷之中，到處都是火鬃龍人。",
			source = "https://warcraft.wiki.gg/wiki/Stonemaul_Ruins",
