		},
		["caverns of time"] = {
			name = "時光洞穴",
			short = "時光洞穴位於塔納利斯東部的沙地之下，是一座與地上世界隔絕的曲折迷宮。青銅龍軍團在此守望著時間本身的分岔路徑。",
			full = "時光洞穴位於塔納利斯東部的沙地之下，是一座與地上世界隔絕的曲折迷宮。青銅龍軍團在此守望著時間本身的分岔路徑。自世界初生以來，這便是泰坦賦予他們的神聖職責：守護洞穴，不讓凡人闖入，因為低等種族的插手足以攪亂歷史的洪流。洞穴的中心矗立著一座巨大的沙漏。\n\n時光守護者諾茲多姆與他的龍族一同居住於此，閒暇時熱衷於收藏稀世的古物。第二次大戰結束後，法師克拉蘇斯藉由一件名為永世玫瑰的器物進入了諾茲多姆的巢穴，這件器物能讓他在轉瞬之間跨越遙遠的距離。諾茲多姆對這次闖入十分不悅，因為它打擾了他收藏古物的雅興，而他也毫不掩飾地表達了自己的不滿。",
			source = "https://warcraft.wiki.gg/wiki/Caverns_of_Time",
		},
		["dunemaul compound"] = {
			name = "砂槌營地",
			short = "砂槌營地是砂槌巨魔的聚居地，散布在塔納利斯的沙地上，整個氏族在烈日下聚居於一座座土造的棲身之所中。",
			full = "砂槌營地是砂槌巨魔的聚居地，散布在塔納利斯的沙地上，整個氏族在烈日下聚居於一座座土造的棲身之所中。",
			source = "https://warcraft.wiki.gg/wiki/Dunemaul_Compound",
		},
		["eastmoon ruins"] = {
			name = "東月廢墟",
			short = "石砌的階台與龜裂的石柱標示著東月廢墟的所在，它位於塔納利斯的大裂口以西，是一座早已荒廢的食人妖聚落僅存的遺跡。",
			full = "石砌的階台與龜裂的石柱標示著東月廢墟的所在，它位於塔納利斯的大裂口以西，是一座早已荒廢的食人妖聚落僅存的遺跡。食人妖離去後，砂槌巨魔佔據了這些崩塌的石造建築，至今仍盤據於此。",
			source = "https://warcraft.wiki.gg/wiki/Eastmoon_Ruins",
		},
		["gadgetzan"] = {
			name = "加基森",
			short = "加基森聳立於塔納利斯北部的沙漠之中，終年籠罩在黑色的煙霧之下，它是哥布林企業之首——熱砂企業的首府。",
			full = "加基森聳立於塔納利斯北部的沙漠之中，終年籠罩在黑色的煙霧之下，它是哥布林企業之首——熱砂企業的首府。在這裡，哥布林的信條主宰一切：利益高於忠誠。部落與聯盟都正式承認這座城市為中立之地，哥布林打手在街頭巡邏，隨時準備把膽敢將戰火帶進這座貿易之城的蠢貨揍成肉泥。在這裡，決定誰受歡迎的不是旗幟，而是錢包。\n\n這份中立從來就不是人人都能接受的。廢土強盜奪取了東北方的熱影廢墟與清泉平原。哥布林對那些古老廢墟毫不在乎，但清泉平原可就另當別論了：加基森水業公司頂著沙漠的烈日在那裡建造並維護的水塔，是維繫這座城市命脈的液態黃金。哥布林可不打算交出他們揮汗建起的水塔，於是來自世界各個角落的傭兵被捲入其中，為加基森保衛水源，對抗那些想讓它陷落的強盜。",
			source = "https://warcraft.wiki.gg/wiki/Gadgetzan",
		},
		["gaping chasm"] = {
			name = "大裂口",
			short = "大裂口裡擠滿了哈薩利異種蠍，牠們的蟲巢群在塔納利斯東南部的岩層中四處鑽鑿。",
			full = "大裂口裡擠滿了哈薩利異種蠍，牠們的蟲巢群在塔納利斯東南部的岩層中四處鑽鑿。\n\n高級勘探員菲茲杜瑟曾派他的下屬謝申克深入裂口進行勘測。謝申克再也沒有回來。他死在了蟲巢之間，後來只有他的裝備被找回，送到了菲茲杜瑟手上——而菲茲杜瑟始終不知道，是他親手把謝申克送上了死路。",
			source = "https://warcraft.wiki.gg/wiki/Gaping_Chasm",
		},
		["lands end beach"] = {
			name = "天涯海灘",
			short = "天涯海灘位於塔納利斯的最南端，是卡林多東南角與大海交會之處。海岸一片寧靜，最引人注目的只有在此漫遊的生物。",
			full = "天涯海灘位於塔納利斯的最南端，是卡林多東南角與大海交會之處。海岸一片寧靜，最引人注目的只有在此漫遊的生物。浪滑海龜與沙岸螃蟹沿著東側的沙灘緩緩前行，無人打擾。",
			source = "https://warcraft.wiki.gg/wiki/Land's_End_Beach",
		},
		["lost rigger cove"] = {
			name = "落帆海灣",
			short = "落帆海灣三面被群山環抱，在塔納利斯海岸上藏著南海海盜的港口，船塢裡正忙著建造一艘新船。",
			full = "落帆海灣三面被群山環抱，在塔納利斯海岸上藏著南海海盜的港口，船塢裡正忙著建造一艘新船。",
			source = "https://warcraft.wiki.gg/wiki/Lost_Rigger_Cove",
