		["noonshade ruins"] = {
			name = "熱影廢墟",
			short = "熱影廢墟位於加基森以東，是早已消失的食人妖所遺留下的風化石塊。這些廢墟當年有何用途，建造它們的人後來又去了哪裡，沙漠的黃沙已不再訴說。",
			full = "熱影廢墟位於加基森以東，是早已消失的食人妖所遺留下的風化石塊。這些廢墟當年有何用途，建造它們的人後來又去了哪裡，沙漠的黃沙已不再訴說。",
			source = "https://warcraft.wiki.gg/wiki/Noonshade_Ruins",
		},
		["noxious lair"] = {
			name = "腐化之巢",
			short = "塔納利斯西南部的沙地上留著一道傷痕，那裡曾經有水。在異種蠍到來之前，這片土地上曾有一片寬廣而淺的水域，或許是河，或許是湖，而森提帕爾蟲群在那裡找到的一切，都被牠們吸乾了。",
			full = "塔納利斯西南部的沙地上留著一道傷痕，那裡曾經有水。在異種蠍到來之前，這片土地上曾有一片寬廣而淺的水域，或許是河，或許是湖，而森提帕爾蟲群在那裡找到的一切，都被牠們吸乾了。塔納利斯西部也因此乾涸。\n\n地表仍保留著失去之物的輪廓。大地向下凹陷，塌落而空洞，俯瞰著安戈洛環形山，彷彿仍記得自己曾是一道湖岸。巨大的蟲爪零星地從沙中直直豎起，不時抽搐，彷彿被掩埋的生物在出擊的瞬間凝固了。每一支蟲爪周圍的土壤都又黑又濕，沾滿了異種蠍的黏液，那是這個曾經擁有湖泊的地方僅存的水氣。\n\n在地表之下，腐化之巢就和森提帕爾在塔納利斯鑿出的其他蟲巢一樣：潮濕、悶熱，靜得令人毛骨悚然，隧道壁上覆滿了異種蠍的酸液。",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Lair",
		},
		["sandsorrow watch"] = {
			name = "流沙崗哨",
			short = "流沙崗哨在加基森以西，橫跨塔納利斯乾涸的盆地，由法拉基食人妖以及他們從自己族人屍體中喚起的殭屍所佔據。",
			full = "流沙崗哨在加基森以西，橫跨塔納利斯乾涸的盆地，由法拉基食人妖以及他們從自己族人屍體中喚起的殭屍所佔據。",
			source = "https://warcraft.wiki.gg/wiki/Sandsorrow_Watch",
		},
		["south seas"] = {
			name = "南海",
			short = "已知大陸以南的海域向外展開，成為無盡之海中廣闊的一片，洋流從一座座島嶼旁流過，而這些島嶼的名字大多只有水手才知道。",
			full = "已知大陸以南的海域向外展開，成為無盡之海中廣闊的一片，洋流從一座座島嶼旁流過，而這些島嶼的名字大多只有水手才知道。贊達拉便從這片海域中升起，那是食人妖帝國古老的故鄉。凱贊也位於其中，那是一座火山島，島上的居民與大陸上的各方勢力保持著距離。\n\n越靠近荊棘谷，海面就因暗礁與隱蔽的海灣而越發險惡，在這樣的水域中，船長若不是對每一塊礁石都瞭若指掌，就會賠上整艘船。這片海域點綴著許多小島，有些不過是一道沙洲，有些則留有廢墟，而建造它們的人早已消失在浪濤之下。\n\n這片海之所以值得一提，與其說是因為曾在此發生過哪一場戰役，不如說是因為它吞沒了許多事物，又將它們半掩半露地重現：沉沒的神廟、淹沒的海岸，以及退潮時透過清澈海水隱約可見的廢墟。這是一片屬於邊界與夾縫之地的海，沿著荊棘谷、塔納利斯與奧丹姆的邊境流淌，把潮水願意帶來的一切，送往它所分隔的海岸。",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southbreak shore"] = {
			name = "塔納利斯南海",
			short = "塔納利斯南海靜靜地沿著塔納利斯的南緣延伸，是一片平坦的海灘，幾乎不見生機。海龜與海巨人在浪花間漫遊。",
			full = "塔納利斯南海靜靜地沿著塔納利斯的南緣延伸，是一片平坦的海灘，幾乎不見生機。海龜與海巨人在浪花間漫遊。",
			source = "https://warcraft.wiki.gg/wiki/Southbreak_Shore",
		},
		["southmoon ruins"] = {
			name = "南月廢墟",
			short = "南月廢墟是塔納利斯南部一座古老食人妖聚落的遺跡，石塊飽經風化，半掩在沙漠的黃沙之中。",
			full = "南月廢墟是塔納利斯南部一座古老食人妖聚落的遺跡，石塊飽經風化，半掩在沙漠的黃沙之中。",
			source = "https://warcraft.wiki.gg/wiki/Southmoon_Ruins",
		},
		["steamwheedle port"] = {
			name = "熱砂港",
			short = "熱砂港坐落於塔納利斯的東岸，一條道路向西通往它的母城加基森，一座碼頭則伸向凱贊。",
			full = "熱砂港坐落於塔納利斯的東岸，一條道路向西通往它的母城加基森，一座碼頭則伸向凱贊。它隸屬於熱砂企業，這些哥布林只要金子夠好，來者不拒。\n\n港口的居民中有一位葉基亞，正是他的所作所為，促成了靈魂掠奪者哈卡的回歸。",
			source = "https://warcraft.wiki.gg/wiki/Steamwheedle_Port",
		},
		["thistleshrub valley"] = {
			name = "灌木谷",
			short = "灌木谷裡長滿了巨大的仙人掌，在如此貧瘠的沙漠中竟能孕育出生機，實在令人稱奇。",
			full = "灌木谷裡長滿了巨大的仙人掌，在如此貧瘠的沙漠中竟能孕育出生機，實在令人稱奇。昔日在此叢生的荊棘灌木近來已日漸稀疏，如今在它們之間可以找到沙漠花朵，只是數量稀少。",
			source = "https://warcraft.wiki.gg/wiki/Thistleshrub_Valley",
		},
		["uldum"] = {
			name = "奧丹姆",
			short = "奧丹姆位於卡林多的南岸，北有安戈洛環形山，東有塔納利斯，西北有希利蘇斯，將它團團圍住。",
			full = "奧丹姆位於卡林多的南岸，北有安戈洛環形山，東有塔納利斯，西北有希利蘇斯，將它團團圍住。這是一片蘊藏著豐富泰坦傳說的土地，山間的通道被層層遮蔽，凡人的眼睛無從找到入口。",
			source = "https://warcraft.wiki.gg/wiki/Uldum",
		},
		["valley of the watchers"] = {
			name = "守衛之谷",
			short = "守衛之谷守護著塔納利斯南部，一座堅不可摧的巨門在此矗立，擋住了通往奧丹姆的去路。山嶺巨人沙丘粉碎者作為它的守望者在此遊蕩。",
			full = "守衛之谷守護著塔納利斯南部，一座堅不可摧的巨門在此矗立，擋住了通往奧丹姆的去路。山嶺巨人沙丘粉碎者作為它的守望者在此遊蕩。",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_the_Watchers",
		},
		["waterspring field"] = {
			name = "清泉平原",
			short = "清泉平原因平原上聳立的水塔而得名，這些水塔從地底深處的蓄水層汲取水源。",
			full = "清泉平原因平原上聳立的水塔而得名，這些水塔從地底深處的蓄水層汲取水源。它們是加基森的哥布林所建造的，目的是為他們在塔納利斯沙漠中的營運確保水源。\n\n這項計畫沒能敵過廢土遊牧民。這群遊牧的強盜闖進平原，乾脆將它據為己有，奪下水塔，全然不顧建造它們的哥布林。他們至今仍盤據在此，無論先前逃離的是什麼，他們都很慶幸能得到這片土地——他們不願談起在此之前的那座巨魔營地，只說這裡比那裡好。",
			source = "https://warcraft.wiki.gg/wiki/Waterspring_Field",
		},
		["wavestrider beach"] = {
			name = "破浪海灘",
			short = "破浪海灘沿著塔納利斯的東岸延伸，是熱砂港與落帆海灣之間的一段沙灘。",
			full = "破浪海灘沿著塔納利斯的東岸延伸，是熱砂港與落帆海灣之間的一段沙灘。沙漠爬行者在此橫行於海灘上，與牠們共享這片海岸的還有鋼顎鉗嘴龜。",
			source = "https://warcraft.wiki.gg/wiki/Wavestrider_Beach",
		},
		["zalashjis den"] = {
			name = "薩拉辛之穴",
			short = "薩拉辛之穴至今仍沿用著曾在此穴居者的名字。流傳下來的故事中，沒有一個提到薩拉辛究竟是誰，也沒有提到這個地方後來怎麼了。",
			full = "薩拉辛之穴至今仍沿用著曾在此穴居者的名字。流傳下來的故事中，沒有一個提到薩拉辛究竟是誰，也沒有提到這個地方後來怎麼了。薩拉辛是否仍然活著，抑或死在這裡，還是死在別處，沒有人能說得準。",
			source = "https://warcraft.wiki.gg/wiki/Zalashji's_Den",
		},
		["zulfarrak"] = {
			name = "祖爾法拉克",
			short = "在塔納利斯仍是古拉巴什帝國治下的森林時，祖爾法拉克曾是一座叢林之城。",
			full = "在塔納利斯仍是古拉巴什帝國治下的森林時，祖爾法拉克曾是一座叢林之城。當大崩裂撕裂了古老的世界，叢林被焚燒殆盡，化為沙漠，在此建城的法拉基食人妖發現自己被困在了黃沙之中。他們堅持了下來，並在磨練中成為了沙怒部族，即使在食人妖之中，這個部族也以殘酷無情和黑暗的神秘法術而聞名。\n\n在這座飽受烈日炙烤的城牆之內，食人妖的傳說提到了一把名為鞭笞者蘇薩斯的劍，據說它能讓所觸及的任何敵人心生恐懼、變得虛弱。很久以前，這把劍被折成了兩半，傳聞兩半至今仍在城中某處，遺落在城內的庭院與神廟之間。\n\n祖爾法拉克的中心有一座聖池，據說沙怒部族在它平靜的池水之下，讓某個遠比他們古老的存在沉睡著——那是一位半神，一旦甦醒，便會為這座城市和城中的一切帶來毀滅。",
			source = "https://warcraft.wiki.gg/wiki/Zul'Farrak",
		},
	},
