		},
		["hetaeras clutch"] = {
			name = "赫塔拉的巢穴",
			short = "赫塔拉的巢穴位於艾薩拉外海的風暴海灣之下，原是一座神殿，如今已成了九頭蛇的巢穴。",
			full = "赫塔拉的巢穴位於艾薩拉外海的風暴海灣之下，原是一座神殿，如今已成了九頭蛇的巢穴。",
			source = "https://warcraft.wiki.gg/wiki/Hetaera's_Clutch",
		},
		["jagged reef"] = {
			name = "鋸齒暗礁",
			short = "鋸齒暗礁是艾薩拉的北方海岸，沙灘一再被突出的岩石和小小的海灣切斷。礁石與淺灘隱藏在水面之下，使得這段海岸危機四伏。",
			full = "鋸齒暗礁是艾薩拉的北方海岸，沙灘一再被突出的岩石和小小的海灣切斷。礁石與淺灘隱藏在水面之下，使得這段海岸危機四伏。魚人、九頭蛇與龍蝦人佔據著這片海岸，或在淺水中游弋，或在沙灘上緩緩覓食。",
			source = "https://warcraft.wiki.gg/wiki/Jagged_Reef",
		},
		["lake mennar"] = {
			name = "門納爾湖",
			short = "門納爾湖的湖心一片平靜，但湖岸四周的土地都屬於龍人。",
			full = "門納爾湖的湖心一片平靜，但湖岸四周的土地都屬於龍人。任何越過這道防線的人都會發現，湖泊本身並無危險，在戒備森嚴的湖岸之間，是一處寧靜而令人神清氣爽的所在。\n\n這是除了北裂境之外，世上少數幾個藍龍軍團曾現身的地方之一，唯一能與之相比的只有冬泉谷的麥索瑞爾。在這片湖水附近，常能見到年幼的蒼藍雛龍。",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mennar",
		},
		["legash encampment"] = {
			name = "雷加什營地",
			short = "雷加什薩特的營地位於艾薩拉北部，烏索蘭以東。",
			full = "雷加什薩特的營地位於艾薩拉北部，烏索蘭以東。\n\n大法師克希雷姆曾在此找到一本魔典，這項發現讓這座原本毫不起眼、滿是受邪能侵染之生物的營地引起了注意。",
			source = "https://warcraft.wiki.gg/wiki/Legash_Encampment",
		},
		["ravencrest monument"] = {
			name = "黑羽紀念碑",
			short = "艾薩拉南端的懸崖上留有一座巨像的殘骸，只是如今剩下的部分已難以配得上這個稱號。",
			full = "艾薩拉南端的懸崖上留有一座巨像的殘骸，只是如今剩下的部分已難以配得上這個稱號。只剩斷裂的雙腿仍矗立在海面之上，巨像的其餘部分則散落在周圍的岩石上，或已滑落到下方的浪濤之中。\n\n如今惡鞭納迦佔據著這片廢墟。這裡無法從海上抵達；想要前往的人必須從陸路而來，穿過通往埃達拉斯廢墟之外的橋，才能站在那雙傾倒的巨腿之下——毫無疑問，它曾經是一座令人嘆為觀止的巨像。",
			source = "https://warcraft.wiki.gg/wiki/Ravencrest_Monument",
		},
		["rethress sanctum"] = {
			name = "雷瑟斯聖所",
			short = "雷瑟斯聖所殘破地立於廢墟海岸之中，位於黑羽紀念碑的西南方。如今已無人看守。只有魚人與龍蝦人在傾頹的石塊間遊蕩，除此之外，再無人會來到這裡。",
			full = "雷瑟斯聖所殘破地立於廢墟海岸之中，位於黑羽紀念碑的西南方。如今已無人看守。只有魚人與龍蝦人在傾頹的石塊間遊蕩，除此之外，再無人會來到這裡。",
			source = "https://warcraft.wiki.gg/wiki/Rethress_Sanctum",
		},
		["ruined reaches"] = {
			name = "廢墟海岸",
			short = "艾薩拉的南方海岸毫不掩飾它的殘破。懸崖與沙灘碎裂成一道道海灣，水下暗藏的淺灘所困住的船隻，多到任何水手都不願去數。",
			full = "艾薩拉的南方海岸毫不掩飾它的殘破。懸崖與沙灘碎裂成一道道海灣，水下暗藏的淺灘所困住的船隻，多到任何水手都不願去數。失事的船隻半埋在沙中，旁邊是更古老、更奇異的廢墟，而建造它們的人早已不在。魚人、九頭蛇與龍蝦人出沒於海岸線上，即使是熟悉這段海岸的人，走在上頭也得小心翼翼。\n\n在西岸的沙灘上方，一座地精建築矗立在山丘上，只能從內陸經由一條陡峭的小徑抵達。布利莫·機簧與茱比·機簧在此安家並做起了買賣。樓上他們的私人寢室裡擺著第三張床。沒有人知道這張床屬於誰，也不知道究竟有沒有人睡在上面。",
			source = "https://warcraft.wiki.gg/wiki/Ruined_Reaches",
		},
		["ruins of eldarath"] = {
			name = "埃達拉斯廢墟",
			short = "在世界破碎之前，埃達拉斯是精靈貴族的偉大據點之一，也是一座奧術學問之城，最強大的法師們將符文與石板刻於石上，立在公共場所，讓每個路過的人都能思索其中對奧術的洞見。",
			full = "在世界破碎之前，埃達拉斯是精靈貴族的偉大據點之一，也是一座奧術學問之城，最強大的法師們將符文與石板刻於石上，立在公共場所，讓每個路過的人都能思索其中對奧術的洞見。\n\n這座城市並非無聲無息地陷落。在先祖之戰中，卡多雷反抗軍曾在此與燃燒軍團決一死戰。當大崩裂將世界撕裂，埃達拉斯無法承受——城市的大部分崩塌碎裂，沉入了下方風暴海灣的海水之中。\n\n殘存的部分緊附在東側的懸崖上，是一片破碎的塔群，曾以此為家的夜精靈早已對它避之唯恐不及。如今納迦佔據了這片廢墟，督軍克雷利安從辛瑪洛神殿統治著剩下的一切。在殘骸之間，古老精靈貴族的符文石板依然矗立，其中的奧術智慧歷經漫長歲月仍未受損。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Eldarath",
		},
		["scalebeards cave"] = {
			name = "鱗鬚海龜洞穴",
			short = "風暴海灣中一座小島上的洞穴，以一隻稀有的老海龜鱗鬚為名。這裡是牠的家，但牠卻很少在此歇息，因為牠更喜歡遠赴無盡之海狩獵，讓巢穴空無一物。",
			full = "風暴海灣中一座小島上的洞穴，以一隻稀有的老海龜鱗鬚為名。這裡是牠的家，但牠卻很少在此歇息，因為牠更喜歡遠赴無盡之海狩獵，讓巢穴空無一物。",
			source = "https://warcraft.wiki.gg/wiki/Scalebeard's_Cave",
		},
		["shadowsong shrine"] = {
			name = "影歌神殿",
			short = "影歌神殿是艾薩拉西部一座布滿廢墟的山丘，關於它為何得此名，並沒有明確的記載。",
			full = "影歌神殿是艾薩拉西部一座布滿廢墟的山丘，關於它為何得此名，並沒有明確的記載。它與賈羅德·影歌同名，他在先祖之戰中領導了反抗軍；也與他的妹妹瑪翼夫同名，這位典獄官最為人所知的，是她在伊利丹·怒風於海加爾山背叛之後將他囚禁。至於這兩人與這座山丘有何關聯，沒有人說得上來。\n\n能說得上來的，是在那裡遊蕩的東西。精靈貴族的鬼魂徘徊在石塊之間，渴望著任何靠近的活物。",
			source = "https://warcraft.wiki.gg/wiki/Shadowsong_Shrine",
		},
		["shattered strand"] = {
			name = "破碎海岸",
			short = "破碎海岸沿著艾薩拉風暴海灣的北側延伸，到處都是九頭蛇、海巨人、龍蝦人與魚人，各自佔據著自己的一段沙灘。",
			full = "破碎海岸沿著艾薩拉風暴海灣的北側延伸，到處都是九頭蛇、海巨人、龍蝦人與魚人，各自佔據著自己的一段沙灘。儘管四處擠滿了利爪與觸手，亞考蘭神殿與艾達拉之塔依然從岸邊拔地而起。\n\n哥布林也在這段海岸上圈地，在尖牙與潮水之間炒作著海濱地產。",
			source = "https://warcraft.wiki.gg/wiki/Shattered_Strand",
		},
		["southfury river"] = {
			name = "怒水河",
			short = "怒水河發源於海加爾山的高處，從一座高山湖泊傾瀉而下，化為一道瀑布，轟然墜入低地。",
			full = "怒水河發源於海加爾山的高處，從一座高山湖泊傾瀉而下，化為一道瀑布，轟然墜入低地。從那裡開始，河面寬闊、水流湍急，將大地一分為二：它標示著梣谷與艾薩拉的交界，再往南則是貧瘠之地的盡頭與杜洛塔的起點。在河口處，河水越過最後一道瀑布，奔入無盡之海，就在哥布林港口棘齒城的東北方。\n\n沿途有數座橋橫跨河面，一座連接艾薩拉與梣谷，另一座則連接杜洛塔與貧瘠之地。\n\n這條河依然滋養著兩岸的田地，所經之處，土壤依舊青翠。",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["southridge beach"] = {
			name = "南山海灘",
			short = "南山海灘沿著風暴海灣的南緣延伸，沙灘上散落著昔日偉大城市埃達拉斯的廢墟。",
			full = "南山海灘沿著風暴海灣的南緣延伸，沙灘上散落著昔日偉大城市埃達拉斯的廢墟。如今納迦佔據著這片海岸，與龍蝦人、九頭蛇、魚人，以及偶爾從深海現身的海巨人共享此地。",
			source = "https://warcraft.wiki.gg/wiki/Southridge_Beach",
		},
		["storm cliffs"] = {
			name = "暴風崖",
			short = "暴風崖聳立於艾薩拉，被棲息在岩石間的惡鞭納迦所佔據。在懸崖的最東端矗立著黑羽紀念碑，孤零零地俯瞰著這片納迦盤據的岩石。",
			full = "暴風崖聳立於艾薩拉，被棲息在岩石間的惡鞭納迦所佔據。在懸崖的最東端矗立著黑羽紀念碑，孤零零地俯瞰著這片納迦盤據的岩石。",
			source = "https://warcraft.wiki.gg/wiki/Storm_Cliffs",
		},
		["talrendis point"] = {
			name = "塔倫迪斯營地",
			short = "塔倫迪斯營地位於艾薩拉西南部，兩座哨塔監視著與梣谷的邊境，一座月井仍滋潤著南邊的土地。",
			full = "塔倫迪斯營地位於艾薩拉西南部，兩座哨塔監視著與梣谷的邊境，一座月井仍滋潤著南邊的土地。\n\n這座營地起初只是一處小小的夜精靈營地，一座設在森林邊緣的崗哨。",
			source = "https://warcraft.wiki.gg/wiki/Talrendis_Point",
		},
		["temple of arkkoran"] = {
			name = "亞考蘭神殿",
			short = "亞考蘭神殿曾經用於崇拜伊露恩，它的石塊築於艾薩拉的東北海岸。那份神聖早已不復存在。",
			full = "亞考蘭神殿曾經用於崇拜伊露恩，它的石塊築於艾薩拉的東北海岸。那份神聖早已不復存在。如今海巨人亞考羅克盤踞在神殿頂端，由魚人和龍蝦人護衛，牠們會撲向任何靠近的人。周圍的海岸，也就是破碎海岸，同樣不是安全的通道，那裡有九頭蛇和海巨人把守，兇猛程度不亞於亞考羅克本身。",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Arkkoran",
		},
		["temple of zin malor"] = {
			name = "辛瑪洛神殿",
			short = "辛瑪洛神殿矗立在埃達拉斯廢墟之中，它的石造外形仿照附近的亞考蘭神殿，也與後來建於達納蘇斯的月神殿相似。",
			full = "辛瑪洛神殿矗立在埃達拉斯廢墟之中，它的石造外形仿照附近的亞考蘭神殿，也與後來建於達納蘇斯的月神殿相似。它是在夜精靈轉向奧術魔法之前的年代，為了崇奉伊露恩而建造的。\n\n神殿中曾存放著辛瑪洛水晶，這件贈禮本意是要向精靈貴族傳達一個訊息：他們根本不需要奧術魔法。如今水晶已經不在，很久以前便被人帶走了。\n\n此後神殿落入了惡鞭部族的納迦手中。如今督軍克雷利安統治著那裡，將昔日專為崇拜女神而保留的尊位據為己有。",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Zin-Malor",
		},
		["thalassian base camp"] = {
			name = "薩拉斯營地",
			short = "雷加什營地上方的山丘屬於血精靈，山坡上分布著一座座小型的防禦據點，由魔導師雷姆托里指揮。",
			full = "雷加什營地上方的山丘屬於血精靈，山坡上分布著一座座小型的防禦據點，由魔導師雷姆托里指揮。她與部落達成了一項交易，承諾將她的探險隊發掘出的任何東西分出一份，以換取保護探險隊所需的金錢與兵器。這項交易並未兌現。雷姆托里拿走了資助，卻什麼也沒有回報，背叛的消息傳開之後，據說她和她的追隨者都欠下了一筆必須以血償還的仇。\n\n雷姆托里本人很少待在營地裡，她一心在自己挑選的護衛陪同下探索艾薩拉，留下博學者鷹盔在她不在時守住山丘。這兩人真正追求的並不是黃金。在營地的一道山脊上擺著一本卡多雷召喚寶典，這東西能將惡魔召喚到世上，它的存在揭示了這支探險隊的真面目：這不是一場尋寶之旅，而是披著尋寶外衣的某種更黑暗的勾當。",
			source = "https://warcraft.wiki.gg/wiki/Thalassian_Base_Camp",
		},
		["tower of eldara"] = {
			name = "艾達拉之塔",
			short = "艾達拉之塔矗立在風暴海灣上方最東北端的陸地上，塔下的沙岸有魚人、龍蝦人與九頭蛇巡弋。",
			full = "艾達拉之塔矗立在風暴海灣上方最東北端的陸地上，塔下的沙岸有魚人、龍蝦人與九頭蛇巡弋。這座塔曾屬於遍布這片海岸的夜精靈文明，但如今它大門緊閉，早已荒廢。",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Eldara",
		},
		["ursolan"] = {
			name = "烏索蘭",
			short = "烏索蘭之名來自烏索爾，也就是熊怪一族所崇敬的熊之半神。如今這裡是木喉熊怪一處廣大的聚落，向南穿過要塞，一路延伸到熊頭。",
			full = "烏索蘭之名來自烏索爾，也就是熊怪一族所崇敬的熊之半神。如今這裡是木喉熊怪一處廣大的聚落，向南穿過要塞，一路延伸到熊頭。",
			source = "https://warcraft.wiki.gg/wiki/Ursolan",
		},
		["valormok"] = {
			name = "瓦羅莫克",
			short = "瓦羅莫克是部落在艾薩拉的一座前哨站，位於西北部，哈達爾營地的北方。駐守在此的戰士們熬過了艱困的時日，但仍懷抱著希望。",
			full = "瓦羅莫克是部落在艾薩拉的一座前哨站，位於西北部，哈達爾營地的北方。駐守在此的戰士們熬過了艱困的時日，但仍懷抱著希望。\n\n那份希望卻遭到了內部的背叛。貝爾戈洛姆·石槌曾派遣血精靈魔導師雷姆托里，帶著一隊獸人戰士到這個地區尋找財寶與強大的神器。雷姆托里找到了她所追尋的東西，但她不願分享這項發現，反而對護送她的戰士們下手，殺死了他們，將戰利品據為己有。營地的領袖阿格圖·血拳絕不會讓這場屠殺就此了結。他正在尋找戰士，為他死去的同袍以及石槌受創的尊嚴報仇，並要讓魔導師雷姆托里死在她附近的營地裡。",
			source = "https://warcraft.wiki.gg/wiki/Valormok",
		},
	},
	-- 費伍德森林: 18 subzones
	[1448] = {
