		["irontree cavern"] = {
			name = "鐵木山洞",
			short = "在洞穴深處，扭木那扭曲的枝幹已經紮下了根，生出了撕碎者與苔蘚剝皮者，牠們取代了任何活著的守護者，在黑暗中潛行。",
			full = "在洞穴深處，扭木那扭曲的枝幹已經紮下了根，生出了撕碎者與苔蘚剝皮者，牠們取代了任何活著的守護者，在黑暗中潛行。",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Cavern",
		},
		["irontree woods"] = {
			name = "鐵木森林",
			short = "鐵木森林曾是費伍德森林北部一片寧靜的林間空地，直到燃燒軍團的腐化將它扭曲成了另一副模樣。",
			full = "鐵木森林曾是費伍德森林北部一片寧靜的林間空地，直到燃燒軍團的腐化將它扭曲成了另一副模樣。夜精靈的三位偉大古樹曾居住於此，這三棵活著的樹名叫哈斯塔特、斯托瑪與瓦爾圖斯。腐化並沒有放過他們：三者都在原地石化，至今仍被封存在森林之中，死在奪走他們性命的枯萎之間。\n\n然而，有某種東西拒絕就此死去。注入森林中心的月井之水孕育出了一棵幼苗。在悉心照料下，它長大、開花，然後回到它誕生的土地，紮根在石化的逝者之間，等待著有朝一日成為古樹，取代他們的位置。",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Woods",
		},
		["jadefire glen"] = {
			name = "碧火谷",
			short = "在費伍德森林南部被腐化的林地中，碧火谷庇護著一座薩特營地，這些惡魔生物將這片遭到污染的谷地據為己有，在它的腐朽之中蓬勃生長，並將腐化進一步散播到周圍的樹林。",
			full = "在費伍德森林南部被腐化的林地中，碧火谷庇護著一座薩特營地，這些惡魔生物將這片遭到污染的谷地據為己有，在它的腐朽之中蓬勃生長，並將腐化進一步散播到周圍的樹林。",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Glen",
