		["jadefire run"] = {
			name = "碧火小徑",
			short = "碧火小徑位於費伍德森林北部，是這個地區最強大的薩特的居所。任何膽敢靠近的人都應當小心。",
			full = "碧火小徑位於費伍德森林北部，是這個地區最強大的薩特的居所。任何膽敢靠近的人都應當小心。這裡的建築遵循的是惡魔而非凡人的設計。",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Run",
		},
		["jaedenar"] = {
			name = "加德納爾",
			short = "加德納爾從曾經屬於夜精靈的土地上拔地而起，它的石塊比如今盤據其上的腐化更為古老。",
			full = "加德納爾從曾經屬於夜精靈的土地上拔地而起，它的石塊比如今盤據其上的腐化更為古老。廢墟之下有兩座德魯伊獸穴，曾經是神聖之地，而暗影議會正是在這褻瀆的根基上建立了他們的統治，並以崇拜欺詐者基爾加丹之意為此地命名。\n\n第三次大戰之後，這片廢墟落入了貝恩霍勒領主和他所率領的暗影議會手中。獸人與被遺忘者的術士充斥著廳堂，而他們並非獨自前來：魅魔、地獄獵犬、惡魔守衛與薩特都在他們之間穿梭。廢墟的中心矗立著暗影堡，那是暗影議會在艾澤拉斯的權力中樞，旁邊則是以基爾加丹之名建立的欺詐者神祠。",
			source = "https://warcraft.wiki.gg/wiki/Jaedenar",
		},
		["morlosaran"] = {
			name = "摩羅薩蘭",
			short = "摩羅薩蘭曾是一座偉大的夜精靈聚落，建於大崩裂撕裂世界之前。",
			full = "摩羅薩蘭曾是一座偉大的夜精靈聚落，建於大崩裂撕裂世界之前。如今它已成為費伍德森林南緣的一片廢墟，與亞米薩蘭、巴莎蘭、奧迪拉蘭和塔迪薩蘭等地一樣，這些都曾是繁榮的城市，如今只剩下石塊，以及對一個早已失落的黃金時代的追憶。",
			source = "https://warcraft.wiki.gg/wiki/Morlos'Aran",
		},
		["ruins of constellas"] = {
			name = "克斯特拉斯廢墟",
			short = "這裡斷裂的石柱曾屬於海加爾山附近的一座夜精靈聚落。一座月井仍靜臥在它的中心，但井中已不再蘊含純淨的光芒。",
			full = "這裡斷裂的石柱曾屬於海加爾山附近的一座夜精靈聚落。一座月井仍靜臥在它的中心，但井中已不再蘊含純淨的光芒。邪能的腐化已經滲入了井水，如今薩特薩瓦瑟拉斯代替薩瓦里克照料著它，像栽培一座用來下毒的花園一般培育著腐化。在廢墟更深處，一道火牆擋住了通往他的去路。\n\n德魯伊同胞並沒有讓這些惡魔安然無事，他們不斷出擊，力圖將這片土地從在此紮根的邪能手中奪回。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Constellas",
		},
		["shadow hold"] = {
			name = "暗影堡",
			short = "在費伍德森林西部的加德納爾之下，有一座曾是夜精靈獸穴的迷宮。暗影議會很久以前便佔據了這裡，如今術士與他們的惡魔僕從在隧道中四處遊蕩。",
			full = "在費伍德森林西部的加德納爾之下，有一座曾是夜精靈獸穴的迷宮。暗影議會很久以前便佔據了這裡，如今術士與他們的惡魔僕從在隧道中四處遊蕩。薩特王子薩瓦利斯與恐懼魔王貝恩霍勒領主都居住在其中。\n\n聖騎士特雷·萊弗治與夜精靈亞科納琳·星影深入費伍德森林，追查暗影議會活動的蹤跡。邪教徒將兩人都抓了起來，關在暗影堡內。特雷在那裡被折磨致死，他的靈魂也被俘虜他的人扭曲、腐化。亞科納琳仍被囚禁在深處，受到折磨她的人看守，等待著一場至今仍未到來的救援。",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Hold",
		},
		["shatter scar vale"] = {
			name = "碎痕谷",
			short = "碎痕谷是第三次大戰期間，燃燒軍團橫掃費伍德森林時地獄火墜落之處。它們留下的坑洞至今仍在悶燒，在大地上留下傷痕，而惡魔依舊在其間遊蕩。",
			full = "碎痕谷是第三次大戰期間，燃燒軍團橫掃費伍德森林時地獄火墜落之處。它們留下的坑洞至今仍在悶燒，在大地上留下傷痕，而惡魔依舊在其間遊蕩。",
			source = "https://warcraft.wiki.gg/wiki/Shatter_Scar_Vale",
		},
		["shrine of the deceiver"] = {
			name = "欺詐者神祠",
			short = "欺詐者神祠是費伍德森林加德納爾的一座腐化獸穴，得名自燃燒軍團之主——欺詐者基爾加丹。",
			full = "欺詐者神祠是費伍德森林加德納爾的一座腐化獸穴，得名自燃燒軍團之主——欺詐者基爾加丹。暗影議會的術士充斥著它的深處，對毫無準備的人來說，這裡是個危險之地。",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Deceiver",
		},
		["talonbranch glade"] = {
			name = "刺枝林地",
			short = "刺枝林地位於費伍德森林北部，木喉要塞以南，就在通往月光林地與冬泉谷的道路旁。",
			full = "刺枝林地位於費伍德森林北部，木喉要塞以南，就在通往月光林地與冬泉谷的道路旁。",
			source = "https://warcraft.wiki.gg/wiki/Talonbranch_Glade",
		},
		["timbermaw hold"] = {
			name = "木喉要塞",
			short = "木喉要塞位於費伍德森林東北部，是木喉熊怪部族的首府。它的隧道開闢出一條通往月光林地與冬泉谷的通道。",
			full = "木喉要塞位於費伍德森林東北部，是木喉熊怪部族的首府。它的隧道開闢出一條通往月光林地與冬泉谷的通道。\n\n當燃燒軍團的腐化悄悄侵入卡林多的神聖森林，熊怪們受到它的影響，被扭曲成了瘋狂的模樣。唯有木喉部族逃過了那片黑暗，他們躲藏在要塞之中，眼看著他們所深愛的森林化為一片潰爛而扭曲的景象。即使在惡魔的首領被擊倒許久之後，森林中的污染依然揮之不去。\n\n木喉要塞的熊怪對所有陌生人都心存戒備，擔心自己會被誤認為墮落的同族而遭到見面就攻擊。然而他們也明白自己無法獨自支撐下去，而那些贏得他們信任的人會發現，木喉部族將友誼看得比什麼都重要。最重要的是，他們只希望能終結墮落同胞的苦難，並為費伍德森林這道傷口找到治癒之法。",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- 安戈洛環形山: 9 subzones
	[1449] = {
		["fire plume ridge"] = {
			name = "火羽山",
			short = "火羽山聳立於安戈洛環形山的中心，是一座焦黑岩石構成的山，熔岩沿著山坡緩緩流下，火元素在熱浪中蠢動。",
			full = "火羽山聳立於安戈洛環形山的中心，是一座焦黑岩石構成的山，熔岩沿著山坡緩緩流下，火元素在熱浪中蠢動。淺層的岩漿脈絡在環形山底部流淌，為遍布安戈洛各處嘶嘶作響的蒸氣池與間歇泉提供熱源，使整座盆地彷彿都隨著這座山的火焰而呼吸。\n\n山頂的一座洞穴中住著火焰使者，它是盤據這座山的火元素中最強大的一個，也是這座山燃燒之心的主宰。在這裡閃爍舞動的火焰之靈訴說著數百年的歷程：燃燒，熄滅為餘燼，再度燃起，周而復始，永無止境。\n\n並非每個來到這座山的人都能駕馭它。一位名叫林哥的旅人前來探索山坡，卻迷失了方向，最後因熱衰竭而倒下。至今仍能在南邊的洞穴裡找到他，他始終沒能走出來。",
			source = "https://warcraft.wiki.gg/wiki/Fire_Plume_Ridge",
		},
		["fungal rock"] = {
			name = "蘑菇石",
			short = "蘑菇石位於安戈洛環形山的東北側岩壁上，是一座洞窟，猩猩居住在其中，與在黑暗中生長的幽靈菇為伴。",
			full = "蘑菇石位於安戈洛環形山的東北側岩壁上，是一座洞窟，猩猩居住在其中，與在黑暗中生長的幽靈菇為伴。洞外，一座瀑布下方匯聚成一個小水池，那裡站著卡爾納·雷塔維的機械猿猴A-Me 01。",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Rock",
		},
		["golakka hot springs"] = {
			name = "葛拉卡溫泉",
			short = "葛拉卡溫泉終年蒸氣繚繞，安戈洛環形山的火山核心在環形山西部將熱力傾注到水池與間歇泉中。",
			full = "葛拉卡溫泉終年蒸氣繚繞，安戈洛環形山的火山核心在環形山西部將熱力傾注到水池與間歇泉中。由這些蒸氣與火焰所孕育的怒火元素在岸邊徘徊，讓溫泉持續沸騰的同一股力量，也將牠們從大地中召喚而出。\n\n克拉蘭克曾經來到這裡，追查溫泉與附近火羽山的火焰之間的關聯，後來他的探索又將他帶往了別處。",
			source = "https://warcraft.wiki.gg/wiki/Golakka_Hot_Springs",
		},
		["ironstone plateau"] = {
			name = "鐵石高原",
			short = "光禿的岩石沿著東北側的岩壁，從安戈洛的一片翠綠中突出。與環形山的其他地方相比，鐵石高原十分寧靜，幾乎沒有掠食者。",
			full = "光禿的岩石沿著東北側的岩壁，從安戈洛的一片翠綠中突出。與環形山的其他地方相比，鐵石高原十分寧靜，幾乎沒有掠食者。年幼的翼手龍在此築巢，高原的靜謐讓它有別於安戈洛那永不停歇的蓬勃生長。",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Plateau",
		},
		["lakkari tar pits"] = {
			name = "拉卡利油沼",
			short = "馬紹爾營地以北的黑色湖泊濃稠而惡臭，躺在安戈洛的一片翠綠之中。數以百計的骨骸從湖面突出，那是野獸的遺骸，牠們以為踏上的是堅實的地面，結果卻落了空。",
			full = "馬紹爾營地以北的黑色湖泊濃稠而惡臭，躺在安戈洛的一片翠綠之中。數以百計的骨骸從湖面突出，那是野獸的遺骸，牠們以為踏上的是堅實的地面，結果卻落了空。食腐動物在湖邊徘徊，等著焦油完成它未竟之事，而焦油獸則從油沼中升起。",
			source = "https://warcraft.wiki.gg/wiki/Lakkari_Tar_Pits",
		},
		["marshals refuge"] = {
			name = "馬紹爾營地",
			short = "馬紹爾營地位於安戈洛環形山的北緣，由威利德·馬紹爾與霍萊伊·馬紹爾率領的馬紹爾探險隊所建立。",
			full = "馬紹爾營地位於安戈洛環形山的北緣，由威利德·馬紹爾與霍萊伊·馬紹爾率領的馬紹爾探險隊所建立。他們進入環形山的探險，並沒有為所遇到的一切做好準備；安戈洛的野獸實在太過兇猛，探險隊的基地營一個接一個地被攻陷。探險隊的殘部逃往高處，最後在環形山的邊緣這裡脫身。\n\n這座營地正是那場撤退的結果，是一處勉強保住、而非奪來的立足點。",
			source = "https://warcraft.wiki.gg/wiki/Marshal's_Refuge",
		},
		["marshlands"] = {
			name = "沼澤地",
			short = "這片沼澤蔓延於安戈洛環形山的東南部，是一大片低窪的死水與蔓生的雜草，大多數初次從塔納利斯下到環形山的人都會先來到這裡，因為其他的路徑都十分險惡。",
			full = "這片沼澤蔓延於安戈洛環形山的東南部，是一大片低窪的死水與蔓生的雜草，大多數初次從塔納利斯下到環形山的人都會先來到這裡，因為其他的路徑都十分險惡。迅猛龍成群結隊地穿梭於蘆葦之間，有些咬一口便帶有劇毒。\n\n在這裡可以找到藍色能量水晶，它們的力量已經滲入沼澤本身，也滲入了在潮濕地面上獵食的迅猛龍體內，在牠們身上留下了印記。\n\n在一座從水中隆起的土丘上，托爾瓦·尋路者正在守望，他是從環形山的其他地方划著獨木舟來到這裡的。",
			source = "https://warcraft.wiki.gg/wiki/Marshlands",
		},
		["slithering scar"] = {
			name = "巨痕谷",
			short = "巨痕谷蔓延於安戈洛環形山的南部，是格里什族群的蟲巢。",
			full = "巨痕谷蔓延於安戈洛環形山的南部，是格里什族群的蟲巢。\n\n這座蟲巢曾經有一位女王，只要觸動蟲巢中的格里什異種蠍水晶，就能將她召喚出來。",
			source = "https://warcraft.wiki.gg/wiki/Slithering_Scar",
