		["terror run"] = {
			name = "恐懼小道",
			short = "在巨痕谷以西的恐懼小道，紅色水晶從地面生長而出，這是安戈洛環形山其他地方都見不到的景象。這條小道上的野獸吸收了水晶的力量，從牠們身上便看得出來。",
			full = "在巨痕谷以西的恐懼小道，紅色水晶從地面生長而出，這是安戈洛環形山其他地方都見不到的景象。這條小道上的野獸吸收了水晶的力量，從牠們身上便看得出來。",
