	-- 月光林地: 5 subzones
	[1450] = {
		["lake eluneara"] = {
			name = "月神湖",
			short = "清澈如水晶的湖水充滿了月光林地的中心，在林木之下平靜如鏡。湖面之下沉睡著瘋狂的半神年獸，牠在許多世紀之前便被擊敗，卻從未真正離開這片深水。",
			full = "清澈如水晶的湖水充滿了月光林地的中心，在林木之下平靜如鏡。湖面之下沉睡著瘋狂的半神年獸，牠在許多世紀之前便被擊敗，卻從未真正離開這片深水。湖水讓牠保持沉寂，彷彿平靜水面下一股無聲的重壓。",
			source = "https://warcraft.wiki.gg/wiki/Lake_Elune'ara",
		},
		["nighthaven"] = {
			name = "永夜港",
			short = "在月神湖畔矗立著永夜港，這是一座由夜精靈石造建築與月井構成的村落，也是塞納里奧議會德魯伊的家園。",
			full = "在月神湖畔矗立著永夜港，這是一座由夜精靈石造建築與月井構成的村落，也是塞納里奧議會德魯伊的家園。這是一處寧靜而隱蔽的所在，對大多數外人緊閉大門，村民們一心奉獻於德魯伊之道與對大自然的照料。\n\n永夜港每年只開放一次門戶，那是在慶祝新年慶典的時候，人們在湖面上燃放煙火，向伊露恩的力量致敬，迎接那些平日在這裡絕不會受到歡迎的陌生人。\n\n然而這座村落也曾見過比任何節慶都更黑暗的夜晚。守護者雷姆洛斯就是在這裡，與遭到腐化、轉而與村落為敵的夢魘之龍伊蘭尼庫斯對峙。夢魘生物湧向永夜港，眼看就要將它徹底毀滅，直到泰蘭妲·語風終於到來，召喚伊露恩的光芒，淨化了侵佔巨龍的腐化。月井至今仍燃燒著同樣的光芒。",
			source = "https://warcraft.wiki.gg/wiki/Nighthaven",
		},
		["shrine of remulos"] = {
			name = "雷姆洛斯神殿",
			short = "雷姆洛斯神殿矗立於月光林地西部，是為了紀念守望此地的守護者而建。神殿中住著夜精靈塔加里，他指引著想要學習水棲形態的年輕德魯伊。",
			full = "雷姆洛斯神殿矗立於月光林地西部，是為了紀念守望此地的守護者而建。神殿中住著夜精靈塔加里，他指引著想要學習水棲形態的年輕德魯伊。",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Remulos",
		},
		["stormrage barrow dens"] = {
			name = "怒風獸穴",
			short = "在月光林地寧靜的草地之下，沉睡著一座座獸穴，它們深陷於大地之中，許多夜精靈德魯伊從未真正離開這裡，他們的肉體在此安息，靈魂則漫遊於翡翠夢境。",
			full = "在月光林地寧靜的草地之下，沉睡著一座座獸穴，它們深陷於大地之中，許多夜精靈德魯伊從未真正離開這裡，他們的肉體在此安息，靈魂則漫遊於翡翠夢境。\n\n瑪法里恩·怒風曾在這裡沉睡，這些獸穴也因此以他為名。第三次大戰期間，當提克迪奧斯與他的恐懼魔王到來時，他們襲擊了沉睡中的瑪法里恩，幾乎將他的獸穴撕成碎片。是泰蘭妲·語風喚醒了他，將他召回人世，對抗阿克蒙德與燃燒軍團。\n\n後來，當塞納里奧議會談起要培育第二棵世界之樹時，瑪法里恩回到獸穴中冥想。泰蘭妲後來前來尋找他，卻發現他的身軀一動也不動，彷彿沉睡一般，怎麼也喚不醒。議會認為最好不要移動他：如果他的靈魂仍在夢境中徘徊，尋找回家的路，那麼它需要在離開時的地方找到自己的身軀。於是他便留在了那裡，由塞納里奧議會與伊露恩姊妹會守護著，身軀靜靜地躺在以他為名的獸穴之中。",
			source = "https://warcraft.wiki.gg/wiki/Stormrage_Barrow_Dens",
		},
		["timbermaw hold"] = {
			name = "木喉要塞",
			short = "木喉要塞位於費伍德森林東北部，一條隧道從這裡貫穿，通往月光林地與冬泉谷。它是木喉熊怪部族的首府。",
			full = "木喉要塞位於費伍德森林東北部，一條隧道從這裡貫穿，通往月光林地與冬泉谷。它是木喉熊怪部族的首府。\n\n當燃燒軍團的腐化悄悄侵入卡林多的神聖森林，熊怪們都受到了它的影響。唯有木喉部族逃過了那片黑暗，他們躲藏在要塞之中，無助地眼看著他們所深愛的森林被扭曲成一片潰爛的景象。即使在腐化的源頭被摧毀之後，森林中的污染依然揮之不去。\n\n如今木喉部族對所有陌生人都心存戒備，擔心自己會被誤認為墮落的同族而遭到見面就攻擊。然而他們也明白自己無法獨自支撐下去，而那些贏得他們信任的人會發現，木喉部族將友誼看得比什麼都重要。他們的薩滿傳統延續至今，精於以獸皮製作護甲，也保有古老的醫療知識。最重要的是，這個部族渴望終結墮落同胞的苦難，好讓這座古老的森林有朝一日能再度響起它所失去的吟唱與歡笑。",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
