			full = "甲蟲之牆沿著希利蘇斯的南緣延伸，將沙漠與牆外的安其拉廢城隔絕開來。它在流沙之戰結束時從沙地中拔起，龐大的砂岩牆身高聳入天至少百呎。在這個高度之上，石牆已無法再往上升，青銅龍軍團便在那裡編織魔法，形成一道比石牆還要高出許多倍的屏障。\n\n建造它的夜精靈與青銅龍將它命名為伊瑞納艾希爾，意思是「抵禦暗影之盾」。這個名字清楚地說明了它的用途：克蘇恩與它的異種蠍蟲群被封印在安其拉之中，而這道牆便矗立在那份恐怖與世界其他地方之間。",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Wall",
		},
		["southwind village"] = {
			name = "南風村",
			short = "南風村曾是夜精靈在希利蘇斯的一座前哨站。它沒能在流沙之戰中倖存。",
			full = "南風村曾是夜精靈在希利蘇斯的一座前哨站。它沒能在流沙之戰中倖存。\n\n當其拉蟲族成群結隊地崛起，范達爾·鹿盔之子瓦爾斯坦·鹿盔率領一支夜精靈軍隊前去守衛這座村落。他的部隊在原地遭到屠殺，瓦爾斯坦本人則被拉賈克斯將軍生擒，而他奉命守衛的村落就在他身後被撕成碎片。\n\n其拉蟲族留下的廢墟並沒有就此空無一物。在屠殺中倒下的德魯伊與哨兵的靈魂徘徊在殘骸之間，漫無目的地遊蕩，被束縛在他們死去的地方，跟隨著琥珀月之影。南風村至今仍屹立，但它不是一片寂靜的廢墟，而是一片鬧鬼之地，這裡的亡者至今仍未了卻與它的牽絆。",
			source = "https://warcraft.wiki.gg/wiki/Southwind_Village",
		},
		["staghelm point"] = {
			name = "鹿盔崗哨",
			short = "一座夜精靈高塔曾經矗立在希利蘇斯東北部的一座山峰上。永恆守望者拉羅沙爾在這裡堅守崗位，一頭屬於諾茲多姆子嗣的青銅幼龍在她頭頂的天空中盤旋。",
			full = "一座夜精靈高塔曾經矗立在希利蘇斯東北部的一座山峰上。永恆守望者拉羅沙爾在這裡堅守崗位，一頭屬於諾茲多姆子嗣的青銅幼龍在她頭頂的天空中盤旋。沿著道路從高塔往下走，便是暮光基地，那是一座庇護著暮光邪教徒的洞穴，洞口還有一座小營地，是這位守望者必須應付的威脅。",
			source = "https://warcraft.wiki.gg/wiki/Staghelm_Point",
		},
		["swarming pillar"] = {
			name = "蟲群之柱",
			short = "蟲群之柱聳立在塞納里奧城堡以南，是一座被異種蠍隧道鑽得千瘡百孔的山峰，它的山坡從未有片刻平靜。",
			full = "蟲群之柱聳立在塞納里奧城堡以南，是一座被異種蠍隧道鑽得千瘡百孔的山峰，它的山坡從未有片刻平靜。一團由小型異種蠍組成的霧靄無時無刻不在岩石周圍盤旋，正是這片活生生的雲讓這根石柱得名，而在它腳下的沙地之中，有一座蟲巢的巢室，在希利蘇斯地底如蜂窩般密布的眾多巢穴中，它是最大的一座。",
			source = "https://warcraft.wiki.gg/wiki/Swarming_Pillar",
		},
		["twilight base camp"] = {
