		["twilight post"] = {
			name = "暮光崗哨",
			short = "暮光崗哨位於希利蘇斯西北部，在塞納里奧城堡以西、暮光營地的西北方，是暮光之錘在那片飽受沖刷、淤沙飛揚的土地上所佔據的一處立足點。",
			full = "暮光崗哨位於希利蘇斯西北部，在塞納里奧城堡以西、暮光營地的西北方，是暮光之錘在那片飽受沖刷、淤沙飛揚的土地上所佔據的一處立足點。",
