		["frostfire hot springs"] = {
			name = "冰火溫泉",
			short = "在冬泉谷的最西緣，一連串的水池冒著蒸氣，池水的溫度與周圍冰封的大地格格不入。沒有人能解釋為什麼這些溫泉會在冰雪之下灼熱滾燙。",
			full = "在冬泉谷的最西緣，一連串的水池冒著蒸氣，池水的溫度與周圍冰封的大地格格不入。沒有人能解釋為什麼這些溫泉會在冰雪之下灼熱滾燙。在附近紮營的多諾瓦·雪山懷疑，或許是某種惡魔的污染從暗語峽谷向北滲透，一路來到這裡，溫熱了岩石。\n\n最靠近木喉要塞的那座水池，始終沒能擺脫寒水部族的掌控。他們至今仍佔據著它，而這些熊怪可不打算與人分享他們所佔有的溫暖。",
			source = "https://warcraft.wiki.gg/wiki/Frostfire_Hot_Springs",
