		["ice thistle hills"] = {
			name = "冰薊嶺",
			short = "冰薊嶺聳立於永望鎮的東南方，是冰薊雪人的家園，牠們在一座沿山坡向上延伸的洞穴中築窩，並在周圍的山坡上四處遊蕩。",
			full = "冰薊嶺聳立於永望鎮的東南方，是冰薊雪人的家園，牠們在一座沿山坡向上延伸的洞穴中築窩，並在周圍的山坡上四處遊蕩。牠們厚實的毛皮與蒼白的角，深受那些冒著嚴寒前來獵取的人所珍視。\n\n開闊的山坡上長著冰蓋草，洞穴內的岩石中則有瑟銀礦脈穿過。最罕見的是，據說在洞穴的最邊緣，有時會綻放一朵黑蓮花，在雪人的領地中顯得脆弱而奇異。",
			source = "https://warcraft.wiki.gg/wiki/Ice_Thistle_Hills",
		},
		["lake keltheril"] = {
			name = "凱斯利爾湖",
			short = "凱斯利爾湖冰封的湖水靜靜地躺在冬泉谷的中心，周圍環繞著與它同名的廢墟。",
			full = "凱斯利爾湖冰封的湖水靜靜地躺在冬泉谷的中心，周圍環繞著與它同名的廢墟。這些廢墟是古老的精靈貴族所建，而曾經居住在那裡的人，在他們的殿堂傾頹時並沒有離開。他們的靈魂至今仍徘徊不去，飽受折磨，飄蕩在冰面與碎石之間。",
			source = "https://warcraft.wiki.gg/wiki/Lake_Kel'Theril",
		},
		["mazthoril"] = {
			name = "麥索瑞爾",
			short = "在冬泉谷的冰層深處，凱斯利爾湖附近，麥索瑞爾洞窟在地底展開，寒冷而廣闊，充滿了魔法。",
			full = "在冬泉谷的冰層深處，凱斯利爾湖附近，麥索瑞爾洞窟在地底展開，寒冷而廣闊，充滿了魔法。這裡住著一群效忠於瑪里苟斯的藍龍，牠們的女族長也在此獨自守望。\n\n海蕾很少以世人所認為的真身示人，她只以一名高等精靈的模樣出現在洞窟的最高處，要到達那裡，必須經由設在遙遠下方地面上的一道傳送符文。除了她的同族之外，很少有人能見到她的面容。\n\n她在身邊布下了與她的隱遁相稱的守衛。四頭強大的幼龍只聽命於她一人。法術之喉沿著冬泉谷低地的三分之一緩緩地巡行，從不間斷，而法力之爪與占卜者則守在洞窟後方的符文旁，就像守著一扇上了鎖的門的哨兵。",
			source = "https://warcraft.wiki.gg/wiki/Mazthoril",
		},
		["moon horror den"] = {
			name = "慘月洞穴",
			short = "從永望鎮的大門往東北方走一小段路，地勢便向上升起，通往一座名為慘月洞穴的小洞穴，那裡住著兇猛的狂怒梟獸。",
			full = "從永望鎮的大門往東北方走一小段路，地勢便向上升起，通往一座名為慘月洞穴的小洞穴，那裡住著兇猛的狂怒梟獸。洞穴與南邊的寒水村之間隔著一座山，兩地看似相近，卻沒有直接相通的路，只能繞過高地騎行很長一段路。",
