		["ruins of keltheril"] = {
			name = "凱斯利爾廢墟",
			short = "凱斯利爾廢墟破碎地散落在與它同名的湖泊邊緣，是一座偉大的夜精靈城市僅存的遺跡。",
			full = "凱斯利爾廢墟破碎地散落在與它同名的湖泊邊緣，是一座偉大的夜精靈城市僅存的遺跡。它在大崩裂中陷落，那時世界本身都被撕裂，而它從此再也沒能重新崛起。\n\n如今在那裡徘徊的，是化為不安的悲傷。凱斯利爾陷落時死去的精靈貴族並未安息；他們的靈魂仍留在北側廢墟傾倒的石柱之間，飽受折磨，無法放下他們所失去的一切。高等精靈的鬼魂則在東側一帶出沒，其中有遭到背叛的遊俠，還有一位大法師。\n\n一塊名為辛瑪洛的水晶與這個地方的陷落息息相關，牽連著一場在此吞噬了一代又一代精靈的毀滅。那段故事屬於凱斯利爾本身，屬於那些傾倒的石塊，以及仍在其間行走的鬼魂。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Kel'Theril",
		},
		["starfall village"] = {
			name = "墜星村",
			short = "墜星村位於穿越冬泉谷的道路旁，是聯盟在那片寒冷國度中唯一的立足點。",
			full = "墜星村位於穿越冬泉谷的道路旁，是聯盟在那片寒冷國度中唯一的立足點。這座聚落由一座夜精靈的小屋與一棟較小的房子組成，附近便是班薩羅獸穴，它深陷於大地之中，就像它所得名的墓丘一樣。",
			source = "https://warcraft.wiki.gg/wiki/Starfall_Village",
		},
		["timbermaw hold"] = {
			name = "木喉要塞",
			short = "木喉要塞位於費伍德森林北部的隧道之中，這條通道通往月光林地與冬泉谷，而它也是木喉熊怪部族最後的據點。",
			full = "木喉要塞位於費伍德森林北部的隧道之中，這條通道通往月光林地與冬泉谷，而它也是木喉熊怪部族最後的據點。\n\n當燃燒軍團的腐化悄悄侵入卡林多的神聖森林，那片土地上的熊怪紛紛淪陷，被扭曲成野蠻而殘忍的模樣。唯有木喉部族逃過了這樣的命運，他們堅守在自己的隧道之中，眼看著他們所深愛的森林在周圍化為一片潰爛而扭曲的景象。即使在腐化的源頭被摧毀之後，森林中的污染依然沒有消散。\n\n木喉部族至今仍對所有陌生人心存戒備，擔心自己會被誤認為墮落的同族，還來不及證明自己便遭到砍殺。然而他們也明白自己無法獨自支撐下去，而對那些贏得他們信任的人，他們十分慷慨：他們堅守古老的薩滿之道，並毫無保留地分享他們所保有的醫療知識。他們最大的心願，是終結墮落同胞的苦難，並為費伍德森林所受的創傷找到治癒之法。",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
		["timbermaw post"] = {
			name = "木喉崗哨",
			short = "木喉崗哨保留著一個已經名不副實的名字。",
			full = "木喉崗哨保留著一個已經名不副實的名字。這座營地曾經屬於木喉部族，但如今它已聽命於墮落的寒水熊怪，他們將這裡完全佔據，營地位於冰火溫泉的東南方、凱斯利爾湖的西邊。",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Post",
		},
		["winterfall village"] = {
			name = "寒水村",
			short = "寒水村攀附在冬泉谷東側的山坡上，靠近永望鎮，村裡的熊怪早已墮落。村子的頂端有一座小洞穴，那是冬泉酋長的寶座，他就在那裡統治著這座聚落。",
			full = "寒水村攀附在冬泉谷東側的山坡上，靠近永望鎮，村裡的熊怪早已墮落。村子的頂端有一座小洞穴，那是冬泉酋長的寶座，他就在那裡統治著這座聚落。",
			source = "https://warcraft.wiki.gg/wiki/Winterfall_Village",
		},
	},
	-- 暴風城: 3 subzones
	[1453] = {
		["champions hall"] = {
			name = "勇士大廳",
			short = "在暴風城舊城區的南邊矗立著勇士大廳，聯盟的軍官們駐紮於此，在舊城之中另闢一隅，正與他們的軍階相稱。",
			full = "在暴風城舊城區的南邊矗立著勇士大廳，聯盟的軍官們駐紮於此，在舊城之中另闢一隅，正與他們的軍階相稱。",
			source = "https://warcraft.wiki.gg/wiki/Champions'_Hall",
		},
		["deeprun tram"] = {
			name = "礦道地鐵",
			short = "國王麥格尼·銅鬚建造礦道地鐵，並不是為了貪圖舒適。",
			full = "國王麥格尼·銅鬚建造礦道地鐵，並不是為了貪圖舒適。第二次大戰後的那些年裡，暴風城正從廢墟中艱辛地重建，麥格尼對鐵爐堡的援助送達人類盟友手中的速度之慢感到不耐，也擔憂一旦戰火再起，矮人士兵趕去支援的速度會太過遲緩。他求助於艾澤拉斯最受推崇的工程師——大工匠格爾賓·梅卡托克，要他解決這個問題。梅卡托克給出的答案，是一條深入地底的鐵路，將兩座首都直接連接起來。\n\n建造者在隧道的路徑下方遇到了一座地底湖泊，但他們並沒有繞道而行。地鐵至今仍從湖中穿過，封閉的軌道並非從湖邊經過，而是從湖水之下通過。\n\n地精每天都在照料這條地鐵，讓它的兩組三節車廂在鐵爐堡與暴風城之間快速而平穩地往返，所有穿越地下月台的人都能免費搭乘。",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["valley of heroes"] = {
			name = "英雄谷",
			short = "一座淺色石橋載著每一位旅人越過暴風城南門前的護城河，進入一座綠意盎然的山谷，谷中兩旁矗立著雕像，它們既是為了榮耀，也同樣是為了哀悼而立。",
			full = "一座淺色石橋載著每一位旅人越過暴風城南門前的護城河，進入一座綠意盎然的山谷，谷中兩旁矗立著雕像，它們既是為了榮耀，也同樣是為了哀悼而立。\n\n第二次大戰之後，當暴風城從廢墟中重建時，這座城市向那些率領聯盟遠征軍穿過黑暗之門、從彼端將它封閉的英雄們致敬。庫德蘭·蠻錘與大法師卡德加立於道路左側；指揮官達納斯·托爾貝恩與遊俠隊長艾蘭里亞·風行者立於右側；而在道路的盡頭，也就是道路分岔、通往城內之處，矗立著率領他們所有人的圖拉揚將軍。這五人之中，沒有一個人回來。\n\n多年以後，艾蘭里亞與圖拉揚的兒子阿拉托爾被帶到山谷中參加一場典禮，由一位白銀之手騎士扛在肩上。他抬頭望著母親的石像，那是一張他毫無記憶的臉。然而她的某種氣息在那裡觸動了他，因為這個男孩露出了微笑，朝雕像伸出了手。在他成長的歲月裡，他一次又一次地回到這裡，站在她的面容前，雖然記不得她，卻明白她曾經深愛著他。",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Heroes",
		},
	},
	-- 奧格瑪: 2 subzones
	[1454] = {
