		["ragefire chasm"] = {
			name = "怒焰裂谷",
			short = "在奧格瑪的地底，大地裂開成一道烈焰峽谷，隧道中充斥著熔岩與濃煙。穴居人已經開始從這裡的深處向上攀爬，部落稱這個部族為怒焰穴居人。",
			full = "在奧格瑪的地底，大地裂開成一道烈焰峽谷，隧道中充斥著熔岩與濃煙。穴居人已經開始從這裡的深處向上攀爬，部落稱這個部族為怒焰穴居人。牛頭人先知瑪加薩曾試圖與他們議和，希望能讓他們遠離上方的城市。她得到的卻只有敵意。事情很快就變得明朗：這些生物對外交毫無興趣，如果放任不管，他們甚至可能徹底淹沒部落。\n\n更糟的是，陰謀已經伸入了奧格瑪內部。尼爾魯·火刃隱藏著自己身為燃刃氏族領袖的真正效忠對象，將索爾忠誠的追隨者引誘到裂谷之中，把他們送給藏身在那裡的一群黑暗邪教徒，一方面藉此除掉他們，另一方面也藉此試探這些邪教徒是否可信。索爾對這場背叛所知道的，遠比他表現出來的更多，但邪教徒的首領們至今仍盤據著他們據為己有的洞窟。",
			source = "https://warcraft.wiki.gg/wiki/Ragefire_Chasm",
		},
	},
