	-- 達納蘇斯: 5 subzones
	[1457] = {
		["cenarion enclave"] = {
			name = "塞納里奧區",
			short = "塞納里奧區位於達納蘇斯的西北部，是一片圓形的樹林，其中的橡樹與梣樹比城中其他地方的石造殿堂還要高聳。",
			full = "塞納里奧區位於達納蘇斯的西北部，是一片圓形的樹林，其中的橡樹與梣樹比城中其他地方的石造殿堂還要高聳。這裡的每一棵樹上都有符文，它們不是刻出來的，而是從活生生的樹皮中生長而成，而樹林中的聚會場所本身也是由木材與石頭交融而成，彷彿是培育而生，而非建造而成。\n\n這裡向來是城中德魯伊的據點，正如月神殿是祭司的據點。大德魯伊范達爾·鹿盔在塞納里奧區的枝幹間領導著他們，而矗立於樹林中心、最大的一座活體建築，便是他本人的居所。\n\n這片樹林至今仍為聚集在其下的修會服務：德魯伊來到這裡學習古老的傳統，獵人在最東邊的樹中接受訓練，而在塞納里奧區巨樹的樹腳下，則可以學習騎乘夜刃豹，達納蘇斯的騎手們便是騎著牠們穿越荒野。在地面之下，最西邊的樹幹中隱藏著一個神秘的盜賊公會的據點，只有早已知道該往哪裡找的人才會知曉。",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Enclave",
		},
		["craftsmens terrace"] = {
			name = "工匠區",
			short = "工匠區位於達納蘇斯的北部，這裡是屬於貿易的地方，而非戰爭或崇拜。城中的工匠在此經營他們的店鋪，疲憊的旅人也可以在達納蘇斯的一間旅店中歇息。",
			full = "工匠區位於達納蘇斯的北部，這裡是屬於貿易的地方，而非戰爭或崇拜。城中的工匠在此經營他們的店鋪，疲憊的旅人也可以在達納蘇斯的一間旅店中歇息。銀色黎明的使館同樣設在這裡，這個外來勢力在這座精靈城市中獲得了一席之地。\n\n工匠區南邊與戰士區相鄰，西邊則與塞納里奧區相接。",
			source = "https://warcraft.wiki.gg/wiki/Craftsmen's_Terrace",
		},
		["temple gardens"] = {
			name = "神殿花園",
			short = "在達納蘇斯的中心，坐落著神殿花園，這是一大片由水域、步道與小島構成的地方，得名自就在南方聳立的宏偉月神殿。",
			full = "在達納蘇斯的中心，坐落著神殿花園，這是一大片由水域、步道與小島構成的地方，得名自就在南方聳立的宏偉月神殿。一座座橋梁向四面八方延伸，北接塞納里奧區，東連工匠區、戰士區與貿易區，南通月神殿，使得穿越城市的每一條道路似乎都匯聚於此。\n\n最大的一座島上設有城中的銀行，而花園西緣的一座傳送門則可以通往世界之樹腳下的魯瑟蘭村，讓這個由水與石構成的寧靜中心，同時也成為達納蘇斯與外面世界之間的門檻。",
			source = "https://warcraft.wiki.gg/wiki/Temple_Gardens",
		},
		["tradesmens terrace"] = {
			name = "貿易區",
			short = "貿易區位於達納蘇斯的南部，店主們在此擺設攤位，商人們在此聚集議價，使它成為整座城市的商業中心。",
			full = "貿易區位於達納蘇斯的南部，店主們在此擺設攤位，商人們在此聚集議價，使它成為整座城市的商業中心。它的北邊通往戰士區，往西的道路則通向月神殿與神殿花園。\n\n這裡的建築依照夜精靈的方式以木材生長而成，輕盈而優雅。",
			source = "https://warcraft.wiki.gg/wiki/Tradesmen's_Terrace",
